# Timeframe mapping for different API providers
def convert_timeframe_for_provider(timeframe: str, provider: str = "polygon") -> str:
    """Convert timeframe format for different API providers"""
    if provider == "polygon":
        # Polygon.io uses specific format
        mapping = {
            "1m": "1min", "1min": "1min",
            "5m": "5min", "5min": "5min", 
            "15m": "15min", "15min": "15min",
            "30m": "30min", "30min": "30min",
            "45m": "45min", "45min": "45min",
            "1h": "1h", "1hour": "1h",
            "2h": "2h", "2hour": "2h",
            "4h": "4h", "4hour": "4h",
            "8h": "8h", "8hour": "8h",
            "1d": "1day", "1day": "1day",
            "1w": "1week", "1week": "1week",
            "1M": "1month", "1month": "1month"
        }
        return mapping.get(timeframe, timeframe)
    elif provider == "twelvedata":
        # TwelveData uses different format
        mapping = {
            "1d": "1day", "1day": "1day",
            "1w": "1week", "1week": "1week",
            "1M": "1month", "1month": "1month"
        }
        return mapping.get(timeframe, timeframe)
    
    return timeframe

# Persistent Interactions System - Makes all Discord interactions never expire
class PersistentInteractionManager:
    """Global manager for persistent interactions that never expire"""
    
    active_views = weakref.WeakSet()
    renewal_tasks = {}
    
    @classmethod
    def register_view(cls, view):
        """Register a view for automatic management"""
        cls.active_views.add(view)
        
        # Create renewal task
        if hasattr(view, 'auto_renew') and view.auto_renew:
            task = asyncio.create_task(cls._auto_renewal_loop(view))
            cls.renewal_tasks[id(view)] = task
    
    @classmethod
    def unregister_view(cls, view):
        """Remove view from management"""
        view_id = id(view)
        if view_id in cls.renewal_tasks:
            task = cls.renewal_tasks[view_id]
            if not task.done():
                task.cancel()
            del cls.renewal_tasks[view_id]
    
    @classmethod
    async def _auto_renewal_loop(cls, view):
        """Background task that periodically renews views"""
        try:
            while getattr(view, 'auto_renew', False):
                # Wait for renewal time (13 minutes to be safe)
                await asyncio.sleep(13 * 60)
                
                # Check if view still exists and needs renewal
                if view in cls.active_views and hasattr(view, 'renew_view'):
                    await view.renew_view()
                else:
                    break
                    
        except asyncio.CancelledError:
            pass
        except Exception as e:
            print(f"Error in auto-renewal loop: {e}")
    
    @classmethod
    async def renew_all_views(cls):
        """Manually renew all active views"""
        for view in list(cls.active_views):
            try:
                if hasattr(view, 'renew_view'):
                    await view.renew_view()
            except Exception as e:
                print(f"Error renewing view: {e}")
    
    @classmethod
    def get_active_count(cls) -> int:
        """Get count of active persistent views"""
        return len(cls.active_views)

class PersistentView(discord.ui.View):
    """Base view that automatically renews itself to prevent expiration"""
    
    def __init__(self, timeout_minutes: int = 14, auto_renew: bool = True):
        # Set timeout just under Discord's limit
        super().__init__(timeout=timeout_minutes * 60)
        self.auto_renew = auto_renew
        self.renewal_task = None
        self.original_interaction = None
        self.persistent_data = {}
        self.renewal_count = 0
        
    async def on_timeout(self):
        """Handle timeout by renewing the view if auto_renew is enabled"""
        if hasattr(self, 'auto_renew') and self.auto_renew and self.original_interaction:
            await self.renew_view()
        else:
            await self.cleanup()
    
    async def renew_view(self):
        """Create a new identical view to replace the expired one"""
        try:
            # Create new view with same state - pass timeout_minutes and auto_renew properly
            new_view = self.__class__(timeout_minutes=14, auto_renew=self.auto_renew)
            new_view.persistent_data = self.persistent_data.copy()
            new_view.renewal_count = self.renewal_count + 1
            new_view.original_interaction = self.original_interaction
            
            # Copy any additional attributes
            for attr in ['selected_pair', 'selected_timeframe', 'analysis_mode']:
                if hasattr(self, attr):
                    setattr(new_view, attr, getattr(self, attr))
            
            # Update the message with renewed view
            embed = discord.Embed(
                title="🔄 Interface Renewed",
                description=f"Interface automatically renewed (#{new_view.renewal_count})\nAll functions remain active.",
                color=discord.Color.blue()
            )
            
            try:
                if hasattr(self.original_interaction, 'edit_original_response'):
                    await self.original_interaction.edit_original_response(embed=embed, view=new_view)
                else:
                    # Fallback to followup if original response expired
                    await self.original_interaction.followup.send(embed=embed, view=new_view, ephemeral=True)
            except discord.HTTPException:
                # If interaction fully expired, send a new message
                if hasattr(self.original_interaction, 'channel'):
                    await self.original_interaction.channel.send(embed=embed, view=new_view)
            
            # Register the new view in the global tracker
            PersistentInteractionManager.register_view(new_view)
            
        except Exception as e:
            print(f"Error renewing view: {e}")
            await self.cleanup()
    
    async def cleanup(self):
        """Clean up resources when view truly expires"""
        if self.renewal_task and not self.renewal_task.done():
            self.renewal_task.cancel()
        
        # Remove from global tracker
        PersistentInteractionManager.unregister_view(self)

class PersistentRefreshButton(discord.ui.Button):
    """Button to manually refresh persistent interfaces"""
    
    def __init__(self):
        super().__init__(
            style=discord.ButtonStyle.secondary, 
            label="🔄 Refresh Interface",
            emoji="🔄"
        )
    
    async def callback(self, interaction: discord.Interaction):
        # Get the parent view
        view = self.view
        if hasattr(view, 'renew_view'):
            await view.renew_view()
            
            embed = discord.Embed(
                title="✅ Interface Refreshed",
                description="Interface has been manually refreshed and will continue to auto-renew.",
                color=discord.Color.green()
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)
        else:
            await interaction.response.send_message("Refresh not available for this interface.", ephemeral=True)

# Safe division and calculation functions to prevent division and scale errors
# Using safe_divide from safe_math_utils

def calculate_technical_indicators(df):
    """Calculate comprehensive technical indicators for the given DataFrame"""
    try:
        if df is None or len(df) < 20:
            return {}
        
        import ta
        
        # Fallback functions for optional modules
        def get_volume_profile_analysis(df):
            return {'volume_profile': None, 'poc': None, 'vah': None, 'val': None}
        
        # Import advanced analysis modules
        # Forex Factory sentiment analysis removed
        
        try:
            from advanced_volume_analysis import get_volume_profile_analysis as import_volume_analysis
            get_volume_profile_analysis = import_volume_analysis
        except ImportError:
            print("Advanced volume analysis module not available")
        
        indicators = {}
        
        # Calculate basic indicators using numpy for better compatibility
        close = df['close'].values
        high = df['high'].values
        low = df['low'].values
        
        # RSI calculation
        delta = np.diff(close)
        gain = np.where(delta > 0, delta, 0)
        loss = np.where(delta < 0, -delta, 0)
        
        if len(gain) >= 14:
            avg_gain = safe_mean(gain[:14])
            avg_loss = safe_mean(loss[:14])
            for i in range(14, len(gain)):
                avg_gain = (avg_gain * 13 + gain[i]) / 14
                avg_loss = (avg_loss * 13 + loss[i]) / 14
            
            rs = safe_divide(avg_gain, (avg_loss + 1e-10), 1.0)
            rsi = 100 - safe_divide(100, (1 + rs), 50)
            indicators['rsi'] = rsi
        else:
            indicators['rsi'] = 50
        
        # Simple Moving Averages
        if len(close) >= 20:
            indicators['sma_20'] = safe_mean(close[-20:], close[-1])
        else:
            indicators['sma_20'] = close[-1]
            
        if len(close) >= 50:
            indicators['sma_50'] = safe_mean(close[-50:], close[-1])
        else:
            indicators['sma_50'] = close[-1]
        
        # MACD calculation
        if len(close) >= 26:
            ema_12 = close[-1]  # Simplified EMA
            ema_26 = safe_mean(close[-26:], close[-1])
            macd = ema_12 - ema_26
            indicators['macd'] = macd
            indicators['macd_signal'] = macd * 0.9  # Simplified signal
            indicators['macd_histogram'] = macd - indicators['macd_signal']
        else:
            indicators['macd'] = 0
            indicators['macd_signal'] = 0
            indicators['macd_histogram'] = 0
        
        # Bollinger Bands
        if len(close) >= 20:
            sma = safe_mean(close[-20:], close[-1])
            std = safe_std(close[-20:], 0.001)
            indicators['bb_upper'] = sma + (2 * std)
            indicators['bb_middle'] = sma
            indicators['bb_lower'] = sma - (2 * std)
            indicators['bb_width'] = safe_divide(indicators['bb_upper'] - indicators['bb_lower'], indicators['bb_middle'], 0.04)
        else:
            indicators['bb_upper'] = close[-1] * 1.02
            indicators['bb_middle'] = close[-1]
            indicators['bb_lower'] = close[-1] * 0.98
            indicators['bb_width'] = 0.04
        
        # ATR calculation
        if len(high) >= 14:
            tr = np.maximum(high[1:] - low[1:], 
                           np.maximum(np.abs(high[1:] - close[:-1]), 
                                     np.abs(low[1:] - close[:-1])))
            atr = safe_mean(tr[-14:], high[-1] - low[-1])
            indicators['atr'] = atr
        else:
            indicators['atr'] = (high[-1] - low[-1])
        
        # Stochastic oscillator
        if len(high) >= 14:
            lowest_low = np.min(low[-14:])
            highest_high = np.max(high[-14:])
            range_val = highest_high - lowest_low
            k_percent = 100 * safe_divide(close[-1] - lowest_low, range_val, 0.5)
            indicators['stoch'] = k_percent
            indicators['stoch_k'] = k_percent
            indicators['stoch_d'] = k_percent * 0.9  # Simplified %D
        else:
            indicators['stoch'] = 50
            indicators['stoch_k'] = 50
            indicators['stoch_d'] = 50
        
        # Williams %R
        if len(high) >= 14:
            highest_high = np.max(high[-14:])
            lowest_low = np.min(low[-14:])
            range_val = highest_high - lowest_low
            williams_r = -100 * safe_divide(highest_high - close[-1], range_val, 0.5)
            indicators['williams_r'] = williams_r
        else:
            indicators['williams_r'] = -50
        
        # CCI calculation
        if len(close) >= 20:
            typical_price = (high + low + close) / 3
            sma_tp = safe_mean(typical_price[-20:], typical_price[-1])
            mad = safe_mean(np.abs(typical_price[-20:] - sma_tp), 0.001)
            cci = safe_divide(typical_price[-1] - sma_tp, 0.015 * mad, 0)
            indicators['cci'] = cci
        else:
            indicators['cci'] = 0
        
        # Volume indicators (if available)
        if 'volume' in df.columns and not df['volume'].isna().all():
            volume = df['volume'].values
            if len(volume) >= 20:
                indicators['volume_sma'] = safe_mean(volume[-20:], volume[-1])
                # Simplified MFI
                typical_price = (high + low + close) / 3
                money_flow = typical_price * volume
                price_diff = np.diff(typical_price[-15:])
                positive_mask = price_diff > 0
                negative_mask = price_diff < 0
                
                positive_flow = np.sum(money_flow[-14:][positive_mask]) if np.any(positive_mask) else 0
                negative_flow = np.sum(money_flow[-14:][negative_mask]) if np.any(negative_mask) else 0
                
                mfi_ratio = safe_divide(positive_flow, negative_flow, 1)
                mfi = 100 - safe_divide(100, 1 + mfi_ratio, 50)
                indicators['mfi'] = mfi
            else:
                indicators['volume_sma'] = volume[-1] if len(volume) > 0 else 0
                indicators['mfi'] = 50
        
        # ROC (Rate of Change)
        if len(close) >= 12:
            roc = safe_divide(close[-1] - close[-12], close[-12], 0) * 100
            indicators['roc'] = roc
        else:
            indicators['roc'] = 0
        
        # ADX (simplified)
        if len(high) >= 14:
            indicators['adx'] = min(float(abs(indicators['rsi'] - 50) * 2), 100.0)
        else:
            indicators['adx'] = 25
        
        return indicators
        
    except Exception as e:
        print(f"Error calculating technical indicators: {e}")
        return {}

def detect_market_structure(df):
    """Detect basic market structure patterns"""
    try:
        if df is None or len(df) < 30:
            return {'structure': 'Unknown', 'trend': 'Neutral', 'strength': 50}
        
        # Calculate recent price action
        recent_data = df.tail(20)
        close_prices = recent_data['close']
        
        # Determine trend using multiple timeframe analysis
        short_trend = 1 if close_prices.iloc[-1] > close_prices.iloc[-5] else -1
        medium_trend = 1 if close_prices.iloc[-1] > close_prices.iloc[-10] else -1
        long_trend = 1 if close_prices.iloc[-1] > close_prices.iloc[-15] else -1
        
        trend_score = short_trend + medium_trend + long_trend
        
        # Determine structure
        if trend_score >= 2:
            structure = 'Uptrend'
            trend = 'Bullish'
            strength = min(90, 60 + (trend_score * 10))
        elif trend_score <= -2:
            structure = 'Downtrend'
            trend = 'Bearish'
            strength = min(90, 60 + (abs(trend_score) * 10))
        else:
            structure = 'Sideways'
            trend = 'Neutral'
            strength = 50
        
        # Calculate volatility
        volatility = safe_divide(safe_std(close_prices), safe_mean(close_prices))
        
        return {
            'structure': structure,
            'trend': trend,
            'strength': strength,
            'volatility': volatility,
            'trend_score': trend_score
        }
        
    except Exception as e:
        print(f"Error detecting market structure: {e}")
        return {'structure': 'Unknown', 'trend': 'Neutral', 'strength': 50}

def calculate_ict_patterns(df):
    """Calculate essential ICT (Inner Circle Trader) patterns"""
    try:
        if df is None or len(df) < 30:
            return {'patterns': [], 'total_score': 0, 'bullish_score': 0, 'bearish_score': 0}
        
        patterns = []
        bullish_score = 0
        bearish_score = 0
        
        # Fair Value Gaps (FVG)
        fvg_patterns = detect_fair_value_gaps(df)
        if fvg_patterns:
            patterns.extend(fvg_patterns)
            for pattern in fvg_patterns:
                if pattern['type'] == 'bullish_fvg':
                    bullish_score += 2
                elif pattern['type'] == 'bearish_fvg':
                    bearish_score += 2
        
        # Order Blocks
        ob_patterns = detect_order_blocks(df)
        if ob_patterns:
            patterns.extend(ob_patterns)
            for pattern in ob_patterns:
                if pattern['type'] == 'bullish_ob':
                    bullish_score += 3
                elif pattern['type'] == 'bearish_ob':
                    bearish_score += 3
        
        # Liquidity Sweeps
        sweep_patterns = detect_liquidity_sweeps(df)
        if sweep_patterns:
            patterns.extend(sweep_patterns)
            for pattern in sweep_patterns:
                if pattern['type'] == 'buy_side_sweep':
                    bearish_score += 1  # Often bearish after sweep
                elif pattern['type'] == 'sell_side_sweep':
                    bullish_score += 1  # Often bullish after sweep
        
        total_score = bullish_score + bearish_score
        
        return {
            'patterns': patterns,
            'total_score': total_score,
            'bullish_score': bullish_score,
            'bearish_score': bearish_score,
            'bullish_percentage': safe_divide(bullish_score, max(total_score, 1), 0) * 100,
            'bearish_percentage': safe_divide(bearish_score, max(total_score, 1), 0) * 100,
            'neutral_percentage': max(0, 100 - (safe_divide(bullish_score + bearish_score, max(total_score, 1), 0) * 100))
        }
        
    except Exception as e:
        print(f"Error calculating ICT patterns: {e}")
        return {'patterns': [], 'total_score': 0, 'bullish_score': 0, 'bearish_score': 0}

def detect_fair_value_gaps(df):
    """Detect Fair Value Gaps in price data"""
    try:
        if df is None or len(df) < 5:
            return []
        
        patterns = []
        for i in range(2, len(df)):
            prev_candle = df.iloc[i-2]
            middle_candle = df.iloc[i-1] 
            current_candle = df.iloc[i]
            
            # Bullish FVG: gap between previous high and current low
            if (prev_candle['high'] < current_candle['low'] and 
                middle_candle['high'] < current_candle['low']):
                patterns.append({
                    'type': 'bullish_fvg',
                    'index': i,
                    'gap_low': prev_candle['high'],
                    'gap_high': current_candle['low'],
                    'strength': current_candle['low'] - prev_candle['high']
                })
            
            # Bearish FVG: gap between previous low and current high
            elif (prev_candle['low'] > current_candle['high'] and 
                  middle_candle['low'] > current_candle['high']):
                patterns.append({
                    'type': 'bearish_fvg',
                    'index': i,
                    'gap_low': current_candle['high'],
                    'gap_high': prev_candle['low'],
                    'strength': prev_candle['low'] - current_candle['high']
                })
        
        return patterns
    except Exception as e:
        print(f"Error detecting FVG: {e}")
        return []

def detect_order_blocks(df):
    """Detect Order Blocks - high volume areas with strong rejection"""
    try:
        if df is None or len(df) < 10:
            return []
        
        patterns = []
        for i in range(5, len(df)-1):
            current = df.iloc[i]
            
            # Look for strong rejection candles
            body_size = abs(current['close'] - current['open'])
            wick_size = max(current['high'] - max(current['open'], current['close']),
                           min(current['open'], current['close']) - current['low'])
            
            if wick_size > body_size * 2:  # Strong wick rejection
                if current['close'] > current['open']:  # Bullish rejection
                    patterns.append({
                        'type': 'bullish_ob',
                        'index': i,
                        'level': current['low'],
                        'strength': wick_size / body_size if body_size > 0 else 3
                    })
                else:  # Bearish rejection
                    patterns.append({
                        'type': 'bearish_ob',
                        'index': i,
                        'level': current['high'],
                        'strength': wick_size / body_size if body_size > 0 else 3
                    })
        
        return patterns
    except Exception as e:
        print(f"Error detecting order blocks: {e}")
        return []

def detect_liquidity_sweeps(df):
    """Detect liquidity sweeps at recent highs/lows"""
    try:
        if df is None or len(df) < 20:
            return []
        
        patterns = []
        recent_data = df.tail(20)
        
        # Find recent significant highs and lows
        highs = recent_data['high'].rolling(5, center=True, min_periods=1).max()
        lows = recent_data['low'].rolling(5, center=True, min_periods=1).min()
        
        current_price = df['close'].iloc[-1]
        
        # Check for sweep of recent high
        recent_high = highs.max()
        if current_price > recent_high * 1.0005:  # Small threshold for sweep
            patterns.append({
                'type': 'buy_side_sweep',
                'level': recent_high,
                'current_price': current_price
            })
        
        # Check for sweep of recent low
        recent_low = lows.min()
        if current_price < recent_low * 0.9995:  # Small threshold for sweep
            patterns.append({
                'type': 'sell_side_sweep',
                'level': recent_low,
                'current_price': current_price
            })
        
        return patterns
    except Exception as e:
        print(f"Error detecting liquidity sweeps: {e}")
        return []



