def calculate_risk_adjusted_metrics(df, signal, confidence, pair="EUR/USD"):
    """Calculate comprehensive risk-adjusted scoring metrics for signals."""
    try:
        if df is None or df.empty or len(df) < 20:
            return {
                'volatility_adjusted_score': confidence * 0.8,
                'sharpe_ratio': 0,
                'max_drawdown': 15,
                'risk_reward_ratio': 1.0,
                'volatility_percentile': 50,
                'risk_adjusted_confidence': confidence * 0.8,
                'risk_grade': 'C'
            }
        
        # Calculate price returns
        returns = df['close'].pct_change().dropna()
        if len(returns) < 10:
            return {'risk_adjusted_confidence': confidence * 0.8, 'risk_grade': 'C'}
        
        # 1. Volatility Analysis
        volatility = safe_std(returns) * np.sqrt(252)  # Annualized volatility
        recent_volatility = safe_std(returns.tail(20)) * np.sqrt(252)
        
        # Calculate volatility percentile (0-100)
        rolling_vol = returns.rolling(20, min_periods=1).std().dropna()
        if len(rolling_vol) > 0:
            current_vol_percentile = safe_mean((rolling_vol.iloc[-1] > rolling_vol).astype(int)) * 100
        else:
            current_vol_percentile = 50
        
        # 2. Maximum Drawdown Calculation
        cumulative_returns = (1 + returns).cumprod()
        running_max = cumulative_returns.expanding().max()
        drawdown = safe_divide(cumulative_returns - running_max, running_max, 0)
        if hasattr(drawdown, 'min'):
            max_drawdown = abs(drawdown.min()) * 100  # Convert to percentage
        else:
            max_drawdown = abs(drawdown) * 100 if drawdown < 0 else 0
        
        # 3. Sharpe Ratio (annualized, assuming 0% risk-free rate)
        if volatility > 0 and len(returns) > 0:
            sharpe_ratio = safe_divide(safe_mean(returns) * 252, volatility)
        else:
            sharpe_ratio = 0
        
        # 4. Risk-Reward Analysis
        # Estimate potential risk/reward based on recent price action
        atr = calculate_atr_simple(df)
        current_price = df['close'].iloc[-1]
        
        # Dynamic stop loss based on volatility and ATR
        if 'JPY' in pair:
            risk_multiplier = 1.2  # JPY pairs typically more volatile
        else:
            risk_multiplier = 1.0
            
        estimated_stop_loss = atr * 1.5 * risk_multiplier
        estimated_take_profit = atr * 2.5 * risk_multiplier
        risk_reward_ratio = safe_divide(estimated_take_profit, max(estimated_stop_loss, atr * 0.5), 1.0)
        
        # 5. Volatility Adjusted Score
        # Penalize high volatility, reward moderate volatility
        if current_vol_percentile > 80:  # Very high volatility
            volatility_multiplier = 0.75
        elif current_vol_percentile > 60:  # High volatility
            volatility_multiplier = 0.85
        elif current_vol_percentile < 20:  # Very low volatility
            volatility_multiplier = 0.90  # Also penalize very low vol
        else:  # Moderate volatility (sweet spot)
            volatility_multiplier = 1.0
        
        # 6. Maximum Drawdown Penalty
        if max_drawdown > 20:  # Very high drawdown risk
            drawdown_multiplier = 0.70
        elif max_drawdown > 15:  # High drawdown risk
            drawdown_multiplier = 0.80
        elif max_drawdown > 10:  # Moderate drawdown risk
            drawdown_multiplier = 0.90
        else:  # Low drawdown risk
            drawdown_multiplier = 1.0
        
        # 7. Sharpe Ratio Bonus/Penalty
        if sharpe_ratio > 1.0:  # Excellent risk-adjusted returns
            sharpe_multiplier = 1.1
        elif sharpe_ratio > 0.5:  # Good risk-adjusted returns
            sharpe_multiplier = 1.05
        elif sharpe_ratio < -0.5:  # Poor risk-adjusted returns
            sharpe_multiplier = 0.80
        else:  # Neutral
            sharpe_multiplier = 1.0
        
        # 8. Risk-Reward Ratio Adjustment
        if risk_reward_ratio > 2.0:  # Excellent R:R
            rr_multiplier = 1.08
        elif risk_reward_ratio > 1.5:  # Good R:R
            rr_multiplier = 1.04
        elif risk_reward_ratio < 1.0:  # Poor R:R
            rr_multiplier = 0.85
        else:  # Acceptable R:R
            rr_multiplier = 1.0
        
        # 9. Final Risk-Adjusted Confidence
        risk_adjusted_confidence = (
            confidence * 
            volatility_multiplier * 
            drawdown_multiplier * 
            sharpe_multiplier * 
            rr_multiplier
        )
        
        # Cap the final score
        risk_adjusted_confidence = max(45, min(95, risk_adjusted_confidence))
        
        # 10. Risk Grade Assignment
        if risk_adjusted_confidence >= 80 and max_drawdown < 10 and sharpe_ratio > 0.5:
            risk_grade = 'A+'
        elif risk_adjusted_confidence >= 75 and max_drawdown < 15:
            risk_grade = 'A'
        elif risk_adjusted_confidence >= 70:
            risk_grade = 'B+'
        elif risk_adjusted_confidence >= 65:
            risk_grade = 'B'
        elif risk_adjusted_confidence >= 60:
            risk_grade = 'C+'
        else:
            risk_grade = 'C'
        
        return {
            'volatility_adjusted_score': round(confidence * volatility_multiplier, 1),
            'sharpe_ratio': round(sharpe_ratio, 2),
            'max_drawdown': round(max_drawdown, 1),
            'risk_reward_ratio': round(risk_reward_ratio, 2),
            'volatility_percentile': round(current_vol_percentile, 1),
            'risk_adjusted_confidence': round(risk_adjusted_confidence, 1),
            'risk_grade': risk_grade,
            'volatility_multiplier': round(volatility_multiplier, 2),
            'drawdown_multiplier': round(drawdown_multiplier, 2),
            'sharpe_multiplier': round(sharpe_multiplier, 2),
            'rr_multiplier': round(rr_multiplier, 2),
            'estimated_stop_loss_pips': round(estimated_stop_loss * 10000, 1),
            'estimated_take_profit_pips': round(estimated_take_profit * 10000, 1)
        }
        
    except Exception as e:
        print(f"Error calculating risk metrics for {pair}: {e}")
        return {
            'risk_adjusted_confidence': confidence * 0.8,
            'risk_grade': 'C',
            'volatility_adjusted_score': confidence * 0.8
        }

def calculate_atr_simple(df, period=14):
    """Simple ATR calculation for risk assessment."""
    try:
        if len(df) < period:
            return safe_mean(df['high'] - df['low'])
        
        high_low = df['high'] - df['low']
        high_close = abs(df['high'] - df['close'].shift())
        low_close = abs(df['low'] - df['close'].shift())
        
        tr = pd.concat([high_low, high_close, low_close], axis=1).max(axis=1)
        atr_series = tr.rolling(period, min_periods=1).mean()
        atr = atr_series.iloc[-1] if len(atr_series) > 0 else None
        
        return atr if atr is not None and not pd.isna(atr) else safe_mean(df['high'] - df['low'])
    except:
        return safe_mean(df['high'] - df['low'])



def calculate_entry_confidence(df, indicators, main_signal, pair):
    """Enhanced entry confidence calculation optimized for 1-minute accuracy."""
    try:
        confidence_data = {
            'confidence': 55,
            'quality': 'Moderate',
            'timing_score': 50,
            'signal_strength': 'Weak',
            'entry_factors': []
        }
        
        if df is None or df.empty or len(df) < 15:
            return confidence_data
        
        # Enhanced momentum analysis
        rsi = indicators.get('rsi', 50)
        macd_line = indicators.get('macd', 0)
        macd_signal = indicators.get('macd_signal', 0)
        macd_histogram = indicators.get('macd_histogram', 0)
        
        # Base timing score
        timing_score = 45  # Start lower to be more selective
        entry_factors = []
        
        # 1. Enhanced RSI Analysis
        if main_signal == 'BUY':
            # Bullish RSI conditions
            if 25 <= rsi <= 40:  # Oversold but recovering
                timing_score += 20
                entry_factors.append(f"RSI oversold recovery: {rsi:.1f}")
            elif 40 < rsi <= 60:  # Healthy bullish zone
                timing_score += 15
                entry_factors.append(f"RSI bullish zone: {rsi:.1f}")
            elif 60 < rsi <= 75:  # Strong but not extreme
                timing_score += 10
                entry_factors.append(f"RSI strong: {rsi:.1f}")
            elif rsi > 80:  # Overbought - risky
                timing_score -= 5
                entry_factors.append(f"RSI overbought risk: {rsi:.1f}")
                
        elif main_signal == 'SELL':
            # Bearish RSI conditions
            if 60 <= rsi <= 75:  # Overbought but starting to fall
                timing_score += 20
                entry_factors.append(f"RSI overbought decline: {rsi:.1f}")
            elif 40 <= rsi < 60:  # Healthy bearish zone
                timing_score += 15
                entry_factors.append(f"RSI bearish zone: {rsi:.1f}")
            elif 25 <= rsi < 40:  # Strong but not extreme
                timing_score += 10
                entry_factors.append(f"RSI strong: {rsi:.1f}")
            elif rsi < 20:  # Oversold - risky
                timing_score -= 5
                entry_factors.append(f"RSI oversold risk: {rsi:.1f}")
        
        # 2. Enhanced MACD Analysis with Histogram
        macd_diff = macd_line - macd_signal
        
        if main_signal == 'BUY':
            if macd_diff > 0 and macd_histogram > 0:  # MACD bullish and accelerating
                if abs(macd_diff) > 0.0015:
                    timing_score += 25
                    entry_factors.append("Strong MACD bullish acceleration")
                elif abs(macd_diff) > 0.0008:
                    timing_score += 15
                    entry_factors.append("MACD bullish momentum")
                else:
                    timing_score += 8
                    entry_factors.append("MACD bullish alignment")
            elif macd_diff > 0 and macd_histogram <= 0:  # Bullish but slowing
                timing_score += 5
                entry_factors.append("MACD bullish but slowing")
                
        elif main_signal == 'SELL':
            if macd_diff < 0 and macd_histogram < 0:  # MACD bearish and accelerating
                if abs(macd_diff) > 0.0015:
                    timing_score += 25
                    entry_factors.append("Strong MACD bearish acceleration")
                elif abs(macd_diff) > 0.0008:
                    timing_score += 15
                    entry_factors.append("MACD bearish momentum")
                else:
                    timing_score += 8
                    entry_factors.append("MACD bearish alignment")
            elif macd_diff < 0 and macd_histogram >= 0:  # Bearish but slowing
                timing_score += 5
                entry_factors.append("MACD bearish but slowing")
        
        # 3. Enhanced Price Action Analysis
        recent_candles = df.tail(5)
        if len(recent_candles) >= 5:
            # Calculate candle strength and patterns
            current_candle = recent_candles.iloc[-1]
            prev_candle = recent_candles.iloc[-2]
            
            # Candle body strength
            body_size = abs(current_candle['close'] - current_candle['open'])
            candle_range = current_candle['high'] - current_candle['low']
            body_strength = safe_divide(body_size, candle_range, 0)
            
            if main_signal == 'BUY':
                # Bullish candle patterns
                if (current_candle['close'] > current_candle['open'] and 
                    body_strength > 0.6):  # Strong bullish candle
                    timing_score += 15
                    entry_factors.append("Strong bullish candle")
                elif current_candle['close'] > current_candle['open']:
                    timing_score += 8
                    entry_factors.append("Bullish candle")
                
                # Price progression
                if (current_candle['close'] > prev_candle['close'] and
                    current_candle['high'] > prev_candle['high']):
                    timing_score += 10
                    entry_factors.append("Bullish price progression")
                    
            elif main_signal == 'SELL':
                # Bearish candle patterns
                if (current_candle['close'] < current_candle['open'] and 
                    body_strength > 0.6):  # Strong bearish candle
                    timing_score += 15
                    entry_factors.append("Strong bearish candle")
                elif current_candle['close'] < current_candle['open']:
                    timing_score += 8
                    entry_factors.append("Bearish candle")
                
                # Price progression
                if (current_candle['close'] < prev_candle['close'] and
                    current_candle['low'] < prev_candle['low']):
                    timing_score += 10
                    entry_factors.append("Bearish price progression")
        
        # 4. Momentum Consistency Check
        if len(recent_candles) >= 4:
            closes = recent_candles['close'].values
            price_changes = np.diff(closes)
            
            if main_signal == 'BUY':
                bullish_moves = np.sum(price_changes > 0)
                if bullish_moves >= 3:  # 3 out of 4 moves bullish
                    timing_score += 12
                    entry_factors.append("Strong bullish consistency")
                elif bullish_moves >= 2:
                    timing_score += 6
                    entry_factors.append("Good bullish trend")
                    
            elif main_signal == 'SELL':
                bearish_moves = np.sum(price_changes < 0)
                if bearish_moves >= 3:  # 3 out of 4 moves bearish
                    timing_score += 12
                    entry_factors.append("Strong bearish consistency")
                elif bearish_moves >= 2:
                    timing_score += 6
                    entry_factors.append("Good bearish trend")
        
        # 5. Volatility and Volume Proxy Analysis
        if len(df) >= 20:
            # Calculate volume proxy
            body_sizes = abs(df['close'] - df['open'])
            ranges = df['high'] - df['low']
            volume_proxy = body_sizes + (ranges - body_sizes) * 0.2
            
            recent_volume = safe_mean(volume_proxy.tail(3), 0.001)
            avg_volume = safe_mean(volume_proxy.tail(15), 0.001)
            
            if recent_volume > avg_volume * 1.25:
                timing_score += 12
                entry_factors.append("High volume confirmation")
            elif recent_volume > avg_volume * 1.1:
                timing_score += 6
                entry_factors.append("Volume increase")
            
            # Volatility check
            recent_volatility = safe_mean(ranges.tail(5), 0.001)
            avg_volatility = safe_mean(ranges.tail(20), 0.001)
            
            if 1.1 <= safe_divide(recent_volatility, avg_volatility, 1.0) <= 1.8:
                timing_score += 8
                entry_factors.append("Optimal volatility expansion")
            elif safe_divide(recent_volatility, avg_volatility, 1.0) > 2.5:
                timing_score -= 8
                entry_factors.append("Excessive volatility risk")
        
        # 6. Support/Resistance Proximity (1-minute specific)
        try:
            current_price = df['close'].iloc[-1]
            high_20 = df['high'].tail(20).max()
            low_20 = df['low'].tail(20).min()
            range_20 = high_20 - low_20
            
            # Check proximity to key levels
            distance_to_high = safe_divide(high_20 - current_price, range_20, 0.5)
            distance_to_low = safe_divide(current_price - low_20, range_20, 0.5)
            
            if main_signal == 'BUY' and distance_to_low < 0.25:  # Near support
                timing_score += 10
                entry_factors.append("Near support level")
            elif main_signal == 'SELL' and distance_to_high < 0.25:  # Near resistance
                timing_score += 10
                entry_factors.append("Near resistance level")
            elif main_signal == 'BUY' and distance_to_high < 0.15:  # Too close to resistance
                timing_score -= 8
                entry_factors.append("Too close to resistance")
            elif main_signal == 'SELL' and distance_to_low < 0.15:  # Too close to support
                timing_score -= 8
                entry_factors.append("Too close to support")
        except Exception:
            pass
        
        # Convert timing score to confidence with enhanced scaling
        entry_confidence = max(50, min(88, 45 + (timing_score - 45) * 0.5))
        
        # Signal strength assessment
        if timing_score >= 90:
            signal_strength = 'Exceptional'
            quality = 'Excellent'
        elif timing_score >= 75:
            signal_strength = 'Strong'
            quality = 'Very Good'
        elif timing_score >= 65:
            signal_strength = 'Good'
            quality = 'Good'
        elif timing_score >= 55:
            signal_strength = 'Moderate'
            quality = 'Moderate'
        elif timing_score >= 45:
            signal_strength = 'Weak'
            quality = 'Poor'
        else:
            signal_strength = 'Very Weak'
            quality = 'Very Poor'
        
        confidence_data.update({
            'confidence': round(entry_confidence, 1),
            'quality': quality,
            'timing_score': round(timing_score, 1),
            'signal_strength': signal_strength,
            'entry_factors': entry_factors
        })
        
        return confidence_data
        
    except Exception as e:
        print(f"Error in enhanced entry confidence calculation: {e}")
        return {
            'confidence': 55, 
            'quality': 'Moderate', 
            'timing_score': 50,
            'signal_strength': 'Weak',
            'entry_factors': ['Error in calculation']
        }

