        rsi_7_prev = data['rsi_7'].iloc[-2] if len(data) > 1 else rsi_7
        
        # 2. Ultra-fast RSI (5-period) for momentum confirmation
        data['rsi_5'] = calculate_rsi(data['close'], period=5)
        rsi_5 = data['rsi_5'].iloc[-1]
        
        # 3. Fast Stochastic (5,3,3) - much more responsive than default (14,3,3)
