        # Use safe rolling mean for stochastic D
        stoch_k_values = data['stoch_k_fast'].fillna(50)
        data['stoch_d_fast'] = stoch_k_values.rolling(3, min_periods=1).mean().fillna(50)
        stoch_k = data['stoch_k_fast'].iloc[-1]
