def calculate_timeframe_alignment(main_signal_data, entry_signal_data):
    """Calculate alignment score between analysis and entry timeframes."""
    try:
        alignment_score = 50  # Base score
        
        # Signal direction alignment
        if main_signal_data['signal'] != 'NEUTRAL' and entry_signal_data.get('timing_score', 50) > 60:
            alignment_score += 20
        
        # Confidence alignment
        main_conf = main_signal_data['confidence']
        entry_conf = entry_signal_data['confidence']
        
        conf_diff = abs(main_conf - entry_conf)
        if conf_diff < 5:  # Very close confidence
            alignment_score += 15
        elif conf_diff < 10:  # Close confidence
            alignment_score += 10
        elif conf_diff > 20:  # Very different confidence
            alignment_score -= 10
        
        # Quality alignment
        entry_quality = entry_signal_data.get('quality', 'Moderate')
        if entry_quality in ['Excellent', 'Good']:
            alignment_score += 10
        elif entry_quality == 'Poor':
            alignment_score -= 15
        
        return max(0, min(100, alignment_score))
        
    except Exception as e:
        print(f"Error calculating timeframe alignment: {e}")
        return 50

def cleanup_memory():
    """Enhanced memory cleanup with better performance"""
    # Clear matplotlib figures first
    try:
        import matplotlib.pyplot as plt
        plt.close('all')
    except:
        pass
    
    # Clear plotly figures
    try:
        import plotly.io as pio
        pio.renderers.default = None
    except:
        pass
    
    # Targeted cleanup of large objects
    import sys
    for obj_name in list(sys.modules.keys()):
        if obj_name.startswith('pandas') or obj_name.startswith('numpy'):
            continue  # Keep essential modules
    
    # Force garbage collection
    collected = gc.collect()
    
    # Additional cleanup for circular references
    if collected > 0:
        gc.collect()  # Second pass for nested references
    
    return collected

def get_memory_usage():
    """Get current memory usage statistics"""
    try:
        process = psutil.Process()
        memory_info = process.memory_info()
        return {
            'rss': memory_info.rss / 1024 / 1024,  # MB
            'vms': memory_info.vms / 1024 / 1024,  # MB
            'percent': process.memory_percent()
        }
    except:
        return {'rss': 0, 'vms': 0, 'percent': 0}

def should_cleanup_memory():
    """Check if memory cleanup is needed"""
    memory = get_memory_usage()
    return memory['percent'] > 80 or memory['rss'] > 400  # Cleanup if >80% or >400MB

def optimize_dataframe_memory(df):
    """Optimize DataFrame memory usage by downcasting numeric types"""
    if df is None or df.empty:
        return df
    
    try:
        # Create a copy to avoid modifying original
        optimized_df = df.copy()
        
        # Downcast numeric columns
        for col in optimized_df.select_dtypes(include=['float64']).columns:
            optimized_df[col] = pd.to_numeric(optimized_df[col], downcast='float')
        
        for col in optimized_df.select_dtypes(include=['int64']).columns:
            optimized_df[col] = pd.to_numeric(optimized_df[col], downcast='integer')
        
        # Convert object columns to category if they have few unique values
        for col in optimized_df.select_dtypes(include=['object']).columns:
            if optimized_df[col].nunique() / len(optimized_df) < 0.5:
                optimized_df[col] = optimized_df[col].astype('category')
        
        return optimized_df
    except Exception as e:
        print(f"Memory optimization error: {e}")
        return df

# Caching functions removed for real-time accuracy

def check_rate_limit(user_id):
    """Check if user has exceeded rate limits"""
    current_time = time.time()
    user_requests = USER_REQUEST_LIMITS[user_id]
    
    # Remove requests older than 1 minute
    user_requests[:] = [req_time for req_time in user_requests if current_time - req_time < 60]
    
    # Check limits based on user type
    limit = PREMIUM_LIMIT if user_id in PREMIUM_USERS else MAX_REQUESTS_PER_MINUTE
    
    if len(user_requests) >= limit:
        return False, f"Rate limit exceeded. You can make {limit} requests per minute."
    
    # Add current request
    user_requests.append(current_time)
    return True, ""

