def assess_market_condition(analysis):
    """Assess market condition for delay optimization"""
    try:
        if not analysis or 'error' in analysis:
            return 'unknown'
        
        volatility = analysis.get('volatility_regime', 'normal')
        confidence = analysis.get('confidence', 50)
        signal_score = analysis.get('signal_score', 0)
        
        if volatility == 'high' and confidence >= 75:
            return 'trending_high_confidence'
        elif volatility == 'high' and confidence < 65:
            return 'volatile_uncertain'
        elif signal_score >= 70:
            return 'strong_signal'
        elif signal_score <= 40:
            return 'weak_signal'
        else:
            return 'neutral'
            
    except Exception:
        return 'unknown'

def calculate_delay_optimization_score(analysis):
    """Calculate optimization score for delayed data handling"""
    try:
        if not analysis or 'error' in analysis:
            return 0
        
        score = 0
        
        # Trend strength contributes to better delay handling
        if analysis.get('trend') == 'bullish' or analysis.get('trend') == 'bearish':
            score += 20
        
        # Signal strength
        signal_score = analysis.get('signal_score', 0)
        score += min(signal_score * 0.3, 25)
        
        # RSI in optimal ranges
        rsi = analysis.get('rsi', 50)
        if 35 <= rsi <= 65:
            score += 15
        elif 25 <= rsi <= 35 or 65 <= rsi <= 75:
            score += 10
        
        # MACD confirmation
        macd = analysis.get('macd', 0)
        if abs(macd) > 0.0001:  # Significant MACD signal
            score += 10
        
        # Session optimization
        if analysis.get('delay_compensated'):
            score += 15
        
        # Volatility penalty for delayed data
        if analysis.get('volatility_regime') == 'high':
            score -= 10
        
        return max(min(score, 100), 0)
        
    except Exception:
        return 50

