class CommandLockView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=300)
    
    @discord.ui.button(label="Toggle Signal Commands", style=discord.ButtonStyle.primary)
    async def toggle_signal(self, interaction: discord.Interaction, button: discord.ui.Button):
        command_locks['signal'] = not command_locks['signal']
        status = "disabled" if command_locks['signal'] else "enabled"
        bot_stats['admin_actions'].append(f"Signal commands {status} by {interaction.user}")
        
        embed = discord.Embed(
            title=f"🔒 Signal Commands {status.title()}",
            description=f"Signal commands are now **{status}**",
            color=discord.Color.red() if command_locks['signal'] else discord.Color.green()
        )
        await interaction.response.send_message(embed=embed, ephemeral=True)
    
    @discord.ui.button(label="Toggle All Commands", style=discord.ButtonStyle.danger)
    async def toggle_all(self, interaction: discord.Interaction, button: discord.ui.Button):
        # Lock all commands except help, about, and profile
        lockable_commands = ['signal', 'pairs', 'settings', 'crypto', 'education', 'alerts', 'ping', 'authorization', 'blacklist']
        all_disabled = all(command_locks[key] for key in lockable_commands)
        new_state = not all_disabled
        
        for cmd in lockable_commands:
            command_locks[cmd] = new_state
        
        status = "disabled" if new_state else "enabled"
        bot_stats['admin_actions'].append(f"All commands {status} by {interaction.user}")
        
        embed = discord.Embed(
            title=f"🔒 All Commands {status.title()}",
            description=f"All user commands are now **{status}**\n\n**Always Available:** help, about, profile",
            color=discord.Color.red() if new_state else discord.Color.green()
        )
        await interaction.response.send_message(embed=embed, ephemeral=True)
    
    @discord.ui.button(label="← Back to Dashboard", style=discord.ButtonStyle.secondary)
    async def back_to_dashboard(self, interaction: discord.Interaction, button: discord.ui.Button):
        embed = discord.Embed(
            title="🛠️ Admin Dashboard",
            description="Select a category to manage bot functions",
            color=discord.Color.gold()
        )
        await interaction.response.edit_message(embed=embed, view=AdminDashboardView())

