class AddGuildModal(discord.ui.Modal, title="Add Guild"):
    def __init__(self):
        super().__init__()
        
    guild_id = discord.ui.TextInput(
        label="Guild ID",
        placeholder="Enter the guild ID to allow",
        required=True,
        max_length=20
    )
    
    async def on_submit(self, interaction: discord.Interaction):
        try:
            guild_id = str(int(self.guild_id.value.strip()))
            user_data = load_user_data()
            
            if 'response_targeting' not in user_data:
                user_data['response_targeting'] = {
                    'mode': 'global',
                    'allowed_guilds': [],
                    'allowed_channels': {}
                }
            
            if guild_id not in user_data['response_targeting']['allowed_guilds']:
                user_data['response_targeting']['allowed_guilds'].append(guild_id)
                save_user_data(user_data)
                
                embed = discord.Embed(
                    title="✅ Guild Added",
                    description=f"Guild ID `{guild_id}` has been added to allowed guilds",
                    color=discord.Color.green()
                )
            else:
                embed = discord.Embed(
                    title="⚠️ Guild Already Added",
                    description=f"Guild ID `{guild_id}` is already in the allowed list",
                    color=discord.Color.orange()
                )
            
            await interaction.response.send_message(embed=embed, ephemeral=True)
            
        except ValueError:
            embed = discord.Embed(
                title="❌ Invalid Guild ID",
                description="Please enter a valid numeric guild ID",
                color=discord.Color.red()
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)

class RemoveGuildModal(discord.ui.Modal, title="Remove Guild"):
    def __init__(self):
        super().__init__()
        
    guild_id = discord.ui.TextInput(
        label="Guild ID",
        placeholder="Enter the guild ID to remove",
        required=True,
        max_length=20
    )
    
    async def on_submit(self, interaction: discord.Interaction):
        try:
            guild_id = str(int(self.guild_id.value.strip()))
            user_data = load_user_data()
            
            if 'response_targeting' in user_data and guild_id in user_data['response_targeting']['allowed_guilds']:
                user_data['response_targeting']['allowed_guilds'].remove(guild_id)
                # Also remove any channel configurations for this guild
                if guild_id in user_data['response_targeting'].get('allowed_channels', {}):
                    del user_data['response_targeting']['allowed_channels'][guild_id]
                save_user_data(user_data)
                
                embed = discord.Embed(
                    title="✅ Guild Removed",
                    description=f"Guild ID `{guild_id}` has been removed from allowed guilds",
                    color=discord.Color.green()
                )
            else:
                embed = discord.Embed(
                    title="⚠️ Guild Not Found",
                    description=f"Guild ID `{guild_id}` is not in the allowed list",
                    color=discord.Color.orange()
                )
            
            await interaction.response.send_message(embed=embed, ephemeral=True)
            
        except ValueError:
            embed = discord.Embed(
                title="❌ Invalid Guild ID",
                description="Please enter a valid numeric guild ID",
                color=discord.Color.red()
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)

class SetGuildChannelsModal(discord.ui.Modal, title="Set Guild Channels"):
    def __init__(self):
        super().__init__()
        
    guild_id = discord.ui.TextInput(
        label="Guild ID",
        placeholder="Enter the guild ID",
        required=True,
        max_length=20
    )
    
    channel_names = discord.ui.TextInput(
        label="Channel Names (comma separated)",
        placeholder="general, trading-signals, bot-commands",
        required=False,
        max_length=200,
        style=discord.TextStyle.paragraph
    )
    
    async def on_submit(self, interaction: discord.Interaction):
        try:
            guild_id = str(int(self.guild_id.value.strip()))
            user_data = load_user_data()
            
            if 'response_targeting' not in user_data:
                user_data['response_targeting'] = {
                    'mode': 'global',
                    'allowed_guilds': [],
                    'allowed_channels': {}
                }
            
            # Check if guild is in allowed list
            if guild_id not in user_data['response_targeting']['allowed_guilds']:
                embed = discord.Embed(
                    title="⚠️ Guild Not Allowed",
                    description=f"Guild ID `{guild_id}` must be added to allowed guilds first",
                    color=discord.Color.orange()
                )
                await interaction.response.send_message(embed=embed, ephemeral=True)
                return
            
            # Process channel names
            if self.channel_names.value.strip():
                channels = [ch.strip() for ch in self.channel_names.value.split(',') if ch.strip()]
                user_data['response_targeting']['allowed_channels'][guild_id] = channels
                
                embed = discord.Embed(
                    title="✅ Channels Set",
                    description=f"Channels for guild `{guild_id}` have been configured",
                    color=discord.Color.green()
                )
                embed.add_field(name="Channels", value=", ".join(channels), inline=False)
            else:
                # Remove channel restrictions for this guild
                if guild_id in user_data['response_targeting']['allowed_channels']:
                    del user_data['response_targeting']['allowed_channels'][guild_id]
                
                embed = discord.Embed(
                    title="✅ Channels Cleared",
                    description=f"Channel restrictions removed for guild `{guild_id}`\nBot will respond in all channels in this guild",
                    color=discord.Color.green()
                )
            
            save_user_data(user_data)
            await interaction.response.send_message(embed=embed, ephemeral=True)
            
        except ValueError:
            embed = discord.Embed(
                title="❌ Invalid Guild ID",
                description="Please enter a valid numeric guild ID",
                color=discord.Color.red()
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)

