        user_data = load_user_data()
        fingerprints = user_data.get('user_fingerprints', {})
        
        # Group by fingerprint
        fingerprint_groups = defaultdict(list)
        for uid, fp in fingerprints.items():
            fingerprint_groups[fp].append(uid)
        
        # Find groups with multiple accounts
        linked_groups = {fp: uids for fp, uids in fingerprint_groups.items() if len(uids) > 1}
        
        embed = discord.Embed(
            title="👥 Linked Account Groups",
            color=discord.Color.purple()
        )
        
        if linked_groups:
            for i, (fp, uids) in enumerate(list(linked_groups.items())[:5]):
                users_text = "\n".join([f"• <@{uid}>" for uid in uids])
                embed.add_field(name=f"Group {i+1} ({fp[:8]}...)", value=users_text, inline=False)
        else:
            embed.add_field(name="Status", value="No linked accounts detected", inline=False)
        
        await interaction.response.send_message(embed=embed, ephemeral=True)
    
