# ===== SECURITY MIDDLEWARE =====

async def handle_access_denial(interaction, error_msg):
    """Handle access denial by either initiating verification flow or showing error"""
    if "VERIFICATION_REQUIRED" in error_msg:
        await initiate_verification_flow(interaction)
    else:
        embed = discord.Embed(title="🚫 Access Denied", description=error_msg, color=discord.Color.red())
        await interaction.response.send_message(embed=embed, ephemeral=True)

def check_response_targeting(interaction: discord.Interaction) -> bool:
    """
    Check if the bot should respond based on response targeting configuration
    
    Args:
        interaction: Discord interaction object
        
    Returns:
        True if bot should respond, False otherwise
    """
    user_data = load_user_data()
    config = user_data.get('response_targeting', {
        'mode': 'global',
        'allowed_guilds': [],
        'allowed_channels': {}
    })
    
    # Global mode - respond everywhere
    if config['mode'] == 'global':
        return True
    
    # Guild specific mode
    guild_id = str(interaction.guild_id) if interaction.guild else None
    if not guild_id:
        return False  # No guild context
    
    # Check if guild is allowed
    if guild_id not in config['allowed_guilds']:
        return False
    
    # Check if specific channels are configured for this guild
    if guild_id in config['allowed_channels']:
        allowed_channels = config['allowed_channels'][guild_id]
        if allowed_channels:  # If specific channels are configured
            channel_name = interaction.channel.name if interaction.channel else None
            if channel_name not in allowed_channels:
                return False
    
    return True

def security_check(user_id, command_name, guild_id=None):
    """Comprehensive security check for all commands"""
    user_data = load_user_data()
    
    # Check if user is blacklisted
    if str(user_id) in user_data.get('blacklisted_users', []):
        return False, "You are blacklisted from using this bot."
    
    # Check if command category is locked - only allow help, about, and profile when locked
    if command_locks.get(command_name, False):
        allowed_commands = ['help', 'about', 'profile']
        if command_name not in allowed_commands:
            return False, f"The {command_name} commands are currently disabled by administrators."
    
    # Check if user has agreed to terms
    if not check_user_agreement(user_id):
        return False, "VERIFICATION_REQUIRED: You must agree to our privacy policy and terms of service first."
    
    # Check if user is verified
    verification = user_data.get('user_verification', {}).get(str(user_id), {})
    if not verification.get('verified', False):
        return False, "VERIFICATION_REQUIRED: You must complete captcha verification first."
    
    # Check for rapid command usage
    is_rapid, violation_count = check_rapid_commands(user_id)
    if is_rapid:
        return False, f"Too many commands in quick succession. Slow down! (Violation #{violation_count})"
    
    # Check cooldowns for signal commands
    if command_name == 'signal':
        on_cooldown, remaining = check_cooldown(user_id)
        if on_cooldown:
            return False, f"Signal cooldown active. Please wait {remaining} seconds before requesting another signal."
    
    # Check for alt accounts
    is_alt, linked_accounts = check_alt_accounts(user_id)
    if is_alt:
        return False, f"Multiple accounts detected. Only one account per user is allowed."
    
    # Create user profile and fingerprint
    try:
        username = f"User{user_id}"
        create_user_profile(user_id, username, str(guild_id) if guild_id else None)
        
        # Store fingerprint
        user_data = load_user_data()
        if 'user_fingerprints' not in user_data:
            user_data['user_fingerprints'] = {}
        user_data['user_fingerprints'][str(user_id)] = create_user_fingerprint(user_id, guild_id)
        save_user_data(user_data)
    except Exception as e:
        print(f"Error creating user profile: {e}")
    
    return True, "Security check passed"



async def initiate_verification_flow(interaction):
    """Start the verification flow with privacy policy and terms"""
    user_id = interaction.user.id
    
    # Show privacy policy first
    privacy_view = PrivacyPolicyView(user_id)
    content = privacy_view.get_privacy_content(1)
    embed = discord.Embed(
        title=content["title"],
        description=content["description"],
        color=discord.Color.blue()
    )
    embed.set_footer(text=content["footer"])
    
    await interaction.response.send_message(embed=embed, view=privacy_view, ephemeral=True)



