api_reset_times = {key: datetime.now(timezone.utc) for key in TWELVE_DATA_KEYS}

import time

class CircuitBreaker:
    def __init__(self, failure_threshold=5, recovery_timeout=300):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.failure_count = 0
        self.last_failure_time = None
        self.state = 'CLOSED'
        self.success_count = 0
    
    def call(self, func, *args, **kwargs):
        current_time = time.time()

        if self.state == 'OPEN':
            if self.last_failure_time is not None and current_time - self.last_failure_time > self.recovery_timeout:
                self.state = 'HALF_OPEN'
                self.success_count = 0
                print("Circuit breaker moved to HALF_OPEN state")
            else:
                remaining_time = int(self.recovery_timeout - (current_time - (self.last_failure_time or current_time)))
                raise Exception(f"Circuit breaker is OPEN. Will retry in {remaining_time} seconds")
        
        try:
            result = func(*args, **kwargs)

            if self.state == 'HALF_OPEN':
                self.success_count += 1
                if self.success_count >= 3:
                    self.state = 'CLOSED'
                    self.failure_count = 0
                    print("Circuit breaker moved to CLOSED state after successful recovery")
            elif self.state == 'CLOSED':
                self.failure_count = max(0, self.failure_count - 1)

            return result

        except Exception as e:
            self.failure_count += 1
            self.last_failure_time = current_time

            if self.state == 'HALF_OPEN':
                self.state = 'OPEN'
                print("Circuit breaker returned to OPEN state due to failure during recovery")
            elif self.failure_count >= self.failure_threshold:
                self.state = 'OPEN'
                print(f"Circuit breaker OPENED after {self.failure_count} failures")

            raise e

    def reset(self):
        """Manually reset the circuit breaker"""
        self.state = 'CLOSED'
        self.failure_count = 0
        self.success_count = 0
        self.last_failure_time = None
        print("Circuit breaker manually reset")

# Example usage
api_circuit_breaker = CircuitBreaker()

def get_next_api_client():
    """Get the next available API client with rate limit management."""
    global current_api_index
    
    # Find the best available API key
    current_time = datetime.now(timezone.utc)
    best_key_index = None
    
    # First, try to find a key with available calls
    for i in range(len(TWELVE_DATA_KEYS)):
        key = TWELVE_DATA_KEYS[i]
        
        # Reset counters every minute
        if (current_time - api_reset_times[key]).total_seconds() >= 60:
            api_call_counts[key] = 0
            api_reset_times[key] = current_time
        
        # Check if this key has available calls - reduced for heartbeat protection
        if api_call_counts[key] < 3:  # Reduced from 6 to 3 for low-resource protection
            best_key_index = i
            break
    
    # If no key has available calls, use the one with the lowest count
    if best_key_index is None:
        best_key_index = min(range(len(TWELVE_DATA_KEYS)), 
                           key=lambda i: api_call_counts[TWELVE_DATA_KEYS[i]])
        print(f"All API keys rate limited, using key {best_key_index} with {api_call_counts[TWELVE_DATA_KEYS[best_key_index]]} calls")
    
    # Switch to the best key
    if best_key_index != current_api_index:
        print(f"Switching from API key {current_api_index} to {best_key_index}")
        current_api_index = best_key_index
    
    current_key = TWELVE_DATA_KEYS[current_api_index]
    
    # Increment call count
    api_call_counts[current_key] += 1
    
    return TDClient(apikey=current_key), current_api_index

