# Health monitoring
class HealthMonitor:
    def __init__(self):
        self.api_failures = 0
        self.db_failures = 0
        self.last_successful_signal = datetime.now(timezone.utc)
        self.memory_warnings = 0
    
    def record_api_failure(self):
        self.api_failures += 1
        if self.api_failures > 50:  # Too many failures
            print(f"CRITICAL: {self.api_failures} API failures detected")
    
    def record_db_failure(self):
        self.db_failures += 1
        if self.db_failures > 10:
            print(f"CRITICAL: {self.db_failures} database failures detected")
    
    def record_successful_signal(self):
        self.last_successful_signal = datetime.now(timezone.utc)
        self.api_failures = max(0, self.api_failures - 1)  # Decay failures
    
    def check_health(self):
        time_since_success = (datetime.now(timezone.utc) - self.last_successful_signal).total_seconds()
        if time_since_success > 3600:  # No successful signals in 1 hour
            return False, "No successful signals in over 1 hour"
        return True, "System healthy"

health_monitor = HealthMonitor()

# SQLite database setup
def backup_database(force=False):
    """Create backup of database with frequency control"""
    try:
        import shutil
        import os
        
        # Only backup if forced or if last backup was more than 1 hour ago
        if not force:
            backup_files = [f for f in os.listdir('.') if f.startswith('signals_backup_')]
            if backup_files:
                backup_files.sort(reverse=True)
                latest_backup = backup_files[0]
                # Extract timestamp from filename
                try:
                    backup_time_str = latest_backup.replace('signals_backup_', '').replace('.db', '')
                    backup_time = datetime.strptime(backup_time_str, "%Y%m%d_%H%M%S")
                    if (datetime.now(timezone.utc) - backup_time).total_seconds() < 3600:  # Less than 1 hour
                        return  # Skip backup
                except:
                    pass  # If we can't parse time, proceed with backup
        
        timestamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
        shutil.copy2('signals.db', f'signals_backup_{timestamp}.db')
        print(f"Database backed up to signals_backup_{timestamp}.db")
        
        # Clean up old backups (keep only last 5)
        backup_files = [f for f in os.listdir('.') if f.startswith('signals_backup_')]
        if len(backup_files) > 3:
            backup_files.sort()
            for old_backup in backup_files[:-3]:
                try:
                    os.remove(old_backup)
                    print(f"Removed old backup: {old_backup}")
                except:
                    pass
                    
    except Exception as e:
        print(f"Database backup failed: {e}")

def init_db():
    try:
        # Backup existing database only if forced
        if os.path.exists('signals.db'):
            backup_database(force=True)
        
        conn = sqlite3.connect('signals.db', timeout=30.0)
        conn.execute('PRAGMA journal_mode=WAL')  # Better concurrency
        conn.execute('PRAGMA synchronous=NORMAL')  # Better performance
        c = conn.cursor()
        
        # Signals table
        c.execute('''CREATE TABLE IF NOT EXISTS signals
                     (timestamp TEXT, pair TEXT, signal TEXT, price REAL, expiry TEXT,
                      rsi REAL, macd REAL, bb_upper REAL, bb_lower REAL, stoch_k REAL, stoch_d REAL)''')
        
        # Create user_settings table with complete schema (don't drop existing)
        c.execute('''CREATE TABLE IF NOT EXISTS user_settings
                     (user_id TEXT PRIMARY KEY, notifications_enabled INTEGER DEFAULT 1,
                      preferred_expiry TEXT DEFAULT '5m', min_confidence INTEGER DEFAULT 70,
                      risk_tolerance TEXT DEFAULT 'medium',
                      signal_filters TEXT DEFAULT '', alert_schedule TEXT DEFAULT 'always',
                      dm_notifications INTEGER DEFAULT 1, show_recommendations INTEGER DEFAULT 1)''')
        
        # Add missing columns if they don't exist
        try:
            c.execute('ALTER TABLE user_settings ADD COLUMN dm_notifications INTEGER DEFAULT 1')
        except:
            pass  # Column already exists
        
        try:
            c.execute('ALTER TABLE user_settings ADD COLUMN show_recommendations INTEGER DEFAULT 1')
        except:
            pass  # Column already exists
        
        # User alerts table  
        c.execute('''CREATE TABLE IF NOT EXISTS user_alerts
                     (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, pair TEXT, 
                      alert_type TEXT, target_value REAL, condition_type TEXT, 
                      is_active INTEGER DEFAULT 1, created_timestamp TEXT, triggered_timestamp TEXT,
                      alert_name TEXT, expiry_timestamp TEXT, notification_sent INTEGER DEFAULT 0)''')
        
        # Alert history table
        c.execute('''CREATE TABLE IF NOT EXISTS alert_history
                     (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, pair TEXT,
                      alert_type TEXT, target_value REAL, condition_type TEXT,
                      triggered_price REAL, triggered_timestamp TEXT, alert_name TEXT)''')
        
        # Analytics data table has been removed for simplification
        
        conn.commit()
        conn.close()
        
    except sqlite3.Error as e:
        print(f"Database initialization error: {e}")
    except Exception as e:
        print(f"Error in database initialization: {e}")

init_db()

