def fetch_coingecko_ohlc(crypto_id, vs_currency="usd", days=30):
    """Fetch OHLC data from CoinGecko for a cryptocurrency."""
    try:
        # CoinGecko OHLC endpoint
        url = f"https://api.coingecko.com/api/v3/coins/{crypto_id}/ohlc"
        params = {
            'vs_currency': vs_currency.lower(),
            'days': min(days, 365)  # CoinGecko limit
        }
        
        response = requests.get(url, params=params, timeout=10)
        response.raise_for_status()
        
        data = response.json()
        
        if not data:
            print(f"No OHLC data returned for {crypto_id}")
            return None
        
        # Convert to DataFrame
        df_data = []
        for candle in data:
            timestamp, open_price, high_price, low_price, close_price = candle
            dt = pd.to_datetime(timestamp, unit='ms')
            df_data.append({
                'datetime': dt,
                'open': float(open_price),
                'high': float(high_price), 
                'low': float(low_price),
                'close': float(close_price)
            })
        
        if not df_data:
            print(f"No valid OHLC data for {crypto_id}")
            return None
            
        df = pd.DataFrame(df_data)
        df = df.sort_values('datetime').reset_index(drop=True)
        
        # Validate data quality
        if len(df) < 10:
            print(f"Insufficient OHLC data for {crypto_id}: {len(df)} candles")
            return None
            
        return df
        
    except requests.exceptions.RequestException as e:
        print(f"Network error fetching CoinGecko OHLC for {crypto_id}: {e}")
        return None
    except Exception as e:
        print(f"Error fetching CoinGecko OHLC for {crypto_id}: {e}")
        return None

def fetch_coingecko_current_price(crypto_id, vs_currency="usd"):
    """Fetch current price from CoinGecko for a cryptocurrency."""
    try:
        url = "https://api.coingecko.com/api/v3/simple/price"
        params = {
            'ids': crypto_id,
            'vs_currencies': vs_currency.lower()
        }
        
        response = requests.get(url, params=params, timeout=10)
        response.raise_for_status()
        
        data = response.json()
        
        if crypto_id in data and vs_currency.lower() in data[crypto_id]:
            return float(data[crypto_id][vs_currency.lower()])
        else:
            print(f"Price data not found for {crypto_id}/{vs_currency}")
            return None
            
    except requests.exceptions.RequestException as e:
        print(f"Network error fetching CoinGecko price for {crypto_id}: {e}")
        return None
    except Exception as e:
        print(f"Error fetching CoinGecko price for {crypto_id}: {e}")
        return None



