def analyze_market_structure(df):
    """Analyze market structure: trends, higher highs/lows, break of structure."""
    # Enhanced validation - always return a tuple
    if df is None:
        print("analyze_market_structure received None dataframe")
        return ("No data", {})
    
    if not hasattr(df, 'empty'):
        print("analyze_market_structure received invalid dataframe object")
        return ("Invalid data format", {})
        
    if df.empty:
        print("analyze_market_structure received empty dataframe")
        return ("Insufficient data", {})
        
    if len(df) < 10:
        print(f"analyze_market_structure received insufficient data: {len(df)} rows")
        return ("Insufficient data", {})
    
    # Validate required columns
    required_columns = ['high', 'low', 'close']
    if not all(col in df.columns for col in required_columns):
        print(f"analyze_market_structure missing columns. Has: {list(df.columns)}, Needs: {required_columns}")
        return ("Missing required columns", {})
    
    # Clean data by removing NaN values
    df_clean = df[required_columns].dropna()
    if len(df_clean) < 10:
        print(f"analyze_market_structure: insufficient clean data after removing NaN: {len(df_clean)} rows")
        return ("Insufficient clean data", {})

    try:
        # Use cleaned data for analysis
        df = df_clean.reset_index(drop=True)
        
        # Additional safety checks for column data types
        for col in required_columns:
            if not pd.api.types.is_numeric_dtype(df[col]):
                print(f"analyze_market_structure found non-numeric data in {col} column")
                return ("Invalid data - non-numeric values", {})

        # Find swing highs and lows
        swing_highs = []
        swing_lows = []

        for i in range(2, len(df) - 2):
            try:
                # Additional safety checks for each iteration
                if (i-2 < 0 or i+2 >= len(df)):
                    continue
                    
                # Get values safely with NaN check
                current_high = df['high'].iloc[i]
                current_low = df['low'].iloc[i]
                
                if pd.isna(current_high) or pd.isna(current_low):
                    continue
                
                # Swing high: current high > 2 previous and 2 next highs
                if (current_high > df['high'].iloc[i-1] and 
                    current_high > df['high'].iloc[i-2] and
                    current_high > df['high'].iloc[i+1] and 
                    current_high > df['high'].iloc[i+2]):
                    swing_highs.append({'index': i, 'price': float(current_high)})

                # Swing low: current low < 2 previous and 2 next lows
                if (current_low < df['low'].iloc[i-1] and 
                    current_low < df['low'].iloc[i-2] and
                    current_low < df['low'].iloc[i+1] and 
                    current_low < df['low'].iloc[i+2]):
                    swing_lows.append({'index': i, 'price': float(current_low)})
                    
            except (IndexError, KeyError, ValueError, TypeError) as e:
                print(f"Error processing swing point at index {i}: {e}")
                continue

        # Determine trend based on recent swings
        trend = "Consolidation"
        structure_info = {}

        if len(swing_highs) >= 2 and len(swing_lows) >= 2:
            recent_highs = swing_highs[-2:]
            recent_lows = swing_lows[-2:]

            # Higher highs and higher lows = uptrend
            if (recent_highs[1]['price'] > recent_highs[0]['price'] and 
                recent_lows[1]['price'] > recent_lows[0]['price']):
                trend = "Uptrend"
            # Lower highs and lower lows = downtrend
            elif (recent_highs[1]['price'] < recent_highs[0]['price'] and 
                  recent_lows[1]['price'] < recent_lows[0]['price']):
                trend = "Downtrend"

            # Check for break of structure
            try:
                current_price = df['close'].iloc[-1]
                if pd.isna(current_price):
                    current_price = df['close'].dropna().iloc[-1] if not df['close'].dropna().empty else 0
                
                if len(swing_lows) > 0 and current_price > 0:
                    last_swing_low = swing_lows[-1]['price']
                    if current_price < last_swing_low and trend == "Uptrend":
                        structure_info['break_of_structure'] = f"Bearish BOS at {last_swing_low:.5f}"

                if len(swing_highs) > 0 and current_price > 0:
                    last_swing_high = swing_highs[-1]['price']
                    if current_price > last_swing_high and trend == "Downtrend":
                        structure_info['break_of_structure'] = f"Bullish BOS at {last_swing_high:.5f}"
            except (IndexError, KeyError, ValueError, TypeError) as e:
                print(f"Error checking break of structure: {e}")
                pass

        structure_info['trend'] = trend
        structure_info['swing_highs'] = swing_highs[-2:] if len(swing_highs) >= 2 else swing_highs
        structure_info['swing_lows'] = swing_lows[-2:] if len(swing_lows) >= 2 else swing_lows

        return (trend, structure_info)
        
    except Exception as e:
        print(f"Critical error in analyze_market_structure: {e}")
        import traceback
        traceback.print_exc()
        return ("Error", {})

def detect_liquidity_zones(df):
    """Enhanced liquidity detection with comprehensive ICT concepts."""
    if len(df) < 20:
        return {}

    liquidity_info = {}
    current_price = df['close'].iloc[-1]
    
    # Enhanced equal highs and lows detection
    equal_highs = []
    equal_lows = []
    tolerance = 0.0002  # Slightly wider tolerance for forex
    
    # Find swing highs and lows first
    swing_highs = []
    swing_lows = []
    
    for i in range(2, len(df) - 2):
        # Swing high: higher than 2 candles on each side
        if (df['high'].iloc[i] > df['high'].iloc[i-1] and 
            df['high'].iloc[i] > df['high'].iloc[i-2] and
            df['high'].iloc[i] > df['high'].iloc[i+1] and 
            df['high'].iloc[i] > df['high'].iloc[i+2]):
            swing_highs.append({'price': df['high'].iloc[i], 'index': i})
            
        # Swing low: lower than 2 candles on each side
        if (df['low'].iloc[i] < df['low'].iloc[i-1] and 
            df['low'].iloc[i] < df['low'].iloc[i-2] and
            df['low'].iloc[i] < df['low'].iloc[i+1] and 
            df['low'].iloc[i] < df['low'].iloc[i+2]):
            swing_lows.append({'price': df['low'].iloc[i], 'index': i})
    
    # Group swing points that are within tolerance (equal levels)
    for i, swing1 in enumerate(swing_highs):
        count = 1
        for j, swing2 in enumerate(swing_highs[i+1:], i+1):
            if abs(swing1['price'] - swing2['price']) <= tolerance:
                count += 1
        if count >= 2:
            equal_highs.append({
                'price': swing1['price'],
                'count': count,
                'type': 'Equal Highs Liquidity',
                'strength': 'High' if count >= 3 else 'Medium',
                'distance_from_current': abs(current_price - swing1['price']),
                'last_touch_index': swing1['index']
            })
    
    for i, swing1 in enumerate(swing_lows):
        count = 1
        for j, swing2 in enumerate(swing_lows[i+1:], i+1):
            if abs(swing1['price'] - swing2['price']) <= tolerance:
                count += 1
        if count >= 2:
            equal_lows.append({
                'price': swing1['price'],
                'count': count,
                'type': 'Equal Lows Liquidity',
                'strength': 'High' if count >= 3 else 'Medium',
                'distance_from_current': abs(current_price - swing1['price']),
                'last_touch_index': swing1['index']
            })

    # Enhanced liquidity grab detection
    liquidity_grabs = []
    liquidity_sweeps = []
    
    # Check for recent liquidity sweeps (last 5 candles)
    for i in range(max(0, len(df) - 5), len(df)):
        candle = df.iloc[i]
        
        # Check if this candle swept above recent highs
        recent_highs = [h['price'] for h in swing_highs[-3:]] if swing_highs else []
        for high_level in recent_highs:
            if candle['high'] > high_level and candle['close'] < high_level:
                liquidity_grabs.append({
                    'type': 'Buy-side Liquidity Sweep',
                    'level': high_level,
                    'sweep_candle_index': i,
                    'description': f'Swept above {high_level:.5f}, then rejected',
                    'strength': 'High' if abs(candle['high'] - high_level) < tolerance else 'Medium'
                })
        
        # Check if this candle swept below recent lows
        recent_lows = [l['price'] for l in swing_lows[-3:]] if swing_lows else []
        for low_level in recent_lows:
            if candle['low'] < low_level and candle['close'] > low_level:
                liquidity_grabs.append({
                    'type': 'Sell-side Liquidity Sweep',
                    'level': low_level,
                    'sweep_candle_index': i,
                    'description': f'Swept below {low_level:.5f}, then rejected',
                    'strength': 'High' if abs(candle['low'] - low_level) < tolerance else 'Medium'
                })

    # Detect liquidity pools (consolidation areas with high touch count)
    liquidity_pools = []
    price_levels = {}
    
    # Count touches at each price level
    for i in range(len(df)):
        high_level = round(df['high'].iloc[i] / tolerance) * tolerance
        low_level = round(df['low'].iloc[i] / tolerance) * tolerance
        
        price_levels[high_level] = price_levels.get(high_level, 0) + 1
        price_levels[low_level] = price_levels.get(low_level, 0) + 1
    
    # Find levels with multiple touches (liquidity pools)
    for price, touch_count in price_levels.items():
        if touch_count >= 4:  # Minimum 4 touches to be considered a pool
            liquidity_pools.append({
                'price': price,
                'touch_count': touch_count,
                'type': 'Liquidity Pool',
                'strength': 'Extreme' if touch_count >= 8 else 'High' if touch_count >= 6 else 'Medium',
                'distance_from_current': abs(current_price - price)
            })
    
    # Sort by strength and proximity
    equal_highs = sorted(equal_highs, key=lambda x: (x['count'], -x['distance_from_current']), reverse=True)[:3]
    equal_lows = sorted(equal_lows, key=lambda x: (x['count'], -x['distance_from_current']), reverse=True)[:3]
    liquidity_pools = sorted(liquidity_pools, key=lambda x: (x['touch_count'], -x['distance_from_current']), reverse=True)[:3]

    liquidity_info['equal_highs'] = equal_highs
    liquidity_info['equal_lows'] = equal_lows
    liquidity_info['liquidity_grabs'] = liquidity_grabs[-3:]  # Last 3 grabs
    liquidity_info['liquidity_pools'] = liquidity_pools
    liquidity_info['total_zones'] = len(equal_highs) + len(equal_lows) + len(liquidity_pools)

    return liquidity_info

def detect_order_block(df):
    """Enhanced order block detection with proper ICT validation - ONLY RESPECTED ORDER BLOCKS."""
    if df is None or df.empty or len(df) < 15:
        default_length = max(15, len(df) if df is not None and not df.empty else 15)
        return (pd.Series([False] * default_length), 
                pd.Series([False] * default_length), 
                {}, {})

    try:
        bullish_ob = pd.Series([False] * len(df), index=df.index)
        bearish_ob = pd.Series([False] * len(df), index=df.index)
    except Exception as e:
        print(f"Error creating order block series: {e}")
        return (pd.Series([False] * len(df)), 
                pd.Series([False] * len(df)), 
                {}, {})

    bullish_ob_levels = {}
    bearish_ob_levels = {}
    
    # Look for order blocks with sufficient future data to validate respect
    for i in range(8, len(df) - 8):  # Need more future candles to properly check respect
        
        # Enhanced Bullish Order Block Detection
        displacement_strength = calculate_displacement_strength(df, i)
        volume_confirmation = calculate_volume_confirmation(df, i)
        
        # Check for strong bullish displacement
        if (df['close'].iloc[i] > df['open'].iloc[i] and  # Current candle is bullish
            df['close'].iloc[i] > df['high'].iloc[i-1] and  # Breaks previous high
            displacement_strength > 0.01):  # Higher threshold for quality displacements
            
            # Find the order block candle (last bearish before displacement)
            ob_candle_idx = find_order_block_candle(df, i, 'bullish')
            
            if ob_candle_idx is not None:
                # ICT Rule: CRITICAL - Only use order blocks that have been respected
                respect_count = check_order_block_respect(df, ob_candle_idx, i, 'bullish')
                
                if respect_count >= 2:  # Must be respected at least twice for high quality
                    bullish_ob.iloc[ob_candle_idx] = True
                    
                    # Calculate order block strength including respect factor
                    ob_strength = calculate_order_block_strength(df, ob_candle_idx, i, 'bullish')
                    respect_strength = min(1.0, respect_count * 0.25)  # Respect bonus
                    
                    # Quality check - only use if recent and well-respected
                    if i >= len(df) - 15 and respect_count >= 2:
                        bullish_ob_levels = {
                            'low': df['low'].iloc[ob_candle_idx],
                            'high': df['high'].iloc[ob_candle_idx],
                            'type': f'Respected Bullish Order Block ({respect_count}x)',
                            'strength': min(1.0, ob_strength + respect_strength),
                            'displacement_size': displacement_strength * 100,
                            'volume_confirmation': volume_confirmation,
                            'candle_index': ob_candle_idx,
                            'displacement_index': i,
                            'time_to_react': i - ob_candle_idx,
                            'respect_count': respect_count,
                            'quality': 'Excellent' if respect_count >= 3 else 'High',
                            'last_reaction_strength': calculate_last_reaction_strength(df, ob_candle_idx, i),
                            'is_fresh': check_if_order_block_fresh(df, ob_candle_idx, i)
                        }

        # Enhanced Bearish Order Block Detection
        displacement_strength = calculate_displacement_strength(df, i, direction='bearish')
        
        if (df['close'].iloc[i] < df['open'].iloc[i] and  # Current candle is bearish
            df['close'].iloc[i] < df['low'].iloc[i-1] and  # Breaks previous low
            displacement_strength > 0.01):  # Higher threshold for quality
            
            ob_candle_idx = find_order_block_candle(df, i, 'bearish')
            
            if ob_candle_idx is not None:
                # ICT Rule: CRITICAL - Only use order blocks that have been respected
                respect_count = check_order_block_respect(df, ob_candle_idx, i, 'bearish')
                
                if respect_count >= 2:  # Must be respected at least twice for high quality
                    bearish_ob.iloc[ob_candle_idx] = True
                    
                    ob_strength = calculate_order_block_strength(df, ob_candle_idx, i, 'bearish')
                    respect_strength = min(1.0, respect_count * 0.25)
                    
                    # Quality check - only use if recent and well-respected
                    if i >= len(df) - 15 and respect_count >= 2:
                        bearish_ob_levels = {
                            'low': df['low'].iloc[ob_candle_idx],
                            'high': df['high'].iloc[ob_candle_idx],
                            'type': f'Respected Bearish Order Block ({respect_count}x)',
                            'strength': min(1.0, ob_strength + respect_strength),
                            'displacement_size': displacement_strength * 100,
                            'volume_confirmation': volume_confirmation,
                            'candle_index': ob_candle_idx,
                            'displacement_index': i,
                            'time_to_react': i - ob_candle_idx,
                            'respect_count': respect_count,
                            'quality': 'Excellent' if respect_count >= 3 else 'High',
                            'last_reaction_strength': calculate_last_reaction_strength(df, ob_candle_idx, i),
                            'is_fresh': check_if_order_block_fresh(df, ob_candle_idx, i)
                        }

    return bullish_ob, bearish_ob, bullish_ob_levels, bearish_ob_levels

def calculate_displacement_strength(df, index, direction='bullish'):
    """Calculate the strength of price displacement from order block."""
    try:
        if direction == 'bullish':
            start_price = df['low'].iloc[index-3:index].min()
            end_price = df['close'].iloc[index]
        else:
            start_price = df['high'].iloc[index-3:index].max()
            end_price = df['close'].iloc[index]
        
        if start_price == 0:
            return 0
        
        displacement = abs(end_price - start_price) / start_price
        return displacement
    except:
        return 0

def find_order_block_candle(df, displacement_index, direction):
    """Find the actual order block candle before displacement."""
    try:
        search_range = min(5, displacement_index)
        
        for i in range(displacement_index - 1, displacement_index - search_range - 1, -1):
            if i < 0:
                break
                
            candle = df.iloc[i]
            
            if direction == 'bullish':
                # Look for last bearish/neutral candle before bullish displacement
                if candle['close'] <= candle['open']:
                    return i
            else:
                # Look for last bullish/neutral candle before bearish displacement
                if candle['close'] >= candle['open']:
                    return i
        
        return displacement_index - 1  # Fallback
    except:
        return None

def calculate_order_block_strength(df, ob_index, displacement_index, direction):
    """Calculate order block strength based on multiple factors."""
    try:
        strength = 0.5  # Base strength
        
        # 1. Displacement magnitude
        displacement = calculate_displacement_strength(df, displacement_index, direction)
        strength += min(0.3, displacement * 30)  # Up to 0.3 bonus
        
        # 2. Volume confirmation (using range as proxy)
        ob_range = df['high'].iloc[ob_index] - df['low'].iloc[ob_index]
        avg_range = (df['high'] - df['low']).iloc[max(0, ob_index-10):ob_index].mean()
        
        if ob_range > avg_range * 1.5:
            strength += 0.15
        
        # 3. Time between OB and displacement (faster = stronger)
        time_diff = displacement_index - ob_index
        if time_diff <= 3:
            strength += 0.15
        elif time_diff <= 5:
            strength += 0.1
        
        # 4. Subsequent price respect (if available)
        if displacement_index < len(df) - 3:
            respect_count = 0
            ob_level = (df['high'].iloc[ob_index] + df['low'].iloc[ob_index]) / 2
            
            for i in range(displacement_index + 1, min(len(df), displacement_index + 6)):
                if direction == 'bullish':
                    if df['low'].iloc[i] >= ob_level * 0.999:  # Respected as support
                        respect_count += 1
                else:
                    if df['high'].iloc[i] <= ob_level * 1.001:  # Respected as resistance
                        respect_count += 1
            
            strength += respect_count * 0.05
        
        return min(1.0, strength)
    except:
        return 0.5

def check_order_block_respect(df, ob_index, displacement_index, direction):
    """Check how many times an order block has been respected after displacement - Enhanced ICT validation."""
    try:
        if direction == 'bullish':
            # For bullish OB, check if price bounces from the OB zone
            ob_high = df['high'].iloc[ob_index]
            ob_low = df['low'].iloc[ob_index]
            ob_mid = (ob_high + ob_low) / 2
            
            respect_count = 0
            last_respect_strength = 0
            
            # Check future price action after displacement
            for i in range(displacement_index + 1, len(df)):
                # If price comes back to OB zone (tests the level)
                if (df['low'].iloc[i] <= ob_high and df['low'].iloc[i] >= ob_low):
                    # Check if it bounced with conviction (next 3-5 candles move higher)
                    bounce_confirmed = False
                    bounce_strength = 0
                    
                    for j in range(i + 1, min(i + 5, len(df))):
                        if df['close'].iloc[j] > df['close'].iloc[i]:
                            bounce_strength += (df['close'].iloc[j] - df['close'].iloc[i]) / df['close'].iloc[i]
                    
                    # Require significant bounce (at least 0.3% move up)
                    if bounce_strength > 0.003:
                        bounce_confirmed = True
                        last_respect_strength = bounce_strength
                    
                    if bounce_confirmed:
                        respect_count += 1
                        
        else:  # bearish
            # For bearish OB, check if price rejects from the OB zone
            ob_high = df['high'].iloc[ob_index]
            ob_low = df['low'].iloc[ob_index]
            
            respect_count = 0
            last_respect_strength = 0
            
            # Check future price action after displacement
            for i in range(displacement_index + 1, len(df)):
                # If price comes back to OB zone (tests the level)
                if (df['high'].iloc[i] >= ob_low and df['high'].iloc[i] <= ob_high):
                    # Check if it rejected with conviction (next 3-5 candles move lower)
                    rejection_confirmed = False
                    rejection_strength = 0
                    
                    for j in range(i + 1, min(i + 5, len(df))):
                        if df['close'].iloc[j] < df['close'].iloc[i]:
                            rejection_strength += (df['close'].iloc[i] - df['close'].iloc[j]) / df['close'].iloc[i]
                    
                    # Require significant rejection (at least 0.3% move down)
                    if rejection_strength > 0.003:
                        rejection_confirmed = True
                        last_respect_strength = rejection_strength
                    
                    if rejection_confirmed:
                        respect_count += 1
        
        return respect_count
    except:
        return 0

def calculate_last_reaction_strength(df, ob_index, displacement_index):
    """Calculate the strength of the last reaction from the order block."""
    try:
        ob_high = df['high'].iloc[ob_index]
        ob_low = df['low'].iloc[ob_index]
        
        # Find the most recent test of the order block
        for i in range(len(df) - 1, displacement_index, -1):
            if (df['low'].iloc[i] <= ob_high and df['low'].iloc[i] >= ob_low) or \
               (df['high'].iloc[i] >= ob_low and df['high'].iloc[i] <= ob_high):
                # Calculate reaction strength from this point
                reaction_start = df['close'].iloc[i]
                reaction_end = df['close'].iloc[-1]
                strength = abs(reaction_end - reaction_start) / reaction_start
                return strength
        
        return 0
    except:
        return 0

def check_if_order_block_fresh(df, ob_index, displacement_index):
    """Check if the order block is still fresh (not heavily tested)."""
    try:
        ob_high = df['high'].iloc[ob_index]
        ob_low = df['low'].iloc[ob_index]
        
        # Count how many times price has tested this level
        test_count = 0
        for i in range(displacement_index + 1, len(df)):
            if (df['low'].iloc[i] <= ob_high and df['low'].iloc[i] >= ob_low) or \
               (df['high'].iloc[i] >= ob_low and df['high'].iloc[i] <= ob_high):
                test_count += 1
        
        # Fresh if tested 3 times or less
        return test_count <= 3
    except:
        return True

def calculate_volume_confirmation(df, index):
    """Calculate volume confirmation using price action as proxy."""
    try:
        current_range = df['high'].iloc[index] - df['low'].iloc[index]
        current_body = abs(df['close'].iloc[index] - df['open'].iloc[index])
        
        avg_range = (df['high'] - df['low']).iloc[max(0, index-10):index].mean()
        
        # High volume proxy indicators
        volume_score = 0
        
        # Large range compared to average
        if current_range > avg_range * 1.5:
            volume_score += 0.5
        
        # Large body indicating strong conviction
        if current_body > current_range * 0.7:
            volume_score += 0.3
        
        # Closing near extremes
        close_position = (df['close'].iloc[index] - df['low'].iloc[index]) / current_range if current_range > 0 else 0.5
        if close_position > 0.8 or close_position < 0.2:
            volume_score += 0.2
        
        return min(1.0, volume_score)
    except:
        return 0.5

def detect_fair_value_gap(df):
    """Enhanced Fair Value Gap detection with proper ICT three-candle structure - ONLY UNFILLED FVGS."""
    if df is None or df.empty or len(df) < 5:
        # Return safe default values
        default_length = max(5, len(df) if df is not None and not df.empty else 5)
        return pd.Series([False] * default_length), {}

    try:
        fvg = pd.Series([False] * len(df), index=df.index)
        fvg_levels = {}
        latest_unfilled_fvg = None
    except Exception as e:
        print(f"Error creating FVG series: {e}")
        return pd.Series([False] * len(df)), {}

    # Need at least 3 candles to detect FVG + buffer for validation
    for i in range(2, len(df) - 2):  # Leave buffer to check if filled
        candle_1 = df.iloc[i-2]  # First candle
        candle_2 = df.iloc[i-1]  # Middle candle (displacement candle - must be significant)
        candle_3 = df.iloc[i]    # Third candle
        
        # ICT Rule: Middle candle must show significant displacement
        displacement_size = abs(candle_2['close'] - candle_2['open']) / candle_2['open']
        if displacement_size < 0.005:  # Increased minimum threshold for quality
            continue
        
        # Bullish FVG: Low of candle 3 > High of candle 1
        # Middle candle must be bullish with strong upward movement
        if (candle_3['low'] > candle_1['high'] and 
            candle_2['close'] > candle_2['open'] and  # Displacement candle must be bullish
            candle_2['close'] > candle_1['high']):    # Displacement must break above candle 1
            
            gap_size = candle_3['low'] - candle_1['high']
            
            # ICT Rule: Gap must be significant relative to average range
            avg_range = (df['high'] - df['low']).iloc[max(0, i-10):i].mean()
            if gap_size > avg_range * 0.15:  # Increased threshold for quality gaps
                
                temp_fvg = {
                    'upper': candle_3['low'],
                    'lower': candle_1['high'], 
                    'type': 'Bullish FVG',
                    'size': gap_size,
                    'candle_index': i,
                    'displacement_candle_index': i-1,
                    'displacement_size': displacement_size * 100,
                    'strength': 'High' if displacement_size > 0.01 else 'Medium'
                }
                
                # ICT Rule: CRITICAL - Only use unfilled FVGs
                is_filled = check_if_fvg_filled(df, temp_fvg, i)
                if not is_filled:
                    # Double-check by ensuring current price hasn't traded through the gap
                    current_price = df['close'].iloc[-1]
                    if current_price > temp_fvg['upper']:  # Price is above gap, gap is intact
                        fvg.iloc[i] = True
                        latest_unfilled_fvg = temp_fvg

        # Bearish FVG: High of candle 3 < Low of candle 1
        # Middle candle must be bearish with strong downward movement  
        elif (candle_3['high'] < candle_1['low'] and
              candle_2['close'] < candle_2['open'] and  # Displacement candle must be bearish
              candle_2['close'] < candle_1['low']):     # Displacement must break below candle 1
            
            gap_size = candle_1['low'] - candle_3['high']
            
            # ICT Rule: Gap must be significant relative to average range
            avg_range = (df['high'] - df['low']).iloc[max(0, i-10):i].mean()
            if gap_size > avg_range * 0.15:  # Increased threshold for quality gaps
                
                temp_fvg = {
                    'upper': candle_1['low'],
                    'lower': candle_3['high'],
                    'type': 'Bearish FVG', 
                    'size': gap_size,
                    'candle_index': i,
                    'displacement_candle_index': i-1,
                    'displacement_size': displacement_size * 100,
                    'strength': 'High' if displacement_size > 0.01 else 'Medium'
                }
                
                # ICT Rule: CRITICAL - Only use unfilled FVGs
                is_filled = check_if_fvg_filled(df, temp_fvg, i)
                if not is_filled:
                    # Double-check by ensuring current price hasn't traded through the gap
                    current_price = df['close'].iloc[-1]
                    if current_price < temp_fvg['lower']:  # Price is below gap, gap is intact
                        fvg.iloc[i] = True
                        latest_unfilled_fvg = temp_fvg

    # Return the most recent unfilled FVG if found
    if latest_unfilled_fvg:
        fvg_levels = latest_unfilled_fvg
        
        # Add additional analysis for unfilled gaps only
        current_price = df['close'].iloc[-1]
        fvg_levels['distance_from_current'] = abs(current_price - ((fvg_levels['upper'] + fvg_levels['lower']) / 2))
        fvg_levels['is_filled'] = False  # Guaranteed unfilled
        fvg_levels['quality'] = 'High' if fvg_levels['displacement_size'] > 1.0 else 'Medium'
        
        # Determine expected reaction based on current price position
        if fvg_levels['type'] == 'Bullish FVG':
            if current_price > fvg_levels['upper']:
                fvg_levels['expected_reaction'] = 'Strong support expected if price returns to unfilled FVG'
                fvg_levels['bias'] = 'Bullish on retest'
            else:
                fvg_levels['expected_reaction'] = 'Price may test gap before strong bounce'
                fvg_levels['bias'] = 'Bullish pending'
        else:
            if current_price < fvg_levels['lower']:
                fvg_levels['expected_reaction'] = 'Strong resistance expected if price returns to unfilled FVG'
                fvg_levels['bias'] = 'Bearish on retest'
            else:
                fvg_levels['expected_reaction'] = 'Price may test gap before strong rejection'
                fvg_levels['bias'] = 'Bearish pending'

    return fvg, fvg_levels

def detect_smart_money_concepts(df):
    """Analyze smart money behavior: inducement, displacement, breaker blocks."""
    if len(df) < 10:
        return {}

    smc_info = {}

    # Detect displacement (strong directional moves)
    displacement_threshold = 0.002  # 0.2% move
    recent_moves = []

    for i in range(5, len(df)):
        # Calculate percentage move
        move_pct = abs(df['close'].iloc[i] - df['close'].iloc[i-1]) / df['close'].iloc[i-1]
        if move_pct > displacement_threshold:
            direction = "Bullish" if df['close'].iloc[i] > df['close'].iloc[i-1] else "Bearish"
            recent_moves.append({
                'type': f'{direction} Displacement',
                'size': move_pct * 100,
                'from': df['close'].iloc[i-1],
                'to': df['close'].iloc[i]
            })

    # Detect potential inducement (false breakouts)
    current_price = df['close'].iloc[-1]
    recent_high = df['high'].tail(10).max()
    recent_low = df['low'].tail(10).min()

    inducement = []

    # Check for false breakout above recent high
    if len(df) >= 5:
        last_5_high = df['high'].tail(5).max()
        if current_price < last_5_high * 0.998 and last_5_high >= recent_high * 0.999:
            inducement.append({
                'type': 'Bearish Inducement',
                'description': f'False break above {last_5_high:.5f}, now below'
            })

    # Check for false breakout below recent low
    if len(df) >= 5:
        last_5_low = df['low'].tail(5).min()
        if current_price > last_5_low * 1.002 and last_5_low <= recent_low * 1.001:
            inducement.append({
                'type': 'Bullish Inducement',
                'description': f'False break below {last_5_low:.5f}, now above'
            })

    smc_info['displacement'] = recent_moves[-2:] if recent_moves else []
    smc_info['inducement'] = inducement

    return smc_info

def detect_candlestick_patterns(df):
    """Detect key candlestick patterns in ICT context."""
    if len(df) < 3:
        return {}

    patterns = {}
    current = df.iloc[-1]
    prev = df.iloc[-2] if len(df) > 1 else current

    # Engulfing patterns
    if len(df) >= 2:
        # Bullish engulfing
        if (prev['close'] < prev['open'] and  # Previous bearish
            current['close'] > current['open'] and  # Current bullish
            current['open'] < prev['close'] and  # Current opens below prev close
            current['close'] > prev['open']):  # Current closes above prev open
            patterns['engulfing'] = 'Bullish Engulfing'

        # Bearish engulfing
        elif (prev['close'] > prev['open'] and  # Previous bullish
              current['close'] < current['open'] and  # Current bearish
              current['open'] > prev['close'] and  # Current opens above prev close
              current['close'] < prev['open']):  # Current closes above prev open
            patterns['engulfing'] = 'Bearish Engulfing'

    # Pin bar / Hammer patterns
    body_size = abs(current['close'] - current['open'])
    total_range = current['high'] - current['low']

    if total_range > 0:
        body_ratio = body_size / total_range

        # Pin bar criteria: small body (< 30% of total range)
        if body_ratio < 0.3:
            upper_wick = current['high'] - max(current['open'], current['close'])
            lower_wick = min(current['open'], current['close']) - current['low']

            # Bullish pin bar (hammer): long lower wick
            if lower_wick > body_size * 2 and upper_wick < body_size:
                patterns['pin_bar'] = 'Bullish Pin Bar (Hammer)'

            # Bearish pin bar (shooting star): long upper wick
            elif upper_wick > body_size * 2 and lower_wick < body_size:
                patterns['pin_bar'] = 'Bearish Pin Bar (Shooting Star)'

    return patterns

def detect_chart_patterns(df):
    """Comprehensive chart pattern detection with robust error handling."""
    # Enhanced validation
    if df is None or not hasattr(df, 'empty') or df.empty or len(df) < 20:
        return {}
    
    # Validate required columns
    required_columns = ['high', 'low', 'close', 'open']
    if not all(col in df.columns for col in required_columns):
        print(f"Chart patterns: Missing required columns. Has: {list(df.columns)}")
        return {}
    
    patterns = {}
    
    try:
        # Validate data quality
        if (df['high'].isnull().any() or df['low'].isnull().any() or 
            df['close'].isnull().any() or df['open'].isnull().any()):
            print("Chart patterns: NaN values found in OHLC data")
            return {}
        
        # Detect various chart patterns with individual error handling
        pattern_functions = [
            ('head_and_shoulders', detect_head_and_shoulders),
            ('triangles', detect_triangles),
            ('flags_pennants', detect_flags_pennants),
            ('double_patterns', detect_double_patterns),
            ('wedges', detect_wedges),
            ('channels', detect_channels),
            ('cup_and_handle', detect_cup_and_handle),
            ('ascending_descending', detect_ascending_descending_patterns),
            ('harmonic_patterns', detect_harmonic_patterns),
            ('elliott_wave', detect_elliott_wave_pattern)
        ]
        
        for pattern_name, pattern_func in pattern_functions:
            try:
                pattern_result = pattern_func(df)
                if pattern_result and isinstance(pattern_result, dict):
                    patterns.update(pattern_result)
            except Exception as e:
                print(f"Error in {pattern_name} detection: {e}")
                continue
        
    except Exception as e:
        print(f"Critical error in chart pattern detection: {e}")
        return {}
    
    return patterns

def validate_data_continuity(df, symbol, interval):
    """Validate and improve data continuity by detecting gaps."""
    if df is None or df.empty or len(df) < 10:
        return df
    
    try:
        # Define expected time intervals
        interval_minutes = {
            '1min': 1,
            '5min': 5,
            '15min': 15,
            '1h': 60,
            '4h': 240,
            '1day': 1440
        }
        
        expected_interval = interval_minutes.get(interval, 5)
        
        # Check for gaps in the data
        df_sorted = df.sort_values('datetime').reset_index(drop=True)
        gaps_found = 0
        
        for i in range(1, len(df_sorted)):
            time_diff = (df_sorted['datetime'].iloc[i] - df_sorted['datetime'].iloc[i-1]).total_seconds() / 60
            
            # Allow some tolerance (1.5x expected interval)
            if time_diff > expected_interval * 1.5:
                gaps_found += 1
        
        gap_ratio = gaps_found / (len(df_sorted) - 1) if len(df_sorted) > 1 else 0
        
        # Fill small gaps with interpolation (only for minor gaps)
        if gap_ratio < 0.05:  # Less than 5% gaps - safe to interpolate
            df_filled = fill_minor_gaps(df_sorted, expected_interval)
            return df_filled
        
        return df_sorted
        
    except Exception as e:
        print(f"Error validating data continuity for {symbol}: {e}")
        return df

def fill_minor_gaps(df, expected_interval_minutes):
    """Fill minor gaps in OHLC data using interpolation."""
    try:
        df_filled = df.copy()
        df_filled = df_filled.sort_values('datetime').reset_index(drop=True)
        
        filled_rows = []
        
        for i in range(len(df_filled)):
            filled_rows.append(df_filled.iloc[i].to_dict())
            
            # Check if there's a gap to the next row
            if i < len(df_filled) - 1:
                current_time = df_filled['datetime'].iloc[i]
                next_time = df_filled['datetime'].iloc[i + 1]
                time_diff_minutes = (next_time - current_time).total_seconds() / 60
                
                # If gap is 2-3 intervals, fill it
                if expected_interval_minutes * 2 <= time_diff_minutes <= expected_interval_minutes * 3:
                    # Calculate how many intervals to fill
                    intervals_to_fill = int(time_diff_minutes / expected_interval_minutes) - 1
                    
                    if intervals_to_fill > 0 and intervals_to_fill <= 2:  # Only fill 1-2 missing intervals
                        current_price = df_filled['close'].iloc[i]
                        next_price = df_filled['open'].iloc[i + 1]
                        
                        for j in range(1, intervals_to_fill + 1):
                            fill_time = current_time + timedelta(minutes=expected_interval_minutes * j)
                            
                            # Linear interpolation for the gap
                            weight = j / (intervals_to_fill + 1)
                            interpolated_price = current_price + (next_price - current_price) * weight
                            
                            # Create realistic OHLC for interpolated candle
                            price_variance = abs(next_price - current_price) * 0.3
                            
                            filled_row = {
                                'datetime': fill_time,
                                'open': interpolated_price - price_variance * 0.1,
                                'high': interpolated_price + price_variance * 0.3,
                                'low': interpolated_price - price_variance * 0.3,
                                'close': interpolated_price
                            }
                            
                            filled_rows.append(filled_row)
        
        # Create new dataframe from filled rows
        if len(filled_rows) > len(df_filled):
            df_result = pd.DataFrame(filled_rows)
            df_result = df_result.sort_values('datetime').reset_index(drop=True)
            return df_result
        
        return df_filled
        
    except Exception as e:
        print(f"Error filling gaps: {e}")
        return df

    

def detect_head_and_shoulders(df):
    """Detect head and shoulders patterns with enhanced validation and trend analysis."""
    patterns = {}
    
    # Enhanced validation
    if df is None or not hasattr(df, 'empty') or df.empty or len(df) < 20:
        return patterns
    
    # Validate required columns
    required_columns = ['high', 'low', 'close', 'volume'] if 'volume' in df.columns else ['high', 'low', 'close']
    if not all(col in df.columns for col in required_columns):
        return patterns
    
    try:
        # Find swing highs and lows with enhanced criteria
        swing_highs = []
        swing_lows = []
        
        # Use dynamic lookback based on data length
        lookback = min(3, len(df) // 20)
        
        for i in range(lookback, len(df) - lookback):
            try:
                current_high = df['high'].iloc[i]
                current_low = df['low'].iloc[i]
                
                if pd.isna(current_high) or pd.isna(current_low):
                    continue
                
                # Enhanced swing high detection with volume confirmation
                is_swing_high = True
                for j in range(i - lookback, i + lookback + 1):
                    if j != i and df['high'].iloc[j] >= current_high:
                        is_swing_high = False
                        break
                
                if is_swing_high:
                    # Calculate strength based on volume (if available)
                    strength = 1.0
                    current_volume = 1.0
                    avg_volume = 1.0
                    
                    if 'volume' in df.columns:
                        avg_volume = df['volume'].iloc[max(0, i-10):i+1].mean()
                        current_volume = df['volume'].iloc[i]
                        if pd.notna(avg_volume) and avg_volume > 0 and pd.notna(current_volume):
                            if current_volume > avg_volume * 1.2:
                                strength = 1.5
                    
                    swing_highs.append({
                        'index': i, 
                        'price': float(current_high),
                        'strength': strength,
                        'volume_ratio': current_volume / avg_volume if avg_volume > 0 else 1.0
                    })
                
                # Enhanced swing low detection
                is_swing_low = True
                for j in range(i - lookback, i + lookback + 1):
                    if j != i and df['low'].iloc[j] <= current_low:
                        is_swing_low = False
                        break
                
                if is_swing_low:
                    strength = 1.0
                    current_volume = 1.0
                    avg_volume = 1.0
                    
                    if 'volume' in df.columns:
                        avg_volume = df['volume'].iloc[max(0, i-10):i+1].mean()
                        current_volume = df['volume'].iloc[i]
                        if pd.notna(avg_volume) and avg_volume > 0 and pd.notna(current_volume):
                            if current_volume > avg_volume * 1.2:
                                strength = 1.5
                    
                    swing_lows.append({
                        'index': i, 
                        'price': float(current_low),
                        'strength': strength,
                        'volume_ratio': current_volume / avg_volume if avg_volume > 0 else 1.0
                    })
                    
            except (IndexError, KeyError, ValueError, TypeError) as e:
                continue
        
        # Enhanced head and shoulders detection with trend context
        if len(swing_highs) >= 3:
            try:
                # Look for the best H&S pattern in recent data
                for start_idx in range(max(0, len(swing_highs) - 5), len(swing_highs) - 2):
                    if start_idx + 2 >= len(swing_highs):
                        continue
                        
                    left_shoulder = swing_highs[start_idx]
                    head = swing_highs[start_idx + 1]
                    right_shoulder = swing_highs[start_idx + 2]
                    
                    # Enhanced pattern validation
                    if (left_shoulder['price'] > 0 and head['price'] > 0 and right_shoulder['price'] > 0):
                        # Head must be significantly higher than both shoulders
                        head_prominence = min(
                            (head['price'] - left_shoulder['price']) / left_shoulder['price'],
                            (head['price'] - right_shoulder['price']) / right_shoulder['price']
                        )
                        
                        if head_prominence > 0.005:  # At least 0.5% higher
                            # Shoulders should be relatively equal (within 3%)
                            shoulder_diff = safe_divide(abs(left_shoulder['price'] - right_shoulder['price']), left_shoulder['price'], 0)
                            
                            if shoulder_diff < 0.03:
                                # Check time symmetry (pattern should be somewhat symmetric)
                                left_time = head['index'] - left_shoulder['index']
                                right_time = right_shoulder['index'] - head['index']
                                time_symmetry = safe_divide(min(left_time, right_time), max(left_time, right_time), 0)
                                
                                if time_symmetry > 0.5:  # Reasonable symmetry
                                    # Calculate neckline more accurately
                                    neckline_left = get_neckline_point(df, left_shoulder['index'], head['index'])
                                    neckline_right = get_neckline_point(df, head['index'], right_shoulder['index'])
                                    neckline = (neckline_left + neckline_right) / 2
                                    
                                    # Calculate pattern reliability
                                    reliability = calculate_pattern_reliability(
                                        head_prominence, shoulder_diff, time_symmetry,
                                        left_shoulder.get('volume_ratio', 1),
                                        head.get('volume_ratio', 1),
                                        right_shoulder.get('volume_ratio', 1)
                                    )
                                    
                                    patterns['head_and_shoulders'] = {
                                        'type': 'Head and Shoulders',
                                        'bias': 'Bearish',
                                        'left_shoulder': left_shoulder['price'],
                                        'head': head['price'],
                                        'right_shoulder': right_shoulder['price'],
                                        'neckline': neckline,
                                        'target': neckline - (head['price'] - neckline),
                                        'strength': 'High' if reliability > 0.8 else 'Medium',
                                        'reliability': reliability,
                                        'time_span': right_shoulder['index'] - left_shoulder['index'],
                                        'volume_confirmation': any(swing.get('volume_ratio', 1) > 1.2 for swing in [left_shoulder, head, right_shoulder])
                                    }
                                    break
            except Exception as e:
                print(f"Error in H&S detection: {e}")
        
        # Enhanced inverse head and shoulders detection
        if len(swing_lows) >= 3:
            try:
                for start_idx in range(max(0, len(swing_lows) - 5), len(swing_lows) - 2):
                    if start_idx + 2 >= len(swing_lows):
                        continue
                        
                    left_shoulder = swing_lows[start_idx]
                    head = swing_lows[start_idx + 1]
                    right_shoulder = swing_lows[start_idx + 2]
                    
                    if (left_shoulder['price'] > 0 and head['price'] > 0 and right_shoulder['price'] > 0):
                        # Head must be significantly lower than both shoulders
                        head_prominence = min(
                            safe_divide(left_shoulder['price'] - head['price'], head['price'], 0),
                            safe_divide(right_shoulder['price'] - head['price'], head['price'], 0)
                        )
                        
                        if head_prominence > 0.005:
                            shoulder_diff = safe_divide(abs(left_shoulder['price'] - right_shoulder['price']), left_shoulder['price'], 0)
                            
                            if shoulder_diff < 0.03:
                                left_time = head['index'] - left_shoulder['index']
                                right_time = right_shoulder['index'] - head['index']
                                time_symmetry = safe_divide(min(left_time, right_time), max(left_time, right_time), 0)
                                
                                if time_symmetry > 0.5:
                                    neckline_left = get_neckline_point(df, left_shoulder['index'], head['index'], is_low=False)
                                    neckline_right = get_neckline_point(df, head['index'], right_shoulder['index'], is_low=False)
                                    neckline = (neckline_left + neckline_right) / 2
                                    
                                    reliability = calculate_pattern_reliability(
                                        head_prominence, shoulder_diff, time_symmetry,
                                        left_shoulder.get('volume_ratio', 1),
                                        head.get('volume_ratio', 1),
                                        right_shoulder.get('volume_ratio', 1)
                                    )
                                    
                                    patterns['inverse_head_and_shoulders'] = {
                                        'type': 'Inverse Head and Shoulders',
                                        'bias': 'Bullish',
                                        'left_shoulder': left_shoulder['price'],
                                        'head': head['price'],
                                        'right_shoulder': right_shoulder['price'],
                                        'neckline': neckline,
                                        'target': neckline + (neckline - head['price']),
                                        'strength': 'High' if reliability > 0.8 else 'Medium',
                                        'reliability': reliability,
                                        'time_span': right_shoulder['index'] - left_shoulder['index'],
                                        'volume_confirmation': any(swing.get('volume_ratio', 1) > 1.2 for swing in [left_shoulder, head, right_shoulder])
                                    }
                                    break
            except Exception as e:
                print(f"Error in inverse H&S detection: {e}")
        
        return patterns
        
    except Exception as e:
        print(f"Critical error in detect_head_and_shoulders: {e}")
        return {}

def get_neckline_point(df, start_idx, end_idx, is_low=True):
    """Calculate neckline point between two swing points."""
    try:
        if is_low:
            # For head and shoulders, find the lowest point between shoulders
            section = df['low'].iloc[start_idx:end_idx+1]
            return section.max()
        else:
            # For inverse head and shoulders, find the highest point between shoulders
            section = df['high'].iloc[start_idx:end_idx+1]
            return section.min()
    except:
        return df['close'].iloc[start_idx] if start_idx < len(df) else df['close'].iloc[-1]

def calculate_pattern_reliability(prominence, symmetry_error, time_symmetry, vol1, vol2, vol3):
    """Calculate overall pattern reliability score."""
    try:
        # Prominence score (higher prominence = more reliable)
        prominence_score = min(1.0, prominence * 100)  # Scale to 0-1
        
        # Symmetry score (lower error = more reliable)
        symmetry_score = max(0, 1 - symmetry_error * 10)
        
        # Time symmetry score
        time_score = time_symmetry
        
        # Volume score (higher volume = more reliable)
        avg_volume_ratio = (vol1 + vol2 + vol3) / 3
        volume_score = min(1.0, avg_volume_ratio / 1.5)
        
        # Weighted combination
        reliability = (prominence_score * 0.4 + symmetry_score * 0.3 + 
                      time_score * 0.2 + volume_score * 0.1)
        
        return max(0, min(1, reliability))
    except:
        return 0.5

def detect_triangles(df):
    """Detect triangle patterns with advanced trend line analysis and breakout prediction."""
    patterns = {}

    # Enhanced validation
    if df is None or not hasattr(df, 'empty') or df.empty or len(df) < 30:
        return patterns

    # Validate required columns
    required_columns = ['high', 'low', 'close', 'datetime']
    if not all(col in df.columns for col in required_columns):
        return patterns

    try:
        # Use larger dataset for better pattern recognition
        analysis_data = df.tail(50).copy() if len(df) >= 50 else df.copy()
        
        # Validate data quality
        if analysis_data[['high', 'low', 'close']].isnull().any().any():
            print("Triangle detection: NaN values found in price data")
            return patterns

        # Enhanced swing point detection with variable lookback
        swing_highs = []
        swing_lows = []
        lookback = max(2, len(analysis_data) // 25)  # Dynamic lookback

        for i in range(lookback, len(analysis_data) - lookback):
            try:
                current_high = analysis_data['high'].iloc[i]
                current_low = analysis_data['low'].iloc[i]
                
                if pd.isna(current_high) or pd.isna(current_low):
                    continue

                # Enhanced swing high detection with strength calculation
                is_swing_high = True
                for j in range(i - lookback, i + lookback + 1):
                    if j != i and j >= 0 and j < len(analysis_data):
                        if analysis_data['high'].iloc[j] >= current_high:
                            is_swing_high = False
                            break

                if is_swing_high:
                    # Calculate swing strength based on price movement
                    strength = calculate_swing_strength(analysis_data, i, True)
                    swing_highs.append({
                        'index': i, 
                        'price': float(current_high),
                        'strength': strength,
                        'datetime': analysis_data['datetime'].iloc[i]
                    })

                # Enhanced swing low detection
                is_swing_low = True
                for j in range(i - lookback, i + lookback + 1):
                    if j != i and j >= 0 and j < len(analysis_data):
                        if analysis_data['low'].iloc[j] <= current_low:
                            is_swing_low = False
                            break

                if is_swing_low:
                    strength = calculate_swing_strength(analysis_data, i, False)
                    swing_lows.append({
                        'index': i, 
                        'price': float(current_low),
                        'strength': strength,
                        'datetime': analysis_data['datetime'].iloc[i]
                    })

            except (IndexError, ValueError, TypeError) as e:
                continue

        # Advanced triangle pattern detection
        if len(swing_highs) >= 3 and len(swing_lows) >= 3:
            try:
                # Filter swings by strength (keep only significant ones)
                significant_highs = [s for s in swing_highs if s['strength'] > 0.3]
                significant_lows = [s for s in swing_lows if s['strength'] > 0.3]
                
                if len(significant_highs) >= 2 and len(significant_lows) >= 2:
                    # Calculate trend lines using multiple methods
                    high_trend = calculate_robust_trendline(significant_highs)
                    low_trend = calculate_robust_trendline(significant_lows)
                    
                    if high_trend and low_trend:
                        # Calculate convergence point
                        convergence = calculate_convergence_point(high_trend, low_trend)
                        
                        # Determine triangle type with enhanced criteria
                        triangle_type = classify_triangle_pattern(
                            high_trend, low_trend, significant_highs, significant_lows, analysis_data
                        )
                        
                        if triangle_type:
                            # Calculate pattern reliability and breakout prediction
                            reliability = calculate_triangle_reliability(
                                significant_highs, significant_lows, high_trend, low_trend, analysis_data
                            )
                            
                            breakout_prediction = predict_triangle_breakout(
                                triangle_type, high_trend, low_trend, analysis_data, convergence
                            )
                            
                            # Add the pattern to results
                            pattern_key = triangle_type['type'].lower().replace(' ', '_')
                            patterns[pattern_key] = {
                                **triangle_type,
                                'upper_trendline': high_trend,
                                'lower_trendline': low_trend,
                                'convergence_point': convergence,
                                'reliability': reliability,
                                'breakout_prediction': breakout_prediction,
                                'time_to_apex': convergence.get('time_to_apex', 0),
                                'volume_analysis': analyze_triangle_volume(analysis_data, significant_highs, significant_lows),
                                'swing_count': {'highs': len(significant_highs), 'lows': len(significant_lows)}
                            }

            except Exception as e:
                print(f"Error in advanced triangle detection: {e}")
                return patterns

    except Exception as e:
        print(f"Critical error in triangle detection: {e}")
        return patterns

    return patterns

def calculate_swing_strength(df, index, is_high=True):
    """Calculate the strength of a swing point based on price movement and volume."""
    try:
        if index < 5 or index >= len(df) - 5:
            return 0.5
        
        # Calculate price movement strength
        price_column = 'high' if is_high else 'low'
        current_price = df[price_column].iloc[index]
        
        # Prevent division by zero and NaN
        if pd.isna(current_price) or current_price <= 0:
            return 0.5
        
        # Compare with surrounding prices
        before_prices = df[price_column].iloc[index-5:index].dropna()
        after_prices = df[price_column].iloc[index+1:index+6].dropna()
        
        if len(before_prices) == 0 or len(after_prices) == 0:
            return 0.5
        
        if is_high:
            before_max = before_prices.max()
            after_max = after_prices.max()
            if pd.isna(before_max) or pd.isna(after_max):
                return 0.5
            price_diff = current_price - max(before_max, after_max)
            strength = min(2.0, abs(price_diff) / current_price * 100)
        else:
            before_min = before_prices.min()
            after_min = after_prices.min()
            if pd.isna(before_min) or pd.isna(after_min):
                return 0.5
            price_diff = min(before_min, after_min) - current_price
            strength = min(2.0, abs(price_diff) / current_price * 100)
        
        # Add volume confirmation if available
        if 'volume' in df.columns:
            current_volume = df['volume'].iloc[index]
            avg_volume_data = df['volume'].iloc[max(0, index-10):index+11].dropna()
            if len(avg_volume_data) > 0:
                avg_volume = avg_volume_data.mean()
                if not pd.isna(avg_volume) and avg_volume > 0 and current_volume > avg_volume * 1.5:
                    strength *= 1.3
        
        return max(0, min(1, strength / 2))  # Normalize to 0-1
    except Exception as e:
        print(f"Error in calculate_swing_strength: {e}")
        return 0.5

def calculate_robust_trendline(swing_points):
    """Calculate a robust trend line using multiple regression methods."""
    try:
        if len(swing_points) < 2:
            return None
        
        # Extract x (time indices) and y (prices) coordinates
        x_coords = [point['index'] for point in swing_points]
        y_coords = [point['price'] for point in swing_points]
        
        # Use weighted regression based on swing strength
        weights = [point['strength'] for point in swing_points]
        
        # Calculate trend line using weighted least squares
        trend_line = np.polyfit(x_coords, y_coords, 1, w=weights)
        
        # Calculate R-squared for trend line quality
        y_pred = np.polyval(trend_line, x_coords)
        ss_res = np.sum((y_coords - y_pred) ** 2)
        ss_tot = np.sum((y_coords - safe_mean(y_coords, 0)) ** 2)
        r_squared = 1 - (ss_res / ss_tot) if ss_tot != 0 else 0
        
        return {
            'slope': float(trend_line[0]),
            'intercept': float(trend_line[1]),
            'r_squared': float(r_squared),
            'points_count': len(swing_points),
            'strength_weighted': True
        }
    except:
        return None

def calculate_convergence_point(high_trend, low_trend):
    """Calculate where the two trend lines will converge."""
    try:
        # Solve for intersection: high_slope * x + high_intercept = low_slope * x + low_intercept
        slope_diff = high_trend['slope'] - low_trend['slope']
        
        if abs(slope_diff) < 1e-10:  # Lines are parallel
            return {'converges': False, 'time_to_apex': float('inf')}
        
        intercept_diff = low_trend['intercept'] - high_trend['intercept']
        convergence_x = intercept_diff / slope_diff
        convergence_y = high_trend['slope'] * convergence_x + high_trend['intercept']
        
        # Calculate time to apex (assuming current position is at the last data point)
        current_index = max([point['index'] for trend in [high_trend, low_trend] for point in trend.get('points', [])])
        time_to_apex = max(0, convergence_x - current_index)
        
        return {
            'converges': True,
            'x': float(convergence_x),
            'y': float(convergence_y),
            'time_to_apex': float(time_to_apex)
        }
    except:
        return {'converges': False, 'time_to_apex': float('inf')}

def classify_triangle_pattern(high_trend, low_trend, highs, lows, df):
    """Classify the type of triangle pattern with enhanced criteria."""
    try:
        high_slope = high_trend['slope']
        low_slope = low_trend['slope']
        
        # Calculate price range for context
        price_range = df['high'].max() - df['low'].min()
        slope_threshold = price_range * 0.0001  # Dynamic threshold
        
        # Calculate angle between trend lines for better classification
        slope_diff = abs(high_slope - low_slope)
        convergence_angle = np.arctan(slope_diff) * 180 / np.pi
        
        # Enhanced classification logic
        if abs(high_slope) < slope_threshold and abs(low_slope) < slope_threshold:
            # Both lines relatively flat - rectangle/consolidation
            return {
                'type': 'Rectangle',
                'bias': 'Neutral (Range-bound)',
                'strength': 'Medium',
                'breakout_expected': True,
                'pattern_quality': 'Consolidation'
            }
        elif abs(high_slope) < slope_threshold and low_slope > slope_threshold:
            # Flat top, rising bottom - ascending triangle
            resistance_level = safe_mean([h['price'] for h in highs[-3:]], highs[-1]['price'] if highs else 0)
            return {
                'type': 'Ascending Triangle',
                'bias': 'Bullish',
                'resistance_level': float(resistance_level),
                'strength': 'High' if convergence_angle > 10 else 'Medium',
                'breakout_expected': True,
                'pattern_quality': 'Strong' if high_trend['r_squared'] > 0.7 else 'Moderate'
            }
        elif high_slope < -slope_threshold and abs(low_slope) < slope_threshold:
            # Falling top, flat bottom - descending triangle
            support_level = np.mean([l['price'] for l in lows[-3:]])
            return {
                'type': 'Descending Triangle',
                'bias': 'Bearish',
                'support_level': float(support_level),
                'strength': 'High' if convergence_angle > 10 else 'Medium',
                'breakout_expected': True,
                'pattern_quality': 'Strong' if low_trend['r_squared'] > 0.7 else 'Moderate'
            }
        elif high_slope < -slope_threshold and low_slope > slope_threshold:
            # Both lines converging - symmetrical triangle
            return {
                'type': 'Symmetrical Triangle',
                'bias': 'Neutral (Breakout Direction)',
                'strength': 'High' if convergence_angle > 15 else 'Medium',
                'breakout_expected': True,
                'pattern_quality': 'Strong' if min(high_trend['r_squared'], low_trend['r_squared']) > 0.6 else 'Moderate'
            }
        elif high_slope > slope_threshold and low_slope > slope_threshold:
            # Both lines rising - broadening formation
            return {
                'type': 'Broadening Formation',
                'bias': 'Volatile (High uncertainty)',
                'strength': 'Low',
                'breakout_expected': False,
                'pattern_quality': 'Uncertain'
            }
        
        return None
    except:
        return None

def calculate_triangle_reliability(highs, lows, high_trend, low_trend, df):
    """Calculate the reliability score of the triangle pattern."""
    try:
        score = 0.0
        
        # Trend line quality (R-squared values)
        avg_r_squared = (high_trend['r_squared'] + low_trend['r_squared']) / 2
        score += avg_r_squared * 0.3
        
        # Number of touch points
        touch_points = len(highs) + len(lows)
        touch_score = min(1.0, (touch_points - 4) / 6)  # 4-10 touch points optimal
        score += touch_score * 0.25
        
        # Time span of pattern (longer = more reliable)
        if highs and lows:
            pattern_span = max([h['index'] for h in highs] + [l['index'] for l in lows]) - \
                          min([h['index'] for h in highs] + [l['index'] for l in lows])
            time_score = min(1.0, pattern_span / 30)  # Normalize to 30 periods
            score += time_score * 0.2
        
        # Volume confirmation
        if 'volume' in df.columns:
            # Check if volume decreases as pattern progresses (typical for triangles)
            recent_volume = df['volume'].tail(10).mean()
            earlier_volume = df['volume'].iloc[-30:-20].mean() if len(df) >= 30 else recent_volume
            
            if recent_volume < earlier_volume:  # Decreasing volume is good for triangles
                score += 0.15
        
        # Price action quality (lower volatility within pattern)
        pattern_start = min([h['index'] for h in highs] + [l['index'] for l in lows])
        pattern_data = df.iloc[pattern_start:]
        volatility = (pattern_data['high'] - pattern_data['low']).std()
        overall_volatility = (df['high'] - df['low']).std()
        
        if volatility < overall_volatility:  # Lower volatility within pattern
            score += 0.1
        
        return max(0, min(1, score))
    except:
        return 0.5

def predict_triangle_breakout(triangle_type, high_trend, low_trend, df, convergence):
    """Predict the likely direction and timing of triangle breakout."""
    try:
        prediction = {
            'direction': 'Unknown',
            'probability': 0.5,
            'target': None,
            'timing': 'Unknown'
        }
        
        # Pattern-based bias
        if triangle_type['bias'] == 'Bullish':
            prediction['direction'] = 'Upward'
            prediction['probability'] = 0.65
        elif triangle_type['bias'] == 'Bearish':
            prediction['direction'] = 'Downward'
            prediction['probability'] = 0.65
        else:
            # For symmetrical triangles, analyze momentum
            recent_closes = df['close'].tail(5)
            momentum = (recent_closes.iloc[-1] - recent_closes.iloc[0]) / recent_closes.iloc[0]
            
            if momentum > 0.005:  # 0.5% upward momentum
                prediction['direction'] = 'Upward'
                prediction['probability'] = 0.55
            elif momentum < -0.005:
                prediction['direction'] = 'Downward'
                prediction['probability'] = 0.55
        
        # Calculate price target
        current_price = df['close'].iloc[-1]
        pattern_height = abs(df['high'].tail(20).max() - df['low'].tail(20).min())
        
        if prediction['direction'] == 'Upward':
            prediction['target'] = current_price + pattern_height
        elif prediction['direction'] == 'Downward':
            prediction['target'] = current_price - pattern_height
        
        # Timing prediction based on convergence
        if convergence['converges']:
            time_to_apex = convergence['time_to_apex']
            if time_to_apex < 5:
                prediction['timing'] = 'Imminent (within 5 periods)'
            elif time_to_apex < 15:
                prediction['timing'] = f'Near-term (within {int(time_to_apex)} periods)'
            else:
                prediction['timing'] = 'Long-term'
        
        return prediction
    except:
        return {'direction': 'Unknown', 'probability': 0.5, 'target': None, 'timing': 'Unknown'}

def analyze_triangle_volume(df, highs, lows):
    """Analyze volume patterns within the triangle."""
    try:
        if 'volume' not in df.columns:
            return {'available': False}
        
        # Get pattern timeframe
        pattern_start = min([h['index'] for h in highs] + [l['index'] for l in lows])
        pattern_data = df.iloc[pattern_start:]
        
        # Calculate volume trend
        volumes = pattern_data['volume'].values
        x_vals = np.arange(len(volumes))
        
        if len(volumes) > 3:
            volume_trend = np.polyfit(x_vals, volumes, 1)[0]
            
            return {
                'available': True,
                'trend': 'Decreasing' if volume_trend < 0 else 'Increasing',
                'trend_strength': abs(volume_trend),
                'current_vs_average': volumes[-1] / volumes.mean() if volumes.mean() > 0 else 1.0,
                'pattern_typical': volume_trend < 0  # Decreasing volume is typical for triangles
            }
        
        return {'available': True, 'trend': 'Insufficient data'}
    except:
        return {'available': False}

def detect_flags_pennants(df):
    """Detect flag and pennant patterns with enhanced momentum analysis."""
    patterns = {}
    if len(df) < 20:
        return patterns
    
    try:
        # Analyze multiple timeframes for better pattern recognition
        for flagpole_length in [8, 12, 16]:  # Different flagpole lengths
            if len(df) < flagpole_length + 10:
                continue
                
            # Get flagpole data
            flagpole_start = len(df) - flagpole_length - 10
            flagpole_end = len(df) - 10
            flagpole_data = df.iloc[flagpole_start:flagpole_end]
            
            # Get consolidation data
            consolidation_data = df.tail(10)
            
            if len(flagpole_data) < 5 or len(consolidation_data) < 5:
                continue
            
            # Analyze flagpole characteristics
            flagpole_analysis = analyze_flagpole(flagpole_data)
            
            if flagpole_analysis['is_valid']:
                # Analyze consolidation pattern
                consolidation_analysis = analyze_consolidation(consolidation_data, flagpole_analysis)
                
                if consolidation_analysis['is_valid']:
                    # Determine pattern type (flag vs pennant)
                    pattern_type = classify_flag_pennant(consolidation_analysis, flagpole_analysis)
                    
                    if pattern_type:
                        # Calculate pattern reliability and targets
                        reliability = calculate_flag_pennant_reliability(
                            flagpole_analysis, consolidation_analysis, df
                        )
                        
                        targets = calculate_flag_pennant_targets(
                            flagpole_analysis, consolidation_analysis, df
                        )
                        
                        # Create pattern result
                        direction = 'bullish' if flagpole_analysis['direction'] == 'up' else 'bearish'
                        pattern_key = f"{direction}_{pattern_type['type'].lower()}"
                        
                        patterns[pattern_key] = {
                            'type': f"{flagpole_analysis['direction'].title()} {pattern_type['type']}",
                            'bias': 'Bullish' if direction == 'bullish' else 'Bearish',
                            'flagpole_move': flagpole_analysis['magnitude'] * 100,
                            'flagpole_strength': flagpole_analysis['strength'],
                            'consolidation_type': consolidation_analysis['pattern_type'],
                            'consolidation_tightness': consolidation_analysis['tightness'],
                            'volume_confirmation': flagpole_analysis.get('volume_confirmation', False),
                            'reliability': reliability,
                            'targets': targets,
                            'strength': 'High' if reliability > 0.8 else 'Medium' if reliability > 0.6 else 'Low',
                            'time_frame': flagpole_length,
                            'breakout_probability': calculate_breakout_probability(flagpole_analysis, consolidation_analysis)
                        }
                        break  # Use the best pattern found
    
    except Exception as e:
        print(f"Error in flag/pennant detection: {e}")
    
    return patterns

def analyze_flagpole(flagpole_data):
    """Analyze the flagpole characteristics for flag/pennant patterns."""
    try:
        analysis = {
            'is_valid': False,
            'direction': None,
            'magnitude': 0,
            'strength': 0,
            'volume_confirmation': False,
            'momentum_quality': 'Low'
        }
        
        if len(flagpole_data) < 5:
            return analysis
        
        start_price = flagpole_data['close'].iloc[0]
        end_price = flagpole_data['close'].iloc[-1]
        
        # Calculate price movement
        price_change = (end_price - start_price) / start_price
        analysis['magnitude'] = abs(price_change)
        analysis['direction'] = 'up' if price_change > 0 else 'down'
        
        # Minimum movement threshold (1.5% for forex, 3% for crypto)
        min_threshold = 0.015
        if analysis['magnitude'] < min_threshold:
            return analysis
        
        # Analyze momentum quality
        daily_returns = flagpole_data['close'].pct_change().dropna()
        
        # Check for consistent directional movement
        if analysis['direction'] == 'up':
            positive_days = (daily_returns > 0).sum()
            momentum_consistency = positive_days / len(daily_returns)
        else:
            negative_days = (daily_returns < 0).sum()
            momentum_consistency = negative_days / len(daily_returns)
        
        # Strong flagpole should have > 60% consistent moves
        if momentum_consistency > 0.6:
            analysis['momentum_quality'] = 'High'
            analysis['strength'] = min(1.0, momentum_consistency * 1.5)
        elif momentum_consistency > 0.4:
            analysis['momentum_quality'] = 'Medium'
            analysis['strength'] = momentum_consistency
        else:
            return analysis  # Weak momentum
        
        # Volume analysis (if available)
        if 'volume' in flagpole_data.columns:
            flagpole_volume = flagpole_data['volume'].mean()
            # Compare with longer-term average
            if len(flagpole_data) > 10:
                long_term_volume = flagpole_data['volume'].rolling(window=20).mean().iloc[-1]
                if flagpole_volume > long_term_volume * 1.3:
                    analysis['volume_confirmation'] = True
                    analysis['strength'] *= 1.2
        
        # Calculate velocity (price change per period)
        analysis['velocity'] = analysis['magnitude'] / len(flagpole_data)
        
        # Strong flagpoles should be relatively quick
        if analysis['velocity'] > 0.002:  # 0.2% per period
            analysis['strength'] *= 1.1
        
        analysis['is_valid'] = True
        return analysis
        
    except Exception as e:
        print(f"Error in flagpole analysis: {e}")
        return {'is_valid': False, 'direction': None, 'magnitude': 0, 'strength': 0}

def analyze_consolidation(consolidation_data, flagpole_analysis):
    """Analyze the consolidation pattern after the flagpole."""
    try:
        analysis = {
            'is_valid': False,
            'pattern_type': None,
            'tightness': 0,
            'slope': 0,
            'volume_decline': False
        }
        
        if len(consolidation_data) < 5:
            return analysis
        
        # Calculate consolidation range
        high_price = consolidation_data['high'].max()
        low_price = consolidation_data['low'].min()
        consolidation_range = high_price - low_price
        avg_price = consolidation_data['close'].mean()
        
        # Calculate tightness (smaller range = tighter consolidation)
        analysis['tightness'] = 1 - (consolidation_range / avg_price) / 0.02  # Normalize to 2% range
        analysis['tightness'] = max(0, min(1, analysis['tightness']))
        
        # Consolidation should be tight relative to flagpole
        flagpole_range = flagpole_analysis['magnitude']
        relative_tightness = consolidation_range / (avg_price * flagpole_range)
        
        if relative_tightness > 0.5:  # Consolidation too wide
            return analysis
        
        # Analyze consolidation trend (flag vs pennant)
        closes = consolidation_data['close'].values
        x_vals = np.arange(len(closes))
        
        try:
            trend_line = np.polyfit(x_vals, closes, 1)
            analysis['slope'] = trend_line[0]
            
            # Classify pattern type based on slope and shape
            slope_threshold = avg_price * 0.0001  # Small threshold for flat patterns
            
            if abs(analysis['slope']) < slope_threshold:
                # Relatively flat - rectangle or pennant
                if analysis['tightness'] > 0.7:
                    analysis['pattern_type'] = 'Pennant'
                else:
                    analysis['pattern_type'] = 'Rectangle'
            else:
                # Sloped consolidation - flag
                if flagpole_analysis['direction'] == 'up' and analysis['slope'] < 0:
                    analysis['pattern_type'] = 'Flag'  # Pullback flag
                elif flagpole_analysis['direction'] == 'down' and analysis['slope'] > 0:
                    analysis['pattern_type'] = 'Flag'  # Rally flag
                else:
                    analysis['pattern_type'] = 'Continuation Pattern'
        
        except np.linalg.LinAlgError:
            analysis['pattern_type'] = 'Irregular'
        
        # Volume analysis during consolidation
        if 'volume' in consolidation_data.columns:
            early_volume = consolidation_data['volume'].iloc[:3].mean()
            late_volume = consolidation_data['volume'].iloc[-3:].mean()
            
            if late_volume < early_volume * 0.8:  # Volume declining
                analysis['volume_decline'] = True
                analysis['tightness'] *= 1.1  # Bonus for volume confirmation
        
        # Pattern validation
        if (analysis['tightness'] > 0.4 and 
            analysis['pattern_type'] in ['Flag', 'Pennant', 'Rectangle']):
            analysis['is_valid'] = True
        
        return analysis
        
    except Exception as e:
        print(f"Error in consolidation analysis: {e}")
        return {'is_valid': False, 'pattern_type': None, 'tightness': 0}

def classify_flag_pennant(consolidation_analysis, flagpole_analysis):
    """Classify the specific type of flag or pennant pattern."""
    try:
        pattern_type = consolidation_analysis['pattern_type']
        
        if pattern_type == 'Flag':
            # Determine flag orientation
            if flagpole_analysis['direction'] == 'up':
                if consolidation_analysis['slope'] < 0:
                    return {'type': 'Bull Flag', 'quality': 'High'}
                else:
                    return {'type': 'Bull Flag (Weak)', 'quality': 'Medium'}
            else:
                if consolidation_analysis['slope'] > 0:
                    return {'type': 'Bear Flag', 'quality': 'High'}
                else:
                    return {'type': 'Bear Flag (Weak)', 'quality': 'Medium'}
        
        elif pattern_type == 'Pennant':
            direction = flagpole_analysis['direction']
            return {
                'type': f"{'Bull' if direction == 'up' else 'Bear'} Pennant",
                'quality': 'High' if consolidation_analysis['tightness'] > 0.7 else 'Medium'
            }
        
        elif pattern_type == 'Rectangle':
            direction = flagpole_analysis['direction']
            return {
                'type': f"{'Bull' if direction == 'up' else 'Bear'} Rectangle",
                'quality': 'Medium'
            }
        
        return None
        
    except Exception as e:
        print(f"Error in pattern classification: {e}")
        return None

def calculate_flag_pennant_reliability(flagpole_analysis, consolidation_analysis, df):
    """Calculate the reliability score for flag/pennant patterns."""
    try:
        score = 0.0
        
        # Flagpole strength (40% weight)
        score += flagpole_analysis['strength'] * 0.4
        
        # Consolidation tightness (30% weight)
        score += consolidation_analysis['tightness'] * 0.3
        
        # Volume confirmation (15% weight)
        if flagpole_analysis.get('volume_confirmation'):
            score += 0.15
        if consolidation_analysis.get('volume_decline'):
            score += 0.05
        
        # Pattern duration (10% weight) - not too long, not too short
        total_pattern_length = flagpole_analysis.get('time_frame', 10) + 10
        duration_score = 1.0 if 15 <= total_pattern_length <= 25 else 0.7
        score += duration_score * 0.1
        
        # Momentum quality bonus (5% weight)
        if flagpole_analysis.get('momentum_quality') == 'High':
            score += 0.05
        elif flagpole_analysis.get('momentum_quality') == 'Medium':
            score += 0.025
        
        return max(0, min(1, score))
        
    except Exception as e:
        print(f"Error in reliability calculation: {e}")
        return 0.5

def calculate_flag_pennant_targets(flagpole_analysis, consolidation_analysis, df):
    """Calculate price targets for flag/pennant breakouts."""
    try:
        current_price = df['close'].iloc[-1]
        flagpole_magnitude = flagpole_analysis['magnitude']
        direction = flagpole_analysis['direction']
        
        # Primary target: length of flagpole projected from breakout
        if direction == 'up':
            primary_target = current_price * (1 + flagpole_magnitude)
            conservative_target = current_price * (1 + flagpole_magnitude * 0.618)  # 61.8% projection
        else:
            primary_target = current_price * (1 - flagpole_magnitude)
            conservative_target = current_price * (1 - flagpole_magnitude * 0.618)
        
        # Stop loss: opposite side of consolidation
        if direction == 'up':
            stop_loss = df.tail(10)['low'].min()
        else:
            stop_loss = df.tail(10)['high'].max()
        
        # Calculate risk-reward ratio
        risk = abs(current_price - stop_loss)
        reward = abs(primary_target - current_price)
        risk_reward_ratio = reward / risk if risk > 0 else 0
        
        return {
            'primary_target': float(primary_target),
            'conservative_target': float(conservative_target),
            'stop_loss': float(stop_loss),
            'risk_reward_ratio': float(risk_reward_ratio),
            'breakout_confirmation': current_price  # Breakout level to watch
        }
        
    except Exception as e:
        print(f"Error in target calculation: {e}")
        return {}

def calculate_breakout_probability(flagpole_analysis, consolidation_analysis):
    """Calculate the probability of successful breakout continuation."""
    try:
        base_probability = 0.65  # Base probability for continuation patterns
        
        # Adjust based on pattern strength
        strength_bonus = (flagpole_analysis['strength'] - 0.5) * 0.2
        tightness_bonus = (consolidation_analysis['tightness'] - 0.5) * 0.15
        
        # Volume confirmation bonus
        volume_bonus = 0.1 if flagpole_analysis.get('volume_confirmation') else 0
        volume_decline_bonus = 0.05 if consolidation_analysis.get('volume_decline') else 0
        
        # Pattern type bonus
        pattern_bonus = 0.1 if consolidation_analysis['pattern_type'] in ['Flag', 'Pennant'] else 0
        
        probability = base_probability + strength_bonus + tightness_bonus + volume_bonus + volume_decline_bonus + pattern_bonus
        
        return max(0.3, min(0.9, probability))  # Cap between 30% and 90%
        
    except Exception as e:
        print(f"Error in breakout probability calculation: {e}")
        return 0.65

def detect_double_patterns(df):
    """Detect double top and double bottom patterns."""
    patterns = {}
    if len(df) < 20:
        return patterns
    
    # Find swing highs and lows
    swing_highs = []
    swing_lows = []
    
    for i in range(2, len(df) - 2):
        if (df['high'].iloc[i] > df['high'].iloc[i-1] and 
            df['high'].iloc[i] > df['high'].iloc[i-2] and
            df['high'].iloc[i] > df['high'].iloc[i+1] and 
            df['high'].iloc[i] > df['high'].iloc[i+2]):
            swing_highs.append({'index': i, 'price': df['high'].iloc[i]})
        
        if (df['low'].iloc[i] < df['low'].iloc[i-1] and 
            df['low'].iloc[i] < df['low'].iloc[i-2] and
            df['low'].iloc[i] < df['low'].iloc[i+1] and 
            df['low'].iloc[i] < df['low'].iloc[i+2]):
            swing_lows.append({'index': i, 'price': df['low'].iloc[i]})
    
    # Check for double top
    if len(swing_highs) >= 2:
        last_two_highs = swing_highs[-2:]
        price_diff = abs(last_two_highs[0]['price'] - last_two_highs[1]['price'])
        avg_price = (last_two_highs[0]['price'] + last_two_highs[1]['price']) / 2
        
        if price_diff / avg_price < 0.01:  # Peaks within 1% of each other
            patterns['double_top'] = {
                'type': 'Double Top',
                'bias': 'Bearish',
                'first_peak': last_two_highs[0]['price'],
                'second_peak': last_two_highs[1]['price'],
                'strength': 'High'
            }
    
    # Check for double bottom
    if len(swing_lows) >= 2:
        last_two_lows = swing_lows[-2:]
        price_diff = abs(last_two_lows[0]['price'] - last_two_lows[1]['price'])
        avg_price = (last_two_lows[0]['price'] + last_two_lows[1]['price']) / 2
        
        if price_diff / avg_price < 0.01:  # Troughs within 1% of each other
            patterns['double_bottom'] = {
                'type': 'Double Bottom',
                'bias': 'Bullish',
                'first_trough': last_two_lows[0]['price'],
                'second_trough': last_two_lows[1]['price'],
                'strength': 'High'
            }
    
    return patterns

def detect_wedges(df):
    """Detect rising and falling wedge patterns with enhanced convergence analysis."""
    patterns = {}
    if len(df) < 25:
        return patterns
    
    try:
        # Analyze multiple timeframes for better pattern recognition
        for window_size in [20, 30, 40]:
            if len(df) < window_size:
                continue
                
            analysis_data = df.tail(window_size)
            wedge_result = analyze_wedge_pattern(analysis_data, window_size)
            
            if wedge_result and wedge_result.get('is_valid'):
                # Calculate additional metrics
                enhanced_metrics = calculate_wedge_metrics(analysis_data, wedge_result)
                
                # Combine results
                pattern_key = wedge_result['type'].lower().replace(' ', '_')
                patterns[pattern_key] = {
                    **wedge_result,
                    **enhanced_metrics,
                    'analysis_window': window_size
                }
                break  # Use the best pattern found
        
        return patterns
        
    except Exception as e:
        print(f"Error in wedge detection: {e}")
        return {}

def analyze_wedge_pattern(df, window_size):
    """Analyze wedge pattern characteristics with enhanced validation."""
    try:
        # Find swing points with enhanced criteria
        swing_highs = []
        swing_lows = []
        lookback = max(2, window_size // 15)
        
        for i in range(lookback, len(df) - lookback):
            current_high = df['high'].iloc[i]
            current_low = df['low'].iloc[i]
            
            # Enhanced swing high detection
            is_swing_high = True
            for j in range(i - lookback, i + lookback + 1):
                if j != i and df['high'].iloc[j] >= current_high:
                    is_swing_high = False
                    break
            
            if is_swing_high:
                swing_highs.append({'index': i, 'price': current_high})
            
            # Enhanced swing low detection
            is_swing_low = True
            for j in range(i - lookback, i + lookback + 1):
                if j != i and df['low'].iloc[j] <= current_low:
                    is_swing_low = False
                    break
            
            if is_swing_low:
                swing_lows.append({'index': i, 'price': current_low})
        
        # Require minimum swing points
        if len(swing_highs) < 3 or len(swing_lows) < 3:
            return None
        
        # Calculate trend lines
        high_x = [s['index'] for s in swing_highs]
        high_y = [s['price'] for s in swing_highs]
        low_x = [s['index'] for s in swing_lows]
        low_y = [s['price'] for s in swing_lows]
        
        # Fit trend lines with error handling
        try:
            high_trend = np.polyfit(high_x, high_y, 1)
            low_trend = np.polyfit(low_x, low_y, 1)
        except np.linalg.LinAlgError:
            return None
        
        high_slope = high_trend[0]
        low_slope = low_trend[0]
        
        # Calculate convergence
        convergence_analysis = analyze_wedge_convergence(high_trend, low_trend, df)
        
        if not convergence_analysis['converges']:
            return None
        
        # Determine wedge type with enhanced criteria
        price_range = df['high'].max() - df['low'].min()
        slope_threshold = price_range * 0.00005  # Very sensitive threshold
        
        # Calculate slope relationship and convergence angle
        slope_ratio = abs(low_slope / high_slope) if high_slope != 0 else 1
        convergence_angle = convergence_analysis['convergence_angle']
        
        # Enhanced wedge classification
        if (high_slope > slope_threshold and low_slope > slope_threshold and 
            convergence_angle > 5 and convergence_angle < 45):  # Both upward, converging
            
            if low_slope > high_slope * 1.1:  # Lower line rising faster
                wedge_type = 'Rising Wedge'
                bias = 'Bearish'
                reliability = calculate_wedge_reliability(swing_highs, swing_lows, high_trend, low_trend, df, 'rising')
            else:
                return None  # Not a valid rising wedge
                
        elif (high_slope < -slope_threshold and low_slope < -slope_threshold and 
              convergence_angle > 5 and convergence_angle < 45):  # Both downward, converging
              
            if high_slope > low_slope * 1.1:  # Upper line falling slower (converging)
                wedge_type = 'Falling Wedge'
                bias = 'Bullish'
                reliability = calculate_wedge_reliability(swing_highs, swing_lows, high_trend, low_trend, df, 'falling')
            else:
                return None  # Not a valid falling wedge
        else:
            return None  # Not a wedge pattern
        
        # Calculate pattern quality metrics
        pattern_quality = assess_wedge_quality(swing_highs, swing_lows, high_trend, low_trend, df)
        
        # Volume analysis
        volume_analysis = analyze_wedge_volume(df) if 'volume' in df.columns else {}
        
        return {
            'type': wedge_type,
            'bias': bias,
            'is_valid': True,
            'upper_slope': float(high_slope),
            'lower_slope': float(low_slope),
            'convergence_point': convergence_analysis['convergence_point'],
            'convergence_angle': convergence_angle,
            'time_to_apex': convergence_analysis['time_to_apex'],
            'reliability': reliability,
            'pattern_quality': pattern_quality,
            'volume_analysis': volume_analysis,
            'swing_points': {'highs': len(swing_highs), 'lows': len(swing_lows)},
            'strength': 'High' if reliability > 0.8 else 'Medium' if reliability > 0.6 else 'Low'
        }
        
    except Exception as e:
        print(f"Error in wedge pattern analysis: {e}")
        return None

def analyze_wedge_convergence(high_trend, low_trend, df):
    """Analyze the convergence characteristics of wedge trend lines."""
    try:
        high_slope, high_intercept = high_trend
        low_slope, low_intercept = low_trend
        
        # Calculate intersection point
        slope_diff = high_slope - low_slope
        
        if abs(slope_diff) < 1e-10:  # Parallel lines
            return {'converges': False, 'convergence_angle': 0}
        
        # Solve for intersection
        convergence_x = (low_intercept - high_intercept) / slope_diff
        convergence_y = high_slope * convergence_x + high_intercept
        
        # Calculate convergence angle
        angle_rad = np.arctan(abs(slope_diff))
        convergence_angle = np.degrees(angle_rad)
        
        # Time to apex from current position
        current_index = len(df) - 1
        time_to_apex = max(0, convergence_x - current_index)
        
        return {
            'converges': True,
            'convergence_point': {'x': float(convergence_x), 'y': float(convergence_y)},
            'convergence_angle': float(convergence_angle),
            'time_to_apex': float(time_to_apex)
        }
        
    except Exception as e:
        print(f"Error in convergence analysis: {e}")
        return {'converges': False, 'convergence_angle': 0}

def calculate_wedge_reliability(swing_highs, swing_lows, high_trend, low_trend, df, wedge_type):
    """Calculate the reliability score for wedge patterns."""
    try:
        score = 0.0
        
        # Touch points quality (30% weight)
        total_touches = len(swing_highs) + len(swing_lows)
        touch_score = min(1.0, (total_touches - 6) / 4)  # 6-10 touches optimal
        score += touch_score * 0.3
        
        # Trend line fit quality (25% weight)
        high_r_squared = calculate_r_squared([s['index'] for s in swing_highs], 
                                           [s['price'] for s in swing_highs], high_trend)
        low_r_squared = calculate_r_squared([s['index'] for s in swing_lows], 
                                          [s['price'] for s in swing_lows], low_trend)
        
        avg_r_squared = (high_r_squared + low_r_squared) / 2
        score += avg_r_squared * 0.25
        
        # Pattern span (20% weight) - longer patterns more reliable
        pattern_span = max([s['index'] for s in swing_highs] + [s['index'] for s in swing_lows]) - \
                      min([s['index'] for s in swing_highs] + [s['index'] for s in swing_lows])
        span_score = min(1.0, pattern_span / 25)  # Normalize to 25 periods
        score += span_score * 0.2
        
        # Volume confirmation (15% weight)
        if 'volume' in df.columns:
            volume_score = analyze_wedge_volume_pattern(df, wedge_type)
            score += volume_score * 0.15
        
        # Price action within wedge (10% weight)
        # Wedges should show decreasing volatility
        pattern_start = min([s['index'] for s in swing_highs] + [s['index'] for s in swing_lows])
        pattern_data = df.iloc[pattern_start:]
        
        if len(pattern_data) > 5:
            early_volatility = (pattern_data['high'] - pattern_data['low']).iloc[:len(pattern_data)//2].mean()
            late_volatility = (pattern_data['high'] - pattern_data['low']).iloc[len(pattern_data)//2:].mean()
            
            if late_volatility < early_volatility:  # Decreasing volatility
                score += 0.1
        
        return max(0, min(1, score))
        
    except Exception as e:
        print(f"Error in wedge reliability calculation: {e}")
        return 0.5

def calculate_r_squared(x_vals, y_vals, trend_line):
    """Calculate R-squared for trend line fit quality."""
    try:
        if len(x_vals) < 2 or len(y_vals) < 2:
            return 0
        
        y_pred = np.polyval(trend_line, x_vals)
        ss_res = np.sum((y_vals - y_pred) ** 2)
        ss_tot = np.sum((y_vals - np.mean(y_vals)) ** 2)
        
        return 1 - (ss_res / ss_tot) if ss_tot != 0 else 0
        
    except:
        return 0

def analyze_wedge_volume_pattern(df, wedge_type):
    """Analyze volume patterns specific to wedge formations."""
    try:
        if 'volume' not in df.columns or len(df) < 10:
            return 0.5
        
        volumes = df['volume'].values
        
        # Volume should generally decrease in wedges (consolidation)
        x_vals = np.arange(len(volumes))
        volume_trend = np.polyfit(x_vals, volumes, 1)[0]
        
        # Decreasing volume is positive for wedges
        volume_score = 0.7 if volume_trend < 0 else 0.3
        
        # Check for volume spikes at swing points (can indicate false breakouts)
        recent_volumes = volumes[-5:]
        avg_volume = volumes.mean()
        
        spike_count = sum(1 for v in recent_volumes if v > avg_volume * 2)
        if spike_count == 0:  # No recent spikes is good
            volume_score += 0.3
        elif spike_count <= 1:  # One spike acceptable
            volume_score += 0.1
        
        return min(1.0, volume_score)
        
    except:
        return 0.5

def assess_wedge_quality(swing_highs, swing_lows, high_trend, low_trend, df):
    """Assess overall quality metrics for the wedge pattern."""
    try:
        quality = {}
        
        # Pattern symmetry
        high_span = max([s['index'] for s in swing_highs]) - min([s['index'] for s in swing_highs])
        low_span = max([s['index'] for s in swing_lows]) - min([s['index'] for s in swing_lows])
        
        if min(high_span, low_span) > 0:
            symmetry = min(high_span, low_span) / max(high_span, low_span)
            quality['symmetry'] = symmetry
            quality['symmetry_rating'] = 'High' if symmetry > 0.8 else 'Medium' if symmetry > 0.6 else 'Low'
        
        # Touch point distribution
        high_touches = len(swing_highs)
        low_touches = len(swing_lows)
        total_touches = high_touches + low_touches
        
        quality['total_touches'] = total_touches
        quality['touch_balance'] = min(high_touches, low_touches) / max(high_touches, low_touches) if max(high_touches, low_touches) > 0 else 0
        
        # Pattern maturity (how close to apex)
        convergence = analyze_wedge_convergence(high_trend, low_trend, df)
        if convergence['converges']:
            time_to_apex = convergence['time_to_apex']
            if time_to_apex < 5:
                quality['maturity'] = 'Mature (near apex)'
            elif time_to_apex < 15:
                quality['maturity'] = 'Developing'
            else:
                quality['maturity'] = 'Early stage'
        
        return quality
        
    except Exception as e:
        print(f"Error in wedge quality assessment: {e}")
        return {}

def analyze_wedge_volume(df):
    """Comprehensive volume analysis for wedge patterns."""
    try:
        if 'volume' not in df.columns:
            return {'available': False}
        
        volumes = df['volume'].values
        
        # Overall volume trend
        x_vals = np.arange(len(volumes))
        volume_trend_slope = np.polyfit(x_vals, volumes, 1)[0]
        
        # Volume distribution analysis
        early_volume = volumes[:len(volumes)//3].mean()
        middle_volume = volumes[len(volumes)//3:2*len(volumes)//3].mean()
        late_volume = volumes[2*len(volumes)//3:].mean()
        
        # Volume spikes detection
        avg_volume = volumes.mean()
        std_volume = volumes.std()
        spike_threshold = avg_volume + 2 * std_volume
        
        spikes = [i for i, v in enumerate(volumes) if v > spike_threshold]
        
        return {
            'available': True,
            'trend': 'Decreasing' if volume_trend_slope < 0 else 'Increasing',
            'trend_strength': abs(volume_trend_slope),
            'early_volume': early_volume,
            'middle_volume': middle_volume,
            'late_volume': late_volume,
            'volume_progression': 'Declining' if late_volume < early_volume else 'Rising',
            'spike_count': len(spikes),
            'average_volume': avg_volume,
            'wedge_typical': volume_trend_slope < 0 and len(spikes) <= 2  # Typical wedge characteristics
        }
        
    except Exception as e:
        print(f"Error in wedge volume analysis: {e}")
        return {'available': False}

def calculate_wedge_metrics(df, wedge_result):
    """Calculate additional metrics for wedge patterns."""
    try:
        current_price = df['close'].iloc[-1]
        
        # Breakout targets
        pattern_height = df['high'].max() - df['low'].min()
        
        if wedge_result['bias'] == 'Bullish':
            target = current_price + pattern_height * 0.618  # Conservative target
            aggressive_target = current_price + pattern_height
            stop_loss = df['low'].tail(10).min()
        else:
            target = current_price - pattern_height * 0.618
            aggressive_target = current_price - pattern_height
            stop_loss = df['high'].tail(10).max()
        
        # Risk-reward calculation
        risk = abs(current_price - stop_loss)
        reward = abs(target - current_price)
        risk_reward = reward / risk if risk > 0 else 0
        
        # Breakout probability based on position within wedge
        time_to_apex = wedge_result.get('time_to_apex', float('inf'))
        if time_to_apex < 3:
            breakout_probability = 0.8  # High probability near apex
        elif time_to_apex < 10:
            breakout_probability = 0.65
        else:
            breakout_probability = 0.45  # Lower probability far from apex
        
        return {
            'targets': {
                'conservative': float(target),
                'aggressive': float(aggressive_target),
                'stop_loss': float(stop_loss)
            },
            'risk_reward_ratio': float(risk_reward),
            'breakout_probability': breakout_probability,
            'pattern_height': float(pattern_height),
            'current_position': 'Near apex' if time_to_apex < 5 else 'Mid-pattern' if time_to_apex < 15 else 'Early stage'
        }
        
    except Exception as e:
        print(f"Error calculating wedge metrics: {e}")
        return {}

def detect_channels(df):
    """Detect price channels."""
    patterns = {}
    if len(df) < 30:
        return patterns
    
    recent_data = df.tail(30)
    highs = recent_data['high'].values
    lows = recent_data['low'].values
    
    # Check for parallel trend lines
    try:
        x_vals = np.arange(len(highs))
        high_trend = np.polyfit(x_vals, highs, 1)[0]
        low_trend = np.polyfit(x_vals, lows, 1)[0]
        
        # Parallel lines have similar slopes
        if abs(high_trend - low_trend) < 0.0001:
            if high_trend > 0.0001:  # Upward channel
                patterns['ascending_channel'] = {
                    'type': 'Ascending Channel',
                    'bias': 'Bullish (until breakdown)',
                    'slope': high_trend,
                    'strength': 'Medium'
                }
            elif high_trend < -0.0001:  # Downward channel
                patterns['descending_channel'] = {
                    'type': 'Descending Channel',
                    'bias': 'Bearish (until breakout)',
                    'slope': high_trend,
                    'strength': 'Medium'
                }
            else:  # Horizontal channel
                patterns['horizontal_channel'] = {
                    'type': 'Horizontal Channel',
                    'bias': 'Neutral (range-bound)',
                    'resistance': np.mean(highs),
                    'support': np.mean(lows),
                    'strength': 'Medium'
                }
    except:
        pass
    
    return patterns

def detect_cup_and_handle(df):
    """Detect cup and handle pattern."""
    patterns = {}
    if len(df) < 30:
        return patterns
    
    # Look for U-shaped pattern followed by small consolidation
    data = df.tail(30)
    
    # Find the lowest point (bottom of cup)
    lowest_idx = data['low'].idxmin()
    lowest_price = data['low'].min()
    
    # Check for cup formation (U-shape)
    left_side = data.loc[:lowest_idx]
    right_side = data.loc[lowest_idx:]
    
    if len(left_side) >= 10 and len(right_side) >= 10:
        # Check if price recovered on both sides
        left_high = left_side['high'].iloc[0]
        right_high = right_side['high'].iloc[-1]
        
        # Cup criteria: similar heights on both sides, significant dip
        depth = (left_high - lowest_price) / left_high
        height_similarity = abs(left_high - right_high) / left_high
        
        if depth > 0.1 and height_similarity < 0.05:  # Good cup shape
            # Look for handle (small pullback)
            handle_data = right_side.tail(5)
            handle_pullback = (right_high - handle_data['low'].min()) / right_high
            
            if 0.02 < handle_pullback < 0.15:  # Handle pullback 2-15%
                patterns['cup_and_handle'] = {
                    'type': 'Cup and Handle',
                    'bias': 'Bullish',
                    'cup_depth': depth * 100,
                    'handle_pullback': handle_pullback * 100,
                    'breakout_level': right_high,
                    'strength': 'High'
                }
    
    return patterns

def detect_ascending_descending_patterns(df):
    """Detect various ascending/descending patterns."""
    patterns = {}
    if len(df) < 15:
        return patterns
    
    recent_data = df.tail(15)
    
    # Ascending/Descending highs and lows analysis
    highs = recent_data['high'].values
    lows = recent_data['low'].values
    
    # Check for ascending lows (bullish)
    low_trend = np.polyfit(range(len(lows)), lows, 1)[0]
    if low_trend > 0.0001:
        patterns['ascending_lows'] = {
            'type': 'Ascending Lows',
            'bias': 'Bullish',
            'trend_strength': low_trend,
            'strength': 'Medium'
        }
    
    # Check for descending highs (bearish)
    high_trend = np.polyfit(range(len(highs)), highs, 1)[0]
    if high_trend < -0.0001:
        patterns['descending_highs'] = {
            'type': 'Descending Highs',
            'bias': 'Bearish',
            'trend_strength': abs(high_trend),
            'strength': 'Medium'
        }
    
    return patterns



def find_swing_points(df, lookback=3):
    """Find swing highs and lows in price data."""
    swing_highs = []
    swing_lows = []
    
    if len(df) < lookback * 2 + 1:
        return swing_highs, swing_lows
    
    for i in range(lookback, len(df) - lookback):
        # Check for swing high
        is_swing_high = True
        for j in range(i - lookback, i + lookback + 1):
            if j != i and df['high'].iloc[j] >= df['high'].iloc[i]:
                is_swing_high = False
                break
        
        if is_swing_high:
            swing_highs.append({
                'index': i,
                'price': df['high'].iloc[i]
            })
        
        # Check for swing low
        is_swing_low = True
        for j in range(i - lookback, i + lookback + 1):
            if j != i and df['low'].iloc[j] <= df['low'].iloc[i]:
                is_swing_low = False
                break
        
        if is_swing_low:
            swing_lows.append({
                'index': i,
                'price': df['low'].iloc[i]
            })
    
    return swing_highs, swing_lows

def detect_harmonic_patterns(df):
    """Detect Gartley, Butterfly, and Bat harmonic patterns"""
    patterns = {}
    if len(df) < 50:
        return patterns
    
    # Find swing points
    swing_highs, swing_lows = find_swing_points(df)
    
    if len(swing_highs) < 3 or len(swing_lows) < 3:
        return patterns
    
    # Check for bullish patterns (starting from low)
    for i in range(len(swing_lows) - 4):
        try:
            # Get 5 points: X, A, B, C, D
            X = swing_lows[i]
            A = swing_highs[i] if i < len(swing_highs) else None
            B = swing_lows[i+1] if i+1 < len(swing_lows) else None
            C = swing_highs[i+1] if i+1 < len(swing_highs) else None
            D = swing_lows[i+2] if i+2 < len(swing_lows) else None
            
            if not all([X, A, B, C, D]):
                continue
            
            # Calculate Fibonacci ratios with null checks
            if not all(point and 'price' in point for point in [X, A, B, C, D]):
                continue
                
            XA = A['price'] - X['price']
            AB = B['price'] - A['price']
            BC = C['price'] - B['price']
            CD = D['price'] - C['price']
            
            if XA == 0 or AB == 0 or BC == 0:
                continue
            
            # Calculate ratios
            AB_XA = abs(AB / XA)
            BC_AB = abs(BC / AB)
            CD_BC = abs(CD / BC)
            AD_XA = abs((D['price'] - A['price']) / XA)
            
            # Gartley Pattern (Bullish)
            if (0.55 <= AB_XA <= 0.70 and     # AB retracement
                0.38 <= BC_AB <= 0.88 and     # BC retracement  
                1.13 <= CD_BC <= 1.618 and    # CD extension
                0.75 <= AD_XA <= 0.88):       # AD retracement
                patterns['bullish_gartley'] = {
                    'type': 'Bullish Gartley',
                    'bias': 'Bullish',
                    'completion_level': D['price'],
                    'target_1': D['price'] + (XA * 0.382),
                    'target_2': D['price'] + (XA * 0.618),
                    'strength': 'High',
                    'confidence': 85
                }
            
            # Butterfly Pattern (Bullish)
            elif (0.75 <= AB_XA <= 0.88 and   # AB retracement
                  0.38 <= BC_AB <= 0.88 and   # BC retracement
                  1.618 <= CD_BC <= 2.618 and # CD extension
                  1.25 <= AD_XA <= 1.618):    # AD extension
                patterns['bullish_butterfly'] = {
                    'type': 'Bullish Butterfly',
                    'bias': 'Bullish',
                    'completion_level': D['price'],
                    'target_1': D['price'] + (XA * 0.382),
                    'target_2': D['price'] + (XA * 0.618),
                    'strength': 'High',
                    'confidence': 80
                }
            
            # Bat Pattern (Bullish)
            elif (0.38 <= AB_XA <= 0.50 and   # AB retracement
                  0.38 <= BC_AB <= 0.88 and   # BC retracement
                  1.618 <= CD_BC <= 2.618 and # CD extension
                  0.85 <= AD_XA <= 0.90):     # AD retracement
                patterns['bullish_bat'] = {
                    'type': 'Bullish Bat',
                    'bias': 'Bullish',
                    'completion_level': D['price'],
                    'target_1': D['price'] + (XA * 0.382),
                    'target_2': D['price'] + (XA * 0.618),
                    'strength': 'High',
                    'confidence': 82
                }
                
        except (ZeroDivisionError, IndexError):
            continue
    
    # Check for bearish patterns (starting from high)
    for i in range(len(swing_highs) - 4):
        try:
            # Get 5 points: X, A, B, C, D
            X = swing_highs[i]
            A = swing_lows[i] if i < len(swing_lows) else None
            B = swing_highs[i+1] if i+1 < len(swing_highs) else None
            C = swing_lows[i+1] if i+1 < len(swing_lows) else None
            D = swing_highs[i+2] if i+2 < len(swing_highs) else None
            
            if not all([X, A, B, C, D]):
                continue
            
            # Calculate Fibonacci ratios
            XA = X['price'] - A['price']
            AB = B['price'] - A['price']
            BC = C['price'] - B['price']
            CD = D['price'] - C['price']
            
            if XA == 0 or AB == 0 or BC == 0:
                continue
            
            # Calculate ratios
            AB_XA = abs(AB / XA)
            BC_AB = abs(BC / AB)
            CD_BC = abs(CD / BC)
            AD_XA = abs((A['price'] - D['price']) / XA)
            
            # Bearish Gartley Pattern
            if (0.55 <= AB_XA <= 0.70 and
                0.38 <= BC_AB <= 0.88 and
                1.13 <= CD_BC <= 1.618 and
                0.75 <= AD_XA <= 0.88):
                patterns['bearish_gartley'] = {
                    'type': 'Bearish Gartley',
                    'bias': 'Bearish',
                    'completion_level': D['price'],
                    'target_1': D['price'] - (XA * 0.382),
                    'target_2': D['price'] - (XA * 0.618),
                    'strength': 'High',
                    'confidence': 85
                }
            
            # Bearish Butterfly Pattern
            elif (0.75 <= AB_XA <= 0.88 and
                  0.38 <= BC_AB <= 0.88 and
                  1.618 <= CD_BC <= 2.618 and
                  1.25 <= AD_XA <= 1.618):
                patterns['bearish_butterfly'] = {
                    'type': 'Bearish Butterfly',
                    'bias': 'Bearish',
                    'completion_level': D['price'],
                    'target_1': D['price'] - (XA * 0.382),
                    'target_2': D['price'] - (XA * 0.618),
                    'strength': 'High',
                    'confidence': 80
                }
            
            # Bearish Bat Pattern
            elif (0.38 <= AB_XA <= 0.50 and
                  0.38 <= BC_AB <= 0.88 and
                  1.618 <= CD_BC <= 2.618 and
                  0.85 <= AD_XA <= 0.90):
                patterns['bearish_bat'] = {
                    'type': 'Bearish Bat',
                    'bias': 'Bearish',
                    'completion_level': D['price'],
                    'target_1': D['price'] - (XA * 0.382),
                    'target_2': D['price'] - (XA * 0.618),
                    'strength': 'High',
                    'confidence': 82
                }
                
        except (ZeroDivisionError, IndexError):
            continue
    
    return patterns


def check_if_fvg_filled(df, fvg_levels, fvg_candle_index):
    """Check if a Fair Value Gap has been filled by subsequent price action with proper ICT rules."""
    # Enhanced validation
    if (df is None or not hasattr(df, 'empty') or df.empty or 
        fvg_levels is None or not isinstance(fvg_levels, dict)):
        return False
    
    # Validate index bounds
    if (fvg_candle_index is None or fvg_candle_index < 0 or 
        fvg_candle_index >= len(df) - 1):
        return False
    
    # Validate FVG levels structure
    required_keys = ['type', 'upper', 'lower']
    if not all(key in fvg_levels for key in required_keys):
        return False
    
    try:
        # Validate FVG level values
        upper_level = fvg_levels['upper']
        lower_level = fvg_levels['lower']
        fvg_type = fvg_levels['type']
        
        if (not isinstance(upper_level, (int, float)) or 
            not isinstance(lower_level, (int, float)) or
            pd.isna(upper_level) or pd.isna(lower_level)):
            return False
        
        # ICT Rule: FVG is filled when price trades into at least 50% of the gap
        gap_size = upper_level - lower_level
        midpoint = lower_level + (gap_size * 0.5)
        
        # Check candles after the FVG formation
        for i in range(fvg_candle_index + 1, len(df)):
            try:
                candle = df.iloc[i]
                
                # Validate candle data
                if (pd.isna(candle['low']) or pd.isna(candle['high']) or
                    pd.isna(candle['open']) or pd.isna(candle['close'])):
                    continue
                
                candle_low = float(candle['low'])
                candle_high = float(candle['high'])
                
                if fvg_type == 'Bullish FVG':
                    # FVG is filled if price trades back to at least the midpoint of the gap
                    if candle_low <= midpoint:
                        return True
                else:  # Bearish FVG
                    # FVG is filled if price trades back to at least the midpoint of the gap
                    if candle_high >= midpoint:
                        return True
                        
            except (IndexError, KeyError, ValueError, TypeError) as e:
                print(f"Error checking FVG fill at index {i}: {e}")
                continue
        
        return False
        
    except Exception as e:
        print(f"Error in check_if_fvg_filled: {e}")
        return False

def detect_elliott_wave_pattern(df):
    """Detect basic 5-wave Elliott Wave patterns"""
    patterns = {}
    if len(df) < 30:
        return patterns
    
    # Use the existing find_swing_points function
    
    swing_highs, swing_lows = find_swing_points(df, lookback=3)
    
    # Need at least 5 swings for a 5-wave pattern
    if len(swing_highs) < 3 or len(swing_lows) < 3:
        return patterns
    
    # Check for impulse wave (1-2-3-4-5) - bullish
    try:
        # Combine and sort swings by time
        all_swings = []
        for high in swing_highs:
            all_swings.append({**high, 'type': 'high'})
        for low in swing_lows:
            all_swings.append({**low, 'type': 'low'})
        
        all_swings.sort(key=lambda x: x['index'])
        
        # Look for 5-wave pattern in recent swings
        if len(all_swings) >= 9:  # Need at least 9 swings for clear 5-wave
            recent_swings = all_swings[-9:]
            
            # Check if pattern follows: low-high-low-high-low-high-low-high-low
            expected_pattern = ['low', 'high', 'low', 'high', 'low', 'high', 'low', 'high', 'low']
            actual_pattern = [swing['type'] for swing in recent_swings]
            
            if actual_pattern == expected_pattern:
                # Verify Elliott Wave rules
                wave_1 = recent_swings[1]['price'] - recent_swings[0]['price']  # 1st wave up
                wave_2 = recent_swings[2]['price'] - recent_swings[1]['price']  # 2nd wave down
                wave_3 = recent_swings[3]['price'] - recent_swings[2]['price']  # 3rd wave up
                wave_4 = recent_swings[4]['price'] - recent_swings[3]['price']  # 4th wave down
                wave_5 = recent_swings[5]['price'] - recent_swings[4]['price']  # 5th wave up
                
                # Elliott Wave rules:
                # 1. Wave 2 cannot retrace more than 100% of Wave 1
                # 2. Wave 3 cannot be the shortest wave
                # 3. Wave 4 cannot overlap with Wave 1
                
                if (abs(wave_2) < abs(wave_1) and  # Wave 2 rule
                    abs(wave_3) >= abs(wave_1) and abs(wave_3) >= abs(wave_5) and  # Wave 3 rule
                    recent_swings[4]['price'] > recent_swings[1]['price']):  # Wave 4 rule
                    
                    patterns['elliott_wave_impulse'] = {
                        'type': 'Elliott Wave Impulse',
                        'bias': 'Bullish',
                        'wave_5_target': recent_swings[5]['price'],
                        'strength': 'High',
                        'confidence': 78,
                        'completion': 'Wave 5' if len(recent_swings) >= 9 else 'In Progress'
                    }
            
            # Check for bearish impulse (inverted pattern)
            expected_bearish = ['high', 'low', 'high', 'low', 'high', 'low', 'high', 'low', 'high']
            if actual_pattern == expected_bearish:
                wave_1 = recent_swings[0]['price'] - recent_swings[1]['price']  # 1st wave down
                wave_2 = recent_swings[1]['price'] - recent_swings[2]['price']  # 2nd wave up
                wave_3 = recent_swings[2]['price'] - recent_swings[3]['price']  # 3rd wave down
                wave_4 = recent_swings[3]['price'] - recent_swings[4]['price']  # 4th wave up
                wave_5 = recent_swings[4]['price'] - recent_swings[5]['price']  # 5th wave down
                
                if (abs(wave_2) < abs(wave_1) and
                    abs(wave_3) >= abs(wave_1) and abs(wave_3) >= abs(wave_5) and
                    recent_swings[4]['price'] < recent_swings[1]['price']):
                    
                    patterns['elliott_wave_impulse_bearish'] = {
                        'type': 'Elliott Wave Impulse (Bearish)',
                        'bias': 'Bearish',
                        'wave_5_target': recent_swings[5]['price'],
                        'strength': 'High',
                        'confidence': 78,
                        'completion': 'Wave 5' if len(recent_swings) >= 9 else 'In Progress'
                    }
    
    except (IndexError, ZeroDivisionError):
        pass
    
    return patterns

def analyze_order_flow(df):
    """Advanced Order Flow Analysis with institutional detection and smart money tracking"""
    if len(df) < 20:
        return {}
    
    order_flow_data = {}
    
    # 1. Enhanced Buying vs Selling Pressure Analysis
    buying_pressure = []
    selling_pressure = []
    institutional_signals = []
    retail_signals = []
    
    for i in range(1, len(df)):
        # Calculate candle characteristics
        open_price = df['open'].iloc[i]
        close_price = df['close'].iloc[i]
        high_price = df['high'].iloc[i]
        low_price = df['low'].iloc[i]
        
        candle_range = high_price - low_price
        body_size = abs(close_price - open_price)
        
        if candle_range == 0:
            continue
            
        # Enhanced volume proxy calculation
        volume_proxy = candle_range + (body_size * 0.5)
        
        # Upper and lower wicks
        upper_wick = high_price - max(open_price, close_price)
        lower_wick = min(open_price, close_price) - low_price
        
        # Institutional vs Retail Detection
        avg_range = df['high'].iloc[max(0, i-20):i].sub(df['low'].iloc[max(0, i-20):i]).mean()
        
        # Large range suggests institutional activity
        is_institutional = candle_range > avg_range * 2.5
        
        # Determine buying vs selling pressure based on candle structure
        if close_price > open_price:  # Bullish candle
            pressure_strength = body_size
            
            # Strong buying pressure indicators
            if body_size > candle_range * 0.7:  # Large body
                pressure_strength *= 1.5
            elif lower_wick > upper_wick * 2:  # Rejection of lower prices
                pressure_strength *= 1.3
            
            buying_pressure.append(pressure_strength)
            
            if is_institutional:
                institutional_signals.append(('buy', pressure_strength, i))
            else:
                retail_signals.append(('buy', pressure_strength, i))
                
        else:  # Bearish candle
            pressure_strength = body_size
            
            # Strong selling pressure indicators
            if body_size > candle_range * 0.7:  # Large body
                pressure_strength *= 1.5
            elif upper_wick > lower_wick * 2:  # Rejection of higher prices
                pressure_strength *= 1.3
            
            selling_pressure.append(pressure_strength)
            
            if is_institutional:
                institutional_signals.append(('sell', pressure_strength, i))
            else:
                retail_signals.append(('sell', pressure_strength, i))
    
    # Calculate enhanced pressure metrics
    total_buying = sum(buying_pressure) if buying_pressure else 0
    total_selling = sum(selling_pressure) if selling_pressure else 0
    total_pressure = total_buying + total_selling
    
    # Institutional vs Retail participation
    inst_buying = sum(s[1] for s in institutional_signals if s[0] == 'buy')
    inst_selling = sum(s[1] for s in institutional_signals if s[0] == 'sell')
    retail_buying = sum(s[1] for s in retail_signals if s[0] == 'buy')
    retail_selling = sum(s[1] for s in retail_signals if s[0] == 'sell')
    
    total_institutional = inst_buying + inst_selling
    total_retail = retail_buying + retail_selling
    total_participation = total_institutional + total_retail
    
    if total_pressure > 0:
        buying_percentage = (total_buying / total_pressure) * 100
        selling_percentage = (total_selling / total_pressure) * 100
    else:
        buying_percentage = selling_percentage = 50
    
    # Enhanced pressure analysis
    order_flow_data['pressure_analysis'] = {
        'buying_pressure': buying_percentage,
        'selling_pressure': selling_percentage,
        'dominant_flow': 'Buying' if buying_percentage > 60 else 'Selling' if selling_percentage > 60 else 'Balanced',
        'flow_strength': max(buying_percentage, selling_percentage) - 50,
        'institutional_participation': (total_institutional / total_participation * 100) if total_participation > 0 else 0,
        'retail_participation': (total_retail / total_participation * 100) if total_participation > 0 else 0,
        'smart_money_bias': 'Bullish' if inst_buying > inst_selling else 'Bearish' if inst_selling > inst_buying else 'Neutral'
    }
    
    # 2. Advanced Market Microstructure Analysis
    microstructure = analyze_market_microstructure(df)
    order_flow_data['microstructure'] = microstructure
    
    # 3. Liquidity Analysis
    liquidity_analysis = analyze_liquidity_flow(df)
    order_flow_data['liquidity'] = liquidity_analysis
    
    # 4. Order Flow Imbalance Detection (Enhanced)
    imbalances = detect_advanced_order_flow_imbalances(df)
    order_flow_data['imbalances'] = imbalances
    
    # 5. Market Participation Analysis
    participation = analyze_market_participation(df)
    order_flow_data['participation'] = participation
    
    # 6. Price Level Order Flow
    price_level_flow = analyze_price_level_order_flow(df)
    order_flow_data['price_level_flow'] = price_level_flow
    
    # 7. Enhanced Delta Analysis with Institutional Separation
    delta_analysis = calculate_enhanced_delta_analysis(df)
    order_flow_data['delta_analysis'] = delta_analysis
    
    # 8. Order Flow Momentum
    momentum_analysis = analyze_order_flow_momentum(df)
    order_flow_data['momentum'] = momentum_analysis
    
    return order_flow_data

def analyze_market_microstructure(df):
    """Analyze market microstructure for tick direction and spread analysis"""
    if len(df) < 10:
        return {}
    
    microstructure = {}
    
    # Tick direction analysis
    tick_directions = []
    spread_analysis = []
    
    for i in range(1, len(df)):
        prev_close = df['close'].iloc[i-1]
        curr_close = df['close'].iloc[i]
        
        # Tick direction (uptick/downtick)
        if curr_close > prev_close:
            tick_directions.append(1)  # Uptick
        elif curr_close < prev_close:
            tick_directions.append(-1)  # Downtick
        else:
            tick_directions.append(0)  # No change
        
        # Spread analysis (high-low as proxy for bid-ask spread)
        spread = df['high'].iloc[i] - df['low'].iloc[i]
        spread_pct = (spread / df['close'].iloc[i]) * 100 if df['close'].iloc[i] > 0 else 0
        spread_analysis.append(spread_pct)
    
    # Calculate microstructure metrics
    upticks = sum(1 for t in tick_directions if t == 1)
    downticks = sum(1 for t in tick_directions if t == -1)
    total_ticks = len(tick_directions)
    
    if total_ticks > 0:
        uptick_ratio = (upticks / total_ticks) * 100
        downtick_ratio = (downticks / total_ticks) * 100
    else:
        uptick_ratio = downtick_ratio = 50
    
    # Spread trend analysis
    recent_spreads = spread_analysis[-10:] if len(spread_analysis) >= 10 else spread_analysis
    avg_spread = sum(recent_spreads) / len(recent_spreads) if recent_spreads else 0
    
    # Market impact analysis
    price_moves = [abs(df['close'].iloc[i] - df['close'].iloc[i-1]) / df['close'].iloc[i-1] 
                   for i in range(1, len(df)) if df['close'].iloc[i-1] > 0]
    avg_price_move = sum(price_moves) / len(price_moves) if price_moves else 0
    
    microstructure = {
        'uptick_ratio': uptick_ratio,
        'downtick_ratio': downtick_ratio,
        'tick_direction_bias': 'Bullish' if uptick_ratio > 55 else 'Bearish' if downtick_ratio > 55 else 'Neutral',
        'average_spread': avg_spread,
        'spread_trend': 'Widening' if len(spread_analysis) > 5 and spread_analysis[-1] > spread_analysis[-5] else 'Tightening',
        'market_impact': avg_price_move,
        'liquidity_condition': 'Good' if avg_spread < 0.1 else 'Poor' if avg_spread > 0.3 else 'Moderate'
    }
    
    return microstructure

def analyze_liquidity_flow(df):
    """Analyze liquidity conditions and flow patterns"""
    if len(df) < 20:
        return {}
    
    liquidity_data = {}
    
    # Calculate liquidity proxy using range and volume
    liquidity_events = []
    volume_proxy = df['high'] - df['low']
    
    for i in range(5, len(df)):
        current_range = df['high'].iloc[i] - df['low'].iloc[i]
        avg_range = volume_proxy.iloc[i-5:i].mean()
        
        # Liquidity drought detection (very low range)
        if current_range < avg_range * 0.3:
            liquidity_events.append(('drought', i, current_range))
        
        # Liquidity surge detection (very high range)
        elif current_range > avg_range * 3.0:
            liquidity_events.append(('surge', i, current_range))
    
    # Analyze recent liquidity events
    recent_events = [e for e in liquidity_events if e[1] >= len(df) - 10]
    drought_count = sum(1 for e in recent_events if e[0] == 'drought')
    surge_count = sum(1 for e in recent_events if e[0] == 'surge')
    
    # Market depth proxy analysis
    depth_proxy = []
    for i in range(1, len(df)):
        body_size = abs(df['close'].iloc[i] - df['open'].iloc[i])
        total_range = df['high'].iloc[i] - df['low'].iloc[i]
        
        if total_range > 0:
            depth_ratio = body_size / total_range
            depth_proxy.append(depth_ratio)
    
    avg_depth = sum(depth_proxy) / len(depth_proxy) if depth_proxy else 0
    
    liquidity_data = {
        'recent_drought_events': drought_count,
        'recent_surge_events': surge_count,
        'liquidity_trend': 'Improving' if surge_count > drought_count else 'Deteriorating' if drought_count > surge_count else 'Stable',
        'market_depth_proxy': avg_depth,
        'depth_quality': 'Good' if avg_depth > 0.6 else 'Poor' if avg_depth < 0.3 else 'Moderate',
        'total_liquidity_events': len(liquidity_events)
    }
    
    return liquidity_data

def detect_advanced_order_flow_imbalances(df):
    """Detect sophisticated order flow imbalances with institutional patterns"""
    if len(df) < 15:
        return {}
    
    imbalances = {
        'structural_imbalances': [],
        'momentum_imbalances': [],
        'institutional_imbalances': [],
        'gap_analysis': {}
    }
    
    for i in range(2, len(df) - 1):
        current = df.iloc[i]
        prev = df.iloc[i-1]
        prev_prev = df.iloc[i-2]
        
        # Structural imbalances (gaps)
        if current['low'] > prev['high']:  # Gap up
            gap_size = current['low'] - prev['high']
            gap_pct = (gap_size / prev['close']) * 100 if prev['close'] > 0 else 0
            
            imbalances['structural_imbalances'].append({
                'type': 'Bullish Gap',
                'size': gap_size,
                'size_pct': gap_pct,
                'index': i,
                'strength': 'Strong' if gap_pct > 1.0 else 'Moderate' if gap_pct > 0.5 else 'Weak'
            })
        
        elif current['high'] < prev['low']:  # Gap down
            gap_size = prev['low'] - current['high']
            gap_pct = (gap_size / prev['close']) * 100 if prev['close'] > 0 else 0
            
            imbalances['structural_imbalances'].append({
                'type': 'Bearish Gap',
                'size': gap_size,
                'size_pct': gap_pct,
                'index': i,
                'strength': 'Strong' if gap_pct > 1.0 else 'Moderate' if gap_pct > 0.5 else 'Weak'
            })
        
        # Momentum imbalances (strong directional moves)
        momentum_threshold = 0.015  # 1.5% move
        price_change = (current['close'] - prev['close']) / prev['close'] if prev['close'] > 0 else 0
        
        if abs(price_change) > momentum_threshold:
            direction = 'Bullish' if price_change > 0 else 'Bearish'
            
            # Check for institutional characteristics
            range_expansion = (current['high'] - current['low']) / (prev['high'] - prev['low']) if (prev['high'] - prev['low']) > 0 else 1
            is_institutional = range_expansion > 2.0
            
            imbalance_data = {
                'type': f'{direction} Momentum Imbalance',
                'strength': abs(price_change) * 100,
                'index': i,
                'institutional_characteristics': is_institutional
            }
            
            if is_institutional:
                imbalances['institutional_imbalances'].append(imbalance_data)
            else:
                imbalances['momentum_imbalances'].append(imbalance_data)
    
    # Gap fill analysis
    gaps = imbalances['structural_imbalances']
    filled_gaps = 0
    unfilled_gaps = 0
    
    for gap in gaps:
        gap_index = gap['index']
        gap_type = gap['type']
        
        # Check if gap was filled in subsequent candles
        filled = False
        for j in range(gap_index + 1, min(len(df), gap_index + 10)):
            if gap_type == 'Bullish Gap':
                if df['low'].iloc[j] <= df['high'].iloc[gap_index - 1]:
                    filled = True
                    break
            else:  # Bearish Gap
                if df['high'].iloc[j] >= df['low'].iloc[gap_index - 1]:
                    filled = True
                    break
        
        if filled:
            filled_gaps += 1
        else:
            unfilled_gaps += 1
    
    imbalances['gap_analysis'] = {
        'total_gaps': len(gaps),
        'filled_gaps': filled_gaps,
        'unfilled_gaps': unfilled_gaps,
        'fill_rate': (filled_gaps / len(gaps) * 100) if gaps else 0
    }
    
    return imbalances

def analyze_market_participation(df):
    """Analyze different types of market participation"""
    if len(df) < 20:
        return {}
    
    participation_data = {}
    
    # Institutional vs Retail participation analysis
    institutional_periods = 0
    retail_periods = 0
    mixed_periods = 0
    
    # Volume proxy and range analysis
    for i in range(10, len(df)):
        current_range = df['high'].iloc[i] - df['low'].iloc[i]
        avg_range = (df['high'].iloc[i-10:i] - df['low'].iloc[i-10:i]).mean()
        
        body_size = abs(df['close'].iloc[i] - df['open'].iloc[i])
        
        # Institutional characteristics: large range, decisive moves
        if current_range > avg_range * 2.5 and body_size > current_range * 0.6:
            institutional_periods += 1
        # Retail characteristics: smaller ranges, indecisive moves
        elif current_range < avg_range * 0.7 or body_size < current_range * 0.3:
            retail_periods += 1
        else:
            mixed_periods += 1
    
    total_periods = institutional_periods + retail_periods + mixed_periods
    
    if total_periods > 0:
        inst_participation = (institutional_periods / total_periods) * 100
        retail_participation = (retail_periods / total_periods) * 100
        mixed_participation = (mixed_periods / total_periods) * 100
    else:
        inst_participation = retail_participation = mixed_participation = 33.33
    
    # Participation quality analysis
    participation_quality = 'High' if inst_participation > 40 else 'Low' if retail_participation > 60 else 'Moderate'
    
    # Participation trend
    recent_inst = sum(1 for i in range(max(0, len(df)-5), len(df)) 
                     if i >= 10 and (df['high'].iloc[i] - df['low'].iloc[i]) > 
                     (df['high'].iloc[i-10:i] - df['low'].iloc[i-10:i]).mean() * 2.5)
    
    participation_trend = 'Increasing Institutional' if recent_inst >= 3 else 'Decreasing Institutional' if recent_inst == 0 else 'Stable'
    
    participation_data = {
        'institutional_participation': inst_participation,
        'retail_participation': retail_participation,
        'mixed_participation': mixed_participation,
        'participation_quality': participation_quality,
        'participation_trend': participation_trend,
        'dominant_participant': 'Institutional' if inst_participation > 50 else 'Retail' if retail_participation > 50 else 'Mixed'
    }
    
    return participation_data

def analyze_price_level_order_flow(df):
    """Analyze order flow at specific price levels"""
    if len(df) < 30:
        return {}
    
    # Find key support and resistance levels
    highs = df['high'].values
    lows = df['low'].values
    closes = df['close'].values
    
    # Identify swing points
    swing_highs = []
    swing_lows = []
    
    for i in range(2, len(df) - 2):
        if (highs[i] > highs[i-1] and highs[i] > highs[i-2] and 
            highs[i] > highs[i+1] and highs[i] > highs[i+2]):
            swing_highs.append({'price': highs[i], 'index': i})
        
        if (lows[i] < lows[i-1] and lows[i] < lows[i-2] and 
            lows[i] < lows[i+1] and lows[i] < lows[i+2]):
            swing_lows.append({'price': lows[i], 'index': i})
    
    # Analyze flow at key levels
    level_analysis = {}
    
    # Check recent interactions with swing levels
    current_price = closes[-1]
    
    for level in swing_highs[-3:]:  # Last 3 resistance levels
        level_price = level['price']
        distance = abs(current_price - level_price) / current_price
        
        if distance < 0.005:  # Within 0.5% of level
            # Analyze order flow near this level
            touches = 0
            rejections = 0
            
            for i in range(level['index'], len(df)):
                if abs(highs[i] - level_price) / level_price < 0.002:
                    touches += 1
                    if closes[i] < level_price * 0.999:  # Rejected from level
                        rejections += 1
            
            level_analysis[f'resistance_{level_price:.5f}'] = {
                'touches': touches,
                'rejections': rejections,
                'respect_rate': (rejections / touches * 100) if touches > 0 else 0,
                'level_strength': 'Strong' if rejections >= touches * 0.7 else 'Weak'
            }
    
    for level in swing_lows[-3:]:  # Last 3 support levels
        level_price = level['price']
        distance = abs(current_price - level_price) / current_price
        
        if distance < 0.005:  # Within 0.5% of level
            touches = 0
            bounces = 0
            
            for i in range(level['index'], len(df)):
                if abs(lows[i] - level_price) / level_price < 0.002:
                    touches += 1
                    if closes[i] > level_price * 1.001:  # Bounced from level
                        bounces += 1
            
            level_analysis[f'support_{level_price:.5f}'] = {
                'touches': touches,
                'bounces': bounces,
                'respect_rate': (bounces / touches * 100) if touches > 0 else 0,
                'level_strength': 'Strong' if bounces >= touches * 0.7 else 'Weak'
            }
    
    return level_analysis

def calculate_enhanced_delta_analysis(df):
    """Enhanced delta analysis with institutional vs retail separation"""
    if len(df) < 10:
        return {}
    
    institutional_delta = 0
    retail_delta = 0
    cumulative_delta = 0
    delta_values = []
    
    for i in range(1, len(df)):
        current = df.iloc[i]
        prev = df.iloc[i-1]
        
        price_change = current['close'] - prev['close']
        volume_proxy = current['high'] - current['low']
        
        # Determine if institutional or retail based on size
        avg_range = (df['high'].iloc[max(0, i-10):i] - df['low'].iloc[max(0, i-10):i]).mean()
        is_institutional = volume_proxy > avg_range * 2.0
        
        # Calculate delta
        if price_change > 0:
            delta = volume_proxy
        elif price_change < 0:
            delta = -volume_proxy
        else:
            delta = 0
        
        cumulative_delta += delta
        delta_values.append(delta)
        
        if is_institutional:
            institutional_delta += delta
        else:
            retail_delta += delta
    
    # Delta momentum analysis
    recent_delta = sum(delta_values[-5:]) if len(delta_values) >= 5 else 0
    older_delta = sum(delta_values[-10:-5]) if len(delta_values) >= 10 else 0
    
    delta_momentum = 'Accelerating' if abs(recent_delta) > abs(older_delta) else 'Decelerating'
    
    # Divergence analysis
    price_direction = 1 if df['close'].iloc[-1] > df['close'].iloc[-10] else -1
    delta_direction = 1 if cumulative_delta > 0 else -1
    
    delta_divergence = 'Bearish Divergence' if price_direction > 0 and delta_direction < 0 else \
                      'Bullish Divergence' if price_direction < 0 and delta_direction > 0 else 'No Divergence'
    
    return {
        'cumulative_delta': cumulative_delta,
        'institutional_delta': institutional_delta,
        'retail_delta': retail_delta,
        'delta_bias': 'Bullish' if cumulative_delta > 0 else 'Bearish',
        'institutional_bias': 'Bullish' if institutional_delta > 0 else 'Bearish',
        'retail_bias': 'Bullish' if retail_delta > 0 else 'Bearish',
        'delta_momentum': delta_momentum,
        'delta_divergence': delta_divergence,
        'recent_delta_strength': abs(recent_delta)
    }

def analyze_order_flow_momentum(df):
    """Analyze momentum characteristics of order flow"""
    if len(df) < 15:
        return {}
    
    momentum_data = {}
    
    # Calculate order flow momentum using price velocity and volume
    momentum_values = []
    
    for i in range(5, len(df)):
        # Price velocity (5-period change)
        price_velocity = (df['close'].iloc[i] - df['close'].iloc[i-5]) / df['close'].iloc[i-5] if df['close'].iloc[i-5] > 0 else 0
        
        # Volume momentum (range expansion/contraction)
        current_range = df['high'].iloc[i] - df['low'].iloc[i]
        avg_range = (df['high'].iloc[i-5:i] - df['low'].iloc[i-5:i]).mean()
        
        volume_momentum = (current_range / avg_range - 1) if avg_range > 0 else 0
        
        # Combined momentum score
        momentum_score = (abs(price_velocity) + volume_momentum) / 2
        momentum_values.append({
            'price_velocity': price_velocity,
            'volume_momentum': volume_momentum,
            'combined_momentum': momentum_score,
            'direction': 'Bullish' if price_velocity > 0 else 'Bearish'
        })
    
    # Analyze momentum characteristics
    recent_momentum = momentum_values[-5:] if len(momentum_values) >= 5 else momentum_values
    
    avg_momentum = sum(m['combined_momentum'] for m in recent_momentum) / len(recent_momentum) if recent_momentum else 0
    
    # Momentum consistency
    bullish_momentum = sum(1 for m in recent_momentum if m['direction'] == 'Bullish')
    momentum_consistency = (bullish_momentum / len(recent_momentum)) if recent_momentum else 0.5
    
    # Momentum quality assessment
    momentum_quality = 'High' if avg_momentum > 0.02 and momentum_consistency > 0.7 else \
                      'Low' if avg_momentum < 0.005 or momentum_consistency < 0.3 else 'Moderate'
    
    # Momentum sustainability
    momentum_trend = []
    for i in range(1, len(momentum_values)):
        if momentum_values[i]['combined_momentum'] > momentum_values[i-1]['combined_momentum']:
            momentum_trend.append(1)
        else:
            momentum_trend.append(-1)
    
    sustainability = 'Sustainable' if sum(momentum_trend[-3:]) > 0 else 'Weakening' if sum(momentum_trend[-3:]) < -1 else 'Stable'
    
    momentum_data = {
        'average_momentum': avg_momentum,
        'momentum_direction': 'Bullish' if momentum_consistency > 0.6 else 'Bearish' if momentum_consistency < 0.4 else 'Neutral',
        'momentum_quality': momentum_quality,
        'momentum_consistency': momentum_consistency * 100,
        'momentum_sustainability': sustainability,
        'institutional_momentum': sum(m['combined_momentum'] for m in recent_momentum if m['combined_momentum'] > 0.03) / len(recent_momentum) if recent_momentum else 0
    }
    
    return momentum_data

def detect_order_flow_imbalances(df):
    """Detect order flow imbalances that suggest directional moves"""
    if len(df) < 10:
        return {}
    
    imbalances = []
    
    for i in range(2, len(df) - 1):
        current = df.iloc[i]
        prev = df.iloc[i-1]
        next_candle = df.iloc[i+1]
        
        # Bullish imbalance: Gap up with strong momentum
        if (current['low'] > prev['high'] and 
            current['close'] > current['open'] and
            (current['close'] - current['open']) > (current['high'] - current['low']) * 0.6):
            
            imbalances.append({
                'type': 'Bullish Imbalance',
                'index': i,
                'gap_size': current['low'] - prev['high'],
                'strength': 'High' if current['close'] > current['open'] * 1.005 else 'Medium',
                'price_level': (current['low'] + prev['high']) / 2
            })
        
        # Bearish imbalance: Gap down with strong momentum
        elif (current['high'] < prev['low'] and 
              current['close'] < current['open'] and
              (current['open'] - current['close']) > (current['high'] - current['low']) * 0.6):
            
            imbalances.append({
                'type': 'Bearish Imbalance',
                'index': i,
                'gap_size': prev['low'] - current['high'],
                'strength': 'High' if current['close'] < current['open'] * 0.995 else 'Medium',
                'price_level': (current['high'] + prev['low']) / 2
            })
    
    return {
        'total_imbalances': len(imbalances),
        'recent_imbalances': imbalances[-3:] if imbalances else [],
        'bullish_count': len([imp for imp in imbalances if 'Bullish' in imp['type']]),
        'bearish_count': len([imp for imp in imbalances if 'Bearish' in imp['type']])
    }

def analyze_absorption_exhaustion(df):
    """Analyze absorption (supply/demand zones) and exhaustion patterns"""
    if len(df) < 15:
        return {}
    
    absorption_zones = []
    exhaustion_signals = []
    
    for i in range(5, len(df) - 5):
        current = df.iloc[i]
        
        # Look for absorption patterns (multiple attempts at same level)
        price_level = current['close']
        tolerance = (current['high'] - current['low']) * 0.3
        
        # Count touches at similar price levels
        touches = 0
        volume_at_level = 0
        
        for j in range(max(0, i-10), min(len(df), i+10)):
            if j != i:
                test_candle = df.iloc[j]
                if (abs(test_candle['close'] - price_level) <= tolerance or
                    abs(test_candle['high'] - price_level) <= tolerance or
                    abs(test_candle['low'] - price_level) <= tolerance):
                    touches += 1
                    volume_at_level += test_candle['high'] - test_candle['low']
        
        # Absorption zone criteria
        if touches >= 3:
            absorption_zones.append({
                'price_level': price_level,
                'touches': touches,
                'volume_at_level': volume_at_level,
                'zone_type': 'Support' if current['close'] > price_level else 'Resistance',
                'strength': 'High' if touches >= 5 else 'Medium'
            })
        
        # Exhaustion patterns (high volume with small price movement)
        candle_range = current['high'] - current['low']
        body_size = abs(current['close'] - current['open'])
        
        if candle_range > 0:
            # High volume (range) but small body suggests exhaustion
            if (candle_range > df['high'].rolling(20).mean().iloc[i] - df['low'].rolling(20).mean().iloc[i] and
                body_size < candle_range * 0.3):
                
                exhaustion_signals.append({
                    'type': 'Volume Exhaustion',
                    'price_level': current['close'],
                    'signal': 'Bullish Exhaustion' if current['close'] > current['open'] else 'Bearish Exhaustion',
                    'intensity': candle_range / body_size if body_size > 0 else 0
                })
    
    return {
        'absorption_zones': absorption_zones[-5:] if absorption_zones else [],
        'exhaustion_signals': exhaustion_signals[-3:] if exhaustion_signals else [],
        'total_absorption_zones': len(absorption_zones),
        'recent_exhaustion_count': len(exhaustion_signals[-5:]) if exhaustion_signals else 0
    }

def calculate_delta_analysis(df):
    """Calculate delta between buying and selling activity"""
    if len(df) < 10:
        return {}
    
    delta_values = []
    cumulative_delta = 0
    
    for i in range(1, len(df)):
        current = df.iloc[i]
        prev = df.iloc[i-1]
        
        # Calculate delta based on price movement and volume proxy
        price_change = current['close'] - prev['close']
        volume_proxy = current['high'] - current['low']
        
        # Positive delta for up moves, negative for down moves
        if price_change > 0:
            delta = volume_proxy
        elif price_change < 0:
            delta = -volume_proxy
        else:
            delta = 0
        
        cumulative_delta += delta
        delta_values.append({
            'period_delta': delta,
            'cumulative_delta': cumulative_delta,
            'price': current['close']
        })
    
    # Analyze delta trends
    recent_delta = delta_values[-10:] if len(delta_values) >= 10 else delta_values
    avg_recent_delta = sum(d['period_delta'] for d in recent_delta) / len(recent_delta)
    
    # Delta divergence analysis
    price_trend = df['close'].iloc[-10:].pct_change().sum()
    delta_trend = sum(d['period_delta'] for d in recent_delta)
    
    divergence = 'None'
    if price_trend > 0.01 and delta_trend < 0:
        divergence = 'Bearish Divergence (Price up, Delta down)'
    elif price_trend < -0.01 and delta_trend > 0:
        divergence = 'Bullish Divergence (Price down, Delta up)'
    
    return {
        'current_cumulative_delta': cumulative_delta,
        'average_recent_delta': avg_recent_delta,
        'delta_trend': 'Bullish' if avg_recent_delta > 0 else 'Bearish' if avg_recent_delta < 0 else 'Neutral',
        'divergence': divergence,
        'delta_strength': abs(avg_recent_delta),
        'total_periods': len(delta_values)
    }

def detect_value_area(df):
    """Detect Value Area High/Low using Market Profile concepts"""
    if len(df) < 30:
        return {}
    
    # Use recent 30 periods for value area calculation
    recent_data = df.tail(30)
    
    # Calculate typical price for each period
    typical_prices = (recent_data['high'] + recent_data['low'] + recent_data['close']) / 3
    
    # Use price range as volume proxy
    volume_proxy = recent_data['high'] - recent_data['low']
    
    # Create price bins
    price_min = recent_data['low'].min()
    price_max = recent_data['high'].max()
    price_range = price_max - price_min
    
    if price_range == 0:
        return {}
    
    # Create 20 price bins
    bin_size = price_range / 20
    bins = []
    
    for i in range(20):
        bin_low = price_min + (i * bin_size)
        bin_high = bin_low + bin_size
        bin_volume = 0
        
        # Calculate volume for this price bin
        for j, typical_price in enumerate(typical_prices):
            if bin_low <= typical_price <= bin_high:
                bin_volume += volume_proxy.iloc[j]
        
        bins.append({
            'price_low': bin_low,
            'price_high': bin_high,
            'price_mid': (bin_low + bin_high) / 2,
            'volume': bin_volume
        })
    
    # Sort bins by volume
    bins.sort(key=lambda x: x['volume'], reverse=True)
    
    # Value Area = 70% of total volume
    total_volume = sum(bin_data['volume'] for bin_data in bins)
    value_area_volume = total_volume * 0.70
    
    # Find continuous price range that contains 70% of volume
    accumulated_volume = 0
    value_area_bins = []
    
    for bin_data in bins:
        if accumulated_volume < value_area_volume:
            value_area_bins.append(bin_data)
            accumulated_volume += bin_data['volume']
    
    if not value_area_bins:
        return {}
    
    # Calculate Value Area High and Low
    value_area_high = max(bin_data['price_high'] for bin_data in value_area_bins)
    value_area_low = min(bin_data['price_low'] for bin_data in value_area_bins)
    
    # Point of Control (POC) - price with highest volume
    poc_bin = bins[0]  # First bin has highest volume
    poc_price = poc_bin['price_mid']
    
    current_price = df['close'].iloc[-1]
    
    # Determine market profile bias
    if current_price > value_area_high:
        profile_bias = 'Bullish (Above Value Area)'
    elif current_price < value_area_low:
        profile_bias = 'Bearish (Below Value Area)'
    else:
        profile_bias = 'Neutral (In Value Area)'
    
    return {
        'value_area_high': value_area_high,
        'value_area_low': value_area_low,
        'point_of_control': poc_price,
        'current_position': profile_bias,
        'value_area_range': value_area_high - value_area_low,
        'distance_from_poc': abs(current_price - poc_price),
        'profile_strength': 'Strong' if accumulated_volume / total_volume > 0.75 else 'Moderate'
    }

def analyze_pattern_confluence(chart_patterns, current_price):
    """Analyze confluence of multiple chart patterns - USED ONLY FOR CONFIRMATION."""
    if not chart_patterns:
        return {
            'dominant_bias': 'Neutral',
            'confluence_score': 0,
            'bullish_patterns': [],
            'bearish_patterns': [],
            'neutral_patterns': [],
            'total_patterns': 0,
            'pattern_strength': 'None',
            'is_confluence_only': True
        }
    
    bullish_patterns = []
    bearish_patterns = []
    neutral_patterns = []
    
    if isinstance(chart_patterns, dict):
        for pattern_name, pattern_data in chart_patterns.items():
            if isinstance(pattern_data, dict) and 'bias' in pattern_data:
                bias = pattern_data['bias'].lower()
                strength = pattern_data.get('strength', 'Medium')
                confidence = pattern_data.get('confidence', 50)
                pattern_type = pattern_data.get('type', pattern_name)
                
                # Only consider high-quality patterns for confluence
                if confidence >= 70 or strength in ['High', 'Excellent']:
                    if 'bullish' in bias:
                        bullish_patterns.append({
                            'name': pattern_type,
                            'strength': strength,
                            'confidence': confidence
                        })
                    elif 'bearish' in bias:
                        bearish_patterns.append({
                            'name': pattern_type,
                            'strength': strength,
                            'confidence': confidence
                        })
                else:
                    neutral_patterns.append({
                        'name': pattern_data['type'],
                        'strength': strength,
                        'confidence': confidence
                    })
    
    # Calculate confluence score - CONSERVATIVE for confluence use only
    confluence_score = 0
    dominant_bias = 'Neutral'
    
    # Weight patterns by strength and confidence
    def calculate_pattern_weight(pattern):
        strength_weights = {'Excellent': 4, 'High': 3, 'Medium-High': 2.5, 'Medium': 2, 'Low': 1}
        confidence_multiplier = pattern.get('confidence', 50) / 100
        return strength_weights.get(pattern['strength'], 2) * confidence_multiplier
    
    bullish_score = sum(calculate_pattern_weight(p) for p in bullish_patterns)
    bearish_score = sum(calculate_pattern_weight(p) for p in bearish_patterns)
    
    # Require higher threshold for confluence (not primary signals)
    if bullish_score > bearish_score and bullish_score >= 4:  # Higher threshold
        dominant_bias = 'Bullish'
        confluence_score = min(bullish_score, 8)  # Lower cap for confluence
    elif bearish_score > bullish_score and bearish_score >= 4:  # Higher threshold
        dominant_bias = 'Bearish'
        confluence_score = min(bearish_score, 8)  # Lower cap for confluence
    
    # Confluence strength assessment
    if confluence_score >= 6:
        pattern_strength = 'Strong Confluence'
    elif confluence_score >= 4:
        pattern_strength = 'Moderate Confluence'
    elif confluence_score >= 2:
        pattern_strength = 'Weak Confluence'
    else:
        pattern_strength = 'No Confluence'
    
    return {
        'dominant_bias': dominant_bias,
        'confluence_score': confluence_score,
        'bullish_patterns': bullish_patterns,
        'bearish_patterns': bearish_patterns,
        'neutral_patterns': neutral_patterns,
        'total_patterns': len(bullish_patterns) + len(bearish_patterns) + len(neutral_patterns),
        'pattern_strength': pattern_strength,
        'is_confluence_only': True,
        'quality_filter_applied': True,
        'confluence_note': 'Patterns used for confirmation only, not primary signals'
    }

def evaluate_confluence_factors(df, indicators, primary_signal, current_price, pair="EUR/USD"):
    """Evaluate confluence factors that support or oppose the primary signal."""
    confluence_factors = {
        'supporting': [],
        'opposing': [],
        'neutral': [],
        'total_score': 0,
        'confluence_strength': 'None'
    }
    
    if primary_signal == "NEUTRAL":
        return confluence_factors
    
    # Bollinger Bands Confluence
    try:
        bb_range = indicators['bb_upper'] - indicators['bb_lower']
        if bb_range > 0:
            bb_position = (current_price - indicators['bb_lower']) / bb_range
            
            if primary_signal == "BUY":
                if bb_position <= 0.2:  # Near lower band supports buy
                    confluence_factors['supporting'].append({
                        'factor': 'Bollinger Bands',
                        'reason': f'Price near lower band ({bb_position*100:.1f}% position)',
                        'weight': 2
                    })
                elif bb_position >= 0.8:  # Near upper band opposes buy
                    confluence_factors['opposing'].append({
                        'factor': 'Bollinger Bands',
                        'reason': f'Price near upper band ({bb_position*100:.1f}% position)',
                        'weight': -2
                    })
                else:
                    confluence_factors['neutral'].append({
                        'factor': 'Bollinger Bands',
                        'reason': f'Price in middle range ({bb_position*100:.1f}% position)',
                        'weight': 0
                    })
            
            elif primary_signal == "SELL":
                if bb_position >= 0.8:  # Near upper band supports sell
                    confluence_factors['supporting'].append({
                        'factor': 'Bollinger Bands',
                        'reason': f'Price near upper band ({bb_position*100:.1f}% position)',
                        'weight': 2
                    })
                elif bb_position <= 0.2:  # Near lower band opposes sell
                    confluence_factors['opposing'].append({
                        'factor': 'Bollinger Bands',
                        'reason': f'Price near lower band ({bb_position*100:.1f}% position)',
                        'weight': -2
                    })
                else:
                    confluence_factors['neutral'].append({
                        'factor': 'Bollinger Bands',
                        'reason': f'Price in middle range ({bb_position*100:.1f}% position)',
                        'weight': 0
                    })
    except:
        pass
    
    # Stochastic Confluence
    try:
        stoch_k = indicators['stoch_k']
        
        if primary_signal == "BUY":
            if stoch_k <= 25:  # Oversold supports buy
                confluence_factors['supporting'].append({
                    'factor': 'Stochastic',
                    'reason': f'Oversold condition (K={stoch_k:.1f})',
                    'weight': 2
                })
            elif stoch_k >= 75:  # Overbought opposes buy
                confluence_factors['opposing'].append({
                    'factor': 'Stochastic',
                    'reason': f'Overbought condition (K={stoch_k:.1f})',
                    'weight': -2
                })
            else:
                confluence_factors['neutral'].append({
                    'factor': 'Stochastic',
                    'reason': f'Neutral zone (K={stoch_k:.1f})',
                    'weight': 0
                })
        
        elif primary_signal == "SELL":
            if stoch_k >= 75:  # Overbought supports sell
                confluence_factors['supporting'].append({
                    'factor': 'Stochastic',
                    'reason': f'Overbought condition (K={stoch_k:.1f})',
                    'weight': 2
                })
            elif stoch_k <= 25:  # Oversold opposes sell
                confluence_factors['opposing'].append({
                    'factor': 'Stochastic',
                    'reason': f'Oversold condition (K={stoch_k:.1f})',
                    'weight': -2
                })
            else:
                confluence_factors['neutral'].append({
                    'factor': 'Stochastic',
                    'reason': f'Neutral zone (K={stoch_k:.1f})',
                    'weight': 0
                })
    except:
        pass
    
    # CCI Confluence
    try:
        cci = indicators.get('cci', 0)
        
        if primary_signal == "BUY":
            if cci <= -100:  # Oversold supports buy
                confluence_factors['supporting'].append({
                    'factor': 'CCI',
                    'reason': f'Oversold condition (CCI={cci:.0f})',
                    'weight': 1
                })
            elif cci >= 100:  # Overbought opposes buy
                confluence_factors['opposing'].append({
                    'factor': 'CCI',
                    'reason': f'Overbought condition (CCI={cci:.0f})',
                    'weight': -1
                })
            else:
                confluence_factors['neutral'].append({
                    'factor': 'CCI',
                    'reason': f'Normal range (CCI={cci:.0f})',
                    'weight': 0
                })
        
        elif primary_signal == "SELL":
            if cci >= 100:  # Overbought supports sell
                confluence_factors['supporting'].append({
                    'factor': 'CCI',
                    'reason': f'Overbought condition (CCI={cci:.0f})',
                    'weight': 1
                })
            elif cci <= -100:  # Oversold opposes sell
                confluence_factors['opposing'].append({
                    'factor': 'CCI',
                    'reason': f'Oversold condition (CCI={cci:.0f})',
                    'weight': -1
                })
            else:
                confluence_factors['neutral'].append({
                    'factor': 'CCI',
                    'reason': f'Normal range (CCI={cci:.0f})',
                    'weight': 0
                })
    except:
        pass
    
    # Support/Resistance Confluence
    try:
        sr_levels = detect_support_resistance(df, pair=pair)
        if sr_levels.get('levels'):
            for level in sr_levels['levels'][:2]:  # Check top 2 levels
                distance_pct = abs(current_price - level['level']) / current_price
                
                if distance_pct < 0.003:  # Within 0.3% of S/R level
                    if primary_signal == "BUY" and level['type'] == 'Support':
                        confluence_factors['supporting'].append({
                            'factor': 'Support Level',
                            'reason': f'Price near key support at {level["level"]:.5f}',
                            'weight': 3
                        })
                    elif primary_signal == "BUY" and level['type'] == 'Resistance':
                        confluence_factors['opposing'].append({
                            'factor': 'Resistance Level',
                            'reason': f'Price near key resistance at {level["level"]:.5f}',
                            'weight': -3
                        })
                    elif primary_signal == "SELL" and level['type'] == 'Resistance':
                        confluence_factors['supporting'].append({
                            'factor': 'Resistance Level',
                            'reason': f'Price near key resistance at {level["level"]:.5f}',
                            'weight': 3
                        })
                    elif primary_signal == "SELL" and level['type'] == 'Support':
                        confluence_factors['opposing'].append({
                            'factor': 'Support Level',
                            'reason': f'Price near key support at {level["level"]:.5f}',
                            'weight': -3
                        })
    except:
        pass
    
    # Chart Pattern Confluence
    try:
        chart_patterns = detect_chart_patterns(df)
        if chart_patterns:
            confluence_analysis = analyze_pattern_confluence(chart_patterns, current_price)
            
            if confluence_analysis['total_patterns'] > 0:
                pattern_bias = confluence_analysis['dominant_bias']
                pattern_strength = confluence_analysis['confluence_score']
                
                if pattern_bias == 'Bullish' and primary_signal == "BUY":
                    confluence_factors['supporting'].append({
                        'factor': 'Chart Patterns',
                        'reason': f'Bullish pattern confluence (score: {pattern_strength})',
                        'weight': min(3, pattern_strength // 2)
                    })
                elif pattern_bias == 'Bearish' and primary_signal == "BUY":
                    confluence_factors['opposing'].append({
                        'factor': 'Chart Patterns',
                        'reason': f'Bearish pattern confluence (score: {pattern_strength})',
                        'weight': -min(3, pattern_strength // 2)
                    })
                elif pattern_bias == 'Bearish' and primary_signal == "SELL":
                    confluence_factors['supporting'].append({
                        'factor': 'Chart Patterns',
                        'reason': f'Bearish pattern confluence (score: {pattern_strength})',
                        'weight': min(3, pattern_strength // 2)
                    })
                elif pattern_bias == 'Bullish' and primary_signal == "SELL":
                    confluence_factors['opposing'].append({
                        'factor': 'Chart Patterns',
                        'reason': f'Bullish pattern confluence (score: {pattern_strength})',
                        'weight': -min(3, pattern_strength // 2)
                    })
                else:
                    confluence_factors['neutral'].append({
                        'factor': 'Chart Patterns',
                        'reason': f'Mixed or neutral pattern signals',
                        'weight': 0
                    })
    except:
        pass
    
    # Calculate total confluence score
    supporting_score = sum(factor['weight'] for factor in confluence_factors['supporting'])
    opposing_score = abs(sum(factor['weight'] for factor in confluence_factors['opposing']))
    total_score = supporting_score - opposing_score
    
    confluence_factors['total_score'] = total_score
    confluence_factors['supporting_score'] = supporting_score
    confluence_factors['opposing_score'] = opposing_score
    
    # Determine confluence strength
    if total_score >= 6:
        confluence_factors['confluence_strength'] = 'Very Strong'
    elif total_score >= 4:
        confluence_factors['confluence_strength'] = 'Strong'
    elif total_score >= 2:
        confluence_factors['confluence_strength'] = 'Moderate'
    elif total_score >= 0:
        confluence_factors['confluence_strength'] = 'Weak'
    else:
        confluence_factors['confluence_strength'] = 'Conflicting'
    
    return confluence_factors

def get_chart_pattern_analysis(df, current_price):
    """Get comprehensive chart pattern analysis - CONFLUENCE ONLY."""
    if len(df) < 20:
        return "📊 **Chart Patterns**: Insufficient data for pattern analysis"
    
