    # Analyze pattern confluence
    confluence = analyze_pattern_confluence(chart_patterns, current_price)
    
    analysis = f"📊 **Chart Pattern Confluence Analysis**\n"
    analysis += f"⚠️ *Patterns used for CONFIRMATION only, not primary signals*\n\n"
    analysis += f"🎯 **Confluence Direction**: {confluence['dominant_bias']}\n"
    analysis += f"📊 **Confluence Strength**: {confluence['pattern_strength']}\n"
    analysis += f"📈 **Confluence Score**: {confluence['confluence_score']}/8\n\n"
    
    # Display supporting patterns
    if confluence['bullish_patterns']:
        analysis += "🟢 **Bullish Confluence Patterns**:\n"
        for pattern in confluence['bullish_patterns'][:2]:  # Show top 2
            confidence = pattern.get('confidence', 'N/A')
