def calculate_advanced_volume_proxy(df):
    """Calculate sophisticated volume proxy using multiple price action factors."""
    try:
        # Base volume proxy
        range_volume = df['high'] - df['low']
        body_volume = abs(df['close'] - df['open'])
        
        # Weighted volume calculation
        # Larger bodies indicate more conviction (higher volume)
        body_weight = 0.7
        range_weight = 0.3
        
        volume_proxy = (body_volume * body_weight) + (range_volume * range_weight)
        
        # Enhanced volume indicators
        tick_volume = range_volume + body_volume  # Total price movement
        
        # Volume quality score (how "clean" the volume is)
        volume_quality = body_volume / range_volume
        volume_quality = volume_quality.where(volume_quality.notna(), 0.5)  # Default to neutral
        
        # Breakout volume detection
        avg_volume = volume_proxy.rolling(window=20).mean()
        volume_spikes = volume_proxy > avg_volume * 2
        
        # Volume accumulation/distribution
        close_position = (df['close'] - df['low']) / (df['high'] - df['low'])
        close_position = close_position.where(close_position.notna(), 0.5)
        
        # Money flow multiplier
        money_flow_multiplier = close_position * 2 - 1  # Range: -1 to 1
        money_flow_volume = volume_proxy * money_flow_multiplier
        
        return {
            'volume_proxy': volume_proxy,
            'tick_volume': tick_volume,
            'volume_quality': volume_quality,
            'volume_spikes': volume_spikes,
            'money_flow_volume': money_flow_volume,
            'close_position': close_position,
            'average_volume': avg_volume
        }
    except Exception as e:
        print(f"Error in advanced volume proxy: {e}")
        return {'volume_proxy': df['high'] - df['low']}

def detect_institutional_volume_patterns(df, volume_proxy):
    """Detect patterns that suggest institutional trading activity."""
    try:
        institutional_patterns = {
            'absorption': [],
            'distribution': [],
            'accumulation': [],
            'smart_money_moves': [],
            'unusual_activity': []
        }
        
        # Calculate average volume
        avg_volume = volume_proxy.rolling(window=20).mean()
        
        for i in range(20, len(df)):
            current_volume = volume_proxy.iloc[i]
            current_price = df['close'].iloc[i]
            prev_price = df['close'].iloc[i-1]
            
            # High volume, small price movement (absorption)
            if (current_volume > avg_volume.iloc[i] * 2.5 and
                abs(current_price - prev_price) / prev_price < 0.005):
                institutional_patterns['absorption'].append({
                    'index': i,
                    'volume_ratio': current_volume / avg_volume.iloc[i],
                    'price_change': abs(current_price - prev_price) / prev_price
                })
            
            # High volume with strong directional move (smart money)
            price_change = (current_price - prev_price) / prev_price
            if (current_volume > avg_volume.iloc[i] * 2.0 and
                abs(price_change) > 0.01):
                institutional_patterns['smart_money_moves'].append({
                    'index': i,
                    'direction': 'Bullish' if price_change > 0 else 'Bearish',
                    'volume_ratio': current_volume / avg_volume.iloc[i],
                    'price_change': price_change
                })
            
            # Accumulation pattern (higher lows with increasing volume)
            if i >= 25:
                recent_lows = df['low'].iloc[i-5:i+1]
                recent_volumes = volume_proxy.iloc[i-5:i+1]
                
                if (recent_lows.iloc[-1] > recent_lows.iloc[0] and
                    recent_volumes.iloc[-1] > recent_volumes.iloc[0]):
                    if recent_volumes.iloc[0] != 0 and not pd.isna(recent_volumes.iloc[0]):
                        strength = (recent_volumes.iloc[-1] / recent_volumes.iloc[0] - 1) * 100
                    else:
                        strength = 100  # Default strength when base volume is zero
                    institutional_patterns['accumulation'].append({
                        'index': i,
                        'strength': strength
                    })
            
            # Distribution pattern (lower highs with increasing volume)
            if i >= 25:
                recent_highs = df['high'].iloc[i-5:i+1]
                recent_volumes = volume_proxy.iloc[i-5:i+1]
                
                if (recent_highs.iloc[-1] < recent_highs.iloc[0] and
                    recent_volumes.iloc[-1] > recent_volumes.iloc[0]):
                    if recent_volumes.iloc[0] != 0 and not pd.isna(recent_volumes.iloc[0]):
                        strength = (recent_volumes.iloc[-1] / recent_volumes.iloc[0] - 1) * 100
                    else:
                        strength = 100  # Default strength when base volume is zero
                    institutional_patterns['distribution'].append({
                        'index': i,
                        'strength': strength
                    })
        
        # Summary statistics
        total_patterns = sum(len(patterns) for patterns in institutional_patterns.values())
        recent_activity = sum(1 for patterns in institutional_patterns.values() 
                             for pattern in patterns if pattern['index'] >= len(df) - 10)
        
        return {
            'patterns': institutional_patterns,
            'total_patterns': total_patterns,
            'recent_activity': recent_activity,
            'activity_score': min(100, recent_activity * 20),
            'dominant_pattern': get_dominant_institutional_pattern(institutional_patterns)
        }
    except Exception as e:
        print(f"Error detecting institutional patterns: {e}")
        return {'patterns': {}, 'total_patterns': 0, 'activity_score': 0}

def get_dominant_institutional_pattern(patterns):
    """Determine the dominant institutional pattern."""
    try:
        pattern_counts = {name: len(pattern_list) for name, pattern_list in patterns.items()}
        
        if not any(pattern_counts.values()):
            return 'None'
        
        dominant = max(pattern_counts, key=pattern_counts.get)
        return dominant if pattern_counts[dominant] > 0 else 'None'
    except:
        return 'None'

def calculate_volume_profile(df, volume_proxy):
    """Calculate volume profile to identify value areas and high volume nodes."""
    try:
        if len(df) < 30:
            current_price = df['close'].iloc[-1] if len(df) > 0 else 1.0
            return {'poc': current_price, 'value_area_high': current_price * 1.001, 'value_area_low': current_price * 0.999}
        
        # Use recent data for volume profile with NaN handling
        recent_data = df.tail(50).dropna()
        recent_volume = volume_proxy.tail(50).dropna()
        
        if len(recent_data) < 10 or len(recent_volume) < 10:
            current_price = df['close'].dropna().iloc[-1] if len(df.dropna()) > 0 else 1.0
            return {'poc': current_price, 'value_area_high': current_price * 1.001, 'value_area_low': current_price * 0.999}
        
        # Create price bins
        price_min = recent_data['low'].min()
        price_max = recent_data['high'].max()
        price_range = price_max - price_min
        
        if price_range == 0:
            current_price = df['close'].iloc[-1]
            return {'poc': current_price, 'value_area_high': current_price, 'value_area_low': current_price}
        
        num_bins = min(20, len(recent_data) // 2)
        bin_size = price_range / num_bins
        
        # Calculate volume for each price level
        volume_bins = []
        for i in range(num_bins):
            bin_low = price_min + (i * bin_size)
            bin_high = bin_low + bin_size
            bin_volume = 0
            
            for j, row in recent_data.iterrows():
                # Check if this candle's range overlaps with the bin
                candle_low = row['low']
                candle_high = row['high']
                
                if candle_high >= bin_low and candle_low <= bin_high:
                    # Calculate overlap percentage
                    overlap_low = max(bin_low, candle_low)
                    overlap_high = min(bin_high, candle_high)
                    candle_range = candle_high - candle_low
                    
                    if candle_range == 0 or pd.isna(candle_range) or candle_range < 1e-10:
                        overlap_percentage = 1.0  # Full overlap for doji candles
                    else:
                        overlap_percentage = (overlap_high - overlap_low) / candle_range
                        overlap_percentage = max(0, min(1, overlap_percentage))
                    
                    # Add proportional volume with safe indexing
                    try:
                        volume_idx = recent_data.index.get_loc(j)
                        if volume_idx < len(recent_volume):
                            bin_volume += recent_volume.iloc[volume_idx] * overlap_percentage
                    except (KeyError, IndexError):
                        # Skip if volume data not available for this index
                        continue
            
            volume_bins.append({
                'price_low': bin_low,
                'price_high': bin_high,
                'price_mid': (bin_low + bin_high) / 2,
                'volume': bin_volume
            })
        
        # Sort by volume to find POC (Point of Control)
        volume_bins.sort(key=lambda x: x['volume'], reverse=True)
        poc = volume_bins[0]['price_mid'] if volume_bins else df['close'].iloc[-1]
        
        # Calculate Value Area (70% of volume)
        total_volume = sum(bin_data['volume'] for bin_data in volume_bins)
        target_volume = total_volume * 0.7
        
        accumulated_volume = 0
        value_area_bins = []
        
        for bin_data in volume_bins:
            if accumulated_volume < target_volume:
                value_area_bins.append(bin_data)
                accumulated_volume += bin_data['volume']
        
        # Determine value area high and low
        if value_area_bins:
            value_area_high = max(bin_data['price_high'] for bin_data in value_area_bins)
            value_area_low = min(bin_data['price_low'] for bin_data in value_area_bins)
        else:
            current_price = df['close'].iloc[-1]
            value_area_high = current_price * 1.002
            value_area_low = current_price * 0.998
        
        # Current price analysis
        current_price = df['close'].iloc[-1]
        if current_price > value_area_high:
            price_position = 'Above Value Area'
        elif current_price < value_area_low:
            price_position = 'Below Value Area'
        else:
            price_position = 'Within Value Area'
        
        return {
            'poc': poc,
            'value_area_high': value_area_high,
            'value_area_low': value_area_low,
            'price_position': price_position,
            'value_area_range': value_area_high - value_area_low,
            'total_volume': total_volume,
            'high_volume_nodes': [bin_data['price_mid'] for bin_data in volume_bins[:3]],
            'volume_distribution': 'Balanced' if len(value_area_bins) > num_bins * 0.6 else 'Concentrated'
        }
    except Exception as e:
        print(f"Error in volume profile calculation: {e}")
        return {'poc': df['close'].iloc[-1], 'value_area_high': 0, 'value_area_low': 0}

def calculate_enhanced_obv(df, volume_proxy):
    """Calculate enhanced On-Balance Volume with smart money detection."""
    try:
        obv_values = []
        obv = 0
        smart_money_obv = 0
        
        # Clean data first
        volume_clean = volume_proxy.dropna()
        if len(volume_clean) < 10:
            return {'trend': 'Unknown', 'current_obv': 0, 'divergence': 'None'}
        
        for i in range(len(df)):
            if i == 0:
                obv_values.append(0)
                continue
            
            # Safe price change calculation
            if pd.isna(df['close'].iloc[i]) or pd.isna(df['close'].iloc[i-1]):
                obv_values.append(obv)
                continue
                
            price_change = df['close'].iloc[i] - df['close'].iloc[i-1]
            current_volume = volume_proxy.iloc[i] if i < len(volume_proxy) else 0
            
            if pd.isna(current_volume):
                current_volume = 0
            
            # Standard OBV
            if price_change > 0:
                obv += current_volume
            elif price_change < 0:
                obv -= current_volume
            
            obv_values.append(obv)
            
            # Smart Money OBV (weighted by volume significance)
            volume_slice = volume_proxy.iloc[max(0, i-10):i+1].dropna()
            if len(volume_slice) > 0:
                avg_volume = volume_slice.mean()
                volume_weight = min(3.0, current_volume / avg_volume) if avg_volume > 0 else 1.0
            else:
                volume_weight = 1.0
            
            if price_change > 0:
                smart_money_obv += current_volume * volume_weight
            elif price_change < 0:
                smart_money_obv -= current_volume * volume_weight
        
        # OBV trend analysis
        if len(obv_values) >= 10:
            recent_obv = obv_values[-5:]
            older_obv = obv_values[-10:-5]
            
            recent_avg = sum(recent_obv) / len(recent_obv)
            older_avg = sum(older_obv) / len(older_obv)
            
            if recent_avg > older_avg * 1.05:
                obv_trend = 'Strong Bullish'
            elif recent_avg > older_avg:
                obv_trend = 'Bullish'
            elif recent_avg < older_avg * 0.95:
                obv_trend = 'Strong Bearish'
            elif recent_avg < older_avg:
                obv_trend = 'Bearish'
            else:
                obv_trend = 'Neutral'
        else:
            obv_trend = 'Insufficient Data'
        
        # OBV divergence detection
        price_trend = df['close'].iloc[-10:].pct_change().sum()
        obv_change = (obv_values[-1] - obv_values[-10]) / abs(obv_values[-10]) if obv_values[-10] != 0 else 0
        
        divergence = 'None'
        if price_trend > 0.02 and obv_change < -0.05:
            divergence = 'Bearish Divergence'
        elif price_trend < -0.02 and obv_change > 0.05:
            divergence = 'Bullish Divergence'
        
        return {
            'trend': obv_trend,
            'current_obv': obv_values[-1],
            'smart_money_obv': smart_money_obv,
            'divergence': divergence,
            'obv_series': obv_values[-20:],  # Last 20 values for plotting
            'obv_strength': abs(obv_change) * 100
        }
    except Exception as e:
        print(f"Error in enhanced OBV calculation: {e}")
        return {'trend': 'Unknown', 'current_obv': 0, 'divergence': 'None'}

def calculate_multi_timeframe_vwap(df, volume_proxy):
    """Calculate VWAP across multiple timeframes."""
    try:
        vwap_data = {}
        
        # Standard VWAP (entire dataset)
        typical_prices = (df['high'] + df['low'] + df['close']) / 3
        cumulative_volume = volume_proxy.cumsum()
        cumulative_pv = (typical_prices * volume_proxy).cumsum()
        
        standard_vwap = cumulative_pv / cumulative_volume
        current_vwap = standard_vwap.iloc[-1]
        
        # Rolling VWAPs
        vwap_periods = [20, 50]
        rolling_vwaps = {}
        
        for period in vwap_periods:
            if len(df) >= period:
                rolling_pv = (typical_prices * volume_proxy).rolling(window=period).sum()
                rolling_vol = volume_proxy.rolling(window=period).sum()
                rolling_vwap = rolling_pv / rolling_vol
                rolling_vwaps[f'vwap_{period}'] = rolling_vwap.iloc[-1]
        
        # VWAP bands (standard deviation bands)
        if len(df) >= 20:
            vwap_20 = rolling_vwaps.get('vwap_20', current_vwap)
            price_deviations = (typical_prices.tail(20) - vwap_20) ** 2
            variance = price_deviations.mean()
            std_dev = np.sqrt(variance)
            
            vwap_upper = vwap_20 + (2 * std_dev)
            vwap_lower = vwap_20 - (2 * std_dev)
        else:
            vwap_upper = current_vwap * 1.01
            vwap_lower = current_vwap * 0.99
        
        # Current price position
        current_price = df['close'].iloc[-1]
        if current_price > vwap_upper:
            position = 'Above Upper Band'
        elif current_price < vwap_lower:
            position = 'Below Lower Band'
        elif current_price > current_vwap:
            position = 'Above VWAP'
        else:
            position = 'Below VWAP'
        
        # VWAP slope (trend direction)
        if len(standard_vwap) >= 5:
            vwap_slope = (standard_vwap.iloc[-1] - standard_vwap.iloc[-5]) / standard_vwap.iloc[-5]
            if vwap_slope > 0.002:
                vwap_trend = 'Rising'
            elif vwap_slope < -0.002:
                vwap_trend = 'Falling'
            else:
                vwap_trend = 'Flat'
        else:
            vwap_trend = 'Unknown'
        
        return {
            'current_vwap': current_vwap,
            'position': position,
            'vwap_upper': vwap_upper,
            'vwap_lower': vwap_lower,
            'vwap_trend': vwap_trend,
            'rolling_vwaps': rolling_vwaps,
            'distance_from_vwap': abs(current_price - current_vwap) / current_vwap * 100,
            'vwap_strength': 'Strong' if abs(current_price - current_vwap) / current_vwap > 0.01 else 'Weak'
        }
    except Exception as e:
        print(f"Error in VWAP calculation: {e}")
        return {'current_vwap': df['close'].iloc[-1], 'position': 'Unknown'}

def analyze_volume_trends(df, volume_proxy):
    """Analyze volume trends and patterns."""
    try:
        if len(df) < 20:
            return {'trend': 'Insufficient Data', 'strength': 0}
        
        # Clean volume data first
        volume_clean = volume_proxy.dropna()
        if len(volume_clean) < 10:
            return {'trend': 'Insufficient Data', 'strength': 0}
        
        # Volume moving averages with NaN handling
        vol_ma_10 = volume_clean.rolling(window=10, min_periods=5).mean()
        vol_ma_20 = volume_clean.rolling(window=20, min_periods=10).mean()
        
        # Get latest valid values
        current_vol = volume_clean.iloc[-1] if len(volume_clean) > 0 else 0
        recent_vol_avg = vol_ma_10.dropna().iloc[-1] if len(vol_ma_10.dropna()) > 0 else current_vol
        longer_vol_avg = vol_ma_20.dropna().iloc[-1] if len(vol_ma_20.dropna()) > 0 else recent_vol_avg
        
        # Volume trend determination with safe calculations
        if pd.isna(longer_vol_avg) or longer_vol_avg <= 1e-10:
            volume_trend = 'Stable'
            trend_strength = 50
        elif pd.isna(recent_vol_avg) or recent_vol_avg <= 1e-10:
            volume_trend = 'Stable'
            trend_strength = 50
        elif recent_vol_avg > longer_vol_avg * 1.2:
            volume_trend = 'Increasing'
            trend_strength = min(100, (recent_vol_avg / longer_vol_avg - 1) * 100)
        elif recent_vol_avg < longer_vol_avg * 0.8:
            volume_trend = 'Decreasing'
            trend_strength = min(100, (1 - recent_vol_avg / longer_vol_avg) * 100)
        else:
            volume_trend = 'Stable'
            trend_strength = 50
        
        # Volume spikes detection
        volume_spikes = []
        spike_threshold = longer_vol_avg * 2.5
        
        for i in range(len(volume_proxy) - 10, len(volume_proxy)):
            if volume_proxy.iloc[i] > spike_threshold:
                spike_direction = 'Bullish' if df['close'].iloc[i] > df['open'].iloc[i] else 'Bearish'
                volume_spikes.append({
                    'index': i,
                    'volume_ratio': volume_proxy.iloc[i] / longer_vol_avg,
                    'direction': spike_direction
                })
        
        # Volume exhaustion detection
        exhaustion_signals = []
        for i in range(len(df) - 5, len(df)):
            vol_ratio = volume_proxy.iloc[i] / vol_ma_20.iloc[i] if vol_ma_20.iloc[i] > 0 else 1
            price_change = abs(df['close'].iloc[i] - df['open'].iloc[i]) / df['open'].iloc[i]
            
            # High volume with small price movement suggests exhaustion
            if vol_ratio > 2.0 and price_change < 0.005:
                exhaustion_signals.append({
                    'index': i,
                    'type': 'Volume Exhaustion',
                    'volume_ratio': vol_ratio
                })
        
        return {
            'trend': volume_trend,
            'strength': trend_strength,
            'current_vs_average': safe_divide(current_vol, recent_vol_avg, 1),
            'volume_spikes': volume_spikes,
            'exhaustion_signals': exhaustion_signals,
            'vol_ma_10': recent_vol_avg,
            'vol_ma_20': longer_vol_avg,
            'spike_count': len(volume_spikes),
            'activity_level': 'High' if len(volume_spikes) > 2 else 'Moderate' if len(volume_spikes) > 0 else 'Low'
        }
    except Exception as e:
        print(f"Error in volume trend analysis: {e}")
        return {'trend': 'Unknown', 'strength': 0}

def detect_volume_divergence(df, volume_proxy):
    """Detect volume divergences with price action."""
    try:
        if len(df) < 20:
            return {'divergence_type': 'None', 'strength': 0}
        
        # Recent price and volume trends
        recent_prices = df['close'].tail(10)
        recent_volumes = volume_proxy.tail(10)
        
        # Calculate trends safely
        try:
            price_slope = np.polyfit(range(len(recent_prices)), recent_prices.values, 1)[0] if len(recent_prices) >= 2 else 0
            volume_slope = np.polyfit(range(len(recent_volumes)), recent_volumes.values, 1)[0] if len(recent_volumes) >= 2 else 0
        except:
            price_slope = 0
            volume_slope = 0
        
        # Normalize slopes for comparison using safe division
        price_trend = safe_divide(price_slope, recent_prices.iloc[0], 0)
        volume_trend = safe_divide(volume_slope, recent_volumes.iloc[0], 0)
        
        # Divergence detection
        divergence_threshold = 0.01  # 1% threshold
        
        if price_trend > divergence_threshold and volume_trend < -divergence_threshold:
            divergence_type = 'Bearish Divergence'
            strength = min(100, abs(price_trend - volume_trend) * 1000)
        elif price_trend < -divergence_threshold and volume_trend > divergence_threshold:
            divergence_type = 'Bullish Divergence'
            strength = min(100, abs(price_trend - volume_trend) * 1000)
        else:
            divergence_type = 'None'
            strength = 0
        
        # Additional confirmation using swing points
        swing_confirmation = False
        if divergence_type != 'None':
            # Look for swing highs/lows in recent data
            for i in range(2, len(recent_prices) - 2):
                if (recent_prices.iloc[i] > recent_prices.iloc[i-1] and 
                    recent_prices.iloc[i] > recent_prices.iloc[i+1]):
                    # Found swing high, check volume
                    if recent_volumes.iloc[i] < safe_mean(recent_volumes.iloc[:i]):
                        swing_confirmation = True
                        break
                elif (recent_prices.iloc[i] < recent_prices.iloc[i-1] and 
                      recent_prices.iloc[i] < recent_prices.iloc[i+1]):
                    # Found swing low, check volume
                    if recent_volumes.iloc[i] < safe_mean(recent_volumes.iloc[:i]):
                        swing_confirmation = True
                        break
        
        return {
            'divergence_type': divergence_type,
            'strength': strength,
            'price_trend': 'Rising' if price_trend > 0 else 'Falling',
            'volume_trend': 'Rising' if volume_trend > 0 else 'Falling',
            'swing_confirmation': swing_confirmation,
            'confidence': 'High' if swing_confirmation and strength > 60 else 'Medium' if strength > 30 else 'Low'
        }
    except Exception as e:
        print(f"Error in volume divergence detection: {e}")
        return {'divergence_type': 'None', 'strength': 0}

def calculate_cumulative_delta(df, volume_proxy):
    """Approximate cumulative delta using price action analysis."""
    try:
        if len(df) < 10:
            return {'cumulative_delta': 0, 'delta_trend': 'Unknown'}
        
        delta_values = []
        cumulative_delta = 0
        
        for i in range(1, len(df)):
            current = df.iloc[i]
            previous = df.iloc[i-1]
            
            price_change = current['close'] - previous['close']
            volume = volume_proxy.iloc[i]
            
            # Estimate buying vs selling pressure
            range_value = current['high'] - current['low']
            if range_value == 0 or pd.isna(range_value) or range_value < 1e-10:
                close_position = 0.5  # Neutral position for doji or invalid data
            else:
                close_position = (current['close'] - current['low']) / range_value
                close_position = max(0, min(1, close_position))
            
            # Delta calculation
            if price_change > 0:
                # Up move - more buying pressure
                buying_volume = volume * close_position
                selling_volume = volume * (1 - close_position)
                delta = buying_volume - selling_volume
            elif price_change < 0:
                # Down move - more selling pressure
                buying_volume = volume * (1 - close_position)
                selling_volume = volume * close_position
                delta = buying_volume - selling_volume
            else:
                # No price change
                delta = volume * (close_position - 0.5) * 2
            
            cumulative_delta += delta
            delta_values.append(delta)
        
        # Delta trend analysis
        if len(delta_values) >= 10:
            recent_delta = sum(delta_values[-5:])
            older_delta = sum(delta_values[-10:-5])
            
            if recent_delta > older_delta * 1.2:
                delta_trend = 'Bullish'
            elif recent_delta < older_delta * 0.8:
                delta_trend = 'Bearish'
            else:
                delta_trend = 'Neutral'
        else:
            delta_trend = 'Unknown'
        
        # Delta divergence with price
        price_direction = 1 if df['close'].iloc[-1] > df['close'].iloc[-10] else -1
        delta_direction = 1 if cumulative_delta > 0 else -1
        
        delta_divergence = 'None'
        if price_direction != delta_direction:
            if price_direction > 0 and delta_direction < 0:
                delta_divergence = 'Bearish (Price up, Delta down)'
            else:
                delta_divergence = 'Bullish (Price down, Delta up)'
        
        return {
            'cumulative_delta': cumulative_delta,
            'delta_trend': delta_trend,
            'recent_delta': sum(delta_values[-5:]) if len(delta_values) >= 5 else 0,
            'delta_divergence': delta_divergence,
            'delta_strength': abs(cumulative_delta),
            'delta_per_period': cumulative_delta / len(delta_values) if delta_values else 0
        }
    except Exception as e:
        print(f"Error in cumulative delta calculation: {e}")
        return {'cumulative_delta': 0, 'delta_trend': 'Unknown'}
    
def get_active_market_sessions():
    """Get currently active market sessions based on UTC time."""
    current_hour = datetime.now(timezone.utc).hour
    active_sessions = []
    
    # Check each session
    for session, times in MARKET_SESSIONS.items():
        start_hour = times['start']
        end_hour = times['end']
        
        # Handle sessions that cross midnight
        if start_hour <= end_hour:
            if start_hour <= current_hour <= end_hour:
                active_sessions.append(session)
        else:
            # Session crosses midnight
            if current_hour >= start_hour or current_hour <= end_hour:
                active_sessions.append(session)
    
    return active_sessions

def analyze_market_conditions(df):
    """Analyze current market conditions for trading."""
    if df is None or df.empty or len(df) < 20:
        return []
    
    conditions = []
    
    try:
        # Check for trending vs ranging
        regime_data = detect_market_regime(df)
        if regime_data.get('regime') == 'Trending':
            conditions.append(f"Trending market ({regime_data.get('strength', 0):.0f}%)")
        elif regime_data.get('regime') == 'Ranging':
            conditions.append(f"Ranging market ({regime_data.get('strength', 0):.0f}%)")
        
        # Check volatility
        if len(df) >= 14:
            atr = ((df['high'] - df['low']).tail(14).mean())
            current_price = df['close'].iloc[-1]
            volatility_pct = (atr / current_price) * 100
            
            if volatility_pct > 2.0:
                conditions.append("High volatility environment")
            elif volatility_pct < 0.5:
                conditions.append("Low volatility environment")
            else:
                conditions.append("Normal volatility")
        
        # Check market sessions
        active_sessions = get_active_market_sessions()
        if active_sessions:
            conditions.append(f"Active sessions: {', '.join(active_sessions)}")
        
    except Exception as e:
        print(f"Error analyzing market conditions: {e}")
    
    return conditions[:5]  # Return top 5 conditions

def analyze_market_sentiment(df):
    """Analyze market sentiment using price action and momentum indicators."""
    
    if len(df) < 30:
        return {'score': 0, 'sentiment': 'Neutral', 'strength': 0, 'factors': []}
    
    sentiment_score = 0
    factors = []
    
    # Initialize analysis here
    analysis = ""
    
    # 1. Consecutive candle analysis
    recent_candles = df.tail(5)
    bullish_candles = sum(1 for i in range(len(recent_candles)) if recent_candles['close'].iloc[i] > recent_candles['open'].iloc[i])
    bearish_candles = sum(1 for i in range(len(recent_candles)) if recent_candles['close'].iloc[i] < recent_candles['open'].iloc[i])
    
    if bullish_candles >= 4:
        sentiment_score += 3
        factors.append('Strong bullish momentum (4/5 green candles)')
    elif bullish_candles >= 3:
        sentiment_score += 1
        factors.append('Bullish momentum (3/5 green candles)')
    elif bearish_candles >= 4:
        sentiment_score -= 3
        factors.append('Strong bearish momentum (4/5 red candles)')
    elif bearish_candles >= 3:
        sentiment_score -= 1
        factors.append('Bearish momentum (3/5 red candles)')
    
    # 2. Price position relative to recent range
    recent_high = df['high'].tail(20).max()
    recent_low = df['low'].tail(20).min()
    current_price = df['close'].iloc[-1]
    
    if recent_high != recent_low:
        price_position = (current_price - recent_low) / (recent_high - recent_low)
        if price_position > 0.8:
            sentiment_score += 2
            factors.append('Price near 20-period highs')
        elif price_position > 0.6:
            sentiment_score += 1
            factors.append('Price above 20-period midpoint')
        elif price_position < 0.2:
            sentiment_score -= 2
            factors.append('Price near 20-period lows')
        elif price_position < 0.4:
            sentiment_score -= 1
            factors.append('Price below 20-period midpoint')
    
    # 3. Moving average alignment
    if len(df) >= 50:
        ema_9 = df['close'].ewm(span=9).mean()
        ema_21 = df['close'].ewm(span=21).mean()
        ema_50 = df['close'].ewm(span=50).mean()
        
        current_ema9 = ema_9.iloc[-1]
        current_ema21 = ema_21.iloc[-1]
        current_ema50 = ema_50.iloc[-1]
        
        if current_ema9 > current_ema21 > current_ema50:
            sentiment_score += 2
            factors.append('Bullish EMA alignment (9>21>50)')
        elif current_ema9 < current_ema21 < current_ema50:
            sentiment_score -= 2
            factors.append('Bearish EMA alignment (9<21<50)')
    
    # 4. Volume momentum (using proxy)
    df['volume_proxy'] = (df['high'] - df['low']) + abs(df['close'] - df['open'])
    recent_volume = df['volume_proxy'].tail(5).mean()
    avg_volume = df['volume_proxy'].tail(20).mean()
    
    if recent_volume > avg_volume * 1.5:
        if sentiment_score > 0:
            sentiment_score += 1
            factors.append('High volume confirms bullish sentiment')
        elif sentiment_score < 0:
            sentiment_score -= 1
            factors.append('High volume confirms bearish sentiment')
    
    # 5. Volatility analysis
    recent_volatility = df['close'].tail(10).std()
    overall_volatility = df['close'].tail(50).std()
    
    signalsOperator = 0
    if recent_volatility > overall_volatility * 1.3:
        signalsOperator += 1
        
        chart_pattern_analysis = get_chart_pattern_analysis(df, current_price)        
        analysis += f"\n{chart_pattern_analysis}"
    # Candlestick Patterns
    patterns = detect_candlestick_patterns(df)
    if patterns:
        analysis += f"\n🕯️ **Candlestick Patterns**:\n"
        for pattern_type, pattern_name in patterns.items():
            analysis += f"   • {pattern_name}\n"

    if not analysis or analysis.strip() == "📊 **Market Structure**":
        analysis = "📊 Neutral ICT Conditions - No significant patterns detected"

    return {
        'score': sentiment_score,
        'sentiment': 'Bullish' if sentiment_score > 0 else 'Bearish' if sentiment_score < 0 else 'Neutral',
        'strength': abs(sentiment_score),
        'factors': factors,
        'analysis': analysis
    }

async def fetch_batch_data(symbols, interval, days_back=0, candle_count=None):
    """Fetch fresh data for multiple symbols using Twelve Data for forex and CoinGecko for crypto."""
    global current_api_index
    results = {}
    
    # Use timeframe-specific candle count if not provided
    if candle_count is None:
        candle_count = TIMEFRAME_CANDLES.get(interval, 200)
    
    # Separate crypto and forex pairs for different handling
    crypto_symbols = [s for s in symbols if is_crypto_pair(s)]
    forex_symbols = [s for s in symbols if not is_crypto_pair(s)]
    
    # Handle crypto pairs with CoinGecko (can be more concurrent as no rate limits)
    if crypto_symbols:
        crypto_semaphore = asyncio.Semaphore(min(5, len(crypto_symbols)))
        
        async def fetch_crypto_with_semaphore(symbol):
            async with crypto_semaphore:
                try:
                    data = await fetch_crypto_data_coingecko(symbol, interval, days_back, candle_count)
                    if data is not None and hasattr(data, '__len__') and len(data) >= 10:
                        return symbol, data
                    await asyncio.sleep(0.2)  # Small delay for CoinGecko
                    return symbol, None
                except Exception as e:
                    print(f"Error fetching crypto {symbol}: {e}")
                    return symbol, None
        
        crypto_tasks = [fetch_crypto_with_semaphore(symbol) for symbol in crypto_symbols]
        crypto_results = await asyncio.gather(*crypto_tasks, return_exceptions=True)
        
        for result in crypto_results:
            if isinstance(result, Exception):
                print(f"Crypto task failed with exception: {result}")
                continue
            symbol, data = result
            if data is not None:
                results[symbol] = data
    
    # Handle forex pairs with Twelve Data (more limited concurrency)
    if forex_symbols:
        max_concurrent = min(3, len(forex_symbols))
        forex_semaphore = asyncio.Semaphore(max_concurrent)
        
        async def fetch_forex_with_semaphore(symbol):
            async with forex_semaphore:
                try:
                    # Add exponential backoff for rate limited requests
                    for attempt in range(3):
                        try:
                            # Run the synchronous function in an executor
                            loop = asyncio.get_event_loop()
                            individual_data = await loop.run_in_executor(
                                None, fetch_data_individual, symbol, interval, days_back, candle_count
                            )
                            if individual_data is not None and hasattr(individual_data, '__len__') and len(individual_data) >= 10:
                                return symbol, individual_data
                            
                            # Small delay between requests
                            await asyncio.sleep(0.5 + (attempt * 0.3))
                            
                        except Exception as e:
                            if "rate limit" in str(e).lower():
                                wait_time = (2 ** attempt) + random.uniform(0, 1)
                                print(f"Rate limited for {symbol}, waiting {wait_time:.1f}s")
                                await asyncio.sleep(wait_time)
                            else:
                                print(f"Error fetching {symbol} (attempt {attempt + 1}): {e}")
                                if attempt == 2:  # Last attempt
                                    break
                                await asyncio.sleep(1)
                    
                    return symbol, None
                    
                except Exception as e:
                    print(f"Critical error for {symbol}: {e}")
                    return symbol, None
        
        # Process forex symbols in chunks to prevent memory issues
        chunk_size = 5
        for i in range(0, len(forex_symbols), chunk_size):
            chunk = forex_symbols[i:i + chunk_size]
            tasks = [fetch_forex_with_semaphore(symbol) for symbol in chunk]
            
            chunk_results = await asyncio.gather(*tasks, return_exceptions=True)
            
            for result in chunk_results:
                if isinstance(result, Exception):
                    print(f"Forex task failed with exception: {result}")
                    continue
                    
                symbol, data = result
                if data is not None:
                    results[symbol] = data
            
            # Small delay between chunks
            if i + chunk_size < len(forex_symbols):
                await asyncio.sleep(1)
    
    print(f"Batch fetch completed: {len(results)}/{len(symbols)} symbols successful")
    return results

def process_dataframe(df):
    """Process raw dataframe from API into standard format with enhanced quality checks."""
    try:
        if df is None:
            print("DataFrame is None in process_dataframe")
            return None
            
        if not hasattr(df, 'empty'):
            print("DataFrame object is invalid in process_dataframe")
            return None
            
        if df.empty:
            print("DataFrame is empty in process_dataframe")
            return None
        
        # Create a copy to avoid modifying original
        df_copy = df.copy()
        
        # Reset index safely
        if hasattr(df_copy, 'reset_index'):
            df_copy = df_copy.reset_index()

        # Check required columns exist
        required_cols = ['open', 'high', 'low', 'close']
        missing_cols = [col for col in required_cols if col not in df_copy.columns]
        if missing_cols:
            print(f"Missing required columns: {missing_cols}. Available: {list(df_copy.columns)}")
            return None

        # Handle datetime column
        if 'datetime' not in df_copy.columns:
            if 'index' in df_copy.columns:
                df_copy['datetime'] = pd.to_datetime(df_copy['index'], errors='coerce')
            elif hasattr(df_copy, 'index') and len(df_copy.index) > 0:
                df_copy['datetime'] = pd.to_datetime(df_copy.index, errors='coerce')
            else:
                print("No datetime column and no valid index available")
                return None
        else:
            df_copy['datetime'] = pd.to_datetime(df_copy['datetime'], errors='coerce')

        # Select only required columns
        try:
            df_processed = df_copy[['datetime', 'open', 'high', 'low', 'close']].copy()
        except KeyError as e:
            print(f"Error selecting columns: {e}")
            return None
        
        # Convert to numeric with better error handling
        for col in ['open', 'high', 'low', 'close']:
            df_processed[col] = pd.to_numeric(df_processed[col], errors='coerce')
        
        # Validate OHLC relationships
        df_processed = validate_ohlc_integrity(df_processed)
        
        # Remove rows with NaN values
        df_processed = df_processed.dropna()
        
        if len(df_processed) < 10:
            return None
        
        # Ensure datetime is valid
        if df_processed['datetime'].isnull().any():
            return None
        
        # Sort by datetime and remove duplicates
        df_processed = df_processed.sort_values('datetime').drop_duplicates(subset=['datetime']).reset_index(drop=True)
        return df_processed
        
    except Exception as e:
        print(f"Error processing dataframe: {e}")
        import traceback
        traceback.print_exc()
        return None

def validate_ohlc_integrity(df):
    """Optimized OHLC data integrity validation with better performance and reliability."""
    try:
        if df is None or df.empty or len(df) == 0:
            return df
        
        # Work on a copy
        df_clean = df.copy()
        
        # Quick NaN check and removal
        nan_mask = df_clean[['open', 'high', 'low', 'close']].isna().any(axis=1)
        if nan_mask.any():
            df_clean = df_clean[~nan_mask].reset_index(drop=True)
        
        if len(df_clean) == 0:
            return pd.DataFrame()
        
        # Vectorized operations for better performance
        opens = df_clean['open'].values
        highs = df_clean['high'].values
        lows = df_clean['low'].values
        closes = df_clean['close'].values
        
        # Check for zero or negative prices (vectorized)
        positive_mask = (opens > 0) & (highs > 0) & (lows > 0) & (closes > 0)
        if not positive_mask.all():
            df_clean = df_clean[positive_mask].reset_index(drop=True)
            opens = df_clean['open'].values
            highs = df_clean['high'].values
            lows = df_clean['low'].values
            closes = df_clean['close'].values
        
        if len(df_clean) == 0:
            return pd.DataFrame()
        
        # Basic OHLC relationship validation (vectorized)
        body_highs = np.maximum(opens, closes)
        body_lows = np.minimum(opens, closes)
        
        # Fix invalid relationships
        invalid_high_mask = highs < body_highs
        invalid_low_mask = lows > body_lows
        
        if invalid_high_mask.any():
            df_clean.loc[invalid_high_mask, 'high'] = body_highs[invalid_high_mask]
        
        if invalid_low_mask.any():
            df_clean.loc[invalid_low_mask, 'low'] = body_lows[invalid_low_mask]
        
        # Update arrays after fixes
        highs = df_clean['high'].values
        lows = df_clean['low'].values
        
        # Calculate statistics for wick validation
        body_sizes = np.abs(closes - opens)
        median_body_size = np.median(body_sizes[body_sizes > 0])
        
        if median_body_size == 0:
            median_body_size = np.mean(highs - lows) * 0.1  # Fallback
        
        # Wick calculations
        upper_wicks = highs - body_highs
        lower_wicks = body_lows - lows
        total_ranges = highs - lows
        
        # Identify unrealistic wicks (more conservative thresholds)
        unrealistic_mask = np.zeros(len(df_clean), dtype=bool)
        
        # Check for extremely long wicks relative to body
        for i in range(len(df_clean)):
            if body_sizes[i] > 0:
                # Wick > 8x body size (reduced from 10x)
                if upper_wicks[i] > body_sizes[i] * 8 or lower_wicks[i] > body_sizes[i] * 8:
                    unrealistic_mask[i] = True
            
            # Check against median body size (reduced threshold)
            if upper_wicks[i] > median_body_size * 12 or lower_wicks[i] > median_body_size * 12:
                unrealistic_mask[i] = True
            
            # Check wick-to-range ratio (more lenient)
            if total_ranges[i] > 0:
                max_wick = max(upper_wicks[i], lower_wicks[i])
                wick_ratio = max_wick / total_ranges[i]
                if wick_ratio > 0.85 and max_wick > body_sizes[i] * 6:
                    unrealistic_mask[i] = True
        
        # Fix unrealistic wicks by capping them
        fixes_applied = 0
        for i in range(len(df_clean)):
            if unrealistic_mask[i]:
                # Calculate reasonable wick size
                max_wick_size = max(body_sizes[i] * 4, median_body_size * 3)
                
                # Cap upper wick
                if upper_wicks[i] > max_wick_size:
                    df_clean.iloc[i, df_clean.columns.get_loc('high')] = body_highs[i] + max_wick_size
                    fixes_applied += 1
                
                # Cap lower wick
                if lower_wicks[i] > max_wick_size:
                    df_clean.iloc[i, df_clean.columns.get_loc('low')] = body_lows[i] - max_wick_size
                    fixes_applied += 1
        
        # Check for extreme price movements (crypto vs forex)
        price_movements = np.abs(closes - opens) / opens
        extreme_movement_threshold = 0.25  # 25% movement threshold
        extreme_mask = price_movements > extreme_movement_threshold
        
        # For forex pairs, be more strict
        if any('/' in str(col) for col in df.columns if 'datetime' not in str(col)):
            extreme_movement_threshold = 0.15  # 15% for forex
            extreme_mask = price_movements > extreme_movement_threshold
        
        # Remove extremely volatile candles that are likely errors
        if extreme_mask.any():
            df_clean = df_clean[~extreme_mask].reset_index(drop=True)
        
        # Final quality check
        if len(df_clean) < len(df) * 0.7:  # If we removed more than 30% of data
            print(f"Warning: Removed {len(df) - len(df_clean)} candles ({((len(df) - len(df_clean))/len(df)*100):.1f}%)")
            # If too much data was removed, return original with basic fixes only
            if len(df_clean) < 10:
                return df.dropna().reset_index(drop=True)
        
        return df_clean.reset_index(drop=True)
        
    except Exception as e:
        print(f"Error in OHLC validation: {e}")
        # Return original data with basic cleanup as fallback
        try:
            return df.dropna().reset_index(drop=True)
        except:
            return df

def fetch_data_individual(symbol, interval, days_back=0, candle_count=None):
    """Individual data fetch with enhanced data continuity. Uses CoinGecko for crypto pairs."""
    global current_api_index
    max_retries = 3
    
    # Check if this is a crypto pair and use CoinGecko
    if is_crypto_pair(symbol):
        return fetch_crypto_data_coingecko_sync(symbol, interval, days_back, candle_count)
    
    # Use timeframe-specific candle count if not provided
    if candle_count is None:
        candle_count = TIMEFRAME_CANDLES.get(interval, 200)
    
    for attempt in range(max_retries):
        try:
            # Add delay to prevent heartbeat rate limiting
            time.sleep(0.5)  # 500ms delay between API requests
            
            current_td, api_index = get_next_api_client()
            
            # Request more data to ensure continuity
            if days_back > 0:
                end_date = datetime.now(timezone.utc)
                start_date = end_date - timedelta(days=days_back + 2)  # Extra buffer
                api_interval = convert_timeframe_for_provider(interval, "twelvedata")
                ts = current_td.time_series(
                    symbol=symbol,
                    interval=api_interval,
                    outputsize=candle_count,
                    start_date=start_date.strftime('%Y-%m-%d %H:%M:%S'),
                    end_date=end_date.strftime('%Y-%m-%d %H:%M:%S')
                )
            else:
                api_interval = convert_timeframe_for_provider(interval, "twelvedata")
                ts = current_td.time_series(
                    symbol=symbol,
                    interval=api_interval,
                    outputsize=candle_count
                )

            # Check if ts is None or empty
            if ts is None:
                print(f"API returned None for {symbol} on attempt {attempt + 1}")
                if attempt < max_retries - 1:
                    time.sleep(2 ** attempt)
                    continue
                else:
                    return None

            # Additional check for ts object
            if not hasattr(ts, 'as_pandas'):
                print(f"API response invalid for {symbol} on attempt {attempt + 1}")
                if attempt < max_retries - 1:
                    time.sleep(2 ** attempt)
                    continue
                else:
                    return None

            df = ts.as_pandas()
            
            # Check if df is None
            if df is None:
                print(f"DataFrame is None for {symbol} on attempt {attempt + 1}")
                if attempt < max_retries - 1:
                    time.sleep(2 ** attempt)
                    continue
                else:
                    return None
            
            result = process_dataframe(df)
            if result is not None and not result.empty:
                validated_result = validate_data_continuity(result, symbol, interval)
                return validated_result
            else:
                print(f"Processed dataframe is empty for {symbol} on attempt {attempt + 1}")
                if attempt < max_retries - 1:
                    time.sleep(2 ** attempt)
                    continue
                
        except requests.exceptions.Timeout:
            print(f"Timeout on attempt {attempt + 1} for {symbol}")
            if attempt < max_retries - 1:
                time.sleep(2 ** attempt)
        except requests.exceptions.RequestException as e:
            print(f"Network error on attempt {attempt + 1} for {symbol}: {e}")
            if attempt < max_retries - 1:
                time.sleep(2 ** attempt)
        except AttributeError as e:
            print(f"API response error for {symbol} on attempt {attempt + 1}: {e}")
            if attempt < max_retries - 1:
                time.sleep(2 ** attempt)
        except Exception as e:
            print(f"Individual fetch failed for {symbol} on attempt {attempt + 1}: {e}")
            if attempt < max_retries - 1:
                time.sleep(1)
    
    print(f"All {max_retries} attempts failed for {symbol}")
    return None
    
def fetch_crypto_data_coingecko_sync(symbol, interval, days_back=0, candle_count=None):
    """Fetch cryptocurrency data from CoinGecko - synchronous version."""
    try:
        # Parse the crypto pair (e.g., "BTC/USD" -> "BTC", "USD")
        crypto, fiat = symbol.split('/')
        
        # Get CoinGecko ID for the cryptocurrency
        crypto_id = get_coingecko_id(crypto)
        if not crypto_id:
            print(f"CoinGecko ID not found for {crypto}")
            return None
        
        # Calculate days for CoinGecko request
        if days_back > 0:
            days = days_back
        else:
            # Estimate days based on interval and candle count
            if candle_count is None:
                candle_count = TIMEFRAME_CANDLES.get(interval, 200)
            
            interval_hours = {
                '1min': 1/60, '5min': 5/60, '15min': 15/60, '30min': 0.5,
                '1h': 1, '4h': 4, '1day': 24
            }
            hours_per_candle = interval_hours.get(interval, 1)
            days = max(1, int((candle_count * hours_per_candle) / 24))
        
        # Limit to CoinGecko's maximum
        days = min(days, 365)
        
        df = fetch_coingecko_ohlc(crypto_id, fiat.lower(), days)
        
        if df is None or df.empty:
            print(f"No CoinGecko OHLC data for {symbol}")
            return None
        
        df_processed = process_dataframe(df)
        if df_processed is not None and not df_processed.empty:
            validated_result = validate_data_continuity(df_processed, symbol, interval)
            print(f"Successfully fetched {len(validated_result)} candles for {symbol} from CoinGecko")
            return validated_result
        
        return None
        
    except Exception as e:
        print(f"Error fetching crypto data from CoinGecko for {symbol}: {e}")
        return None

async def fetch_crypto_data_coingecko(symbol, interval, days_back=0, candle_count=None):
    """Fetch cryptocurrency data from CoinGecko - async version."""
    try:
        # Parse the crypto pair (e.g., "BTC/USD" -> "BTC", "USD")
        crypto, fiat = symbol.split('/')
        
        # Get CoinGecko ID for the cryptocurrency
        crypto_id = get_coingecko_id(crypto)
        if not crypto_id:
            print(f"CoinGecko ID not found for {crypto}")
            return None
        
        # Calculate days for CoinGecko request
        if days_back > 0:
            days = days_back
        else:
            # Estimate days based on interval and candle count
            if candle_count is None:
                candle_count = TIMEFRAME_CANDLES.get(interval, 200)
            
            interval_hours = {
                '1min': 1/60, '5min': 5/60, '15min': 15/60, '30min': 0.5,
                '1h': 1, '4h': 4, '1day': 24
            }
            hours_per_candle = interval_hours.get(interval, 1)
            days = max(1, int((candle_count * hours_per_candle) / 24))
        
        # Limit to CoinGecko's maximum
        days = min(days, 365)
        
        # ✅ Run the blocking CoinGecko API call in a thread pool
        loop = asyncio.get_event_loop()
        df = await loop.run_in_executor(None, fetch_coingecko_ohlc, crypto_id, fiat.lower(), days)
        
        if df is None or df.empty:
            print(f"No CoinGecko OHLC data for {symbol}")
            return None
        
        # ✅ Run the blocking processing in a thread pool too
        df_processed = await loop.run_in_executor(None, process_dataframe, df)
        if df_processed is not None and not df_processed.empty:
            validated_result = await loop.run_in_executor(None, validate_data_continuity, df_processed, symbol, interval)
            print(f"Successfully fetched {len(validated_result)} candles for {symbol} from CoinGecko")
            return validated_result
        
        return None
        
    except Exception as e:
        print(f"Error fetching crypto data from CoinGecko for {symbol}: {e}")
        return None
        
async def fetch_individual_fallback(symbols, interval, days_back, candle_count=None):
    """Fallback to individual requests with delays."""
    results = {}
    for symbol in symbols:
        try:
            # Run the synchronous function in an executor
            loop = asyncio.get_event_loop()
            if is_crypto_pair(symbol):
                data = await fetch_crypto_data_coingecko(symbol, interval, days_back, candle_count)
            else:
                data = await loop.run_in_executor(
                    None, fetch_data_individual, symbol, interval, days_back, candle_count
                )
            if data is not None:
                results[symbol] = data
            await asyncio.sleep(0.5)  # ✅ Non-blocking
        except Exception as e:
            print(f"Fallback failed for {symbol}: {e}")
            continue
    return results


# Fetch Historical or Real-Time Data
async def fetch_data(symbol, interval, days_back=0, candle_count=None):
    """Fetch OHLC data for a single symbol - wrapper for batch function."""
    batch_result = await fetch_batch_data([symbol], interval, days_back, candle_count)
    return batch_result.get(symbol)

# Fetch Indicators
def get_indicators(df, index=-1):
    """Compute 7 optimal high-quality technical indicators."""
    try:
        if df is None:
            print("Error: DataFrame is None in get_indicators")
            return None
            
        if not hasattr(df, 'empty'):
            print("Error: DataFrame object is invalid in get_indicators")
            return None
            
        if df.empty:
            print("Error: DataFrame is empty in get_indicators")
            return None
            
        if len(df) < 20:
            print(f"Error computing indicators: Insufficient data (need 20+ candles, got {len(df)})")
            return None

        try:
            df_copy = df.copy()
        except Exception as e:
            print(f"Error copying dataframe: {e}")
            return None

        # Validate required columns
        required_cols = ['open', 'high', 'low', 'close']
        if not all(col in df_copy.columns for col in required_cols):
            print(f"Error: Missing required columns. Found: {list(df_copy.columns)}")
            return None

        # Convert to numeric with better error handling
        numeric_cols = ['open', 'high', 'low', 'close']
        for col in numeric_cols:
            try:
                df_copy[col] = pd.to_numeric(df_copy[col], errors='coerce')
            except Exception as e:
                print(f"Error converting {col} to numeric: {e}")
                return None

        # Check for NaN values and handle them
        nan_counts = df_copy[numeric_cols].isnull().sum()
        if nan_counts.any():
            print(f"Warning: Found NaN values in OHLC data: {nan_counts.to_dict()}")
            df_copy[numeric_cols] = df_copy[numeric_cols].fillna(method='ffill')
            if df_copy[numeric_cols].isnull().any().any():
                print("Error: Could not handle NaN values in OHLC data")
                return None

        # Validate index is within bounds
        if abs(index) >= len(df_copy):
            return None

        indicators = {}

        # 1. RSI (Relative Strength Index) - 14 period
        delta = df_copy['close'].diff()
        gain = (delta.where(delta > 0, 0)).rolling(window=14).mean()
        loss = (-delta.where(delta < 0, 0)).rolling(window=14).mean()
        
        # Prevent division by zero more robustly
        loss = loss.fillna(0.0001)
        loss = np.where(loss == 0, 0.0001, loss)
        loss = np.where(np.isnan(loss), 0.0001, loss)
        
        # Calculate RS with safe division
        with np.errstate(divide='ignore', invalid='ignore'):
            rs = gain / loss
            rs = np.where(np.isinf(rs), 100, rs)
            rs = np.where(np.isnan(rs), 1, rs)
            rs = pd.Series(rs, index=gain.index)
        
        rsi = 100 - (100 / (1 + rs))
        rsi = rsi.fillna(50.0)  # Fill NaN with neutral RSI value
        
        # Ensure we have valid RSI values
        rsi = np.where(np.isnan(rsi), 50.0, rsi)
        rsi = np.where(np.isinf(rsi), 50.0, rsi)
        
        if len(rsi) > abs(index):
            if hasattr(rsi, 'iloc'):
                indicators["rsi"] = rsi.iloc[index] if not pd.isna(rsi.iloc[index]) else 50.0
            else:
                # Fix subscriptable error by safely accessing array elements
                if isinstance(rsi, (list, np.ndarray)):
                    indicators["rsi"] = float(rsi[index]) if len(rsi) > abs(index) else 50.0
                else:
                    indicators["rsi"] = 50.0
        else:
            indicators["rsi"] = 50.0

        # 2. MACD (Moving Average Convergence Divergence)
        ema12 = df_copy['close'].ewm(span=12).mean()
        ema26 = df_copy['close'].ewm(span=26).mean()
        macd_line = ema12 - ema26
        macd_signal = macd_line.ewm(span=9).mean()
        
        if len(macd_line) > abs(index):
            indicators["macd"] = macd_line.iloc[index] if not pd.isna(macd_line.iloc[index]) else 0.0
        else:
            indicators["macd"] = 0.0
            
        if len(macd_signal) > abs(index):
            indicators["macd_signal"] = macd_signal.iloc[index] if not pd.isna(macd_signal.iloc[index]) else 0.0
        else:
            indicators["macd_signal"] = 0.0

        # 3. Bollinger Bands (20 period, 2 std dev)
        rolling_mean = df_copy['close'].rolling(window=20).mean()
        rolling_std = df_copy['close'].rolling(window=20).std()
        bb_upper = rolling_mean + (rolling_std * 2)
        bb_lower = rolling_mean - (rolling_std * 2)
        
        if len(bb_upper) > abs(index):
            indicators["bb_upper"] = bb_upper.iloc[index] if not pd.isna(bb_upper.iloc[index]) else df_copy['high'].iloc[index]
            indicators["bb_lower"] = bb_lower.iloc[index] if not pd.isna(bb_lower.iloc[index]) else df_copy['low'].iloc[index]
            indicators["bb_middle"] = rolling_mean.iloc[index] if not pd.isna(rolling_mean.iloc[index]) else df_copy['close'].iloc[index]
        else:
            indicators["bb_upper"] = df_copy['high'].iloc[index] if len(df_copy) > abs(index) else 1.0
            indicators["bb_lower"] = df_copy['low'].iloc[index] if len(df_copy) > abs(index) else 1.0
            indicators["bb_middle"] = df_copy['close'].iloc[index] if len(df_copy) > abs(index) else 1.0

        # 4. Stochastic Oscillator (14 period)
        lowest_low = df_copy['low'].rolling(window=14).min()
        highest_high = df_copy['high'].rolling(window=14).max()
        
        range_hh_ll = highest_high - lowest_low
        # More robust handling of zero range
        range_hh_ll = range_hh_ll.replace(0, 0.0001)
        range_hh_ll = range_hh_ll.fillna(0.0001)
        range_hh_ll = np.where(range_hh_ll == 0, 0.0001, range_hh_ll)
        
        stoch_k = 100 * ((df_copy['close'] - lowest_low) / range_hh_ll)
        stoch_k = stoch_k.replace([np.inf, -np.inf], 50.0)
        stoch_k = stoch_k.fillna(50.0)
        stoch_d = stoch_k.rolling(window=3).mean()
        stoch_d = stoch_d.fillna(50.0)
        
        if len(stoch_k) > abs(index):
            indicators["stoch_k"] = stoch_k.iloc[index] if not pd.isna(stoch_k.iloc[index]) else 50.0
        else:
            indicators["stoch_k"] = 50.0
            
        if len(stoch_d) > abs(index):
            indicators["stoch_d"] = stoch_d.iloc[index] if not pd.isna(stoch_d.iloc[index]) else 50.0
        else:
            indicators["stoch_d"] = 50.0

        # 5. Williams %R (14 period)
        range_14 = highest_high - lowest_low
        # More robust handling of zero range
        range_14 = range_14.replace(0, 0.0001)
        range_14 = range_14.fillna(0.0001)
        range_14 = np.where(range_14 == 0, 0.0001, range_14)
        williams_r = -100 * ((highest_high - df_copy['close']) / range_14)
        williams_r = williams_r.replace([np.inf, -np.inf], -50.0)
        williams_r = williams_r.fillna(-50.0)
        
        if len(williams_r) > abs(index):
            indicators["williams_r"] = williams_r.iloc[index] if not pd.isna(williams_r.iloc[index]) else -50.0
        else:
            indicators["williams_r"] = -50.0

        # 6. Money Flow Index (MFI) - 14 period
        typical_price = (df_copy['high'] + df_copy['low'] + df_copy['close']) / 3
        price_volume = abs(df_copy['close'] - df_copy['open']) * typical_price
        raw_money_flow = typical_price * price_volume

        positive_flow = pd.Series(0.0, index=df_copy.index)
        negative_flow = pd.Series(0.0, index=df_copy.index)

        for i in range(1, len(df_copy)):
            if typical_price.iloc[i] > typical_price.iloc[i-1]:
                positive_flow.iloc[i] = raw_money_flow.iloc[i]
            elif typical_price.iloc[i] < typical_price.iloc[i-1]:
                negative_flow.iloc[i] = raw_money_flow.iloc[i]

        positive_mf = positive_flow.rolling(window=14).sum()
        negative_mf = negative_flow.rolling(window=14).sum()

        # More robust handling of zero values
        negative_mf = negative_mf.replace(0, 0.0001)
        negative_mf = negative_mf.fillna(0.0001)
        negative_mf = np.where(negative_mf == 0, 0.0001, negative_mf)
        money_ratio = positive_mf / negative_mf
        money_ratio = money_ratio.replace([np.inf, -np.inf], 1.0)
        money_ratio = money_ratio.fillna(1.0)
        mfi = 100 - (100 / (1 + money_ratio))
        mfi = mfi.fillna(50.0)
        indicators["mfi"] = mfi.iloc[index] if not pd.isna(mfi.iloc[index]) else 50.0

        # 7. Average True Range (ATR) - 14 period
        high_low = df_copy['high'] - df_copy['low']
        high_close = np.abs(df_copy['high'] - df_copy['close'].shift())
        low_close = np.abs(df_copy['low'] - df_copy['close'].shift())
        true_range = pd.concat([high_low, high_close, low_close], axis=1).max(axis=1)
        atr = true_range.rolling(window=14).mean()
        indicators["atr"] = atr.iloc[index] if not pd.isna(atr.iloc[index]) else 0.01

        # 8. Commodity Channel Index (CCI) - 20 period
        typical_price = (df_copy['high'] + df_copy['low'] + df_copy['close']) / 3
        sma_tp = typical_price.rolling(window=20).mean()
        mad = typical_price.rolling(window=20).apply(lambda x: np.mean(np.abs(x - x.mean())), raw=True)
        
        # More robust handling of zero values
        mad = mad.replace(0, 0.0001)
        mad = mad.fillna(0.0001)
        mad = np.where(mad == 0, 0.0001, mad)
        cci = (typical_price - sma_tp) / (0.015 * mad)
        cci = cci.replace([np.inf, -np.inf], 0.0)
        cci = cci.fillna(0.0)
        indicators["cci"] = cci.iloc[index] if not pd.isna(cci.iloc[index]) else 0.0

        # Final validation - ensure values are within valid bounds
        indicators['rsi'] = max(0, min(100, indicators['rsi']))
        indicators['mfi'] = max(0, min(100, indicators['mfi']))
        indicators['stoch_k'] = max(0, min(100, indicators['stoch_k']))
        indicators['stoch_d'] = max(0, min(100, indicators['stoch_d']))
        indicators['williams_r'] = max(-100, min(0, indicators['williams_r']))
        indicators['atr'] = max(0.0001, indicators['atr'])
        indicators['cci'] = max(-500, min(500, indicators['cci']))  # CCI typically ranges -200 to +200, but cap at ±500

        return indicators

    except Exception as e:
        print(f"Error computing indicators: {str(e)} - DataFrame shape: {df.shape}, columns: {list(df.columns)}")
        # Return default values for core indicators
        return {
            "rsi": 50.0, "macd": 0.0, "macd_signal": 0.0,
            "bb_upper": df['high'].iloc[index] if len(df) > abs(index) else 1.0,
            "bb_lower": df['low'].iloc[index] if len(df) > abs(index) else 1.0,
            "bb_middle": df['close'].iloc[index] if len(df) > abs(index) else 1.0,
            "stoch_k": 50.0, "stoch_d": 50.0, "williams_r": -50.0,
            "mfi": 50.0, "atr": 0.01, "cci": 0.0
        }

def get_dynamic_thresholds(df, pair):
    """Calculate dynamic thresholds based on pair volatility characteristics with JPY-specific handling"""
    # Calculate pair-specific volatility
    if len(df) < 30:
        return get_default_thresholds()
    
    # Check if this is a JPY pair
    is_jpy_pair = 'JPY' in pair
    
    # Calculate average true range as volatility measure
    high_low = df['high'] - df['low']
    high_close = np.abs(df['high'] - df['close'].shift())
    low_close = np.abs(df['low'] - df['close'].shift())
    true_range = pd.concat([high_low, high_close, low_close], axis=1).max(axis=1)
    atr = true_range.rolling(window=20).mean().iloc[-1]
    
    # Volatility as percentage of price
    volatility_pct = (atr / df['close'].iloc[-1]) * 100
    
    # JPY-specific volatility scaling (JPY pairs move differently)
    if is_jpy_pair:
        # JPY pairs typically have lower percentage moves but higher absolute moves
        volatility_pct = volatility_pct * 0.7  # Scale down for JPY characteristics
        
        # More conservative thresholds for JPY pairs due to their unique behavior
        if volatility_pct > 1.4:  # High volatility for JPY
            rsi_oversold, rsi_overbought = 25, 75
            stoch_oversold, stoch_overbought = 15, 85
            williams_oversold, williams_overbought = -85, -15
        elif volatility_pct > 0.8:  # Medium volatility for JPY
            rsi_oversold, rsi_overbought = 30, 70
            stoch_oversold, stoch_overbought = 20, 80
            williams_oversold, williams_overbought = -80, -20
        else:  # Low volatility for JPY
            rsi_oversold, rsi_overbought = 35, 65
            stoch_oversold, stoch_overbought = 25, 75
            williams_oversold, williams_overbought = -75, -25
    else:
        # Original logic for non-JPY pairs
        if volatility_pct > 2.0:  # High volatility pairs (exotic pairs)
            rsi_oversold, rsi_overbought = 20, 80
            stoch_oversold, stoch_overbought = 10, 90
            williams_oversold, williams_overbought = -90, -10
        elif volatility_pct > 1.0:  # Medium volatility pairs
            rsi_oversold, rsi_overbought = 25, 75
            stoch_oversold, stoch_overbought = 15, 85
            williams_oversold, williams_overbought = -85, -15
        else:  # Low volatility pairs (major pairs)
            rsi_oversold, rsi_overbought = 30, 70
            stoch_oversold, stoch_overbought = 20, 80
            williams_oversold, williams_overbought = -80, -20
    
    # Pair-specific adjustments
    volatile_jpy_pairs = ['GBP/JPY', 'AUD/JPY', 'EUR/JPY']
    stable_jpy_pairs = ['USD/JPY']
    volatile_pairs = ['GBP/AUD', 'GBP/NZD', 'EUR/GBP']
    stable_pairs = ['EUR/USD', 'USD/CHF', 'USD/CAD']
    
    if any(vp in pair for vp in volatile_jpy_pairs):
        # Extra volatile JPY pairs need wider thresholds
        rsi_oversold -= 8
        rsi_overbought += 8
    elif any(sp in pair for sp in stable_jpy_pairs):
        # Stable JPY pairs can use tighter thresholds
        rsi_oversold += 3
        rsi_overbought -= 3
    elif any(vp in pair for vp in volatile_pairs):
        rsi_oversold -= 5
        rsi_overbought += 5
    elif any(sp in pair for sp in stable_pairs):
        rsi_oversold += 5
        rsi_overbought -= 5
    
    return {
        'rsi_oversold': max(15, min(45, rsi_oversold)),  # Ensure reasonable bounds
        'rsi_overbought': max(55, min(85, rsi_overbought)),
        'stoch_oversold': max(5, min(35, stoch_oversold)),
        'stoch_overbought': max(65, min(95, stoch_overbought)),
        'williams_oversold': max(-95, min(-60, williams_oversold)),
        'williams_overbought': max(-40, min(-5, williams_overbought)),
        'volatility_pct': volatility_pct,
        'is_jpy_pair': is_jpy_pair
    }

def get_default_thresholds():
    """Default thresholds when volatility calculation fails"""
    return {
        'rsi_oversold': 30,
        'rsi_overbought': 70,
        'stoch_oversold': 20,
        'stoch_overbought': 80,
        'williams_oversold': -80,
        'williams_overbought': -20,
        'volatility_pct': 1.0
    }

def detect_market_regime(df):
    """Enhanced market regime detection with adaptive parameters and institutional flow analysis."""
    if len(df) < 50:
        return {'regime': 'Unknown', 'strength': 0, 'details': [], 'confidence': 0}
    
    regime_analysis = {
        'regime': 'Unknown',
        'strength': 0,
        'confidence': 0,
        'details': [],
        'trend_direction': 'Neutral',
        'institutional_flow': {},
        'regime_transition': {},
        'adaptive_parameters': {}
    }
    
    # Enhanced ADX calculation with multiple timeframes
    adx_analysis = calculate_enhanced_adx(df)
    
    # Institutional flow detection
    institutional_flow = detect_institutional_flow(df)
    regime_analysis['institutional_flow'] = institutional_flow
    
    # Market structure analysis
    structure_analysis = analyze_regime_structure(df)
    
    # Volatility regime analysis
    volatility_regime = analyze_volatility_regime(df)
    
    # Combine all analyses
    trend_score = 0
    range_score = 0
    confidence_factors = []
    
    # 1. Enhanced ADX evaluation
    adx = adx_analysis['adx']
    if adx > 35:
        trend_score += 4
        confidence_factors.append(f'Very strong ADX trend ({adx:.1f})')
    elif adx > 25:
        trend_score += 3
        confidence_factors.append(f'Strong ADX trend ({adx:.1f})')
    elif adx > 15:
        trend_score += 1
        confidence_factors.append(f'Weak trend detected ({adx:.1f})')
    else:
        range_score += 3
        confidence_factors.append(f'Range-bound market ({adx:.1f})')
    
    # 2. Institutional flow confirmation
    if institutional_flow['dominant_flow'] != 'Balanced':
        if institutional_flow['flow_strength'] > 15:
            trend_score += 3
            confidence_factors.append(f'Strong institutional {institutional_flow["dominant_flow"].lower()} flow')
        elif institutional_flow['flow_strength'] > 8:
            trend_score += 2
            confidence_factors.append(f'Moderate institutional flow')
    else:
        range_score += 2
        confidence_factors.append('Balanced institutional flow')
    
    # 3. Multi-timeframe EMA analysis
    ema_analysis = analyze_multi_timeframe_emas(df)
    if ema_analysis['alignment_strength'] > 0.8:
        trend_score += 3
        confidence_factors.append(f'Perfect EMA alignment ({ema_analysis["direction"]})')
    elif ema_analysis['alignment_strength'] > 0.6:
        trend_score += 2
        confidence_factors.append(f'Good EMA alignment')
    else:
        range_score += 2
        confidence_factors.append('Mixed EMA signals')
    
    # 4. Price structure and momentum
    momentum_analysis = analyze_price_momentum(df)
    if momentum_analysis['consistency'] > 0.75:
        trend_score += 2
        confidence_factors.append(f'Consistent momentum ({momentum_analysis["direction"]})')
    elif momentum_analysis['consistency'] > 0.6:
        trend_score += 1
    else:
        range_score += 2
        confidence_factors.append('Choppy price action')
    
    # 5. Volatility regime confirmation
    if volatility_regime['regime'] == 'trending':
        trend_score += 2
        confidence_factors.append('Trending volatility pattern')
    elif volatility_regime['regime'] == 'ranging':
        range_score += 2
        confidence_factors.append('Range-bound volatility')
    
    # 6. Market structure breaks
    if structure_analysis['recent_breaks'] > 0:
        trend_score += structure_analysis['recent_breaks']
        confidence_factors.append(f'{structure_analysis["recent_breaks"]} structure breaks detected')
    
    # Determine regime with enhanced logic
    total_score = trend_score + range_score
    if total_score == 0:
        return regime_analysis
    
    # Calculate regime strength and confidence
    if trend_score > range_score * 1.5:  # Clear trending bias
        regime_analysis['regime'] = 'Trending'
        strength = min(100, (trend_score / total_score) * 100)
        confidence = calculate_regime_confidence(trend_score, range_score, adx_analysis, institutional_flow)
        
        # Determine trend direction
        if ema_analysis['direction'] == 'Bullish' or momentum_analysis['direction'] == 'Bullish':
            regime_analysis['trend_direction'] = 'Bullish'
        elif ema_analysis['direction'] == 'Bearish' or momentum_analysis['direction'] == 'Bearish':
            regime_analysis['trend_direction'] = 'Bearish'
            
    elif range_score > trend_score * 1.3:  # Clear ranging bias
        regime_analysis['regime'] = 'Ranging'
        strength = min(100, (range_score / total_score) * 100)
        confidence = calculate_regime_confidence(range_score, trend_score, adx_analysis, institutional_flow)
        
    else:  # Transitional
        regime_analysis['regime'] = 'Transitional'
        strength = 50
        confidence = 30  # Lower confidence for transitional states
    
    # Adaptive parameter suggestions
    regime_analysis['adaptive_parameters'] = get_adaptive_parameters(regime_analysis['regime'], strength, adx)
    
    # Regime transition detection
    regime_analysis['regime_transition'] = detect_regime_transition(df, regime_analysis['regime'])
    
    regime_analysis.update({
        'strength': max(0, min(100, strength)),
        'confidence': max(0, min(100, confidence)),
        'details': confidence_factors[:4],  # Top 4 factors
        'adx': adx,
        'adx_analysis': adx_analysis,
        'volatility_regime': volatility_regime,
        'structure_analysis': structure_analysis
    })
    
    return regime_analysis

def calculate_enhanced_adx(df):
    """Calculate enhanced ADX with multiple timeframes and trend quality."""
    try:
        adx_data = {}
        
        # Standard 14-period ADX
        high_low = df['high'] - df['low']
        high_close = np.abs(df['high'] - df['close'].shift())
        low_close = np.abs(df['low'] - df['close'].shift())
        true_range = pd.concat([high_low, high_close, low_close], axis=1).max(axis=1)
        
        dm_plus = np.where((df['high'] - df['high'].shift()) > (df['low'].shift() - df['low']),
                          np.maximum(df['high'] - df['high'].shift(), 0), 0)
        dm_minus = np.where((df['low'].shift() - df['low']) > (df['high'] - df['high'].shift()),
                           np.maximum(df['low'].shift() - df['low'], 0), 0)
        
        tr_smooth = pd.Series(true_range).rolling(window=14).mean()
        dm_plus_smooth = pd.Series(dm_plus).rolling(window=14).mean()
        dm_minus_smooth = pd.Series(dm_minus).rolling(window=14).mean()
        
        di_plus = 100 * (dm_plus_smooth / tr_smooth)
        di_minus = 100 * (dm_minus_smooth / tr_smooth)
        
        dx = 100 * np.abs(di_plus - di_minus) / (di_plus + di_minus)
        adx = dx.rolling(window=14).mean().iloc[-1]
        
        # ADX trend (rising or falling)
        adx_series = dx.rolling(window=14).mean()
        adx_trend = 'Rising' if adx_series.iloc[-1] > adx_series.iloc[-3] else 'Falling'
        
        # Directional bias
        current_di_plus = di_plus.iloc[-1]
        current_di_minus = di_minus.iloc[-1]
        directional_bias = 'Bullish' if current_di_plus > current_di_minus else 'Bearish'
        
        adx_data = {
            'adx': adx,
            'di_plus': current_di_plus,
            'di_minus': current_di_minus,
            'adx_trend': adx_trend,
            'directional_bias': directional_bias,
            'trend_quality': 'Excellent' if adx > 40 else 'Good' if adx > 25 else 'Weak' if adx > 15 else 'Very Weak'
        }
        
        return adx_data
    except:
        return {'adx': 20, 'trend_quality': 'Unknown'}

def detect_institutional_flow(df):
    """Detect institutional money flow patterns."""
    try:
        if len(df) < 20:
            return {'dominant_flow': 'Unknown', 'flow_strength': 0}
        
        # Large candle detection (institutional moves)
        candle_ranges = df['high'] - df['low']
        avg_range = candle_ranges.rolling(window=20).mean()
        large_candles = candle_ranges > avg_range * 2
        
        # Direction of large candles
        large_bullish = 0
        large_bearish = 0
        
        for i in range(len(df)):
            if large_candles.iloc[i]:
                if df['close'].iloc[i] > df['open'].iloc[i]:
                    large_bullish += 1
                else:
                    large_bearish += 1
        
        # Smart money displacement detection
        displacement_score = 0
        for i in range(5, len(df)):
            price_move = abs(df['close'].iloc[i] - df['close'].iloc[i-5]) / df['close'].iloc[i-5]
            if price_move > 0.02:  # 2% move in 5 periods
                direction = 1 if df['close'].iloc[i] > df['close'].iloc[i-5] else -1
                displacement_score += direction
        
        # Determine dominant flow
        total_large = large_bullish + large_bearish
        if total_large > 0:
            bullish_ratio = large_bullish / total_large
            if bullish_ratio > 0.65:
                dominant_flow = 'Buying'
                flow_strength = (bullish_ratio - 0.5) * 50
            elif bullish_ratio < 0.35:
                dominant_flow = 'Selling'
                flow_strength = (0.5 - bullish_ratio) * 50
            else:
                dominant_flow = 'Balanced'
                flow_strength = 0
        else:
            dominant_flow = 'Balanced'
            flow_strength = 0
        
        return {
            'dominant_flow': dominant_flow,
            'flow_strength': flow_strength,
            'large_bullish_candles': large_bullish,
            'large_bearish_candles': large_bearish,
            'displacement_score': displacement_score
        }
    except:
        return {'dominant_flow': 'Unknown', 'flow_strength': 0}

def analyze_multi_timeframe_emas(df):
    """Analyze EMA alignment across multiple timeframes."""
    try:
        if len(df) < 50:
            return {'alignment_strength': 0, 'direction': 'Neutral'}
        
        # Multiple EMA periods
        ema_periods = [9, 21, 50]
        emas = {}
        
        for period in ema_periods:
            if len(df) >= period:
                emas[period] = df['close'].ewm(span=period).mean().iloc[-1]
        
        if len(emas) < 3:
            return {'alignment_strength': 0, 'direction': 'Neutral'}
        
        # Check alignment
        ema_values = list(emas.values())
        
        # Perfect bullish alignment: EMA9 > EMA21 > EMA50
        if ema_values[0] > ema_values[1] > ema_values[2]:
            alignment_strength = 1.0
            direction = 'Bullish'
        # Perfect bearish alignment: EMA9 < EMA21 < EMA50
        elif ema_values[0] < ema_values[1] < ema_values[2]:
            alignment_strength = 1.0
            direction = 'Bearish'
        # Partial alignment
        elif ema_values[0] > ema_values[1] or ema_values[1] > ema_values[2]:
            alignment_strength = 0.6
            direction = 'Bullish' if ema_values[0] > ema_values[2] else 'Mixed'
        elif ema_values[0] < ema_values[1] or ema_values[1] < ema_values[2]:
            alignment_strength = 0.6
            direction = 'Bearish' if ema_values[0] < ema_values[2] else 'Mixed'
        else:
            alignment_strength = 0.3
            direction = 'Neutral'
        
        return {
            'alignment_strength': alignment_strength,
            'direction': direction,
            'ema_values': emas
        }
    except:
        return {'alignment_strength': 0, 'direction': 'Neutral'}

def analyze_price_momentum(df):
    """Analyze price momentum consistency and strength."""
    try:
        if len(df) < 20:
            return {'consistency': 0, 'direction': 'Neutral'}
        
        # Recent price changes
        recent_changes = df['close'].pct_change().tail(15).dropna()
        
        if len(recent_changes) == 0:
            return {'consistency': 0, 'direction': 'Neutral'}
        
        positive_count = sum(1 for change in recent_changes if change > 0)
        negative_count = len(recent_changes) - positive_count
        
        # Calculate consistency
        max_directional = max(positive_count, negative_count)
        consistency = max_directional / len(recent_changes)
        
        # Determine direction
        if positive_count > negative_count * 1.5:
            direction = 'Bullish'
        elif negative_count > positive_count * 1.5:
            direction = 'Bearish'
        else:
            direction = 'Neutral'
        
        return {
            'consistency': consistency,
            'direction': direction,
            'positive_periods': positive_count,
            'negative_periods': negative_count
        }
    except:
        return {'consistency': 0, 'direction': 'Neutral'}

def analyze_volatility_regime(df):
    """Analyze volatility patterns to determine market regime."""
    try:
        if len(df) < 30:
            return {'regime': 'unknown', 'strength': 0}
        
        # Calculate rolling volatility
        volatility = df['close'].rolling(window=10).std()
        
        # Recent vs historical volatility
        recent_vol = volatility.tail(5).mean()
        historical_vol = volatility.tail(30).mean()
        
        # Volatility clustering
        vol_changes = volatility.pct_change().tail(10).dropna()
        vol_consistency = 1 - (vol_changes.std() if len(vol_changes) > 0 else 1)
        
        # Determine regime
        if recent_vol > historical_vol * 1.3:
            if vol_consistency > 0.6:
                regime = 'trending'  # High, consistent volatility
            else:
                regime = 'choppy'   # High, inconsistent volatility
        elif recent_vol < historical_vol * 0.7:
            regime = 'ranging'      # Low volatility
        else:
            regime = 'transitional' # Medium volatility
        
        strength = min(100, vol_consistency * 100)
        
        return {
            'regime': regime,
            'strength': strength,
            'recent_volatility': recent_vol,
            'historical_volatility': historical_vol,
            'volatility_ratio': recent_vol / historical_vol if historical_vol > 0 else 1
        }
    except:
        return {'regime': 'unknown', 'strength': 0}

def analyze_regime_structure(df):
    """Analyze market structure for regime confirmation."""
    try:
        if len(df) < 20:
            return {'recent_breaks': 0, 'structure_quality': 'Poor'}
        
        # Find swing points
        swing_highs = []
        swing_lows = []
        
        for i in range(2, len(df) - 2):
            if (df['high'].iloc[i] > df['high'].iloc[i-1] and 
                df['high'].iloc[i] > df['high'].iloc[i-2] and
                df['high'].iloc[i] > df['high'].iloc[i+1] and 
                df['high'].iloc[i] > df['high'].iloc[i+2]):
                swing_highs.append({'index': i, 'price': df['high'].iloc[i]})
            
            if (df['low'].iloc[i] < df['low'].iloc[i-1] and 
                df['low'].iloc[i] < df['low'].iloc[i-2] and
                df['low'].iloc[i] < df['low'].iloc[i+1] and 
                df['low'].iloc[i] < df['low'].iloc[i+2]):
                swing_lows.append({'index': i, 'price': df['low'].iloc[i]})
        
        # Count recent structure breaks
        recent_breaks = 0
        current_price = df['close'].iloc[-1]
        
        # Check for breaks of recent highs/lows
        for swing in swing_highs[-3:]:  # Last 3 swing highs
            if current_price > swing['price']:
                recent_breaks += 1
        
        for swing in swing_lows[-3:]:   # Last 3 swing lows
            if current_price < swing['price']:
                recent_breaks += 1
        
        # Structure quality based on swing point clarity
        total_swings = len(swing_highs) + len(swing_lows)
        expected_swings = len(df) // 10  # Rough estimate
        
        if total_swings >= expected_swings * 0.8:
            structure_quality = 'Good'
        elif total_swings >= expected_swings * 0.5:
            structure_quality = 'Moderate'
        else:
            structure_quality = 'Poor'
        
        return {
            'recent_breaks': recent_breaks,
            'structure_quality': structure_quality,
            'swing_highs_count': len(swing_highs),
            'swing_lows_count': len(swing_lows)
        }
    except:
        return {'recent_breaks': 0, 'structure_quality': 'Poor'}

def calculate_regime_confidence(primary_score, secondary_score, adx_analysis, institutional_flow):
    """Calculate confidence in regime detection."""
    try:
        base_confidence = (primary_score / (primary_score + secondary_score)) * 100
        
        # ADX confirmation bonus
        adx = adx_analysis.get('adx', 20)
        if adx > 30:
            base_confidence += 15
        elif adx > 20:
            base_confidence += 8
        
        # Institutional flow confirmation
        flow_strength = institutional_flow.get('flow_strength', 0)
        if flow_strength > 15:
            base_confidence += 10
        elif flow_strength > 8:
            base_confidence += 5
        
        return min(95, base_confidence)
    except:
        return 50

def get_adaptive_parameters(regime, strength, adx):
    """Get adaptive parameters based on detected regime."""
    parameters = {
        'signal_threshold': 70,
        'stop_loss_atr_multiple': 2.0,
        'take_profit_ratio': 2.0,
        'position_sizing': 'normal'
    }
    
    if regime == 'Trending':
        if strength > 80:
            parameters.update({
                'signal_threshold': 65,
                'stop_loss_atr_multiple': 2.5,
                'take_profit_ratio': 3.0,
                'position_sizing': 'aggressive'
            })
        else:
            parameters.update({
                'signal_threshold': 68,
                'stop_loss_atr_multiple': 2.2,
                'take_profit_ratio': 2.5
            })
    elif regime == 'Ranging':
        parameters.update({
            'signal_threshold': 75,
            'stop_loss_atr_multiple': 1.5,
            'take_profit_ratio': 1.5,
            'position_sizing': 'conservative'
        })
    else:  # Transitional
        parameters.update({
            'signal_threshold': 80,
            'stop_loss_atr_multiple': 1.8,
            'take_profit_ratio': 1.8,
            'position_sizing': 'very_conservative'
        })
    
    return parameters

def detect_regime_transition(df, current_regime):
    """Detect potential regime transitions."""
    try:
        if len(df) < 30:
            return {'transition_probability': 0, 'direction': 'Unknown'}
        
        # Compare recent vs older regime characteristics
        recent_data = df.tail(15)
        older_data = df.iloc[-30:-15]
        
        # Volatility change
        recent_vol = recent_data['close'].std()
        older_vol = older_data['close'].std()
        vol_change = (recent_vol - older_vol) / older_vol if older_vol > 0 else 0
        
        # Price action change
        recent_range = (recent_data['high'].max() - recent_data['low'].min()) / recent_data['close'].mean()
        older_range = (older_data['high'].max() - older_data['low'].min()) / older_data['close'].mean()
        range_change = (recent_range - older_range) / older_range if older_range > 0 else 0
        
        # Determine transition probability
        transition_prob = 0
        direction = 'Unknown'
        
        if current_regime == 'Trending':
            if vol_change < -0.3 and range_change < -0.2:
                transition_prob = 70
                direction = 'To Ranging'
        elif current_regime == 'Ranging':
            if vol_change > 0.4 and range_change > 0.3:
                transition_prob = 65
                direction = 'To Trending'
        
        return {
            'transition_probability': transition_prob,
            'direction': direction,
            'volatility_change': vol_change * 100,
            'range_change': range_change * 100
        }
    except:
        return {'transition_probability': 0, 'direction': 'Unknown'}

def adapt_strategy_to_regime(regime_data, indicators, confidence_data):
    """Adapt trading strategy based on market regime"""
    regime = regime_data['regime']
    regime_strength = regime_data['strength']
    adjustments = {'multiplier': 1.0, 'details': []}
    
    if regime == 'Trending':
        # In trending markets, momentum indicators are more reliable
        if regime_strength > 70:
            # Strong trend - boost momentum signals
            adjustments['multiplier'] = 1.15
            adjustments['details'].append('Strong trend detected - momentum boosted')
            
            # Additional trend-following signals
            trend_direction = regime_data.get('trend_direction', 'Neutral')
            if trend_direction != 'Neutral':
                signal_alignment = confidence_data.get('signal', 'NEUTRAL')
                if ((trend_direction == 'Bullish' and signal_alignment == 'BUY') or
                    (trend_direction == 'Bearish' and signal_alignment == 'SELL')):
                    adjustments['multiplier'] *= 1.08
                    adjustments['details'].append('Signal aligns with strong trend')
        
        # In trends, reduce mean reversion signals
        rsi = indicators.get('rsi', 50)
        if ((regime_data.get('trend_direction') == 'Bullish' and rsi > 70) or
            (regime_data.get('trend_direction') == 'Bearish' and rsi < 30)):
            adjustments['multiplier'] *= 0.85
            adjustments['details'].append('Mean reversion signal in trending market')
    
    elif regime == 'Ranging':
        # In ranging markets, mean reversion is more reliable
        if regime_strength > 60:
            # Strong range - boost mean reversion signals
            rsi = indicators.get('rsi', 50)
            stoch_k = indicators.get('stoch_k', 50)
            
            if rsi < 30 or rsi > 70 or stoch_k < 20 or stoch_k > 80:
                adjustments['multiplier'] = 1.12
                adjustments['details'].append('Mean reversion signal in ranging market')
            
            # Reduce momentum signals in ranging markets
            macd_diff = abs(indicators.get('macd', 0) - indicators.get('macd_signal', 0))
            if macd_diff > 0.001:
                adjustments['multiplier'] *= 0.80
                adjustments['details'].append('Momentum signal in ranging market')
    
    elif regime == 'Transitional':
        # In transitional markets, be more conservative
        adjustments['multiplier'] = 0.90
        adjustments['details'].append('Transitional market - reduced confidence')
    
    return adjustments

def calculate_indicator_confidence(df, indicators, index=-1, pair="EUR/USD"):
    """Confluence-based indicator confidence with primary and confirmatory indicators."""
    latest_price = df['close'].iloc[index]
    
    # PRIMARY INDICATORS (for signal generation)
    primary_bullish = 0
    primary_bearish = 0
    primary_weight = 6  # Higher weight for primary indicators
    
    # RSI - Primary momentum indicator
    rsi = indicators['rsi']
    if rsi <= 25:  # Strong oversold
        primary_bullish += 3
    elif rsi <= 35:  # Oversold
        primary_bullish += 2
    elif rsi <= 45:  # Slightly oversold
        primary_bullish += 1
    elif rsi >= 75:  # Strong overbought
        primary_bearish += 3
    elif rsi >= 65:  # Overbought
        primary_bearish += 2
    elif rsi >= 55:  # Slightly overbought
        primary_bearish += 1
    
    # MACD - Primary trend indicator
    macd_diff = indicators['macd'] - indicators['macd_signal']
    if macd_diff > 0.0012:  # Strong bullish momentum
        primary_bullish += 3
    elif macd_diff > 0.0006:  # Moderate bullish momentum
        primary_bullish += 2
    elif macd_diff > 0.0002:  # Weak bullish momentum
        primary_bullish += 1
    elif macd_diff < -0.0012:  # Strong bearish momentum
        primary_bearish += 3
    elif macd_diff < -0.0006:  # Moderate bearish momentum
        primary_bearish += 2
    elif macd_diff < -0.0002:  # Weak bearish momentum
        primary_bearish += 1
    
    # Volume Analysis - Primary market participation indicator
    volume_analysis = calculate_volume_indicators(df)
    if volume_analysis.get('obv_trend') == 'Strong Bullish':
        primary_bullish += 2
    elif volume_analysis.get('obv_trend') == 'Bullish':
        primary_bullish += 1
    elif volume_analysis.get('obv_trend') == 'Strong Bearish':
        primary_bearish += 2
    elif volume_analysis.get('obv_trend') == 'Bearish':
        primary_bearish += 1
    
    # Price momentum - Primary price action indicator
    if len(df) >= 5:
        recent_momentum = (df['close'].iloc[-1] - df['close'].iloc[-5]) / df['close'].iloc[-5]
        if recent_momentum > 0.015:  # Strong upward momentum
            primary_bullish += 2
        elif recent_momentum > 0.008:  # Moderate upward momentum
            primary_bullish += 1
        elif recent_momentum < -0.015:  # Strong downward momentum
            primary_bearish += 2
        elif recent_momentum < -0.008:  # Moderate downward momentum
            primary_bearish += 1
    
    # Market Structure - Primary structural indicator
    try:
        structure_result = analyze_market_structure(df)
        if structure_result and len(structure_result) >= 2:
            trend, structure_info = structure_result
            if trend == "Uptrend":
                primary_bullish += 2
            elif trend == "Downtrend":
                primary_bearish += 2
    except:
        pass
    
    # Calculate primary signal strength
    primary_total = primary_bullish + primary_bearish
    if primary_total == 0:
        primary_signal = "NEUTRAL"
        primary_confidence = 0
    elif primary_bullish > primary_bearish:
        primary_signal = "BUY"
        primary_confidence = min(80, (primary_bullish / 12) * 100)  # Max 80% from primary
    else:
        primary_signal = "SELL"
        primary_confidence = min(80, (primary_bearish / 12) * 100)  # Max 80% from primary
    
    # CONFLUENCE INDICATORS (only add confidence when they align with primary signal)
    confluence_score = 0
    confluence_weight = 0.2  # Much lower weight for confluence
    
    # Only check confluence if we have a primary signal
    if primary_signal != "NEUTRAL":
        
        # Bollinger Bands - Confluence only (only add when aligned, don't subtract when opposed)
        bb_range = indicators['bb_upper'] - indicators['bb_lower']
        if bb_range > 0:
            bb_position = (latest_price - indicators['bb_lower']) / bb_range
            if primary_signal == "BUY" and bb_position <= 0.25:  # Near lower band supports buy
                confluence_score += 2
            elif primary_signal == "SELL" and bb_position >= 0.75:  # Near upper band supports sell
                confluence_score += 2
            # When opposed (e.g., BUY signal near upper band), do nothing - don't reduce confidence
        
        # Stochastic - Confluence only (only add when aligned, don't subtract when opposed)
        stoch_k = indicators['stoch_k']
        if primary_signal == "BUY" and stoch_k <= 30:  # Oversold supports buy
            confluence_score += 2
        elif primary_signal == "SELL" and stoch_k >= 70:  # Overbought supports sell
            confluence_score += 2
        # When opposed (e.g., BUY signal with overbought stoch), do nothing - don't reduce confidence
        
        # CCI - Confluence only (only add when aligned, don't subtract when opposed)
        cci = indicators.get('cci', 0)
        if primary_signal == "BUY" and cci <= -100:  # Oversold supports buy
            confluence_score += 1
        elif primary_signal == "SELL" and cci >= 100:  # Overbought supports sell
            confluence_score += 1
        # When opposed (e.g., BUY signal with overbought CCI), do nothing - don't reduce confidence
        
        # Support/Resistance - Confluence only (only add when aligned, don't subtract when opposed)
        try:
            sr_levels = detect_support_resistance(df, pair=pair)
            if sr_levels.get('levels'):
                current_price = latest_price
                for level in sr_levels['levels'][:3]:  # Check top 3 levels
                    distance_pct = abs(current_price - level['level']) / current_price
                    if distance_pct < 0.002:  # Within 0.2% of S/R level
                        if primary_signal == "BUY" and level['type'] == 'Support':
                            confluence_score += 2  # Strong confluence at support
                        elif primary_signal == "SELL" and level['type'] == 'Resistance':
                            confluence_score += 2  # Strong confluence at resistance
                        # When opposed (e.g., BUY signal at resistance), do nothing - don't reduce confidence
        except:
            pass
        
        # Chart Patterns - Confluence only (only add when aligned, don't subtract when opposed)
        try:
            chart_patterns = detect_chart_patterns(df)
            if chart_patterns:
                current_price = latest_price
                confluence_analysis = analyze_pattern_confluence(chart_patterns, current_price)
                
                if confluence_analysis['dominant_bias'] == 'Bullish' and primary_signal == "BUY":
                    confluence_score += min(3, confluence_analysis['confluence_score'] // 3)
                elif confluence_analysis['dominant_bias'] == 'Bearish' and primary_signal == "SELL":
                    confluence_score += min(3, confluence_analysis['confluence_score'] // 3)
                # When opposed (e.g., BUY signal with bearish patterns), do nothing - don't reduce confidence
        except:
            pass
    
    # Final confidence calculation - only add confluence when it supports the primary signal
    if confluence_score > 0:
        final_confidence = primary_confidence + (confluence_score * confluence_weight * 100)
    else:
        final_confidence = primary_confidence  # No confluence bonus when indicators oppose or are neutral
    
    final_confidence = min(95, final_confidence)  # Cap at 95%
    
    # Determine final signal based on primary with confluence boost
    if primary_signal == "NEUTRAL" or final_confidence < 50:
        final_signal = "NEUTRAL"
        bullish_pct = 30.0
        bearish_pct = 30.0
        neutral_pct = 40.0
    elif primary_signal == "BUY":
        final_signal = "BUY"
        bullish_pct = final_confidence
        bearish_pct = max(5, 100 - final_confidence - 20)
        neutral_pct = 100 - bullish_pct - bearish_pct
    else:  # SELL
        final_signal = "SELL"
        bearish_pct = final_confidence
        bullish_pct = max(5, 100 - final_confidence - 20)
        neutral_pct = 100 - bullish_pct - bearish_pct
    
    return {
        'bullish_percentage': round(bullish_pct, 1),
        'bearish_percentage': round(bearish_pct, 1),
        'neutral_percentage': round(neutral_pct, 1),
        'primary_signal': primary_signal,
        'primary_confidence': round(primary_confidence, 1),
        'confluence_score': confluence_score,
        'final_confidence': round(final_confidence, 1),
        'confluence_used': confluence_score > 0,
        'bullish_signals': primary_bullish,
        'bearish_signals': primary_bearish,
        'total_signals': 10
    }

def generate_chart(df, pair, indicators, signal_data):
    """Memory-optimized chart generation with enhanced performance"""
    try:
        import matplotlib
        matplotlib.use('Agg')  # Use non-interactive backend
        import matplotlib.pyplot as plt
        import matplotlib.dates as mdates
        from matplotlib.patches import Rectangle, Polygon
        from matplotlib.lines import Line2D
        import numpy as np
        import io
        import warnings
        
        # Suppress warnings and optimize matplotlib
        warnings.filterwarnings('ignore')
        plt.ioff()  # Turn off interactive mode
        
        # Validate inputs
        if df is None or df.empty:
            print("Chart generation failed: No data provided")
            return None
            
        if len(df) < 10:
            print(f"Chart generation failed: Insufficient data ({len(df)} candles)")
            return None
            
        # Ensure required columns exist
        required_columns = ['datetime', 'open', 'high', 'low', 'close']
        missing_columns = [col for col in required_columns if col not in df.columns]
        if missing_columns:
            print(f"Chart generation failed: Missing columns {missing_columns}")
            return None

        # Memory-optimized data preparation
        # Limit to last 80 candles for optimal performance and readability
        df_chart = df.tail(80).copy() if len(df) > 80 else df.copy()
        df_chart = df_chart.dropna(subset=['open', 'high', 'low', 'close'])
        
        # Optimize DataFrame memory usage
        df_chart = optimize_dataframe_memory(df_chart)
        
        if len(df_chart) < 10:
            print("Chart generation failed: Insufficient clean data after removing NaN values")
            return None
            
        # Ensure datetime is properly formatted
        if not pd.api.types.is_datetime64_any_dtype(df_chart['datetime']):
            try:
                df_chart['datetime'] = pd.to_datetime(df_chart['datetime'])
            except Exception as e:
                print(f"Chart generation failed: Cannot convert datetime column: {e}")
                return None
        
        # Set up the figure with clean styling and proper margins
        plt.style.use('dark_background')
        fig, (ax1, ax2, ax3) = plt.subplots(3, 1, figsize=(16, 12), 
                                           gridspec_kw={'height_ratios': [4, 0.7, 0.7], 'hspace': 0.4})
        
        # AMOLED dark color scheme
        colors = {
            'bg': '#000000',
            'panel': '#0a0a0a',
            'grid': '#1a1a1a',
            'text': '#ffffff',
            'green': '#00ff41',
            'red': '#ff0844',
            'blue': '#0099ff',
            'yellow': '#ffdd00',
            'purple': '#bb86fc',
            'orange': '#ff6600',
            'cyan': '#00e5ff',
            'lime': '#76ff03',
            'pink': '#ff4081'
        }
        
        fig.patch.set_facecolor(colors['bg'])
        
        # Adjust margins to prevent cutoff
        plt.subplots_adjust(left=0.12, right=0.95, top=0.90, bottom=0.10)
        
        # Prepare data
        dates = df_chart['datetime'].values
        opens = df_chart['open'].values
        highs = df_chart['high'].values
        lows = df_chart['low'].values
        closes = df_chart['close'].values
        
        # Convert dates for matplotlib
        date_nums = mdates.date2num(dates)
        
        # Calculate proper candle width based on data density
        if len(date_nums) > 1:
            avg_interval = (date_nums[-1] - date_nums[0]) / max(1, len(date_nums) - 1)
            candle_width = avg_interval * 0.8  # Increased from 0.6 to 0.8 for better visibility
        else:
            candle_width = 0.001  # Increased default width
        
        # Ensure minimum width to prevent display issues
        candle_width = max(candle_width, 0.0005)  # Increased minimum width
        
        # 1. Enhanced Price chart with ICT analysis and patterns
        ax1.set_facecolor(colors['panel'])
        
        # Draw candlesticks with improved formation
        for i in range(len(df_chart)):
            date_num = date_nums[i]
            open_price = opens[i]
            high_price = highs[i]
            low_price = lows[i]
            close_price = closes[i]
            
            # Determine color
            is_bullish = close_price >= open_price
            color = colors['green'] if is_bullish else colors['red']
            
            # Draw wick (high-low line) with better visibility
            ax1.plot([date_num, date_num], [low_price, high_price], 
                    color=color, linewidth=1.5, alpha=0.9, solid_capstyle='round')
            
            # Draw body
            body_height = abs(close_price - open_price)
            body_bottom = min(open_price, close_price)
            
            if body_height > 0:
                # Regular candle with body - improved appearance
                rect = Rectangle((date_num - candle_width/2, body_bottom), 
                               candle_width, body_height,
                               facecolor=color, edgecolor=color, alpha=0.9, linewidth=0.5)
                ax1.add_patch(rect)
            else:
                # Doji - draw horizontal line with better visibility
                ax1.plot([date_num - candle_width/2, date_num + candle_width/2], 
                        [close_price, close_price], color=color, linewidth=3, alpha=0.9)
        
        # Add Key Support and Resistance Levels with improved zones
        try:
            sr_levels = signal_data.get('sr_levels', {})
            if sr_levels.get('levels'):
                # Find the most important support and resistance
                support_levels = [level for level in sr_levels['levels'] if level['type'] == 'Support']
                resistance_levels = [level for level in sr_levels['levels'] if level['type'] == 'Resistance']
                
                # Get the closest and strongest support
                if support_levels:
                    strongest_support = min(support_levels, key=lambda x: x['distance_pips'])
                    support_price = strongest_support['level']
                    ax1.axhline(y=support_price, color=colors['lime'], linestyle='-', 
                               linewidth=2, alpha=0.8, label=f'Key Support: {support_price:.5f}')
                    
                    # Add minimal support zone with very low transparency
                    support_zone_width = support_price * 0.0002  # Reduced from 0.0005 to 0.0002
                    ax1.fill_between(date_nums, support_price - support_zone_width, 
                                   support_price + support_zone_width, 
                                   color=colors['lime'], alpha=0.1)  # Reduced from 0.2 to 0.1
                    
                    # Add arrow annotation pointing to support level
                    ax1.annotate(f'KEY SUPPORT\n{support_price:.5f}', 
                               xy=(date_nums[-20], support_price),  # Point to the line
                               xytext=(date_nums[-30], support_price - (highs.max() - lows.min()) * 0.15),  # Text position (below and left)
                               color=colors['lime'], fontweight='bold', fontsize=8,
                               bbox=dict(boxstyle="round,pad=0.2", facecolor=colors['panel'], alpha=0.9, edgecolor=colors['lime']),
                               arrowprops=dict(arrowstyle='->', color=colors['lime'], lw=1.5, alpha=0.8))
                
                # Get the closest and strongest resistance
                if resistance_levels:
                    strongest_resistance = min(resistance_levels, key=lambda x: x['distance_pips'])
                    resistance_price = strongest_resistance['level']
                    ax1.axhline(y=resistance_price, color=colors['red'], linestyle='-', 
                               linewidth=2, alpha=0.8, label=f'Key Resistance: {resistance_price:.5f}')
                    
                    # Add minimal resistance zone with very low transparency
                    resistance_zone_width = resistance_price * 0.0002  # Reduced from 0.0005 to 0.0002
                    ax1.fill_between(date_nums, resistance_price - resistance_zone_width, 
                                   resistance_price + resistance_zone_width, 
                                   color=colors['red'], alpha=0.1)  # Reduced from 0.2 to 0.1
                    
                    # Add arrow annotation pointing to resistance level
                    ax1.annotate(f'KEY RESISTANCE\n{resistance_price:.5f}', 
                               xy=(date_nums[-20], resistance_price),  # Point to the line
                               xytext=(date_nums[-30], resistance_price + (highs.max() - lows.min()) * 0.15),  # Text position (above and left)
                               color=colors['red'], fontweight='bold', fontsize=8,
                               bbox=dict(boxstyle="round,pad=0.2", facecolor=colors['panel'], alpha=0.9, edgecolor=colors['red']),
                               arrowprops=dict(arrowstyle='->', color=colors['red'], lw=1.5, alpha=0.8))
        except Exception as e:
            print(f"Warning: Could not add S/R levels: {e}")
        
        # Triangle patterns removed as requested
        
        # Add ICT Analysis Overlays with arrows
        try:
            # Fair Value Gaps
            fvg, fvg_levels = detect_fair_value_gap(df_chart)
            if fvg is not None and hasattr(fvg, 'any') and fvg.any() and fvg_levels:
                fvg_upper = fvg_levels.get('upper')
                fvg_lower = fvg_levels.get('lower')
                fvg_type = fvg_levels.get('type', 'Unknown')
                
                if fvg_upper and fvg_lower and not pd.isna(fvg_upper) and not pd.isna(fvg_lower):
                    # Draw FVG zone
                    fvg_color = colors['green'] if 'Bullish' in fvg_type else colors['red']
                    fill_dates = date_nums[-min(20, len(date_nums)):]
                    ax1.fill_between(fill_dates, fvg_lower, fvg_upper, 
                                   color=fvg_color, alpha=0.3, label=f'{fvg_type}')
                    
                    # Add FVG arrow annotation
                    fvg_mid_price = (fvg_upper + fvg_lower) / 2
                    price_range = highs.max() - lows.min()
                    
                    # Position annotation to the right and offset vertically
                    ax1.annotate(f'FVG\n{fvg_type}', 
                               xy=(date_nums[-15], fvg_mid_price),  # Point to FVG zone
                               xytext=(date_nums[-5], fvg_mid_price + price_range * 0.08),  # Text position (right and up)
                               color=fvg_color, fontweight='bold', fontsize=7, ha='center',
                               bbox=dict(boxstyle="round,pad=0.2", facecolor=colors['panel'], alpha=0.9, edgecolor=fvg_color),
                               arrowprops=dict(arrowstyle='->', color=fvg_color, lw=1, alpha=0.8))
            
            # Order Blocks
            bullish_ob, bearish_ob, bullish_ob_levels, bearish_ob_levels = detect_order_block(df_chart)
            
            if (bullish_ob is not None and hasattr(bullish_ob, 'any') and 
                bullish_ob.any() and bullish_ob_levels):
                ob_high = bullish_ob_levels.get('high')
                ob_low = bullish_ob_levels.get('low')
                if ob_high and ob_low and not pd.isna(ob_high) and not pd.isna(ob_low):
                    fill_dates = date_nums[-min(15, len(date_nums)):]
                    ax1.fill_between(fill_dates, ob_low, ob_high, 
                                   color=colors['green'], alpha=0.4, label='Bullish OB')
                    
                    # Add Order Block arrow annotation
                    ob_mid_price = (ob_high + ob_low) / 2
                    price_range = highs.max() - lows.min()
                    
                    ax1.annotate('BULLISH\nORDER BLOCK', 
                               xy=(date_nums[-12], ob_mid_price),  # Point to order block
                               xytext=(date_nums[-25], ob_mid_price - price_range * 0.12),  # Text position (left and down)
                               color=colors['green'], fontweight='bold', fontsize=7, ha='center',
                               bbox=dict(boxstyle="round,pad=0.2", facecolor=colors['panel'], alpha=0.9, edgecolor=colors['green']),
                               arrowprops=dict(arrowstyle='->', color=colors['green'], lw=1, alpha=0.8))
            
            if (bearish_ob is not None and hasattr(bearish_ob, 'any') and 
                bearish_ob.any() and bearish_ob_levels):
                ob_high = bearish_ob_levels.get('high')
                ob_low = bearish_ob_levels.get('low')
                if ob_high and ob_low and not pd.isna(ob_high) and not pd.isna(ob_low):
                    fill_dates = date_nums[-min(15, len(date_nums)):]
                    ax1.fill_between(fill_dates, ob_low, ob_high, 
                                   color=colors['red'], alpha=0.4, label='Bearish OB')
                    
                    # Add Order Block arrow annotation
                    ob_mid_price = (ob_high + ob_low) / 2
                    price_range = highs.max() - lows.min()
                    
                    ax1.annotate('BEARISH\nORDER BLOCK', 
                               xy=(date_nums[-12], ob_mid_price),  # Point to order block
                               xytext=(date_nums[-25], ob_mid_price + price_range * 0.12),  # Text position (left and up)
                               color=colors['red'], fontweight='bold', fontsize=7, ha='center',
                               bbox=dict(boxstyle="round,pad=0.2", facecolor=colors['panel'], alpha=0.9, edgecolor=colors['red']),
                               arrowprops=dict(arrowstyle='->', color=colors['red'], lw=1, alpha=0.8))
            
            # Market Structure - Draw trend lines connecting swing points
            structure_result = analyze_market_structure(df_chart)
            if structure_result and len(structure_result) >= 2:
                trend, structure_info = structure_result
                if isinstance(structure_info, dict):
                    swing_highs = structure_info.get('swing_highs', [])
                    swing_lows = structure_info.get('swing_lows', [])
                    
                    # Draw trend line connecting swing highs as rays (extended beyond last point)
                    if len(swing_highs) >= 2:
                        high_x_coords = []
                        high_y_coords = []
                        # Use up to 15 swing highs or all available swing highs
                        swing_count = min(15, len(swing_highs))
                        for swing in swing_highs[-swing_count:]:
                            if 'index' in swing and 'price' in swing:
                                idx = swing['index']
                                if idx < len(date_nums):
                                    high_x_coords.append(date_nums[idx])
                                    high_y_coords.append(swing['price'])
                        
                        if len(high_x_coords) >= 2:
                            # Calculate trend line slope and extend it as a ray
                            x_array = np.array(high_x_coords)
                            y_array = np.array(high_y_coords)
                            
                            # Fit trend line to get slope
                            slope, intercept = np.polyfit(x_array, y_array, 1)
                            
                            # Extend the line from first point to beyond the chart
                            extended_x = [high_x_coords[0], date_nums[-1] + (date_nums[-1] - date_nums[0]) * 0.2]
                            extended_y = [slope * x + intercept for x in extended_x]
                            
                            # Draw the extended trend line as a ray
                            ax1.plot(extended_x, extended_y, 
                                    color=colors['yellow'], linestyle='--', linewidth=2, 
                                    alpha=0.8, label='Resistance Trend')
                            
                            # Also plot the actual swing points for reference
                            ax1.plot(high_x_coords, high_y_coords, 
                                    color=colors['yellow'], marker='o', markersize=4,
                                    linestyle='None', alpha=0.6)
                    
                    # Draw trend line connecting swing lows as rays (extended beyond last point)
                    if len(swing_lows) >= 2:
                        low_x_coords = []
                        low_y_coords = []
                        # Use up to 15 swing lows or all available swing lows
                        swing_count = min(15, len(swing_lows))
                        for swing in swing_lows[-swing_count:]:
                            if 'index' in swing and 'price' in swing:
                                idx = swing['index']
                                if idx < len(date_nums):
                                    low_x_coords.append(date_nums[idx])
                                    low_y_coords.append(swing['price'])
                        
                        if len(low_x_coords) >= 2:
                            # Calculate trend line slope and extend it as a ray
                            x_array = np.array(low_x_coords)
                            y_array = np.array(low_y_coords)
                            
                            # Fit trend line to get slope
                            slope, intercept = np.polyfit(x_array, y_array, 1)
                            
                            # Extend the line from first point to beyond the chart
                            extended_x = [low_x_coords[0], date_nums[-1] + (date_nums[-1] - date_nums[0]) * 0.2]
                            extended_y = [slope * x + intercept for x in extended_x]
                            
                            # Draw the extended trend line as a ray
                            ax1.plot(extended_x, extended_y, 
                                    color=colors['cyan'], linestyle='--', linewidth=2, 
                                    alpha=0.8, label='Support Trend')
                            
                            # Also plot the actual swing points for reference
                            ax1.plot(low_x_coords, low_y_coords, 
                                    color=colors['cyan'], marker='o', markersize=4,
                                    linestyle='None', alpha=0.6)
        
        except Exception as e:
            print(f"Warning: Could not add ICT analysis: {e}")
        
        # Add moving averages with proper date alignment and no cutoff
        try:
            # Enhanced MA calculation with full display coverage
            if len(df_chart) >= 10:
                # MA20 with minimum periods to prevent cutoff
                ma20 = df_chart['close'].rolling(window=20, min_periods=5).mean()
                ax1.plot(date_nums, ma20.values, color=colors['blue'], linewidth=2.8, 
                        label='MA20', alpha=0.95, solid_capstyle='round', zorder=3)
                
                # Add current value annotation
                if not pd.isna(ma20.iloc[-1]):
                    ax1.text(date_nums[-1], ma20.iloc[-1], f' {ma20.iloc[-1]:.5f}', 
                            color=colors['blue'], fontsize=8, fontweight='bold', va='center')
            
            if len(df_chart) >= 15:
                # MA50 with minimum periods to prevent cutoff
                ma50 = df_chart['close'].rolling(window=50, min_periods=10).mean()
                ax1.plot(date_nums, ma50.values, color=colors['yellow'], linewidth=2.5, 
                        label='MA50', alpha=0.95, solid_capstyle='round', zorder=3)
                
                # Add current value annotation
                if not pd.isna(ma50.iloc[-1]):
                    ax1.text(date_nums[-1], ma50.iloc[-1], f' {ma50.iloc[-1]:.5f}', 
                            color=colors['yellow'], fontsize=8, fontweight='bold', va='center')
        except Exception as e:
            print(f"Warning: Could not add moving averages: {e}")
        
        # Enhanced ICT Liquidity Zones Display
        try:
            # Add ICT liquidity zones and levels instead of Bollinger Bands
            liquidity_info = detect_liquidity_zones(df_chart)
            
            if liquidity_info:
                # Draw equal highs liquidity zones
                for zone in liquidity_info.get('equal_highs', []):
                    ax1.axhline(y=zone['price'], color=colors['red'], linestyle=':', 
                               alpha=0.7, linewidth=2, label=f'Liquidity High ({zone["count"]}x)')
                
                # Draw equal lows liquidity zones  
                for zone in liquidity_info.get('equal_lows', []):
                    ax1.axhline(y=zone['price'], color=colors['green'], linestyle=':', 
                               alpha=0.7, linewidth=2, label=f'Liquidity Low ({zone["count"]}x)')
                
                # Draw liquidity pools
                for pool in liquidity_info.get('liquidity_pools', []):
                    ax1.axhline(y=pool['price'], color=colors['yellow'], linestyle='-', 
                               alpha=0.8, linewidth=1.5, label=f'Pool ({pool["touch_count"]}x)')
        except Exception as e:
            print(f"Warning: Could not add liquidity zones: {e}")
        
        # Add signal marker with arrow
        try:
            signal = signal_data.get('signal', 'NEUTRAL')
            if signal != 'NEUTRAL':
                latest_price = closes[-1]
                latest_date = dates[-1]
                
                marker_color = colors['green'] if signal == 'BUY' else colors['red']
                marker_symbol = '^' if signal == 'BUY' else 'v'
                
                ax1.scatter([latest_date], [latest_price], 
                           color=marker_color, s=300, marker=marker_symbol, 
                           edgecolor='white', linewidth=3, zorder=10,
                           label=f'{signal} Signal')
                
                # Add signal text with arrow pointing to the signal marker
                price_range = highs.max() - lows.min()
                text_offset = price_range * 0.08
                
                if signal == 'BUY':
                    text_y = latest_price + text_offset
                    arrow_style = '->'
                else:
                    text_y = latest_price - text_offset
                    arrow_style = '->'
                
                ax1.annotate(f'{signal}\nSIGNAL', 
                           xy=(latest_date, latest_price),  # Point to signal marker
                           xytext=(latest_date, text_y),  # Text position
                           color=marker_color, fontweight='bold', fontsize=9, ha='center',
                           bbox=dict(boxstyle="round,pad=0.3", facecolor='white', alpha=0.95, edgecolor=marker_color, linewidth=2),
                           arrowprops=dict(arrowstyle=arrow_style, color=marker_color, lw=2, alpha=0.9))
        except Exception as e:
            print(f"Warning: Could not add signal marker: {e}")
        
        # Calculate proper y-axis range including all indicators to prevent cutoff
        try:
            all_y_values = list(highs) + list(lows)
            
            # Include Bollinger Bands values if available
            if len(df_chart) >= 20:
                rolling_mean = df_chart['close'].rolling(window=20).mean()
                rolling_std = df_chart['close'].rolling(window=20).std()
                bb_upper_series = rolling_mean + (rolling_std * 2)
                bb_lower_series = rolling_mean - (rolling_std * 2)
                
                valid_bb_mask = (bb_upper_series.notna() & bb_lower_series.notna())
                if valid_bb_mask.any():
                    all_y_values.extend(bb_upper_series[valid_bb_mask].values)
                    all_y_values.extend(bb_lower_series[valid_bb_mask].values)
            
            # Include Moving Averages values if available
            if len(df_chart) >= 20:
                ma20 = df_chart['close'].rolling(window=20).mean()
                valid_ma20_mask = ma20.notna()
                if valid_ma20_mask.any():
                    all_y_values.extend(ma20[valid_ma20_mask].values)
            
            if len(df_chart) >= 50:
                ma50 = df_chart['close'].rolling(window=50).mean()
                valid_ma50_mask = ma50.notna()
                if valid_ma50_mask.any():
                    all_y_values.extend(ma50[valid_ma50_mask].values)
            
            # Include Support/Resistance levels
            sr_levels = signal_data.get('sr_levels', {})
            if sr_levels.get('levels'):
                for level in sr_levels['levels']:
                    all_y_values.append(level['level'])
            
            # Calculate range with 5% padding to ensure visibility
            if all_y_values:
                y_min = min(all_y_values)
                y_max = max(all_y_values)
                y_range = y_max - y_min
                padding = y_range * 0.05  # 5% padding
                
                ax1.set_ylim(y_min - padding, y_max + padding)
            
        except Exception as e:
            print(f"Warning: Could not set y-axis range: {e}")
        
        ax1.set_ylabel('Price', color=colors['text'], fontsize=14)
        ax1.grid(True, alpha=0.3, color=colors['grid'])
        
        # Improved legend with better positioning to avoid indicator cutoff
        legend = ax1.legend(loc='upper left', framealpha=0.9, fontsize=9, 
                           bbox_to_anchor=(0.02, 0.98), borderaxespad=0,
                           fancybox=True, shadow=True)
        legend.get_frame().set_facecolor(colors['panel'])
        legend.get_frame().set_edgecolor(colors['grid'])
        
        # 2. Enhanced Volume Analysis subplot
        ax2.set_facecolor(colors['panel'])
        
        try:
            # Calculate volume proxy using price action (since actual volume may not be available)
            body_size = np.abs(closes - opens)
            wick_size = (highs - lows) - body_size
            volume_proxy = body_size + (wick_size * 0.3)  # Bodies matter more than wicks
            
            # Normalize volume for better display
            volume_normalized = (volume_proxy / np.max(volume_proxy)) * 100
            
            # Color bars based on bullish/bearish candles
            colors_volume = [colors['green'] if closes[i] >= opens[i] else colors['red'] for i in range(len(closes))]
            
            ax2.bar(dates, volume_normalized, color=colors_volume, alpha=0.7, width=candle_width*0.8)
            
            # Add volume moving average
            if len(volume_normalized) >= 20:
                vol_ma = pd.Series(volume_normalized).rolling(window=20).mean()
                ax2.plot(dates, vol_ma, color=colors['yellow'], linewidth=2, label='Volume MA(20)')
            
            # Add volume spikes annotation
            vol_threshold = np.percentile(volume_normalized, 80)
            spike_indices = np.where(volume_normalized > vol_threshold)[0]
            
            for idx in spike_indices[-5:]:  # Show last 5 spikes
                if idx < len(dates):
                    ax2.annotate('Volume Spike', 
                               xy=(dates[idx], volume_normalized[idx]),
                               xytext=(dates[idx], volume_normalized[idx] + 20),
                               color=colors['cyan'], fontsize=8, ha='center',
                               arrowprops=dict(arrowstyle='->', color=colors['cyan'], alpha=0.7))
            
            ax2.set_ylabel('Volume Analysis', color=colors['text'], fontsize=12)
            ax2.legend(loc='upper right', framealpha=0.8, fontsize=9)
            
        except Exception as e:
            print(f"Warning: Could not add Volume analysis: {e}")
            ax2.text(0.5, 0.5, 'Volume Data Unavailable', transform=ax2.transAxes, 
                    ha='center', va='center', color=colors['text'], fontsize=12)
        
        ax2.grid(True, alpha=0.3, color=colors['grid'])
        
        # 3. Enhanced Order Flow Analysis subplot  
        ax3.set_facecolor(colors['panel'])
        
        try:
            # Calculate order flow metrics
            price_changes = np.diff(closes)
            
            # Calculate buying vs selling pressure based on price movement and volume proxy
            buying_pressure = []
            selling_pressure = []
            
            for i in range(len(price_changes)):
                if price_changes[i] > 0:  # Price went up - buying pressure
                    buying_pressure.append(volume_normalized[i+1])
                    selling_pressure.append(0)
                else:  # Price went down - selling pressure
                    buying_pressure.append(0)
                    selling_pressure.append(volume_normalized[i+1])
            
            # Pad to match dates length
            buying_pressure = [0] + buying_pressure
            selling_pressure = [0] + selling_pressure
            
            # Plot order flow bars
            ax3.bar(dates, buying_pressure, color=colors['green'], alpha=0.7, 
                   width=candle_width*0.6, label='Buying Pressure')
            ax3.bar(dates, [-x for x in selling_pressure], color=colors['red'], alpha=0.7, 
                   width=candle_width*0.6, label='Selling Pressure')
            
            # Add cumulative order flow line
            cumulative_flow = []
            running_total = 0
            for b, s in zip(buying_pressure, selling_pressure):
                running_total += (b - s)
                cumulative_flow.append(running_total)
            
            # Normalize cumulative flow for better display
            if cumulative_flow:
                max_flow = max(abs(min(cumulative_flow)), abs(max(cumulative_flow)))
                if max_flow > 0:
                    cumulative_flow = [x / max_flow * 50 for x in cumulative_flow]
            
            ax3.plot(dates, cumulative_flow, color=colors['yellow'], linewidth=2, 
                    label='Cumulative Flow', alpha=0.9)
            
            # Add order flow imbalance detection
            recent_buying = sum(buying_pressure[-10:]) if len(buying_pressure) >= 10 else sum(buying_pressure)
            recent_selling = sum(selling_pressure[-10:]) if len(selling_pressure) >= 10 else sum(selling_pressure)
            
            if recent_buying > recent_selling * 1.5 and recent_buying > 0:
                peak_idx = max(range(max(0, len(buying_pressure)-10), len(buying_pressure)), 
                              key=lambda i: buying_pressure[i])
                ax3.annotate('Strong Buying', 
                           xy=(dates[peak_idx], buying_pressure[peak_idx]),
                           xytext=(dates[min(peak_idx+3, len(dates)-1)], buying_pressure[peak_idx] + 20),
                           color=colors['green'], fontweight='bold', fontsize=8,
                           arrowprops=dict(arrowstyle='->', color=colors['green'], alpha=0.8))
            elif recent_selling > recent_buying * 1.5 and recent_selling > 0:
                peak_idx = max(range(max(0, len(selling_pressure)-10), len(selling_pressure)), 
                              key=lambda i: selling_pressure[i])
                ax3.annotate('Strong Selling', 
                           xy=(dates[peak_idx], -selling_pressure[peak_idx]),
                           xytext=(dates[min(peak_idx+3, len(dates)-1)], -selling_pressure[peak_idx] - 20),
                           color=colors['red'], fontweight='bold', fontsize=8,
                           arrowprops=dict(arrowstyle='->', color=colors['red'], alpha=0.8))
            
            ax3.axhline(y=0, color=colors['text'], linestyle='-', alpha=0.8, linewidth=2)
            ax3.set_ylabel('Order Flow', color=colors['text'], fontsize=12)
            ax3.legend(loc='upper right', framealpha=0.8, fontsize=9)
            
        except Exception as e:
            print(f"Warning: Could not add Order Flow: {e}")
            ax3.text(0.5, 0.5, 'Order Flow Data Unavailable', transform=ax3.transAxes, 
                    ha='center', va='center', color=colors['text'], fontsize=12)
        
        ax3.grid(True, alpha=0.3, color=colors['grid'])
        ax3.set_xlabel('Time (UTC)', color=colors['text'], fontsize=12)
        
        # Format x-axis
        for ax in [ax1, ax2, ax3]:
            ax.tick_params(axis='both', colors=colors['text'])
            for spine in ax.spines.values():
                spine.set_color(colors['grid'])
        
        # Format dates on x-axis
        if len(df_chart) > 50:
            ax3.xaxis.set_major_locator(mdates.HourLocator(interval=max(1, len(df_chart)//10)))
        else:
            ax3.xaxis.set_major_locator(mdates.HourLocator(interval=max(1, len(df_chart)//5)))
        ax3.xaxis.set_major_formatter(mdates.DateFormatter('%m/%d %H:%M'))
        
        # Hide x-axis labels for upper subplots
        plt.setp(ax1.get_xticklabels(), visible=False)
        plt.setp(ax2.get_xticklabels(), visible=False)
        
        # Add enhanced signal info to title
        try:
            confidence = signal_data.get('confidence_data', {}).get('confidence', 0)
            signal = signal_data.get('signal', 'NEUTRAL')
            
                        # Create main title
            main_title = f"{pair} Chart Analysis"
            
            # Get ICT analysis summary
            ict_summary = "No ICT patterns"
            if fvg_levels:
                ict_summary = f"{fvg_levels.get('type', 'FVG')} detected"
            elif bullish_ob_levels or bearish_ob_levels:
                ict_summary = "Order Block identified"
            
            # Add title with proper spacing
            fig.suptitle(main_title, color=colors['text'], fontsize=18, y=0.95, fontweight='bold')
            
        except Exception as e:
            print(f"Warning: Could not add signal info: {e}")
            # Fallback simple title
            fig.suptitle(f"{pair} Chart Analysis", color=colors['text'], fontsize=16, y=0.95)
            
        # Adjust layout
        plt.tight_layout()
        
        # Save chart
        buffer = io.BytesIO()
        try:
            plt.savefig(buffer, format='png', dpi=150, 
                       bbox_inches='tight', facecolor=colors['bg'], 
                       edgecolor='none', pad_inches=0.2)
            buffer.seek(0)
            
            chart_bytes = buffer.getvalue()
            
            # Clean up
            buffer.close()
            plt.close(fig)
            
            print(f"Enhanced ICT chart generated successfully for {pair} ({len(chart_bytes)} bytes)")
            return chart_bytes
            
        except Exception as save_error:
            print(f"Error saving chart: {save_error}")
            buffer.close()
            plt.close(fig)
            return None
            
    except ImportError as e:
        print(f"Chart generation failed: Missing required library: {e}")
        return None
    except Exception as e:
        print(f"Critical error in chart generation: {e}")
        import traceback
        traceback.print_exc()
        
        # Clean up any matplotlib figures
        try:
            plt.close('all')
        except:
            pass
        
        return None
    finally:
        # Enhanced memory cleanup
        try:
            plt.close('all')
            plt.clf()
            plt.cla()
            # Force garbage collection with multiple passes
            collected = cleanup_memory()
            if collected > 0:
                print(f"Cleaned up {collected} objects from chart generation")
        except Exception as cleanup_error:
            print(f"Cleanup warning: {cleanup_error}")
            pass

async def create_simplified_signal_embed(signal_data, pair, expiry, user_id=None, prefix="", mode=None):
    """Create simplified signal embed with custom images for BUY/SELL signals."""
    if "error" in signal_data:
        return discord.Embed(
            title="❌ Error",
            description=f"Failed to generate signal for {pair}: {signal_data['error']}",
            color=discord.Color.red()
        )

    signal = signal_data['signal']
    price = signal_data['price']
    indicators = signal_data['indicators']
    confidence_data = signal_data.get('confidence_data', {})

    color = discord.Color.green() if signal == "BUY" else discord.Color.red() if signal == "SELL" else discord.Color.yellow()
    signal_emoji = "🟢" if signal == "BUY" else "🔴" if signal == "SELL" else "🟡"
    confidence = confidence_data.get('confidence', 0)

    # Create title with mode indicator
    title = f"{signal_emoji} {pair} - **{signal}** ({confidence:.1f}%) {prefix}"
    
    # Create description with mode and date info
    description = f"💰 **{price:.5f}** | ⏰ {expiry} | 🎯 Confidence: **{confidence:.1f}%**"
    
    # Add date info for historical/test modes
    if mode in ['historical', 'test']:
        if mode == 'historical':
            if 'df' in signal_data and not signal_data['df'].empty:
                signal_date = signal_data['df']['datetime'].iloc[-1].strftime("%Y-%m-%d %H:%M UTC")
                description += f"\n📅 **Historical Data**: {signal_date}"
        elif mode == 'test':
            description += f"\n🧪 **Test Mode**: Simulated data for weekend testing"
    
    embed = discord.Embed(
        title=title,
        description=description,
        color=color,
        timestamp=datetime.now(timezone.utc)
    )
    
        # Confidence Breakdown
    # Enhanced Confluence Analysis with Agreement/Conflict Detection  
    confluence_analysis = confidence_data.get('confluence_details', {})
    if isinstance(confluence_analysis, dict) and confluence_analysis.get('factors'):
        # Use unified confluence analysis from confidence_data
        factors = confluence_analysis.get('factors', [])
        agreement_stats = confluence_analysis.get('agreement_stats', {})
        factors_summary = confluence_analysis.get('factors_summary', "")
        
        if factors_summary:
            confluence_text = f"**Agreement**: {factors_summary}\n"
            confluence_text += f"**ML Opinion**: {agreement_stats.get('ml_opinion', 'N/A')}\n"
            confluence_text += f"**Quality**: {confluence_analysis.get('quality', 'unknown').title()}\n\n"
            
            # Show top unified factors with details
            displayed_factors = []
            for factor in factors[:5]:  # Show top 5 factors
                if isinstance(factor, dict):
                    name = factor.get('name', 'Unknown Factor')
                    signal = factor.get('signal', 'NEUTRAL')
                    agreement = factor.get('agreement', 'neutral')
                    strength = factor.get('strength', 50)
                    
                    # Use agreement-based emojis
                    emoji = "🟢" if agreement == 'agree' else "🔴" if agreement == 'disagree' else "⚪"
                    strength_emoji = "💪" if strength > 75 else "👍" if strength > 50 else "👌"
                    displayed_factors.append(f"{emoji}{strength_emoji} {name}: {signal}")
            
            if displayed_factors:
                confluence_text += "\n".join(displayed_factors)
                embed.add_field(name="🎯 Enhanced Confluence Analysis", value=confluence_text, inline=False)
    
    # Trade Manager Integration - Show next trade amount if tuned
    if user_id:
        try:
            from trade_manager_system import TradeManagerSystem
            tm_system = TradeManagerSystem()
            session_status = tm_system.get_session_status(str(user_id))
            user_settings = tm_system.load_user_settings(str(user_id))
            
            if (session_status.get('success') and session_status.get('session_active') and 
                user_settings.get('tune_with_signals', False)):
                next_amount = session_status.get('session_data', {}).get('current_state', {}).get('next_trade_amount', 0)
                if next_amount > 0:
                    embed.add_field(
                        name="💰 Next Trade Amount",
                        value=f"**${next_amount:.2f}**\n*Auto-calculated from Trade Manager*",
                        inline=True
                    )
        except Exception:
            pass  # Ignore trade manager errors
    
    # Market Sessions
    active_sessions = get_active_market_sessions()
    if active_sessions:
        sessions_text = " | ".join([f"🟢 {session}" for session in active_sessions])
    else:
        sessions_text = "🔴 No major sessions active"
    embed.add_field(name="🌍 Market Sessions", value=sessions_text, inline=False)

    # Add user settings info if available
    if user_id and confidence_data.get('filtered_by_user_settings'):
        min_confidence = confidence_data.get('user_min_confidence', 70)
        embed.add_field(
            name="⚙️ User Filter Applied",
            value=f"Signal filtered by your min confidence ({min_confidence:.1f}%)",
            inline=False
        )
    
    # Show triggered alerts if any
    if user_id and confidence_data.get('triggered_alerts'):
        alerts = confidence_data['triggered_alerts']
        alert_text = ""
        for alert in alerts[:2]:  # Show max 2 alerts in simplified view
            condition_emoji = "📈" if alert['condition_type'] == 'above' else "📉"
            alert_text += f"{condition_emoji} **ALERT**: {alert['pair']} {alert['condition_type']} {alert['target_value']:.5f}\n"
        
        if alert_text:
            embed.add_field(name="🔔 Price Alerts Triggered", value=alert_text, inline=False)

    # Add custom images for BUY and SELL signals
    if signal == "BUY":
        embed.set_image(url="https://cdn.discordapp.com/attachments/1378322281452933164/1382672379511177298/1749725166036.png?ex=684caa40&is=684b58c0&hm=a444c9b3b2a2f5a591eb25180a1612f2ffbabf8ecee261d3306a868e6b11a114&")
    elif signal == "SELL":
        embed.set_image(url="https://cdn.discordapp.com/attachments/1378322281452933164/1382672379851046973/1749725177819.png?ex=684caa40&is=684b58c0&hm=7143e2302fb35eb0a6dca478f05a347b5a2c16c9c2e9e195d80d1ac695514e9e&")

    embed.add_field(
        name="📋 How to Use",
        value="Click **More Details** for comprehensive analysis including S/R levels, Fibonacci, volume analysis, and advanced patterns.",
        inline=False
    )

    return embed

def get_ict_summary(df, indicators):
    """Get a condensed ICT analysis summary for the simplified embed."""
    if len(df) < 10:
        return "Insufficient data for ICT analysis"

    summary_parts = []

    # Market Structure
    try:
        structure_result = analyze_market_structure(df)
        if structure_result is not None and isinstance(structure_result, (list, tuple)) and len(structure_result) >= 2:
            trend, structure_info = structure_result
        else:
            trend = "Unknown"
            structure_info = {}
    except Exception as e:
        print(f"Error in market structure analysis: {e}")
        trend = "Unknown"
        structure_info = {}
    
    summary_parts.append(f"📊 Structure: {trend}")

    # Order Blocks
    bullish_ob, bearish_ob, bullish_ob_levels, bearish_ob_levels = detect_order_block(df)
    if bullish_ob.iloc[-1] and bullish_ob_levels:
        summary_parts.append("🟢 Bullish OB detected")
    elif bearish_ob.iloc[-1] and bearish_ob_levels:
        summary_parts.append("🔴 Bearish OB detected")

    # Fair Value Gaps
    fvg, fvg_levels = detect_fair_value_gap(df)
    if fvg.iloc[-1] and fvg_levels:
        fvg_type = "Bullish" if "Bullish" in fvg_levels.get('type', '') else "Bearish"
        summary_parts.append(f"📍 {fvg_type} FVG")

    # Smart Money Concepts
    smc_info = detect_smart_money_concepts(df)
    if smc_info.get('displacement'):
        for disp in smc_info['displacement'][-1:]:
            direction = "Bullish" if "Bullish" in disp['type'] else "Bearish"
            summary_parts.append(f"🚀 {direction} displacement")

    if not summary_parts:
        summary_parts.append("📊 Neutral conditions")

    return "\n".join(summary_parts[:3])  # Limit to 3 lines

def get_ict_analysis(df, indicators):
    """Get comprehensive ICT analysis for detailed embeds - ONLY VALID ICT PATTERNS."""
    if len(df) < 15:
        return "Insufficient data for proper ICT analysis (minimum 15 candles required)"

    analysis = ""
    valid_patterns_found = False
    
    # Market Structure Analysis
    try:
        structure_result = analyze_market_structure(df)
        if structure_result is not None and isinstance(structure_result, (list, tuple)) and len(structure_result) >= 2:
            trend, structure_info = structure_result
        else:
            trend = "Unknown"
            structure_info = {}
    except Exception as e:
        print(f"Error in market structure analysis: {e}")
        trend = "Unknown"
        structure_info = {}
    
    if trend != "Unknown" and trend != "No data":
        analysis += f"📊 **Market Structure**: {trend}\n"
        valid_patterns_found = True
    
    # Break of Structure - Only show confirmed breaks
    if isinstance(structure_info, dict) and 'break_of_structure' in structure_info:
        analysis += f"🔥 **Break of Structure**: {structure_info['break_of_structure']}\n"
        valid_patterns_found = True
    
    # Order Blocks - ONLY RESPECTED ORDER BLOCKS (ICT Rule)
    try:
        bullish_ob, bearish_ob, bullish_ob_levels, bearish_ob_levels = detect_order_block(df)
        
        # Only show order blocks that have been respected multiple times
        if bullish_ob_levels and bullish_ob_levels.get('respect_count', 0) >= 2:
            quality = bullish_ob_levels.get('quality', 'Medium')
            freshness = "Fresh" if bullish_ob_levels.get('is_fresh', True) else "Tested"
            analysis += f"🟢 **{bullish_ob_levels['type']}** ({quality} Quality)\n"
            analysis += f"   📍 Zone: {bullish_ob_levels['low']:.5f} - {bullish_ob_levels['high']:.5f}\n"
            analysis += f"   ⚡ Displacement: {bullish_ob_levels['displacement_size']:.2f}% | 🔄 {freshness}\n"
            analysis += f"   💪 Strength: {bullish_ob_levels['strength']:.2f} | 🎯 Expected: Support\n"
            valid_patterns_found = True
            
        if bearish_ob_levels and bearish_ob_levels.get('respect_count', 0) >= 2:
            quality = bearish_ob_levels.get('quality', 'Medium')
            freshness = "Fresh" if bearish_ob_levels.get('is_fresh', True) else "Tested"
            analysis += f"🔴 **{bearish_ob_levels['type']}** ({quality} Quality)\n"
            analysis += f"   📍 Zone: {bearish_ob_levels['low']:.5f} - {bearish_ob_levels['high']:.5f}\n"
            analysis += f"   ⚡ Displacement: {bearish_ob_levels['displacement_size']:.2f}% | 🔄 {freshness}\n"
            analysis += f"   💪 Strength: {bearish_ob_levels['strength']:.2f} | 🎯 Expected: Resistance\n"
            valid_patterns_found = True
            
    except Exception as e:
        print(f"Error detecting order blocks: {e}")
    
    # Fair Value Gaps - ONLY UNFILLED GAPS (ICT Rule)
    try:
        fvg, fvg_levels = detect_fair_value_gap(df)
        if fvg_levels and not fvg_levels.get('is_filled', True):
            fvg_type = fvg_levels.get('type', 'Unknown')
            strength = fvg_levels.get('strength', 'Medium')
            quality = fvg_levels.get('quality', 'Medium')
            displacement = fvg_levels.get('displacement_size', 0)
            bias = fvg_levels.get('bias', 'Neutral')
            
            analysis += f"📍 **{fvg_type}** ({quality} Quality)\n"
            analysis += f"   📊 Gap: {fvg_levels['lower']:.5f} - {fvg_levels['upper']:.5f}\n"
            analysis += f"   ⚡ Displacement: {displacement:.2f}% | ⏳ Status: Unfilled\n"
            analysis += f"   🎯 {fvg_levels.get('expected_reaction', 'Monitor for reaction')}\n"
            analysis += f"   📈 Bias: {bias}\n"
            valid_patterns_found = True
            
    except Exception as e:
        print(f"Error detecting FVG: {e}")
    
    # Liquidity Zones - Only significant and recent liquidity levels
    try:
        liquidity_info = detect_liquidity_zones(df)
        significant_liquidity = False
        
        if liquidity_info.get('equal_highs'):
            for eq_high in liquidity_info['equal_highs'][:1]:  # Only most significant
                if eq_high.get('count', 0) >= 3:  # Increased threshold for significance
                    analysis += f"💧 **Buy-Side Liquidity Pool**: {eq_high['price']:.5f} ({eq_high['count']} equal highs)\n"
                    analysis += f"   🎯 Expected: Liquidity grab above this level\n"
                    valid_patterns_found = True
                    significant_liquidity = True
                    
        if liquidity_info.get('equal_lows'):
            for eq_low in liquidity_info['equal_lows'][:1]:  # Only most significant
                if eq_low.get('count', 0) >= 3:  # Increased threshold for significance
                    analysis += f"💧 **Sell-Side Liquidity Pool**: {eq_low['price']:.5f} ({eq_low['count']} equal lows)\n"
                    analysis += f"   🎯 Expected: Liquidity grab below this level\n"
                    valid_patterns_found = True
                    significant_liquidity = True
                    
        if liquidity_info.get('liquidity_grabs') and significant_liquidity:
            for grab in liquidity_info['liquidity_grabs'][:1]:  # Most recent grab
                analysis += f"⚡ **Recent {grab['type']}**: {grab['description']}\n"
                analysis += f"   💡 Smart money may now reverse direction\n"
                valid_patterns_found = True
                
    except Exception as e:
        print(f"Error detecting liquidity zones: {e}")
    
    # Smart Money Concepts - Only high-impact displacements and confirmed inducement
    try:
        smc_info = detect_smart_money_concepts(df)
        if smc_info.get('displacement'):
            # Only show major displacements (institutional moves)
            major_displacements = [d for d in smc_info['displacement'] if d.get('size', 0) > 1.5]
            for disp in major_displacements[-1:]:  # Most recent major displacement
                analysis += f"🚀 **{disp['type']}** (Institutional Move)\n"
                analysis += f"   📊 Magnitude: {disp['size']:.2f}% | ⚡ Smart money activity detected\n"
                valid_patterns_found = True
                
        if smc_info.get('inducement'):
            # Only show confirmed inducement (false breakouts)
            for ind in smc_info['inducement'][:1]:  # Most recent confirmed inducement
                analysis += f"🎯 **Smart Money Inducement**: {ind['description']}\n"
                analysis += f"   💡 Retail trapped, institutional reversal likely\n"
                valid_patterns_found = True
                
    except Exception as e:
        print(f"Error detecting SMC: {e}")
    
    # Premium/Discount Analysis
    try:
        current_price = df['close'].iloc[-1]
        recent_high = df['high'].tail(20).max()
        recent_low = df['low'].tail(20).min()
        
        if recent_high != recent_low:
            price_position = (current_price - recent_low) / (recent_high - recent_low)
            
            if price_position > 0.7:
                analysis += f"💰 **Premium Zone** ({price_position*100:.1f}%): Look for sells at resistance\n"
                valid_patterns_found = True
            elif price_position < 0.3:
                analysis += f"💰 **Discount Zone** ({price_position*100:.1f}%): Look for buys at support\n"
                valid_patterns_found = True
            elif 0.4 <= price_position <= 0.6:
                analysis += f"💰 **Equilibrium Zone** ({price_position*100:.1f}%): Await directional bias\n"
                valid_patterns_found = True
                
    except Exception as e:
        print(f"Error in premium/discount analysis: {e}")

    if not valid_patterns_found:
        analysis = "📊 **Clean ICT Environment**\n"
        analysis += "✅ No unfilled Fair Value Gaps detected\n"
        analysis += "✅ No respected Order Blocks in immediate area\n"
        analysis += "✅ No significant liquidity imbalances\n"
        analysis += "🎯 **ICT Strategy**: Wait for fresh institutional setups\n"
        analysis += "💡 **Recommendation**: Monitor for new displacements creating valid ICT patterns"

    return analysis

