def get_jpy_specific_adjustments(pair, indicators, df):
    """Get JPY-specific adjustments for signal generation."""
    is_jpy_pair = 'JPY' in pair
    if not is_jpy_pair:
        return {'applied': False}
    
    adjustments = {
        'applied': True,
        'pair_type': 'JPY',
        'volatility_factor': 1.0,
        'signal_threshold_adjustment': 0,
        'confidence_multiplier': 1.0,
        'special_considerations': []
    }
    
    # JPY pairs have different price scales and behavior
    if len(df) >= 14:
        atr = ((df['high'] - df['low']).tail(14).mean())
        volatility_pct = (atr / df['close'].iloc[-1]) * 100
        
        # Adjust for JPY pair volatility characteristics
        if volatility_pct > 1.2:  # High vol for JPY
            adjustments['volatility_factor'] = 0.8
            adjustments['signal_threshold_adjustment'] = 3
            adjustments['special_considerations'].append("High JPY volatility - increased threshold")
        elif volatility_pct < 0.5:  # Low vol for JPY
            adjustments['volatility_factor'] = 1.2
            adjustments['signal_threshold_adjustment'] = -2
            adjustments['special_considerations'].append("Low JPY volatility - decreased threshold")
    
    # Specific JPY pair adjustments
    major_jpy_pairs = ['USD/JPY', 'EUR/JPY', 'GBP/JPY']
    volatile_jpy_pairs = ['GBP/JPY', 'AUD/JPY']
    
    if pair in volatile_jpy_pairs:
        adjustments['confidence_multiplier'] = 0.95
        adjustments['signal_threshold_adjustment'] += 2
        adjustments['special_considerations'].append("Volatile JPY pair - conservative approach")
    elif pair in major_jpy_pairs:
        adjustments['confidence_multiplier'] = 1.02
        adjustments['special_considerations'].append("Major JPY pair - slight confidence boost")
    
    # RSI adjustments for JPY pairs (different overbought/oversold levels)
    rsi = indicators.get('rsi', 50)
    if rsi < 25 or rsi > 75:  # More extreme levels for JPY
        adjustments['confidence_multiplier'] *= 1.1
        adjustments['special_considerations'].append("JPY RSI extreme level")
    
    return adjustments

def get_regime_aware_thresholds(regime_data, is_jpy_pair, expiry):
    """Get signal thresholds based on market regime and pair type."""
    base_threshold = 25
    dominance_threshold = 8
    
    regime = regime_data['regime']
    regime_strength = regime_data['strength']
    
    # Regime-specific threshold adjustments
    if regime == 'Trending' and regime_strength > 70:
        # In strong trends, lower thresholds for trend-following signals
        base_threshold = 22
        dominance_threshold = 6
    elif regime == 'Trending' and regime_strength > 50:
        base_threshold = 24
        dominance_threshold = 7
    elif regime == 'Ranging' and regime_strength > 60:
        # In ranging markets, higher thresholds for mean reversion
        base_threshold = 28
        dominance_threshold = 10
    elif regime == 'Ranging':
        base_threshold = 26
        dominance_threshold = 9
    else:  # Transitional
        base_threshold = 30
        dominance_threshold = 12
    
    # JPY pair adjustments
    if is_jpy_pair:
        base_threshold += 2  # Higher threshold for JPY pairs
        dominance_threshold += 1
    
    # Expiry-specific adjustments
    if expiry == '1m':
        base_threshold -= 3  # Lower for scalping
        dominance_threshold -= 1
    elif expiry == '15m':
        base_threshold += 2  # Higher for longer timeframes
        dominance_threshold += 1
    
    return {
        'base_threshold': base_threshold,
        'dominance_threshold': dominance_threshold,
        'regime': regime,
        'regime_strength': regime_strength
    }

def calculate_trending_market_signals(indicator_conf, ict_conf, regime_data, jpy_adjustments, pair):
    """Calculate signals optimized for trending markets."""
    trend_direction = regime_data.get('trend_direction', 'Neutral')
    regime_strength = regime_data['strength']
    
    # In trending markets, prioritize momentum indicators and trend-following ICT patterns
    momentum_weight = 0.7 if regime_strength > 70 else 0.65
    ict_weight = 1.0 - momentum_weight
    
    # Boost signals that align with trend direction
    bullish_score = (indicator_conf['bullish_percentage'] * momentum_weight + 
                    ict_conf['bullish_percentage'] * ict_weight)
    bearish_score = (indicator_conf['bearish_percentage'] * momentum_weight + 
                    ict_conf['bearish_percentage'] * ict_weight)
    
    # Trend alignment bonus
    if trend_direction == 'Bullish':
        bullish_score *= 1.15
        bearish_score *= 0.85  # Penalize counter-trend signals
    elif trend_direction == 'Bearish':
        bearish_score *= 1.15
        bullish_score *= 0.85
    
    # Apply JPY adjustments
    if jpy_adjustments['applied']:
        multiplier = jpy_adjustments['confidence_multiplier']
        bullish_score *= multiplier
        bearish_score *= multiplier
    
    return bullish_score, bearish_score

def calculate_ranging_market_signals(indicator_conf, ict_conf, regime_data, jpy_adjustments, pair):
    """Calculate signals optimized for ranging markets."""
    regime_strength = regime_data['strength']
    
    # In ranging markets, prioritize mean reversion and ICT support/resistance levels
    mean_reversion_weight = 0.5
    ict_weight = 0.5
    
    # Focus more on ICT patterns in ranging markets (S/R, order blocks)
    bullish_score = (indicator_conf['bullish_percentage'] * mean_reversion_weight + 
                    ict_conf['bullish_percentage'] * ict_weight)
    bearish_score = (indicator_conf['bearish_percentage'] * mean_reversion_weight + 
                    ict_conf['bearish_percentage'] * ict_weight)
    
    # Boost mean reversion signals in strong ranges
    if regime_strength > 60:
        # Check for oversold/overbought conditions
        rsi_boost = 0
        if indicator_conf.get('bullish_signals', 0) > 0:  # Oversold conditions
            rsi_boost = 1.1
        elif indicator_conf.get('bearish_signals', 0) > 0:  # Overbought conditions
            rsi_boost = 1.1
        
        bullish_score *= rsi_boost if indicator_conf.get('bullish_signals', 0) > 0 else 1.0
        bearish_score *= rsi_boost if indicator_conf.get('bearish_signals', 0) > 0 else 1.0
    
    # Apply JPY adjustments
    if jpy_adjustments['applied']:
        multiplier = jpy_adjustments['confidence_multiplier']
        bullish_score *= multiplier
        bearish_score *= multiplier
    
    return bullish_score, bearish_score

def calculate_transitional_market_signals(indicator_conf, ict_conf, jpy_adjustments, pair):
    """Calculate signals for transitional/uncertain markets."""
    # In transitional markets, be very conservative
    bullish_score = (indicator_conf['bullish_percentage'] * 0.5 + 
                    ict_conf['bullish_percentage'] * 0.5) * 0.8  # 20% penalty
    bearish_score = (indicator_conf['bearish_percentage'] * 0.5 + 
                    ict_conf['bearish_percentage'] * 0.5) * 0.8
    
    # Apply JPY adjustments
    if jpy_adjustments['applied']:
        multiplier = jpy_adjustments['confidence_multiplier'] * 0.9  # Extra conservative for JPY
        bullish_score *= multiplier
        bearish_score *= multiplier
    
    return bullish_score, bearish_score

def apply_regime_signal_logic(bullish_score, bearish_score, thresholds, regime_data, jpy_adjustments):
    """Apply regime-aware signal generation logic."""
    base_threshold = thresholds['base_threshold']
    dominance_threshold = thresholds['dominance_threshold']
    
    # Apply JPY threshold adjustments
    if jpy_adjustments['applied']:
        base_threshold += jpy_adjustments['signal_threshold_adjustment']
    
    signal = "NEUTRAL"
    base_confidence = 55
    
    # Generate signals based on regime-adjusted thresholds
    if (bullish_score >= base_threshold and 
        bullish_score > bearish_score + dominance_threshold):
        signal = "BUY"
        strength_factor = min(30, (bullish_score - base_threshold) * 0.8)
        base_confidence = 55 + strength_factor
        
        # Regime-specific confidence adjustments
        if regime_data['regime'] == 'Trending' and regime_data.get('trend_direction') == 'Bullish':
            base_confidence += 3  # Trend alignment bonus
        elif regime_data['regime'] == 'Ranging' and bullish_score >= base_threshold + 5:
            base_confidence += 2  # Mean reversion bonus in ranges
            
    elif (bearish_score >= base_threshold and 
          bearish_score > bullish_score + dominance_threshold):
        signal = "SELL"
        strength_factor = min(30, (bearish_score - base_threshold) * 0.8)
        base_confidence = 55 + strength_factor
        
        # Regime-specific confidence adjustments
        if regime_data['regime'] == 'Trending' and regime_data.get('trend_direction') == 'Bearish':
            base_confidence += 3  # Trend alignment bonus
        elif regime_data['regime'] == 'Ranging' and bearish_score >= base_threshold + 5:
            base_confidence += 2  # Mean reversion bonus in ranges
    
    return signal, base_confidence

def calculate_enhanced_ict_confidence(df, index=-1, pair="EUR/USD"):
    """Enhanced ICT confidence requiring multiple confluences to reduce false positives."""
    # Validate inputs
    if df is None or df.empty:
        print("calculate_enhanced_ict_confidence received invalid dataframe")
        return {
            'bullish_percentage': 0.0,
            'bearish_percentage': 0.0,
            'neutral_percentage': 100.0,
            'bullish_score': 0,
            'bearish_score': 0,
            'neutral_score': 0,
            'total_score': 0,
            'ict_confluences': 0,
            'pattern_quality': 'Low'
        }
    
    # Get individual ICT components
    ict_components = get_ict_component_analysis(df, index)
    
    # Require multiple ICT confluences for strong signals
    required_confluences = 2  # Minimum 2 ICT patterns must align
    quality_threshold = 3     # For high-quality signals, need 3+ confluences
    
    bullish_confluences = sum(1 for comp in ict_components if comp['bias'] == 'bullish' and comp['strength'] >= 3)
    bearish_confluences = sum(1 for comp in ict_components if comp['bias'] == 'bearish' and comp['strength'] >= 3)
    
    total_confluences = bullish_confluences + bearish_confluences
    
    # Only generate signals if minimum confluences are met
    if bullish_confluences >= required_confluences:
        bullish_score = min(25, bullish_confluences * 8)  # Cap at 25%
        pattern_quality = 'High' if bullish_confluences >= quality_threshold else 'Medium'
    else:
        bullish_score = bullish_confluences * 3  # Weak signal
        pattern_quality = 'Low'
    
    if bearish_confluences >= required_confluences:
        bearish_score = min(25, bearish_confluences * 8)  # Cap at 25%
        if pattern_quality != 'High':
            pattern_quality = 'High' if bearish_confluences >= quality_threshold else 'Medium'
    else:
        bearish_score = bearish_confluences * 3  # Weak signal
    
    neutral_score = max(50, 100 - bullish_score - bearish_score)
    
    return {
        'bullish_percentage': round(bullish_score, 1),
        'bearish_percentage': round(bearish_score, 1), 
        'neutral_percentage': round(neutral_score, 1),
        'bullish_score': bullish_confluences,
        'bearish_score': bearish_confluences,
        'neutral_score': 0,
        'total_score': total_confluences,
        'ict_confluences': total_confluences,
        'pattern_quality': pattern_quality,
        'required_confluences_met': total_confluences >= required_confluences
    }

def get_ict_component_analysis(df, index=-1):
    """Analyze individual ICT components with strength ratings."""
    components = []
    
    try:
        # Market Structure
        try:
            structure_result = analyze_market_structure(df)
            if structure_result and len(structure_result) >= 2:
                trend, structure_info = structure_result
                if trend in ['Uptrend', 'Downtrend']:
                    strength = 4 if 'break_of_structure' in structure_info else 3
                    bias = 'bullish' if trend == 'Uptrend' else 'bearish'
                    components.append({
                        'type': 'Market Structure',
                        'bias': bias,
                        'strength': strength,
                        'details': f"{trend} with BOS" if 'break_of_structure' in structure_info else trend
                    })
        except:
            pass
        
        # Order Blocks (require recent and strong)
        try:
            ob_patterns = detect_order_blocks(df)
            for pattern in ob_patterns[-2:]:  # Last 2 patterns
                strength = min(4, int(pattern.get('strength', 2)))
                bias = 'bullish' if pattern['type'] == 'bullish_ob' else 'bearish'
                components.append({
                    'type': f"{bias.title()} Order Block",
                    'bias': bias,
                    'strength': strength,
                    'details': f"Level: {pattern['level']:.5f}"
                })
        except:
            pass
        
        # Fair Value Gaps (only unfilled ones)
        try:
            fvg_patterns = detect_fair_value_gaps(df)
            for pattern in fvg_patterns[-1:]:  # Most recent pattern
                if not pattern.get('is_filled', True):
                    gap_strength = min(4, int(pattern.get('strength', 3)))
                    bias = 'bullish' if pattern['type'] == 'bullish_fvg' else 'bearish'
                    components.append({
                        'type': 'Fair Value Gap',
                        'bias': bias,
                        'strength': gap_strength,
                        'details': f"Unfilled {pattern['type']}"
                    })
        except:
            pass
        
        # Liquidity Zones (only strong grabs)
        try:
            sweep_patterns = detect_liquidity_sweeps(df)
            for pattern in sweep_patterns[-1:]:  # Most recent pattern
                if pattern.get('strength', 0) > 0.001:  # Significant sweep
                    bias = 'bearish' if pattern['type'] == 'buy_side_sweep' else 'bullish'
                    components.append({
                        'type': 'Liquidity Sweep',
                        'bias': bias,
                        'strength': 3,
                        'details': f"{pattern['type']} at {pattern['level']:.5f}"
                    })
        except:
            pass
        
        # Smart Money Displacement (only strong moves)
        try:
            if len(df) >= 20:
                recent_volatility = df['close'].pct_change().tail(10).std()
                if recent_volatility > 0.002:  # Significant volatility
                    price_change = (df['close'].iloc[-1] - df['close'].iloc[-10]) / df['close'].iloc[-10]
                    if abs(price_change) > 0.015:  # 1.5% move
                        bias = 'bullish' if price_change > 0 else 'bearish'
                        strength = 4 if abs(price_change) > 0.025 else 3
                        components.append({
                            'type': 'Smart Money Displacement',
                            'bias': bias,
                            'strength': strength,
                            'details': f"{abs(price_change)*100:.1f}% move"
                        })
        except:
            pass
        
    except Exception as e:
        print(f"Error in ICT component analysis: {e}")
    
    return components

# Missing function implementations to resolve "not found" errors
def analyze_market_structure(df):
    """Analyze market structure for trends and breaks"""
    try:
        if df is None or len(df) < 20:
            return ('Unknown', {})
        
        # Simple trend analysis
        recent_closes = df['close'].tail(20)
        if recent_closes.iloc[-1] > recent_closes.iloc[0]:
            return ('Uptrend', {'strength': 'Medium'})
        elif recent_closes.iloc[-1] < recent_closes.iloc[0]:
            return ('Downtrend', {'strength': 'Medium'})
        else:
            return ('Sideways', {'strength': 'Low'})
    except:
        return ('Unknown', {})

def detect_chart_patterns(df):
    """Detect basic chart patterns"""
    try:
        if df is None or len(df) < 50:
            return []
        
        patterns = []
        # Simple pattern detection based on price action
        highs = df['high'].rolling(5, min_periods=1).max()
        lows = df['low'].rolling(5, min_periods=1).min()
        
        current_high = df['high'].iloc[-1]
        current_low = df['low'].iloc[-1]
        
        if current_high > highs.iloc[-10:-1].max():
            patterns.append({'type': 'breakout_high', 'strength': 3})
        
        if current_low < lows.iloc[-10:-1].min():
            patterns.append({'type': 'breakout_low', 'strength': 3})
            
        return patterns
    except:
        return []

def analyze_pattern_confluence_old(patterns, current_price):
    """Old version - kept for compatibility"""
    try:
        if not patterns:
            return {'confluence_score': 0, 'pattern_strength': 'None', 'total_patterns': 0}
        
        total_strength = sum(p.get('strength', 1) for p in patterns)
        confluence_score = min(10, total_strength)
        
        if confluence_score >= 8:
            pattern_strength = 'Very Strong'
        elif confluence_score >= 6:
            pattern_strength = 'Strong'
        elif confluence_score >= 4:
            pattern_strength = 'Moderate'
        else:
            pattern_strength = 'Weak'
            
        return {
            'confluence_score': confluence_score,
            'pattern_strength': pattern_strength,
            'total_patterns': len(patterns) if isinstance(patterns, list) else 0
        }
    except:
        return {'confluence_score': 0, 'pattern_strength': 'None', 'total_patterns': 0}

def detect_market_regime(df):
    """Detect current market regime"""
    try:
        if df is None or len(df) < 30:
            return {'regime': 'Unknown', 'strength': 50, 'trend_direction': 'Neutral'}
        
        # Calculate trend strength
        prices = df['close'].tail(20)
        trend_direction = 'Bullish' if prices.iloc[-1] > prices.iloc[0] else 'Bearish'
        
        # Calculate volatility
        volatility = prices.pct_change().std()
        
        if volatility > 0.02:
            regime = 'Trending'
            strength = min(90, 60 + (volatility * 1000))
        elif volatility < 0.01:
            regime = 'Ranging'
            strength = 60
        else:
            regime = 'Transitional'
            strength = 55
            
        return {
            'regime': regime,
            'strength': strength,
            'trend_direction': trend_direction
        }
    except:
        return {'regime': 'Unknown', 'strength': 50, 'trend_direction': 'Neutral'}

def detect_order_blocks(df):
    """Detect order block patterns"""
    try:
        if df is None or len(df) < 20:
            return []
        
        patterns = []
        highs = df['high'].values
        lows = df['low'].values
        closes = df['close'].values
        
        # Simple order block detection based on strong moves
        for i in range(10, len(df) - 5):
            # Bullish order block - strong move up after consolidation
            if closes[i] > closes[i-5] * 1.01:  # 1% move up
                patterns.append({
                    'type': 'bullish_ob',
                    'level': lows[i-5:i].min(),
                    'strength': min(4, abs(closes[i] - closes[i-5]) / closes[i-5] * 100)
                })
                
            # Bearish order block - strong move down after consolidation  
            if closes[i] < closes[i-5] * 0.99:  # 1% move down
                patterns.append({
                    'type': 'bearish_ob',
                    'level': highs[i-5:i].max(),
                    'strength': min(4, abs(closes[i-5] - closes[i]) / closes[i-5] * 100)
                })
        
        return patterns[-10:]  # Return last 10 patterns
    except:
        return []

def detect_fair_value_gaps(df):
    """Detect fair value gap patterns"""
    try:
        if df is None or len(df) < 10:
            return []
        
        patterns = []
        highs = df['high'].values
        lows = df['low'].values
        
        # Look for gaps between candles
        for i in range(2, len(df)):
            # Bullish FVG - gap up
            if lows[i] > highs[i-2]:
                gap_size = lows[i] - highs[i-2]
                patterns.append({
                    'type': 'bullish_fvg',
                    'level': (lows[i] + highs[i-2]) / 2,
                    'gap_size': gap_size,
                    'strength': min(4, gap_size / highs[i-2] * 1000),
                    'is_filled': False
                })
                
            # Bearish FVG - gap down
            if highs[i] < lows[i-2]:
                gap_size = lows[i-2] - highs[i]
                patterns.append({
                    'type': 'bearish_fvg',
                    'level': (highs[i] + lows[i-2]) / 2,
                    'gap_size': gap_size,
                    'strength': min(4, gap_size / lows[i-2] * 1000),
                    'is_filled': False
                })
        
        return patterns[-5:]  # Return last 5 patterns
    except:
        return []

def detect_liquidity_sweeps(df):
    """Detect liquidity sweep patterns"""
    try:
        if df is None or len(df) < 20:
            return []
        
        patterns = []
        highs = df['high'].values
        lows = df['low'].values
        
        # Look for sweeps of previous highs/lows
        for i in range(10, len(df)):
            # Buy-side liquidity sweep
            recent_high = highs[i-10:i].max()
            if highs[i] > recent_high:
                strength = (highs[i] - recent_high) / recent_high
                patterns.append({
                    'type': 'buy_side_sweep',
                    'level': highs[i],
                    'strength': strength
                })
            
            # Sell-side liquidity sweep
            recent_low = lows[i-10:i].min()
            if lows[i] < recent_low:
                strength = (recent_low - lows[i]) / recent_low
                patterns.append({
                    'type': 'sell_side_sweep',
                    'level': lows[i],
                    'strength': strength
                })
        
        return patterns[-3:]  # Return last 3 patterns
    except:
        return []

def calculate_technical_indicators(df):
    """Calculate comprehensive technical indicators"""
    try:
        if df is None or len(df) < 50:
            return {}
        
        indicators = {}
        
        # Price-based indicators
        indicators['sma_20'] = df['close'].rolling(20).mean().iloc[-1]
        indicators['sma_50'] = df['close'].rolling(50).mean().iloc[-1] if len(df) >= 50 else df['close'].mean()
        indicators['ema_12'] = df['close'].ewm(span=12).mean().iloc[-1]
        indicators['ema_26'] = df['close'].ewm(span=26).mean().iloc[-1]
        
        # RSI
        delta = df['close'].diff()
        gain = (delta.where(delta > 0, 0)).rolling(window=14).mean()
        loss = (-delta.where(delta < 0, 0)).rolling(window=14).mean()
        rs = gain / loss
        indicators['rsi'] = (100 - (100 / (1 + rs))).iloc[-1]
        
        # MACD
        indicators['macd'] = indicators['ema_12'] - indicators['ema_26']
        indicators['macd_signal'] = df['close'].ewm(span=9).mean().iloc[-1]
        indicators['macd_histogram'] = indicators['macd'] - indicators['macd_signal']
        
        # Bollinger Bands
        bb_period = min(20, len(df))
        bb_sma = df['close'].rolling(bb_period).mean()
        bb_std = df['close'].rolling(bb_period).std()
        indicators['bb_upper'] = (bb_sma + (bb_std * 2)).iloc[-1]
        indicators['bb_lower'] = (bb_sma - (bb_std * 2)).iloc[-1]
        indicators['bb_middle'] = bb_sma.iloc[-1]
        
        # Volume indicators (if available)
        if 'volume' in df.columns:
            indicators['volume_sma'] = df['volume'].rolling(20).mean().iloc[-1]
            indicators['volume_ratio'] = df['volume'].iloc[-1] / indicators['volume_sma']
        
        return indicators
        
    except Exception as e:
        print(f"Error calculating technical indicators: {e}")
        return {}

def detect_market_structure(df):
    """Detect market structure patterns"""
    try:
        if df is None or len(df) < 30:
            return {'structure': 'Unknown', 'trend': 'Neutral', 'strength': 50}
        
        # Calculate trend using multiple timeframes
        short_trend = df['close'].tail(10).iloc[-1] - df['close'].tail(10).iloc[0]
        medium_trend = df['close'].tail(20).iloc[-1] - df['close'].tail(20).iloc[0]
        long_trend = df['close'].tail(min(50, len(df))).iloc[-1] - df['close'].tail(min(50, len(df))).iloc[0]
        
        # Determine overall structure
        if short_trend > 0 and medium_trend > 0 and long_trend > 0:
            structure = 'Bullish Trend'
            trend = 'Bullish'
            strength = min(90, 60 + abs(long_trend / df['close'].iloc[-1] * 100))
        elif short_trend < 0 and medium_trend < 0 and long_trend < 0:
            structure = 'Bearish Trend'
            trend = 'Bearish'
            strength = min(90, 60 + abs(long_trend / df['close'].iloc[-1] * 100))
        else:
            structure = 'Ranging/Consolidation'
            trend = 'Neutral'
            strength = 50
            
        return {
            'structure': structure,
            'trend': trend,
            'strength': strength
        }
        
    except Exception as e:
        print(f"Error detecting market structure: {e}")
        return {'structure': 'Unknown', 'trend': 'Neutral', 'strength': 50}

def calculate_ict_patterns(df):
    """Calculate ICT (Inner Circle Trader) patterns"""
    try:
        if df is None or len(df) < 50:
            return {}
        
        patterns = {}
        
        # Order blocks
        patterns['order_blocks'] = detect_order_blocks(df)
        
        # Fair value gaps
        patterns['fair_value_gaps'] = detect_fair_value_gaps(df)
        
        # Liquidity sweeps
        patterns['liquidity_sweeps'] = detect_liquidity_sweeps(df)
        
        # Market structure
        patterns['market_structure'] = detect_market_structure(df)
        
        # Confluence score
        total_patterns = (len(patterns['order_blocks']) + 
                         len(patterns['fair_value_gaps']) + 
                         len(patterns['liquidity_sweeps']))
        
        patterns['confluence_score'] = min(10, total_patterns)
        
        return patterns
        
    except Exception as e:
        print(f"Error calculating ICT patterns: {e}")
        return {}

def calculate_ict_confidence(df, index=-1):
    """Legacy ICT confidence - now redirects to enhanced version."""
    enhanced_result = calculate_enhanced_ict_confidence(df, index)
    
    # Return in legacy format for compatibility
    return {
        'bullish_percentage': enhanced_result['bullish_percentage'],
        'bearish_percentage': enhanced_result['bearish_percentage'],
        'neutral_percentage': enhanced_result['neutral_percentage'],
        'bullish_score': enhanced_result['bullish_score'],
        'bearish_score': enhanced_result['bearish_score'],
        'neutral_score': enhanced_result['neutral_score'],
        'total_score': enhanced_result['total_score']
    }
    
    try:
        bullish_ob, bearish_ob, bullish_ob_levels, bearish_ob_levels = detect_order_block(df)
        fvg, fvg_levels = detect_fair_value_gap(df)
    except Exception as e:
        print(f"Error in order block/FVG detection: {e}")
        # Return default confidence structure
        return {
            'bullish_percentage': 0.0,
            'bearish_percentage': 0.0,
            'neutral_percentage': 100.0,
            'bullish_score': 0,
            'bearish_score': 0,
            'neutral_score': 0,
            'total_score': 0
        }

    bullish_score = 0
    bearish_score = 0
    max_score = 0

    # Market Structure Analysis (More conservative scoring)
    max_score += 10
    try:
        structure_result = analyze_market_structure(df)
        # Ensure we always get a proper tuple
        if (structure_result is not None and 
            isinstance(structure_result, (list, tuple)) and 
            len(structure_result) >= 2 and
            structure_result[0] is not None):
            trend, structure_info = structure_result
        else:
            print(f"Invalid structure_result: {structure_result}")
            trend = "Unknown"
            structure_info = {}
    except Exception as e:
        print(f"Error in market structure analysis: {e}")
        trend = "Unknown"
        structure_info = {}
    
    if trend == "Uptrend":
        bullish_score += 7  # Reduced from 8 for more conservative
    elif trend == "Downtrend":
        bearish_score += 7  # Reduced from 8 for more conservative
    elif trend == "Consolidation":
        # Much more conservative in consolidation
        recent_closes = df['close'].tail(5)
        if len(recent_closes) >= 5:
            price_change = (recent_closes.iloc[-1] - recent_closes.iloc[0]) / recent_closes.iloc[0]
            if price_change > 0.005:  # Only if significant move (0.5%)
                bullish_score += 2
            elif price_change < -0.005:
                bearish_score += 2

    # Break of Structure (Very strong signal when present)
    if isinstance(structure_info, dict) and 'break_of_structure' in structure_info:
        max_score += 6  # Increased importance
        if "Bullish" in structure_info['break_of_structure']:
            bullish_score += 6
        else:
            bearish_score += 6

    # Order Blocks (High importance but more conservative)
    max_score += 6
    if bullish_ob.iloc[index] and bullish_ob_levels:
        # Check if order block is recent and strong
        ob_strength = bullish_ob_levels.get('strength', 'Medium')
        if ob_strength == 'High':
            bullish_score += 5
        else:
            bullish_score += 3
    elif bearish_ob.iloc[index] and bearish_ob_levels:
        ob_strength = bearish_ob_levels.get('strength', 'Medium')
        if ob_strength == 'High':
            bearish_score += 5
        else:
            bearish_score += 3

    # Fair Value Gaps (More conservative - require unfilled gaps)
    max_score += 5
    if fvg.iloc[index] and fvg_levels:
        gap_strength = fvg_levels.get('strength', 'Medium')
        is_filled = fvg_levels.get('is_filled', True)
        
        if not is_filled:  # Only count unfilled gaps
            if "Bullish" in fvg_levels.get('type', ''):
                score = 4 if gap_strength == 'High' else 2
                bullish_score += score
            else:
                score = 4 if gap_strength == 'High' else 2
                bearish_score += score

    # Chart Pattern Analysis (More conservative scoring)
    max_score += 8
    current_price = df['close'].iloc[-1]
    chart_patterns = detect_chart_patterns(df)
    if chart_patterns:
        confluence = analyze_pattern_confluence(chart_patterns, current_price)
        
        # Only count high-quality patterns
        if confluence['pattern_strength'] == 'High':
            if confluence['dominant_bias'] == 'Bullish' and confluence['confluence_score'] >= 7:
                pattern_score = min(6, confluence['confluence_score'] - 2)  # More conservative
                bullish_score += pattern_score
            elif confluence['dominant_bias'] == 'Bearish' and confluence['confluence_score'] >= 7:
                pattern_score = min(6, confluence['confluence_score'] - 2)  # More conservative
                bearish_score += pattern_score
        elif confluence['pattern_strength'] == 'Medium' and confluence['confluence_score'] >= 8:
            # Higher threshold for medium patterns
            if confluence['dominant_bias'] == 'Bullish':
                bullish_score += 3
            elif confluence['dominant_bias'] == 'Bearish':
                bearish_score += 3

    # Liquidity Analysis (More conservative - only strong signals)
    max_score += 4
    liquidity_info = detect_liquidity_zones(df)
    if liquidity_info.get('liquidity_grabs'):
        strong_grabs = [grab for grab in liquidity_info['liquidity_grabs'] 
                       if grab.get('strength', 'Medium') == 'High']
        if strong_grabs:
            grab = strong_grabs[0]  # Take the first strong grab
            if "Buy-side" in grab['type']:
                bearish_score += 3  # After liquidity grab, reversal expected
            else:
                bullish_score += 3

    # Smart Money Concepts - Displacement (Only very strong signals)
    max_score += 4
    smc_info = detect_smart_money_concepts(df)
    if smc_info.get('displacement'):
        for disp in smc_info['displacement'][-1:]:
            if disp['size'] > 2.0:  # Increased threshold from 1.5 to 2.0
                if "Bullish" in disp['type']:
                    bullish_score += 4
                else:
                    bearish_score += 4
                break

    # Smart Money Concepts - Inducement (Only clear inducement)
    max_score += 3
    if smc_info.get('inducement'):
        for ind in smc_info['inducement']:
            # Only count if description contains clear reversal indicators
            if "False break" in ind.get('description', ''):
                if "Bullish" in ind['type']:
                    bullish_score += 3
                else:
                    bearish_score += 3
                break

    # Candlestick Patterns (More selective)
    max_score += 3
    patterns = detect_candlestick_patterns(df)
    if patterns:
        strong_patterns = ['Bullish Engulfing', 'Bearish Engulfing', 'Bullish Pin Bar (Hammer)', 'Bearish Pin Bar (Shooting Star)']
        for pattern_type, pattern_name in patterns.items():
            if pattern_name in strong_patterns:
                if "Bullish" in pattern_name or "Hammer" in pattern_name:
                    bullish_score += 2
                else:
                    bearish_score += 2
                break

    # Calculate more conservative percentages
    if max_score == 0:
        return {
            'bullish_percentage': 0.0,
            'bearish_percentage': 0.0,
            'neutral_percentage': 100.0,
            'bullish_score': 0,
            'bearish_score': 0,
            'neutral_score': 0,
            'total_score': 0
        }

    # More conservative percentage calculation - max 30% for any direction
    max_percentage = 30
    bullish_percentage = min(max_percentage, (bullish_score / max_score) * 100)
    bearish_percentage = min(max_percentage, (bearish_score / max_score) * 100)
    neutral_percentage = max(40, 100 - bullish_percentage - bearish_percentage)  # Minimum 40% neutral

    return {
        'bullish_percentage': round(bullish_percentage, 1),
        'bearish_percentage': round(bearish_percentage, 1),
        'neutral_percentage': round(neutral_percentage, 1),
        'bullish_score': bullish_score,
        'bearish_score': bearish_score,
        'neutral_score': max_score - bullish_score - bearish_score,
        'total_score': max_score
    }

class TradingStyle:
    """Base class for trading styles"""
    
    def __init__(self, name: str, expiry: str, description: str):
        self.name = name
        self.expiry = expiry
        self.description = description
        self.min_confidence = 70
        self.weight_adjustments = {}
        
    def analyze(self, df: pd.DataFrame, indicators: dict, pair: str) -> dict:
        """Analyze market conditions using this trading style"""
        raise NotImplementedError
        
    def get_confidence_multiplier(self, base_confidence: float) -> float:
        """Get confidence multiplier based on style-specific conditions"""
        return 1.0

class ScalpingStyle(TradingStyle):
    """Enhanced 1-minute expiry strategy with improved accuracy features"""
    
    def __init__(self):
        super().__init__(
            name="Enhanced Scalping",
            expiry="1m",
            description="High-accuracy 1-minute scalping with multi-layer confirmation"
        )
        self.min_confidence = 70  # Slightly lower to allow more signals
        
    def analyze(self, df: pd.DataFrame, indicators: dict, pair: str) -> dict:
        """Enhanced 1-minute scalping analysis with improved accuracy"""
        analysis = {
            'style_confidence': 0,
            'style_factors': [],
            'optimal_conditions': False,
            'risk_level': 'High',
            'style_multiplier': 1.0,
            'micro_trend_score': 0,
            'momentum_quality': 'Unknown'
        }
        
        if len(df) < 30:  # Need more data for better analysis
            return analysis
            
        # Enhanced momentum analysis
        recent_candles = df.tail(10)  # More candles for better context
        momentum_score = 0
        
        # 1. Multi-timeframe momentum detection (using 1-minute data)
        price_changes_1m = recent_candles['close'].pct_change().dropna()
        price_changes_5m = recent_candles.iloc[::5]['close'].pct_change().dropna() if len(recent_candles) >= 5 else price_changes_1m
        
        # Short-term momentum (last 3 candles)
        short_momentum = price_changes_1m.tail(3).mean()
        # Medium-term momentum (last 10 candles)
        medium_momentum = price_changes_1m.mean()
        
        # Momentum consistency check
        momentum_consistency = (price_changes_1m.tail(5) * price_changes_1m.tail(5).mean() > 0).sum()
        
        if abs(short_momentum) > 0.0008 and momentum_consistency >= 3:  # Strong consistent momentum
            momentum_score += 35
            analysis['style_factors'].append("Strong consistent momentum")
            analysis['momentum_quality'] = 'High'
        elif abs(short_momentum) > 0.0005 and momentum_consistency >= 2:
            momentum_score += 20
            analysis['style_factors'].append("Good momentum consistency")
            analysis['momentum_quality'] = 'Medium'
        
        # 2. Enhanced RSI analysis with divergence detection
        rsi = indicators.get('rsi', 50)
        rsi_values = []
        
        # Calculate RSI for last few periods if possible
        try:
            if len(df) >= 20:
                for i in range(-5, 0):
                    temp_indicators = get_indicators(df.iloc[:len(df)+i])
                    if temp_indicators:
                        rsi_values.append(temp_indicators.get('rsi', 50))
                
                # Check for RSI divergence
                if len(rsi_values) >= 3:
                    try:
                        price_data = price_changes_1m.tail(3).values
                        rsi_data = rsi_values[-3:]
                        
                        if len(price_data) >= 2 and len(rsi_data) >= 2:
                            price_trend = np.polyfit(range(len(price_data)), price_data, 1)[0]
                            rsi_trend = np.polyfit(range(len(rsi_data)), rsi_data, 1)[0]
                        else:
                            price_trend = 0
                            rsi_trend = 0
                    except:
                        price_trend = 0
                        rsi_trend = 0
                    
                    # Hidden divergence (good for continuation)
                    if (price_trend > 0 and rsi_trend > 0) or (price_trend < 0 and rsi_trend < 0):
                        momentum_score += 15
                        analysis['style_factors'].append("RSI momentum alignment")
        except Exception:
            pass
        
        # RSI level analysis (more nuanced)
        if 20 <= rsi <= 35 or 65 <= rsi <= 80:  # Strong but not extreme
            momentum_score += 25
            analysis['style_factors'].append(f"RSI strong level: {rsi:.1f}")
        elif rsi < 20 or rsi > 80:  # Extreme levels (reversal risk)
            momentum_score += 10  # Lower bonus due to reversal risk
            analysis['style_factors'].append(f"RSI extreme level: {rsi:.1f} (reversal risk)")
        elif 40 <= rsi <= 60:  # Neutral zone - need other confirmations
            momentum_score += 5
            
        # 3. Enhanced MACD analysis with histogram
        macd_line = indicators.get('macd', 0)
        macd_signal = indicators.get('macd_signal', 0)
        macd_histogram = indicators.get('macd_histogram', 0)
        
        macd_diff = abs(macd_line - macd_signal)
        
        # MACD momentum and direction
        if macd_diff > 0.0015 and abs(macd_histogram) > 0.0008:  # Strong momentum with acceleration
            momentum_score += 30
            analysis['style_factors'].append("Strong MACD momentum with acceleration")
        elif macd_diff > 0.0008 and abs(macd_histogram) > 0.0004:
            momentum_score += 20
            analysis['style_factors'].append("Good MACD momentum")
        elif macd_diff > 0.0004:
            momentum_score += 10
            analysis['style_factors'].append("Moderate MACD momentum")
            
        # 4. Volume-based confirmation (using price action proxy)
        if len(df) >= 20:
            # Create volume proxy using candle body and wick analysis
            body_size = abs(df['close'] - df['open'])
            wick_size = (df['high'] - df['low']) - body_size
            volume_proxy = body_size + (wick_size * 0.3)  # Bodies matter more than wicks
            
            recent_volume = volume_proxy.tail(5).mean()
            avg_volume = volume_proxy.tail(20).mean()
            
            if recent_volume > avg_volume * 1.3:  # Strong volume surge
                momentum_score += 20
                analysis['style_factors'].append("Strong volume confirmation")
            elif recent_volume > avg_volume * 1.15:
                momentum_score += 10
                analysis['style_factors'].append("Volume increase detected")
        
        # 5. Price action pattern recognition
        try:
            last_3_candles = recent_candles.tail(3)
            
            # Engulfing patterns
            if len(last_3_candles) >= 2:
                prev_candle = last_3_candles.iloc[-2]
                curr_candle = last_3_candles.iloc[-1]
                
                # Bullish engulfing
                if (prev_candle['close'] < prev_candle['open'] and 
                    curr_candle['close'] > curr_candle['open'] and
                    curr_candle['close'] > prev_candle['open'] and
                    curr_candle['open'] < prev_candle['close']):
                    momentum_score += 15
                    analysis['style_factors'].append("Bullish engulfing pattern")
                
                # Bearish engulfing
                elif (prev_candle['close'] > prev_candle['open'] and 
                      curr_candle['close'] < curr_candle['open'] and
                      curr_candle['close'] < prev_candle['open'] and
                      curr_candle['open'] > prev_candle['close']):
                    momentum_score += 15
                    analysis['style_factors'].append("Bearish engulfing pattern")
            
            # Hammer/Doji patterns
            if len(last_3_candles) >= 1:
                curr_candle = last_3_candles.iloc[-1]
                body_size = abs(curr_candle['close'] - curr_candle['open'])
                candle_range = curr_candle['high'] - curr_candle['low']
                
                if candle_range > 0:
                    body_ratio = body_size / candle_range
                    
                    # Hammer/Shooting star detection
                    if body_ratio < 0.3:  # Small body
                        lower_wick = min(curr_candle['open'], curr_candle['close']) - curr_candle['low']
                        upper_wick = curr_candle['high'] - max(curr_candle['open'], curr_candle['close'])
                        
                        if lower_wick > body_size * 2 and upper_wick < body_size:  # Hammer
                            momentum_score += 10
                            analysis['style_factors'].append("Hammer pattern detected")
                        elif upper_wick > body_size * 2 and lower_wick < body_size:  # Shooting star
                            momentum_score += 10
                            analysis['style_factors'].append("Shooting star pattern")
        except Exception:
            pass
        
        # 6. Enhanced volatility analysis
        if len(df) >= 20:
            atr_14 = ((df['high'] - df['low']).tail(14).mean())
            atr_5 = ((df['high'] - df['low']).tail(5).mean())
            volatility_pct = (atr_14 / df['close'].iloc[-1]) * 100
            
            # Volatility expansion/contraction analysis
            volatility_ratio = atr_5 / atr_14 if atr_14 > 0 else 1
            
            if 0.6 <= volatility_pct <= 2.0 and 1.1 <= volatility_ratio <= 1.8:  # Optimal expanding volatility
                momentum_score += 25
                analysis['style_factors'].append("Optimal volatility expansion")
                analysis['optimal_conditions'] = True
            elif 0.8 <= volatility_pct <= 2.8 and volatility_ratio >= 1.05:
                momentum_score += 15
                analysis['style_factors'].append("Good volatility conditions")
            elif volatility_pct > 4.0:
                momentum_score -= 15
                analysis['style_factors'].append("Excessive volatility - high risk")
                analysis['risk_level'] = 'Very High'
            elif volatility_pct < 0.4:
                momentum_score -= 10
                analysis['style_factors'].append("Low volatility - poor scalping conditions")
                
        # 7. Enhanced session quality with news impact consideration
        current_hour = datetime.now(timezone.utc).hour
        current_minute = datetime.now(timezone.utc).minute
        
        # Premium sessions with minute-level precision
        if 13 <= current_hour <= 16:  # London-NY overlap
            if 0 <= current_minute <= 30:  # First half hour is typically strongest
                momentum_score += 20
                analysis['style_factors'].append("Premium session - peak activity")
            else:
                momentum_score += 15
                analysis['style_factors'].append("Premium session - London-NY overlap")
        elif current_hour in [8, 9, 14, 15, 21, 22]:  # Market open hours
            momentum_score += 12
            analysis['style_factors'].append("Market opening session")
        elif 8 <= current_hour <= 17 or 13 <= current_hour <= 22:
            momentum_score += 6
            analysis['style_factors'].append("Active trading session")
            
        # 8. Micro-trend analysis (very short-term trend strength)
        if len(recent_candles) >= 5:
            # Calculate micro-trend using linear regression on last 5 candles
            x_values = np.arange(len(recent_candles))
            slope, _ = np.polyfit(x_values, recent_candles['close'].values, 1)
            
            # Normalize slope relative to price
            normalized_slope = (slope / recent_candles['close'].iloc[-1]) * 100
            
            if abs(normalized_slope) > 0.05:  # Strong micro-trend
                momentum_score += 15
                analysis['micro_trend_score'] = abs(normalized_slope)
                analysis['style_factors'].append(f"Strong micro-trend detected")
            elif abs(normalized_slope) > 0.02:
                momentum_score += 8
                analysis['micro_trend_score'] = abs(normalized_slope)
                analysis['style_factors'].append("Moderate micro-trend")
        
        # Apply momentum quality assessment
        if momentum_score >= 80:
            analysis['momentum_quality'] = 'Excellent'
            analysis['style_multiplier'] = 1.20
        elif momentum_score >= 65:
            analysis['momentum_quality'] = 'High'
            analysis['style_multiplier'] = 1.15
        elif momentum_score >= 50:
            analysis['momentum_quality'] = 'Medium'
            analysis['style_multiplier'] = 1.08
        elif momentum_score >= 35:
            analysis['momentum_quality'] = 'Low'
            analysis['style_multiplier'] = 0.95
        else:
            analysis['momentum_quality'] = 'Poor'
            analysis['style_multiplier'] = 0.85
            
        analysis['style_confidence'] = min(100, momentum_score)
        
        return analysis

class SwingStyle(TradingStyle):
    """Optimized for 5-minute expiry - Balance of momentum and mean reversion"""
    
    def __init__(self):
        super().__init__(
            name="Swing Balance",
            expiry="5m", 
            description="Balanced approach using momentum and mean reversion"
        )
        self.min_confidence = 70
        
    def analyze(self, df: pd.DataFrame, indicators: dict, pair: str) -> dict:
        """5-minute swing analysis"""
        analysis = {
            'style_confidence': 0,
            'style_factors': [],
            'optimal_conditions': False,
            'risk_level': 'Medium',
            'style_multiplier': 1.0
        }
        
        if len(df) < 30:
            return analysis
            
        swing_score = 0
        
        # 1. Trend-following component
        if len(df) >= 50:
            ema_9 = df['close'].ewm(span=9).mean()
            ema_21 = df['close'].ewm(span=21).mean()
            
            if ema_9.iloc[-1] > ema_21.iloc[-1]:
                swing_score += 20
                analysis['style_factors'].append("Bullish EMA alignment")
            elif ema_9.iloc[-1] < ema_21.iloc[-1]:
                swing_score += 20
                analysis['style_factors'].append("Bearish EMA alignment")
                
        # 2. Mean reversion component
        rsi = indicators.get('rsi', 50)
        bb_upper = indicators.get('bb_upper', 0)
        bb_lower = indicators.get('bb_lower', 0)
        current_price = df['close'].iloc[-1]
        
        # Bollinger Band position
        if bb_upper > bb_lower:
            bb_position = (current_price - bb_lower) / (bb_upper - bb_lower)
            if bb_position <= 0.2 or bb_position >= 0.8:
                swing_score += 25
                analysis['style_factors'].append("Price at Bollinger Band extreme")
            elif bb_position <= 0.3 or bb_position >= 0.7:
                swing_score += 15
                analysis['style_factors'].append("Price approaching BB extreme")
                
        # 3. RSI confluence
        if 30 <= rsi <= 35 or 65 <= rsi <= 70:
            swing_score += 20
            analysis['style_factors'].append(f"RSI in optimal swing zone: {rsi:.1f}")
        elif rsi < 30 or rsi > 70:
            swing_score += 15
            analysis['style_factors'].append(f"RSI extreme for mean reversion: {rsi:.1f}")
            
        # 4. MACD trend confirmation
        macd = indicators.get('macd', 0)
        macd_signal = indicators.get('macd_signal', 0)
        
        if abs(macd - macd_signal) > 0.0005:
            swing_score += 15
            analysis['style_factors'].append("MACD trend confirmation")
            
        # 5. Stochastic confluence
        stoch_k = indicators.get('stoch_k', 50)
        if stoch_k < 25 or stoch_k > 75:
            swing_score += 15
            analysis['style_factors'].append(f"Stochastic extreme: {stoch_k:.1f}")
            
        # 6. Market structure alignment
        try:
            from main import analyze_market_structure
            structure_result = analyze_market_structure(df)
            if structure_result and len(structure_result) >= 2:
                trend = structure_result[0]
                if trend in ['Uptrend', 'Downtrend']:
                    swing_score += 20
                    analysis['style_factors'].append(f"Clear market structure: {trend}")
                    analysis['optimal_conditions'] = True
        except:
            pass
            
        analysis['style_confidence'] = min(100, swing_score)
        analysis['style_multiplier'] = 1.12 if swing_score >= 80 else 1.05 if swing_score >= 60 else 0.95
        
        return analysis

class TrendFollowingStyle(TradingStyle):
    """Optimized for 15-minute expiry - Strong trend following with confirmations"""
    
    def __init__(self):
        super().__init__(
            name="Trend Following",
            expiry="15m",
            description="Strong trend following with multiple confirmations"
        )
        self.min_confidence = 68
        
    def analyze(self, df: pd.DataFrame, indicators: dict, pair: str) -> dict:
        """15-minute trend following analysis"""
        analysis = {
            'style_confidence': 0,
            'style_factors': [],
            'optimal_conditions': False,
            'risk_level': 'Medium',
            'style_multiplier': 1.0
        }
        
        if len(df) < 50:
            return analysis
            
        trend_score = 0
        
        # 1. Multiple timeframe EMA alignment
        ema_9 = df['close'].ewm(span=9).mean()
        ema_21 = df['close'].ewm(span=21).mean()
        ema_50 = df['close'].ewm(span=50).mean()
        
        current_ema9 = ema_9.iloc[-1]
        current_ema21 = ema_21.iloc[-1]
        current_ema50 = ema_50.iloc[-1]
        
        # Perfect bullish alignment
        if current_ema9 > current_ema21 > current_ema50:
            trend_score += 35
            analysis['style_factors'].append("Perfect bullish EMA alignment")
            analysis['optimal_conditions'] = True
        # Perfect bearish alignment
        elif current_ema9 < current_ema21 < current_ema50:
            trend_score += 35
            analysis['style_factors'].append("Perfect bearish EMA alignment")
            analysis['optimal_conditions'] = True
        # Partial alignment
        elif current_ema9 > current_ema21 or current_ema9 < current_ema21:
            trend_score += 20
            analysis['style_factors'].append("Partial EMA alignment")
            
        # 2. MACD trend strength
        macd = indicators.get('macd', 0)
        macd_signal = indicators.get('macd_signal', 0)
        macd_diff = macd - macd_signal
        
        if abs(macd_diff) > 0.001:
            trend_score += 25
            direction = "bullish" if macd_diff > 0 else "bearish"
            analysis['style_factors'].append(f"Strong {direction} MACD trend")
        elif abs(macd_diff) > 0.0005:
            trend_score += 15
            analysis['style_factors'].append("Moderate MACD trend")
            
        # 3. ADX-like trend strength calculation
        if len(df) >= 20:
            high_low = df['high'] - df['low']
            high_close = np.abs(df['high'] - df['close'].shift())
            low_close = np.abs(df['low'] - df['close'].shift())
            true_range = pd.concat([high_low, high_close, low_close], axis=1).max(axis=1)
            
            # Directional movement
            dm_plus = np.where((df['high'] - df['high'].shift()) > (df['low'].shift() - df['low']),
                              np.maximum(df['high'] - df['high'].shift(), 0), 0)
            dm_minus = np.where((df['low'].shift() - df['low']) > (df['high'] - df['high'].shift()),
                               np.maximum(df['low'].shift() - df['low'], 0), 0)
            
            tr_smooth = pd.Series(true_range).rolling(window=14).mean()
            dm_plus_smooth = pd.Series(dm_plus).rolling(window=14).mean()
            dm_minus_smooth = pd.Series(dm_minus).rolling(window=14).mean()
            
            di_plus = 100 * (dm_plus_smooth / tr_smooth)
            di_minus = 100 * (dm_minus_smooth / tr_smooth)
            
            dx = 100 * np.abs(di_plus - di_minus) / (di_plus + di_minus)
            adx = dx.rolling(window=14).mean().iloc[-1]
            
            if adx > 30:
                trend_score += 25
                analysis['style_factors'].append(f"Strong trend strength (ADX: {adx:.1f})")
            elif adx > 20:
                trend_score += 15
                analysis['style_factors'].append(f"Moderate trend strength (ADX: {adx:.1f})")
                
        # 4. Price momentum consistency
        recent_closes = df['close'].tail(15)
        price_changes = recent_closes.pct_change().dropna()
        
        if len(price_changes) > 0:
            positive_changes = sum(1 for change in price_changes if change > 0)
            consistency_ratio = max(positive_changes, len(price_changes) - positive_changes) / len(price_changes)
            
            if consistency_ratio >= 0.75:
                trend_score += 20
                analysis['style_factors'].append("High price momentum consistency")
            elif consistency_ratio >= 0.65:
                trend_score += 12
                analysis['style_factors'].append("Good price momentum consistency")
                
        # 5. Volume trend confirmation (using price action proxy)
        if len(df) >= 20:
            volume_proxy = (df['high'] - df['low']) + abs(df['close'] - df['open'])
            recent_volume = safe_mean(volume_proxy.tail(10), 0.001)
            overall_volume = safe_mean(volume_proxy.tail(30), 0.001)
            
            if recent_volume > safe_divide(overall_volume * 1.2, 1, 0.001):
                trend_score += 15
                analysis['style_factors'].append("Volume confirms trend")
                
        analysis['style_confidence'] = min(100, trend_score)
        
        return analysis

class TradingStyleManager:
    """Manages different trading styles for different expiry times"""
    
    def __init__(self):
        self.styles = {
            '1m': ScalpingStyle(),
            '5m': SwingStyle(), 
            '15m': TrendFollowingStyle()
        }
        
    def get_style_for_expiry(self, expiry: str) -> Optional[TradingStyle]:
        """Get the optimal trading style for given expiry"""
        return self.styles.get(expiry)
        
    def analyze_with_style(self, df: pd.DataFrame, indicators: dict, expiry: str, pair: str) -> dict:
        """Analyze using the appropriate trading style"""
        style = self.get_style_for_expiry(expiry)
        if not style:
            return {
                'style_name': 'Default',
                'style_confidence': 0,
                'style_factors': ['No specific style for this expiry'],
                'style_multiplier': 1.0,
                'optimal_conditions': False
            }
            
        style_analysis = style.analyze(df, indicators, pair)
        style_analysis['style_name'] = style.name
        style_analysis['style_description'] = style.description
        
        return style_analysis
        
    def get_enhanced_confidence(self, base_confidence: float, style_analysis: dict) -> float:
        """Calculate enhanced confidence using style-specific analysis with conservative scaling"""
        style_multiplier = style_analysis.get('style_multiplier', 1.0)
        style_confidence = style_analysis.get('style_confidence', 0)
        
        # More conservative blending - prioritize base confidence
        enhanced_confidence = (base_confidence * 0.8) + (style_confidence * 0.2)
        
        # Apply conservative style multiplier (cap at 1.1 for safety)
        conservative_multiplier = min(1.1, style_multiplier)
        final_confidence = enhanced_confidence * conservative_multiplier
        
        # Very conservative caps - reaching 90%+ should be extremely rare
        if final_confidence >= 90:
            # Require exceptional conditions for 90%+
            if (style_analysis.get('optimal_conditions') and 
                style_confidence >= 85 and 
                base_confidence >= 85):
                return min(95, final_confidence)
            else:
                return min(95, final_confidence)
        
        return min(95, max(50, final_confidence))
        
    async def get_style_recommendations(self, df: pd.DataFrame, indicators: dict, pair: str) -> dict:
        """Get recommendations for which expiry time works best - now uses unified confidence system"""
        recommendations = {}

        for expiry, style in self.styles.items():
            try:
                # Get unified confidence for this expiry to ensure consistency
                from unified_confidence_system import get_recommendation_confidence
                unified_result = await get_recommendation_confidence(df, indicators, pair, expiry)
                
                # Get style analysis for factors and optimization data
                analysis = style.analyze(df, indicators, pair)
                
                recommendations[expiry] = {
                    'style_name': style.name,
                    'confidence': unified_result.get('confidence', 55),  # Use unified confidence
                    'optimal': analysis['optimal_conditions'],
                    'factors': analysis['style_factors'][:3],  # Top 3 factors
                    'risk_level': analysis['risk_level'],
                    'signal': unified_result.get('signal', 'NEUTRAL')  # Include signal for consistency
                }
            except Exception as e:
                print(f"Error analyzing style for {expiry}: {e}")
                # Fallback to basic analysis if unified system fails
                try:
                    analysis = style.analyze(df, indicators, pair)
                    recommendations[expiry] = {
                        'style_name': style.name,
                        'confidence': 55,  # Safe fallback
                        'optimal': analysis.get('optimal_conditions', False),
                        'factors': analysis.get('style_factors', [])[:3],
                        'risk_level': analysis.get('risk_level', 'medium'),
                        'signal': 'NEUTRAL'
                    }
                except:
                    continue

        # Sort by confidence (unified confidence values)
        sorted_recommendations = sorted(
            recommendations.items(), 
            key=lambda x: x[1]['confidence'],
            reverse=True
        )

        return {
            'best_expiry': sorted_recommendations[0][0] if sorted_recommendations else '5m',
            'all_styles': dict(sorted_recommendations),
            'recommendation_text': f"Best expiry: {sorted_recommendations[0][0]} ({sorted_recommendations[0][1]['style_name']})" if sorted_recommendations else "No clear recommendation"
            }

# Global instance
trading_style_manager = TradingStyleManager()

def calculate_risk_adjusted_metrics(df: pd.DataFrame, signal: str, confidence: float, pair: str) -> Dict[str, Any]:
    """Calculate comprehensive risk-adjusted metrics for trading signals"""
    try:
        if df.empty or len(df) < 20:
            return {
                'risk_grade': 'C',
                'risk_adjusted_confidence': confidence,
                'sharpe_ratio': 0.0,
                'max_drawdown': 15.0,
                'risk_reward_ratio': 1.0,
                'volatility_adjusted_returns': 0.0,
                'estimated_stop_loss_pips': 10.0,
                'estimated_take_profit_pips': 20.0
            }
        
        # Calculate returns
        returns = df['close'].pct_change().dropna()
        
        # Volatility-adjusted returns
        volatility = returns.std() * np.sqrt(252)  # Annualized volatility
        mean_return = returns.mean() * 252  # Annualized return
        volatility_adjusted_returns = mean_return / volatility if volatility > 0 else 0
        
        # Sharpe ratio calculation
        risk_free_rate = 0.02  # 2% risk-free rate
        sharpe_ratio = (mean_return - risk_free_rate) / volatility if volatility > 0 else 0
        
        # Maximum drawdown calculation
        cumulative_returns = (1 + returns).cumprod()
        rolling_max = cumulative_returns.expanding().max()
        drawdown = (cumulative_returns - rolling_max) / rolling_max
        max_drawdown = abs(drawdown.min()) * 100
        
        # ATR for stop loss and take profit estimation
        high_low = df['high'] - df['low']
        high_close = np.abs(df['high'] - df['close'].shift())
        low_close = np.abs(df['low'] - df['close'].shift())
        true_range = pd.concat([high_low, high_close, low_close], axis=1).max(axis=1)
        atr = true_range.rolling(window=14).mean().iloc[-1]
        
        # Convert ATR to pips (approximate)
        pip_value = 0.0001 if 'JPY' not in pair else 0.01
        atr_pips = atr / pip_value
        
        # Estimated stop loss and take profit
        estimated_stop_loss_pips = min(max(atr_pips * 1.5, 8), 25)  # 1.5x ATR, capped
        estimated_take_profit_pips = estimated_stop_loss_pips * 2  # 2:1 risk-reward
        
        # Risk-reward ratio
        risk_reward_ratio = estimated_take_profit_pips / estimated_stop_loss_pips
        
        # Risk grade calculation
        risk_score = 0
        
        # Sharpe ratio contribution (0-30 points)
        if sharpe_ratio > 1.5:
            risk_score += 30
        elif sharpe_ratio > 1.0:
            risk_score += 20
        elif sharpe_ratio > 0.5:
            risk_score += 10
        
        # Max drawdown contribution (0-25 points)
        if max_drawdown < 5:
            risk_score += 25
        elif max_drawdown < 10:
            risk_score += 15
        elif max_drawdown < 20:
            risk_score += 5
        
        # Volatility contribution (0-25 points)
        if volatility < 0.15:
            risk_score += 25
        elif volatility < 0.25:
            risk_score += 15
        elif volatility < 0.35:
            risk_score += 5
        
        # Risk-reward ratio contribution (0-20 points)
        if risk_reward_ratio >= 2.0:
            risk_score += 20
        elif risk_reward_ratio >= 1.5:
            risk_score += 10
        
        # Determine risk grade
        if risk_score >= 75:
            risk_grade = 'A'
        elif risk_score >= 60:
            risk_grade = 'B'
        elif risk_score >= 40:
            risk_grade = 'C'
        else:
            risk_grade = 'D'
        
        # Adjust confidence based on risk metrics
        risk_multiplier = {
            'A': 1.1,
            'B': 1.05,
            'C': 1.0,
            'D': 0.9
        }.get(risk_grade, 1.0)
        
        risk_adjusted_confidence = min(95, confidence * risk_multiplier)
        
        return {
            'risk_grade': risk_grade,
            'risk_adjusted_confidence': risk_adjusted_confidence,
            'sharpe_ratio': sharpe_ratio,
            'max_drawdown': max_drawdown,
            'risk_reward_ratio': risk_reward_ratio,
            'volatility_adjusted_returns': volatility_adjusted_returns,
            'estimated_stop_loss_pips': estimated_stop_loss_pips,
            'estimated_take_profit_pips': estimated_take_profit_pips,
            'volatility': volatility,
            'risk_score': risk_score
        }
    
    except Exception as e:
        print(f"Error calculating risk metrics: {e}")
        return {
            'risk_grade': 'C',
            'risk_adjusted_confidence': confidence,
            'sharpe_ratio': 0.0,
            'max_drawdown': 15.0,
            'risk_reward_ratio': 1.0,
            'volatility_adjusted_returns': 0.0,
            'estimated_stop_loss_pips': 10.0,
            'estimated_take_profit_pips': 20.0
        }

async def get_multi_timeframe_entry_signal(pair: str, analysis_expiry: str, signal_data: Dict[str, Any]) -> Dict[str, Any]:
    """Get enhanced signal using multi-timeframe analysis for better entry timing"""
    try:
        # Skip multi-timeframe for 1m expiry
        if analysis_expiry == '1m':
            return {
                'confidence': signal_data['confidence'],
                'entry_note': '1m uses single timeframe analysis'
            }
        
        # Map analysis expiry to entry timeframe - STANDARDIZED MAPPING (entry function)
        entry_timeframe_map = {
            '1m': None,     # 1m uses only 1m timeframe (no entry timeframe)
            '5m': '1min',   # 5m analysis -> 1m entry
            '15m': '5min',  # 15m analysis -> 5m entry
            '1h': '15min',  # 1h analysis -> 15m entry
            '4h': '1h',     # 4h analysis -> 1h entry
            '1d': '4h'      # 1d analysis -> 4h entry
        }
        
        entry_timeframe = entry_timeframe_map.get(analysis_expiry)
        if not entry_timeframe:
            return {
                'confidence': signal_data['confidence'],
                'entry_note': f'No entry timeframe mapping for {analysis_expiry}'
            }
        
        # Map to API intervals
        interval_map = {
            '1min': '1min',
            '5min': '5min',
            '15min': '15min',
            '1h': '1h',
            '4h': '4h'
        }
        
        entry_interval = interval_map.get(entry_timeframe)
        if not entry_interval:
            return {
                'confidence': signal_data['confidence'],
                'entry_note': f'Invalid entry timeframe: {entry_timeframe}'
            }
        
        # Fetch entry timeframe data
        entry_data = await fetch_batch_data([pair], entry_interval, 0, 100)
        
        if not entry_data or pair not in entry_data:
            return {
                'confidence': signal_data['confidence'],
                'entry_note': f'Failed to fetch {entry_timeframe} data'
            }
        
        entry_df = entry_data[pair]
        if entry_df is None or entry_df.empty:
            return {
                'confidence': signal_data['confidence'],
                'entry_note': f'No {entry_timeframe} data available'
            }
        
        # Calculate indicators for entry timeframe
        entry_indicators = get_indicators(entry_df)
        if not entry_indicators:
            return {
                'confidence': signal_data['confidence'],
                'entry_note': f'Failed to calculate {entry_timeframe} indicators'
            }
        
        # Get entry timeframe confidence (use a shorter expiry for entry TF)
        entry_expiry_map = {
            '1min': '1m',
            '5min': '5m',
            '15min': '15m',
            '1h': '1h',
            '4h': '4h'
        }
        entry_expiry = entry_expiry_map.get(entry_timeframe, '5m')
        
        entry_confidence_data = await calculate_overall_confidence(entry_df, entry_indicators, -1, pair, entry_expiry)
        entry_confidence = entry_confidence_data.get('confidence', 50)
        entry_signal = entry_confidence_data.get('signal', 'NEUTRAL')
        
        # Check signal alignment
        original_signal = signal_data['signal']
        signals_aligned = (original_signal == entry_signal) or (entry_signal == 'NEUTRAL' and entry_confidence < 60)
        
        # Calculate multi-timeframe alignment score
        alignment_score = 100 if signals_aligned else 30
        if signals_aligned and entry_confidence > 60:
            alignment_score = min(100, 70 + (entry_confidence - 60) * 0.75)
        
        # Determine entry quality
        if alignment_score >= 80 and entry_confidence >= 70:
            entry_quality = 'Excellent'
        elif alignment_score >= 60 and entry_confidence >= 60:
            entry_quality = 'Good'
        elif alignment_score >= 40:
            entry_quality = 'Moderate'
        else:
            entry_quality = 'Poor'
        
        # Calculate confidence adjustment
        original_confidence = signal_data['confidence']
        
        if signals_aligned:
            # Boost confidence for aligned signals
            if entry_confidence >= 70:
                confidence_adjustment = min(8, (entry_confidence - 70) * 0.2 + 3)
            elif entry_confidence >= 60:
                confidence_adjustment = min(5, (entry_confidence - 60) * 0.3 + 1)
            else:
                confidence_adjustment = 0
        else:
            # Reduce confidence for misaligned signals
            confidence_adjustment = -min(10, (70 - entry_confidence) * 0.15 + 2)
        
        # Apply conservative adjustment limits
        confidence_adjustment = max(-10, min(8, confidence_adjustment))
        final_confidence = max(50, min(95, original_confidence + confidence_adjustment))
        
        return {
            'confidence': final_confidence,
            'entry_timeframe': entry_timeframe,
            'entry_confidence': entry_confidence,
            'entry_signal': entry_signal,
            'entry_quality': entry_quality,
            'multi_timeframe_alignment': alignment_score,
            'confidence_adjustment': confidence_adjustment,
            'signals_aligned': signals_aligned
        }
    
    except Exception as e:
        print(f"Error in multi-timeframe entry analysis: {e}")
        return {
            'confidence': signal_data['confidence'],
            'entry_note': f'Multi-timeframe analysis error: {str(e)}'
        }

