class DataDeletionConfirmView(discord.ui.View):
    def __init__(self, user_id):
        super().__init__(timeout=300)
        self.user_id = user_id

    @discord.ui.button(label="❌ Cancel", style=discord.ButtonStyle.secondary)
    async def cancel_deletion(self, interaction: discord.Interaction, button: discord.ui.Button):
        embed = discord.Embed(
            title="✅ Data Deletion Cancelled",
            description="Your data has not been deleted and remains intact.",
            color=discord.Color.green()
        )
        await interaction.response.edit_message(embed=embed, view=None)

    @discord.ui.button(label="🗑️ Confirm Delete", style=discord.ButtonStyle.danger)
    async def confirm_deletion(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        
        try:
            # Delete from JSON user data
            user_data = load_user_data()
            
            # Remove user from all data structures
            user_id_str = str(self.user_id)
            if user_id_str in user_data.get("custom_styles", {}):
                del user_data["custom_styles"][user_id_str]
            if user_id_str in user_data.get("user_authorization", {}):
                del user_data["user_authorization"][user_id_str]
            if user_id_str in user_data.get("user_verification", {}):
                del user_data["user_verification"][user_id_str]
            if user_id_str in user_data.get("blacklisted_users", []):
                user_data["blacklisted_users"].remove(user_id_str)
            if user_id_str in user_data.get("user_quotas", {}):
                del user_data["user_quotas"][user_id_str]
            if user_id_str in user_data.get("user_recommendations", {}):
                del user_data["user_recommendations"][user_id_str]
            
            save_user_data(user_data)
            
            # Delete from SQLite database
            conn = sqlite3.connect('signals.db')
            c = conn.cursor()
            
            # Delete user settings
            c.execute("DELETE FROM user_settings WHERE user_id = ?", (user_id_str,))
            
            # Delete user profiles
            c.execute("DELETE FROM user_profiles WHERE user_id = ?", (user_id_str,))
            
            # Delete user alerts
            c.execute("DELETE FROM user_alerts WHERE user_id = ?", (user_id_str,))
            
            # Delete alert history
            c.execute("DELETE FROM alert_history WHERE user_id = ?", (user_id_str,))
            
            conn.commit()
            conn.close()
            
            # Clear from memory caches
            if self.user_id in user_cooldowns:
                del user_cooldowns[self.user_id]
            if self.user_id in command_history:
                del command_history[self.user_id]
            if self.user_id in rapid_command_violations:
                del rapid_command_violations[self.user_id]
            if self.user_id in pending_captchas:
                del pending_captchas[self.user_id]
            if self.user_id in user_fingerprints:
                del user_fingerprints[self.user_id]
            
            embed = discord.Embed(
                title="✅ Data Successfully Deleted",
                description="All your data has been permanently removed from our systems.\n\nThis includes:\n• Trading preferences and settings\n• Alert history and active alerts\n• Usage statistics and profile data\n• Custom styles and recommendations",
                color=discord.Color.green()
            )
            embed.add_field(
                name="🔄 Fresh Start",
                value="You can continue using the bot and your data will be recreated as needed.",
                inline=False
            )
            
            await interaction.followup.edit_message(message_id=interaction.message.id, embed=embed, view=None)
            
        except Exception as e:
            print(f"Error deleting user data: {e}")
            embed = discord.Embed(
                title="❌ Deletion Failed",
                description="An error occurred while deleting your data. Please try again or contact support.",
                color=discord.Color.red()
            )
            await interaction.followup.edit_message(message_id=interaction.message.id, embed=embed, view=None)

