class AlertModal(discord.ui.Modal, title="Create Enhanced Price Alert"):
    def __init__(self, pair):
        super().__init__()
        self.pair = pair

    alert_name = discord.ui.TextInput(
        label="Alert Name (Optional)",
        placeholder="e.g., 'EUR/USD Resistance Break'",
        required=False,
        max_length=50
    )

    price_input = discord.ui.TextInput(
        label="Target Price",
        placeholder="Enter target price (e.g., 1.0850)",
        required=True,
        max_length=10
    )

    condition_input = discord.ui.TextInput(
        label="Condition (above/below)",
        placeholder="above or below",
        required=True,
        max_length=5
    )

    expiry_input = discord.ui.TextInput(
        label="Expiry Hours (Optional)",
        placeholder="e.g., 24 (leave empty for no expiry)",
        required=False,
        max_length=3
    )

    async def on_submit(self, interaction: discord.Interaction):
        try:
            target_price = float(self.price_input.value)
            condition = self.condition_input.value.lower().strip()
            
            if condition not in ['above', 'below']:
                raise ValueError("Invalid condition")
            
            alert_name = self.alert_name.value.strip() if self.alert_name.value else None
            expiry_hours = None
            
            if self.expiry_input.value.strip():
                expiry_hours = int(self.expiry_input.value)
                if expiry_hours <= 0 or expiry_hours > 168:  # Max 1 week
                    raise ValueError("Expiry must be 1-168 hours")
            
            user_id = str(interaction.user.id)
            success, message = add_user_alert(user_id, self.pair, 'price', target_price, condition, alert_name, expiry_hours)
            
            if success:
                embed = discord.Embed(
                    title="🔔 Enhanced Alert Created",
                    description=f"**{alert_name or f'{self.pair} Alert'}**\nWill notify when {self.pair} goes {condition} {target_price:.5f}",
                    color=discord.Color.green()
                )
                
                if expiry_hours:
                    expiry_time = datetime.now(timezone.utc) + timedelta(hours=expiry_hours)
                    embed.add_field(name="⏰ Expires", value=f"<t:{int(expiry_time.timestamp())}:R>", inline=True)
                
                embed.add_field(name="📊 Alert ID", value=message.split(": ")[1], inline=True)
            else:
                embed = discord.Embed(
                    title="❌ Alert Creation Failed",
                    description=message,
                    color=discord.Color.red()
                )
                
        except ValueError as e:
            embed = discord.Embed(
                title="❌ Invalid Input",
                description=f"Error: {str(e)}",
                color=discord.Color.red()
            )
        
        await interaction.response.send_message(embed=embed, ephemeral=True)

