class RecommendationToggle(discord.ui.Button):
    def __init__(self, current_state):
        style = discord.ButtonStyle.success if current_state else discord.ButtonStyle.secondary
        label = "🎯 Recommendations ON" if current_state else "🎯 Recommendations OFF"
        super().__init__(style=style, label=label)
        self.current_state = current_state

    async def callback(self, interaction: discord.Interaction):
        # Check freemium limit before enabling recommendations
        user_id = interaction.user.id
        
        if not self.current_state:  # User wants to turn recommendations ON
            # Check if freemium user has exceeded daily limit
            if not is_user_premium(str(user_id)):
                limit_exceeded, current_count = check_freemium_recommendation_limit(user_id)
                if limit_exceeded:
                    # Don't allow enabling recommendations if limit exceeded
                    embed = discord.Embed(
                        title="📊 Daily Recommendation Limit Reached",
                        description="You've used your 1 daily recommendation as a free user. Upgrade to Premium for unlimited recommendations!",
                        color=discord.Color.orange()
                    )
                    await interaction.response.send_message(embed=embed, ephemeral=True)
                    return
        
        # Toggle state
        self.current_state = not self.current_state

        # Update button appearance
        if self.current_state:
            self.style = discord.ButtonStyle.success
            self.label = "🎯 Recommendations ON"
        else:
            self.style = discord.ButtonStyle.secondary
            self.label = "🎯 Recommendations OFF"

        # Update the view
        view = self.view
        view.show_recommendation = self.current_state

        # Get the current embed
        embed = interaction.message.embeds[0]

        # Get original field count from view
        original_field_count = getattr(view, 'original_field_count', 5)

        # Add or remove recommendation field
        if self.current_state:
            # Remove any existing recommendation fields first
            while len(embed.fields) > original_field_count:
                embed.remove_field(-1)
            
            # Add loading message for recommendation
            embed.add_field(name="🎯 Getting Recommendation...", value="Analyzing top pairs...", inline=False)
            await interaction.response.edit_message(embed=embed, view=view)

            try:
                # Get both types of recommendations with user context and timeout protection
                user_id = str(interaction.user.id)
                recommendations = await asyncio.wait_for(
                    get_multiple_recommendations(view.expiry, view.mode, user_id=user_id),
                    timeout=90.0  # 90 second timeout for entire recommendation process with 16 pairs
                )

                # Update embed with recommendations
                # Remove the loading field
                embed.remove_field(-1)

                if recommendations:
                    # Check if this is a freemium limit response
                    if recommendations.get('freemium_limit'):
                        embed.add_field(name="🎯 Pair Recommendations", value=recommendations['message'], inline=False)
                    else:
                        rec_text = ""
                        
                        # Show single recommended pair (simplified display) with safe access
                        if 'optimal' in recommendations and recommendations['optimal'] and isinstance(recommendations['optimal'], dict):
                            optimal = recommendations['optimal']
                            
                            # Validate required fields exist
                            if 'pair' in optimal and optimal['pair']:
                                # Check if this exceeds user preference
                                preference_indicator = ""
                                if optimal.get('exceeds_user_preference'):
                                    advantage = optimal.get('confidence_advantage', 0)
                                    preference_indicator = f" ⬆️ (+{advantage:.1f}% above your {optimal.get('user_min_confidence', 70)}% preference)"
                                
                                rec_text += f"**🎯 RECOMMENDED PAIR:**\n"
                                rec_text += f"**{optimal['pair']}**{preference_indicator}\n"
                                rec_text += f"💰 Price: {optimal.get('price', 0):.5f} | 📊 Quality: {optimal.get('quality_score', 0):.0f}/100\n"
                                rec_text += f"📈 Trend: {optimal.get('trend_quality', 'Unknown')} | ⭐ Strength: {optimal.get('strength_score', 0):.0f}/100\n"
                                
                                if optimal.get('confidence_tier'):
                                    rec_text += f"🏆 Confidence: {optimal['confidence_tier']}\n"
                            else:
                                rec_text += f"**🎯 RECOMMENDATION STATUS:**\nAnalysis completed but no pair data available.\n"
                        
                        # Add general market condition info
                        if recommendations.get('optimal', {}).get('market_conditions'):
                            key_conditions = recommendations['optimal']['market_conditions'][:2]
                            if key_conditions:
                                rec_text += f"\n✅ Market: {' | '.join(key_conditions)}"
                        
                        embed.add_field(name="🎯 AI-Powered Recommendations", value=rec_text, inline=False)
                        
                        # Increment the recommendation count for free users after successful delivery
                        increment_freemium_recommendation(user_id)
                else:
                    embed.add_field(name="🎯 Recommendations", value="No strong signals found in analyzed pairs. Market may be in consolidation.", inline=False)

                await interaction.edit_original_response(embed=embed, view=view)
            except asyncio.TimeoutError:
                print("Recommendation system timed out in UI layer")
                # Remove loading field and show timeout-specific error
                if len(embed.fields) > original_field_count:
                    embed.remove_field(-1)
                embed.add_field(name="🎯 Recommendations", value="Analysis is taking longer than usual. Please try again in a moment.", inline=False)
                await interaction.edit_original_response(embed=embed, view=view)
            except Exception as e:
                print(f"Error getting recommendations: {e}")
                # Remove loading field and show error
                if len(embed.fields) > original_field_count:
                    embed.remove_field(-1)
                embed.add_field(name="🎯 Recommendations", value="Unable to fetch recommendations at this time", inline=False)
                await interaction.edit_original_response(embed=embed, view=view)
        else:
            # Remove any recommendation fields to restore original state
            while len(embed.fields) > original_field_count:
                embed.remove_field(-1)

            await interaction.response.edit_message(embed=embed, view=view)

