def calculate_enhanced_strength(df, indicators, confidence_data, market_quality):
    """Calculate enhanced strength score for recommendation ranking"""
    try:
        strength_score = 0
        
        # 1. Technical indicator strength (30 points max)
        rsi = indicators.get('rsi', 50)
        macd_diff = indicators.get('macd', 0) - indicators.get('macd_signal', 0)
        stoch = indicators.get('stoch_k', 50)
        
        # RSI extremes
        if rsi <= 20 or rsi >= 80:
            strength_score += 15
        elif rsi <= 30 or rsi >= 70:
            strength_score += 10
        elif rsi <= 35 or rsi >= 65:
            strength_score += 5
        
        # MACD momentum
        if abs(macd_diff) > 0.002:
            strength_score += 10
        elif abs(macd_diff) > 0.001:
            strength_score += 6
        elif abs(macd_diff) > 0.0005:
            strength_score += 3
        
        # Stochastic momentum
        if stoch <= 15 or stoch >= 85:
            strength_score += 5
        elif stoch <= 25 or stoch >= 75:
            strength_score += 3
        
        # 2. Market structure strength (25 points max)
        try:
            structure_result = analyze_market_structure(df)
            if structure_result and len(structure_result) >= 2:
                trend = structure_result[0]
                if trend == "Uptrend":
                    strength_score += 20
                elif trend == "Downtrend":
                    strength_score += 20
                elif trend == "Consolidation":
                    strength_score += 8
        except Exception:
            pass
        
        # 3. Volatility quality (15 points max)
        volatility_score = market_quality.get('volatility', 1.0)
        if 0.8 <= volatility_score <= 2.0:
            strength_score += 15
        elif 0.5 <= volatility_score <= 2.5:
            strength_score += 10
        elif 0.3 <= volatility_score <= 3.0:
            strength_score += 5
        
        # 4. Trend consistency (15 points max)
        if len(df) >= 20:
            recent_closes = df['close'].tail(15)
            price_changes = recent_closes.pct_change().dropna()
            
            if len(price_changes) > 0:
                positive_changes = sum(1 for change in price_changes if change > 0)
                consistency_ratio = max(positive_changes, len(price_changes) - positive_changes) / len(price_changes)
                
                if consistency_ratio >= 0.80:
                    strength_score += 15
                elif consistency_ratio >= 0.70:
                    strength_score += 10
                elif consistency_ratio >= 0.60:
                    strength_score += 6
        
        # 5. Confluence bonus (15 points max)
        confluence_factors = confidence_data.get('confluence_factors', 0)
        if confluence_factors >= 5:
            strength_score += 15
        elif confluence_factors >= 4:
            strength_score += 12
        elif confluence_factors >= 3:
            strength_score += 8
        elif confluence_factors >= 2:
            strength_score += 4
        
        return min(100, strength_score)
        
    except Exception as e:
        print(f"Error calculating enhanced strength: {e}")
        return 50  # Return moderate score on error

def analyze_htf_confluence(htf_signals, current_signal):
    """Analyze higher timeframe confluence for signal confirmation"""
    if not htf_signals or current_signal == "NEUTRAL":
        return {'alignment': 'None', 'score': 0, 'details': []}
    
    alignment_score = 0
    details = []
    
    # Check signal alignment
    aligned_signals = 0
    total_htf_signals = 0
    
    for timeframe, htf_data in htf_signals.items():
        if htf_data['signal'] != "NEUTRAL":
            total_htf_signals += 1
            if htf_data['signal'] == current_signal:
                aligned_signals += 1
                alignment_score += 10
                details.append(f"{timeframe} confirms {current_signal}")
            else:
                alignment_score -= 5
                details.append(f"{timeframe} conflicts ({htf_data['signal']})")
    
    # Check trend alignment
    for timeframe, htf_data in htf_signals.items():
        trend = htf_data.get('trend', 'Consolidation')
        if current_signal == "BUY" and trend == "Uptrend":
            alignment_score += 8
            details.append(f"{timeframe} uptrend supports BUY")
        elif current_signal == "SELL" and trend == "Downtrend":
            alignment_score += 8
            details.append(f"{timeframe} downtrend supports SELL")
        elif trend in ["Uptrend", "Downtrend"]:
            alignment_score -= 3
            details.append(f"{timeframe} trend conflicts")
    
    # Determine alignment quality
    if total_htf_signals > 0:
        alignment_ratio = aligned_signals / total_htf_signals
        if alignment_ratio >= 0.75:
            alignment = "Strong"
        elif alignment_ratio >= 0.5:
            alignment = "Moderate" 
        else:
            alignment = "Weak"
    else:
        alignment = "None"
    
    return {
        'alignment': alignment,
        'score': max(-20, min(30, alignment_score)),  # Cap between -20 and +30
        'details': details[:3],  # Limit to top 3 details
        'aligned_signals': aligned_signals,
        'total_htf_signals': total_htf_signals
    }

# Cryptocurrency Analysis Functions
def calculate_crypto_tp_sl(df, signal, price, indicators):
    """Calculate Take Profit and Stop Loss levels for cryptocurrency trading"""
    tp_levels = []
    sl_level = None
    
    # Calculate ATR for volatility-based TP/SL
    if len(df) >= 14:
        high_low = df['high'] - df['low']
        high_close = np.abs(df['high'] - df['close'].shift())
        low_close = np.abs(df['low'] - df['close'].shift())
        true_range = pd.concat([high_low, high_close, low_close], axis=1).max(axis=1)
        atr = true_range.rolling(window=14).mean().iloc[-1]
    else:
        atr = price * 0.02  # 2% fallback
    
    # Support/Resistance based TP/SL
    sr_levels = detect_support_resistance(df)
    
    if signal == "BUY":
        # Stop Loss: BELOW entry price (price - atr)
        sl_atr = price - (atr * 2)
        sl_support = None
        
        if sr_levels.get('levels'):
            for level in sr_levels['levels']:
                if level['type'] == 'Support' and level['level'] < price:
                    sl_support = level['level'] - (atr * 0.2)  # Slightly below support
                    break
        
        # Use the higher of the two (closer to entry) for better risk management
        sl_level = max(sl_atr, sl_support) if sl_support else sl_atr
        
        # Take Profit levels: ABOVE entry price (price + atr)
        tp1 = price + (atr * 1.5)  # Conservative TP
        tp2 = price + (atr * 2.5)  # Moderate TP
        tp3 = price + (atr * 4)    # Aggressive TP
        
        # Adjust TP based on resistance levels - don't go beyond strong resistance
        if sr_levels.get('levels'):
            for level in sr_levels['levels']:
                if level['type'] == 'Resistance' and level['level'] > price:
                    resistance = level['level']
                    # Adjust TPs to be just below resistance
                    if tp1 > resistance * 0.995:
                        tp1 = resistance * 0.995
                    if tp2 > resistance * 0.995:
                        tp2 = resistance * 0.995
                    if tp3 > resistance * 0.995:
                        tp3 = resistance * 0.995
                    break
        
        # Ensure TPs are properly ordered and above entry
        tp1 = max(tp1, price + (atr * 0.8))  # Minimum TP1
        tp2 = max(tp2, tp1 + (atr * 0.5))    # TP2 above TP1
        tp3 = max(tp3, tp2 + (atr * 0.5))    # TP3 above TP2
        
        tp_levels = [
            {'level': tp1, 'percentage': ((tp1 - price) / price) * 100, 'type': 'Conservative'},
            {'level': tp2, 'percentage': ((tp2 - price) / price) * 100, 'type': 'Moderate'},
            {'level': tp3, 'percentage': ((tp3 - price) / price) * 100, 'type': 'Aggressive'}
        ]
    
    elif signal == "SELL":
        # Stop Loss: ABOVE entry price (price + atr)
        sl_atr = price + (atr * 2)
        sl_resistance = None
        
        if sr_levels.get('levels'):
            for level in sr_levels['levels']:
                if level['type'] == 'Resistance' and level['level'] > price:
                    sl_resistance = level['level'] + (atr * 0.2)  # Slightly above resistance
                    break
        
        # Use the lower of the two (closer to entry) for better risk management
        sl_level = min(sl_atr, sl_resistance) if sl_resistance else sl_atr
        
        # Take Profit levels: BELOW entry price (price - atr)
        tp1 = price - (atr * 1.5)  # Conservative TP
        tp2 = price - (atr * 2.5)  # Moderate TP
        tp3 = price - (atr * 4)    # Aggressive TP
        
        # Adjust TP based on support levels - don't go beyond strong support
        if sr_levels.get('levels'):
            for level in sr_levels['levels']:
                if level['type'] == 'Support' and level['level'] < price:
                    support = level['level']
                    # Adjust TPs to be just above support
                    if tp1 < support * 1.005:
                        tp1 = support * 1.005
                    if tp2 < support * 1.005:
                        tp2 = support * 1.005
                    if tp3 < support * 1.005:
                        tp3 = support * 1.005
                    break
        
        # Ensure TPs are properly ordered and below entry
        tp1 = min(tp1, price - (atr * 0.8))  # Minimum TP1
        tp2 = min(tp2, tp1 - (atr * 0.5))    # TP2 below TP1
        tp3 = min(tp3, tp2 - (atr * 0.5))    # TP3 below TP2
        
        # Ensure no negative prices
        tp1 = max(tp1, price * 0.1)
        tp2 = max(tp2, price * 0.1)
        tp3 = max(tp3, price * 0.1)
        
        tp_levels = [
            {'level': tp1, 'percentage': ((price - tp1) / price) * 100, 'type': 'Conservative'},
            {'level': tp2, 'percentage': ((price - tp2) / price) * 100, 'type': 'Moderate'},
            {'level': tp3, 'percentage': ((price - tp3) / price) * 100, 'type': 'Aggressive'}
        ]
    
    sl_percentage = abs(((sl_level - price) / price) * 100) if sl_level else 0
    
    return {
        'take_profits': tp_levels,
        'stop_loss': {
            'level': sl_level,
            'percentage': sl_percentage
        }
    }

def analyze_crypto_market_structure(df):
    """Advanced market structure analysis for cryptocurrency"""
    if len(df) < 20:
        return {'structure': 'Unknown', 'trend_strength': 0, 'key_levels': []}
    
    # Identify key swing points
    swing_highs = []
    swing_lows = []
    
    for i in range(5, len(df) - 5):
        # More sensitive swing detection for crypto volatility
        if (df['high'].iloc[i] == df['high'].iloc[i-5:i+6].max()):
            swing_highs.append({'index': i, 'price': df['high'].iloc[i]})
        
        if (df['low'].iloc[i] == df['low'].iloc[i-5:i+6].min()):
            swing_lows.append({'index': i, 'price': df['low'].iloc[i]})
    
    # Determine market structure
    structure = "Consolidation"
    trend_strength = 0
    
    if len(swing_highs) >= 2 and len(swing_lows) >= 2:
        recent_highs = swing_highs[-2:]
        recent_lows = swing_lows[-2:]
        
        # Higher highs and higher lows
        if (recent_highs[1]['price'] > recent_highs[0]['price'] and 
            recent_lows[1]['price'] > recent_lows[0]['price']):
            structure = "Bullish Structure"
            trend_strength = 75
        # Lower highs and lower lows
        elif (recent_highs[1]['price'] < recent_highs[0]['price'] and 
              recent_lows[1]['price'] < recent_lows[0]['price']):
            structure = "Bearish Structure"
            trend_strength = 75
        # Mixed signals
        else:
            structure = "Choppy/Ranging"
            trend_strength = 25
    
    # Key levels for crypto trading
    key_levels = []
    
    # Recent significant highs and lows
    if swing_highs:
        recent_high = max(swing_highs[-3:], key=lambda x: x['price'])
        key_levels.append({
            'level': recent_high['price'],
            'type': 'Major Resistance',
            'strength': 'High'
        })
    
    if swing_lows:
        recent_low = min(swing_lows[-3:], key=lambda x: x['price'])
        key_levels.append({
            'level': recent_low['price'],
            'type': 'Major Support',
            'strength': 'High'
        })
    
    # Psychological levels (round numbers)
    current_price = df['close'].iloc[-1]
    if current_price > 1:
        # Find nearest round numbers
        if current_price > 100:
            round_level = round(current_price / 100) * 100
        elif current_price > 10:
            round_level = round(current_price / 10) * 10
        else:
            round_level = round(current_price)
        
        key_levels.append({
            'level': round_level,
            'type': 'Psychological Level',
            'strength': 'Medium'
        })
    
    return {
        'structure': structure,
        'trend_strength': trend_strength,
        'key_levels': key_levels,
        'swing_highs': swing_highs[-3:],
        'swing_lows': swing_lows[-3:]
    }

def analyze_crypto_volume_profile(df):
    """Volume profile analysis for cryptocurrency (using price action as proxy)"""
    if len(df) < 30:
        return {}
    
    # Use price range and body size as volume proxy for crypto
    df_copy = df.copy()
    df_copy['volume_proxy'] = (df_copy['high'] - df_copy['low']) + abs(df_copy['close'] - df_copy['open'])
    
    # Price levels with highest activity
    price_levels = {}
    recent_data = df_copy.tail(50)
    
    for _, row in recent_data.iterrows():
        price_range = row['high'] - row['low']
        if price_range > 0:
            # Distribute volume across price range
            step = price_range / 10
            for i in range(10):
                level = row['low'] + (i * step)
                level = round(level, 5)
                if level not in price_levels:
                    price_levels[level] = 0
                price_levels[level] += row['volume_proxy'] / 10
    
    # Find high volume nodes
    sorted_levels = sorted(price_levels.items(), key=lambda x: x[1], reverse=True)
    
    return {
        'high_volume_nodes': sorted_levels[:5],
        'value_area_high': sorted_levels[0][0] if sorted_levels else df['close'].iloc[-1],
        'value_area_low': sorted_levels[-1][0] if sorted_levels else df['close'].iloc[-1],
        'point_of_control': sorted_levels[0][0] if sorted_levels else df['close'].iloc[-1]
    }

def detect_crypto_patterns(df):
    """Cryptocurrency-specific pattern detection"""
    patterns = {}
    
    if len(df) < 20:
        return patterns
    
    # Crypto-specific patterns
    
    # 1. Pump and Dump detection
    recent_changes = df['close'].pct_change().tail(10)
    max_change = recent_changes.max()
    min_change = recent_changes.min()
    
    if max_change > 0.15:  # 15% spike
        patterns['pump_detected'] = {
            'type': 'Potential Pump',
            'magnitude': max_change * 100,
            'warning': 'High volatility - exercise caution'
        }
    
    if min_change < -0.15:  # 15% drop
        patterns['dump_detected'] = {
            'type': 'Potential Dump',
            'magnitude': abs(min_change) * 100,
            'warning': 'Sharp decline detected'
        }
    
    # 2. Accumulation/Distribution phases
    price_std = df['close'].tail(20).std()
    price_mean = df['close'].tail(20).mean()
    current_price = df['close'].iloc[-1]
    
    if price_std / price_mean < 0.05:  # Low volatility
        patterns['accumulation_phase'] = {
            'type': 'Potential Accumulation',
            'description': 'Low volatility consolidation',
            'implication': 'Possible breakout incoming'
        }
    
    # 3. Breakout patterns
    recent_high = df['high'].tail(20).max()
    recent_low = df['low'].tail(20).min()
    
    if current_price > recent_high * 0.999:
        patterns['upside_breakout'] = {
            'type': 'Upside Breakout',
            'level': recent_high,
            'strength': 'High'
        }
    
    if current_price < recent_low * 1.001:
        patterns['downside_breakout'] = {
            'type': 'Downside Breakout',
            'level': recent_low,
            'strength': 'High'
        }
    
    return patterns


