class AboutView(discord.ui.View):
    """Paginated view for bot information"""
    
    def __init__(self):
        super().__init__(timeout=300)  # 5 minute timeout
        self.current_page = 0
        self.pages = [
            self.create_overview_page,
            self.create_features_page,
            self.create_technology_page,
            self.create_trading_styles_page,
            self.create_commands_page,
            self.create_disclaimer_page
        ]
        self.page_titles = [
            "🏠 Overview",
            "⚡ Features", 
            "🔬 Technology",
            "🎨 Trading Styles",
            "📋 Commands",
            "⚠️ Disclaimer"
        ]
        self.update_buttons()
    
    def update_buttons(self):
        """Update button states based on current page"""
        # Clear all buttons first
        self.clear_items()
        
        # Add navigation buttons
        if len(self.pages) > 1:
            # Previous button
            prev_button = discord.ui.Button(
                label="◀️ Previous",
                style=discord.ButtonStyle.secondary,
                disabled=self.current_page == 0
            )
            prev_button.callback = self.previous_page
            self.add_item(prev_button)
            
            # Page indicator
            page_button = discord.ui.Button(
                label=f"{self.current_page + 1}/{len(self.pages)}",
                style=discord.ButtonStyle.primary,
                disabled=True
            )
            self.add_item(page_button)
            
            # Next button
            next_button = discord.ui.Button(
                label="Next ▶️",
                style=discord.ButtonStyle.secondary,
                disabled=self.current_page == len(self.pages) - 1
            )
            next_button.callback = self.next_page
            self.add_item(next_button)
        
        # Add quick navigation buttons for specific pages
        if self.current_page != 0:  # Home button (except on home page)
            home_button = discord.ui.Button(
                label="🏠 Home",
                style=discord.ButtonStyle.success,
                row=1
            )
            home_button.callback = self.go_home
            self.add_item(home_button)
        
        if self.current_page != 1:  # Features button
            features_button = discord.ui.Button(
                label="⚡ Features",
                style=discord.ButtonStyle.success,
                row=1
            )
            features_button.callback = self.go_features
            self.add_item(features_button)
        
        if self.current_page != 2:  # Technology button
            tech_button = discord.ui.Button(
                label="🔬 Tech",
                style=discord.ButtonStyle.success,
                row=1
            )
            tech_button.callback = self.go_technology
            self.add_item(tech_button)
        
        if self.current_page != 3:  # Trading Styles button
            styles_button = discord.ui.Button(
                label="🎨 Styles",
                style=discord.ButtonStyle.success,
                row=1
            )
            styles_button.callback = self.go_styles
            self.add_item(styles_button)
    
    async def previous_page(self, interaction: discord.Interaction):
        if self.current_page > 0:
            self.current_page -= 1
            await self.update_page(interaction)
    
    async def next_page(self, interaction: discord.Interaction):
        if self.current_page < len(self.pages) - 1:
            self.current_page += 1
            await self.update_page(interaction)
    
    async def go_home(self, interaction: discord.Interaction):
        self.current_page = 0
        await self.update_page(interaction)
    
    async def go_features(self, interaction: discord.Interaction):
        self.current_page = 1
        await self.update_page(interaction)
    
    async def go_technology(self, interaction: discord.Interaction):
        self.current_page = 2
        await self.update_page(interaction)
    
    async def go_styles(self, interaction: discord.Interaction):
        self.current_page = 3
        await self.update_page(interaction)
    
    async def update_page(self, interaction: discord.Interaction):
        """Update the embed and view for the current page"""
        embed = self.pages[self.current_page]()
        self.update_buttons()
        await interaction.response.edit_message(embed=embed, view=self)
    
