@bot.tree.command(name="about", description="Learn everything about this advanced trading bot")
async def about_command(interaction: discord.Interaction):
    """Comprehensive bot information with paginated interface"""
    try:
        view = AboutView()
        embed = view.create_overview_page()
        await interaction.response.send_message(embed=embed, view=view, ephemeral=True)
    except Exception as e:
        print(f"Error in about command: {e}")
        error_embed = discord.Embed(
            title="❌ Error",
            description="An error occurred while loading bot information. Please try again.",
            color=discord.Color.red()
        )
        try:
            if not interaction.response.is_done():
                await interaction.response.send_message(embed=error_embed, ephemeral=True)
            else:
                await interaction.followup.send(embed=error_embed, ephemeral=True)
        except:
            pass
            

