@bot.tree.command(name="signal", description="Get enhanced trading signals with optimized styles for each expiry")
@app_commands.describe(
    expiry="Signal expiry time (uses your preferred setting if not specified)",
    mode="Signal generation mode",
    show_style_analysis="Show detailed trading style analysis"
)
@app_commands.choices(expiry=[
    app_commands.Choice(name="1 Minute (Scalping Style)", value="1m"),
    app_commands.Choice(name="5 Minutes (Swing Style)", value="5m"),
    app_commands.Choice(name="15 Minutes (Trend Following)", value="15m")
])
@app_commands.choices(mode=[
    app_commands.Choice(name="Real-time", value="realtime"),
    app_commands.Choice(name="Historical", value="historical")
])
async def enhanced_signal_command(interaction: discord.Interaction, expiry: str = None, mode: str = "realtime", show_style_analysis: bool = True):
    try:
        user_id = interaction.user.id
        guild_id = interaction.guild_id if interaction.guild else None
        
        # Check response targeting first
        if not check_response_targeting(interaction):
            # Silently ignore - bot is not configured to respond in this guild/channel
            return
        
        # Check command access
        has_access, error_msg = security_check(user_id, 'signal')
        if not has_access:
            await handle_access_denial(interaction, error_msg)
            return
        
        # Comprehensive security check
        security_passed, security_message = security_check(user_id, 'signal', guild_id)
        if not security_passed:
            if "privacy policy" in security_message or "verification" in security_message:
                await initiate_verification_flow(interaction)
                return
            else:
                embed = discord.Embed(
                    title="🚫 Access Denied",
                    description=security_message,
                    color=discord.Color.red()
                )
                await interaction.response.send_message(embed=embed, ephemeral=True)
                return
        
        # Log command execution
        log_command_execution('signal', user_id)
        
        # Set cooldown for signal command
        set_cooldown(user_id)
        
        # Create/update user profile with actual username
        username = interaction.user.display_name or interaction.user.name
        guild_name = interaction.guild.name if interaction.guild else None
        create_user_profile(user_id, username, guild_name)
        
        user_settings = get_user_settings(str(user_id))
        
        # Use user's preferred expiry if not specified
        if expiry is None:
            expiry = user_settings['preferred_expiry']
        
        # Use user's recommendation setting, but check freemium daily limit
        show_rec = user_settings.get('show_recommendations', True)
        
        # For freemium users, check if they've exceeded their daily recommendation limit
        if show_rec and not is_user_premium(str(user_id)):
            limit_exceeded, current_count = check_freemium_recommendation_limit(user_id)
            if limit_exceeded:
                show_rec = False  # Disable recommendations for freemium users who exceeded limit

        # Get trading style info
        style_info = {
            '1m': {'name': 'Scalping Momentum', 'desc': 'High-frequency momentum trading'},
            '5m': {'name': 'Swing Balance', 'desc': 'Balanced momentum and mean reversion'},
            '15m': {'name': 'Trend Following', 'desc': 'Strong trend following with confirmations'}
        }
        
        current_style = style_info.get(expiry, {'name': 'Standard', 'desc': 'Standard analysis'})

        embed = discord.Embed(
            title="📊 Signal Generation",
            color=discord.Color.blue()
        )
        
        embed.add_field(
            name="📛 SetUp", 
            value=f"• {expiry}\n• {mode}\n• {current_style['name']}",
            inline=True
        )
        
        embed.add_field(
            name="🎯 Style Description", 
            value=current_style['desc'], 
            inline=False
        )
        
        # Show user's settings
        settings_text = f"🎯 Min Confidence: {user_settings['min_confidence']}%\n⚡ Risk: {user_settings['risk_tolerance'].title()}\n🎯 Recommendations: {'On' if show_rec else 'Off'}"
        embed.add_field(name="⚙️ Your Settings", value=settings_text, inline=True)
        
        if not show_rec:
            embed.add_field(name="📋 Instructions", value="Use the dropdown below to select a currency pair", inline=False)

        embed.add_field(name="Disclaimer", value="We are not responsible for any of your loss, 5m expiry trades is recommended. (0-3 Pips) delay depending on the broker and currency pair.", inline=False)

        # Store original field count for proper embed restoration
        original_field_count = len(embed.fields)

        if show_rec:
            # Check freemium recommendation limit BEFORE showing recommendation
            if user_id:
                user_id_int = int(user_id) if isinstance(user_id, str) else user_id
                limit_exceeded, current_count = check_freemium_recommendation_limit(user_id_int)
                
                if limit_exceeded:
                    # Get current settings for dynamic message
                    user_data = load_user_data()
                    settings = user_data.get("settings", {})
                    daily_limit = settings.get("FREEMIUM_RECOMMENDATION_LIMIT", 1)
                    
                    embed.add_field(
                        name="⚠️ Daily Limit Reached",
                        value=f"Free users are limited to {daily_limit} recommendation{'s' if daily_limit != 1 else ''} per day.\nYou've used {current_count}/{daily_limit} today.\n\n✨ **Upgrade to Premium** for unlimited recommendations and priority signals!",
                        inline=False
                    )
                    await interaction.response.send_message(embed=embed, view=SignalView(expiry, mode, False), ephemeral=True)
                    return
                else:
                    # Increment the count BEFORE processing recommendation
                    if user_id_int in freemium_daily_recommendations:
                        freemium_daily_recommendations[user_id_int]['count'] += 1
                    else:
                        today = datetime.now(timezone.utc).date()
                        freemium_daily_recommendations[user_id_int] = {'date': today, 'count': 1}
            
            embed.add_field(name="🎯 Analyzing Market...", value="Finding the best trading opportunity with optimized style analysis...", inline=False)
            await interaction.response.send_message(embed=embed, ephemeral=True)
            
            try:
                # Use processing efficiency queue for recommendations
                user_id_int = int(user_id) if isinstance(user_id, str) else user_id
                
                # Queue recommendation request with high priority
                recommendation_queued = await queue_recommendation_request(
                    user_id_int, 
                    get_recommended_pair, 
                    expiry, 
                    mode, 
                    16,  # num_pairs
                    user_id, 
                    "optimal"  # recommendation_type
                )
                
                if recommendation_queued:
                    # Adaptive timeout based on current system load
                    efficiency_manager = get_efficiency_manager()
                    performance = get_system_performance()
                    current_load = performance.load_level
                    timeout_multiplier = 1.0 if current_load.name.lower() == "light" else 1.5 if current_load.name.lower() == "moderate" else 2.0
                    recommendation_timeout = int(45 * timeout_multiplier)
                    
                    recommendation = await asyncio.wait_for(
                        get_recommended_pair(expiry, mode, num_pairs=16, user_id=user_id, recommendation_type="optimal"),
                        timeout=recommendation_timeout
                    )
                else:
                    # Queue is full, provide fallback response
                    recommendation = {'error': 'system_busy', 'message': 'System busy - high demand detected'}

                # Update embed with results
                embed.description = "Advanced trading signals with optimized styles for each expiry time"
                
                # Remove loading message
                if len(embed.fields) > original_field_count:
                    embed.remove_field(-1)

                # Handle different recommendation responses
                if recommendation and 'error' in recommendation:
                    # Handle error cases
                    if recommendation['error'] == 'timeout':
                        error_msg = "⏰ Analysis timed out. Market conditions are being processed - please try again in a moment."
                    else:
                        error_msg = f"⚠️ {recommendation.get('message', 'System temporarily unavailable')}"
                    
                    embed.add_field(name="🎯 Recommendation Status", value=error_msg, inline=False)
                    
                elif recommendation:
                    rec_text = f"**{recommendation['pair']}**\n"
                    rec_text += f"💰 Price: {recommendation['price']:.5f}\n"
                    rec_text += f"📊 Quality: {recommendation['quality_score']:.0f}/100\n"
                    rec_text += f"📈 Trend: {recommendation['trend_quality']}\n"
                    rec_text += f"🎯 Volatility: {recommendation['volatility']:.2f}%\n"
                    rec_text += f"⭐ Strength: {recommendation['strength_score']:.0f}/100\n"
                    rec_text += f"🎨 **Perfect for {current_style['name']} style!**"
                    
                    embed.add_field(name="🎯 AI-Powered Style-Optimized Recommendation", value=rec_text, inline=False)
                else:
                    # Handle case where no recommendations meet user threshold
                    user_settings = get_user_settings(user_id)
                    user_threshold = user_settings['min_confidence']
                    
                    threshold_msg = f"📊 No pairs currently meet your {user_threshold}% confidence threshold.\n\n"
                    threshold_msg += f"💡 **Tip:** Lower your threshold in /settings or wait for stronger market conditions.\n"
                    threshold_msg += f"🔄 Market conditions change frequently - try again in a few minutes."
                    
                    embed.add_field(name="🎯 Recommendation Status", value=threshold_msg, inline=False)
                
                embed.add_field(name="📋 Instructions", value="Use the dropdown below to select a currency pair", inline=False)

                # Create persistent view and update message
                view = SignalView(expiry, mode, show_rec)
                view.original_field_count = original_field_count
                view.original_interaction = interaction
                
                # Register with persistent manager
                PersistentInteractionManager.register_view(view)
                
                await interaction.edit_original_response(embed=embed, view=view)
                
            except asyncio.TimeoutError:
                print("Recommendation request timed out")
                embed.description = "Advanced trading signals with optimized styles for each expiry time"
                if len(embed.fields) > original_field_count:
                    embed.remove_field(-1)
                embed.add_field(name="🎯 Recommendation", value="Analysis timed out - please select a pair manually", inline=False)
                embed.add_field(name="📋 Instructions", value="Use the dropdown below to select a currency pair", inline=False)
                
                view = SignalView(expiry, mode, False)
                view.original_field_count = original_field_count
                await interaction.edit_original_response(embed=embed, view=view)
            except Exception as e:
                print(f"Error getting recommendation: {e}")
                embed.description = "Advanced trading signals with optimized styles for each expiry time"
                if len(embed.fields) > original_field_count:
                    embed.remove_field(-1)
                embed.add_field(name="🎯 Recommendation", value="Unable to fetch recommendation at this time", inline=False)
                embed.add_field(name="📋 Instructions", value="Use the dropdown below to select a currency pair", inline=False)
                
                view = SignalView(expiry, mode, False)
                view.original_field_count = original_field_count
                await interaction.edit_original_response(embed=embed, view=view)
        else:
            # No recommendations, show dropdowns immediately
            view = SignalView(expiry, mode, show_rec)
            view.original_field_count = original_field_count
            await interaction.response.send_message(embed=embed, view=view, ephemeral=True)
    
    except Exception as e:
        print(f"Error in enhanced signal command: {e}")
        try:
            if not interaction.response.is_done():
                embed = discord.Embed(
                    title="❌ Error",
                    description="An error occurred while processing your request. Please try again.",
                    color=discord.Color.red()
                )
                await interaction.response.send_message(embed=embed, ephemeral=True)
        except:
            pass



