@bot.tree.command(name="performance", description="View system performance and load status")
async def performance_command(interaction: discord.Interaction):
    """Show system performance metrics and processing efficiency status"""
    user_id = str(interaction.user.id)
    
    # Check command access
    has_access, error_msg = security_check(user_id, 'performance')
    if not has_access:
        await handle_access_denial(interaction, error_msg)
        return
    
    try:
        # Get performance metrics from efficiency manager
        performance = get_system_performance()
        efficiency_manager = get_efficiency_manager()
        
        embed = discord.Embed(
            title="📊 System Performance Monitor",
            description="Real-time processing efficiency and system health metrics",
            color=discord.Color.blue(),
            timestamp=datetime.now(timezone.utc)
        )
        
        # Current load status
        load_color = {
            LoadLevel.LIGHT: '🟢',
            LoadLevel.MODERATE: '🟡', 
            LoadLevel.HEAVY: '🟠',
            LoadLevel.CRITICAL: '🔴'
        }
        
        current_load = performance.load_level
        load_emoji = load_color.get(current_load, '⚪')
        analysis_mode = get_current_analysis_scope()
        
        embed.add_field(
            name=f"{load_emoji} System Load",
            value=f"**{current_load.name.title()}** Load\n**{analysis_mode.name.title()}** Analysis Mode",
            inline=True
        )
        
        # Queue status
        queue_size = efficiency_manager.request_queue.qsize()
        active_requests = performance.active_requests
        
        embed.add_field(
            name="⚡ Processing Queue",
            value=f"Queue: {queue_size} requests\nActive: {active_requests} processing\nCPU: {performance.cpu_usage:.1f}%\nMemory: {performance.memory_usage:.1f}%",
            inline=True
        )
        
        # Performance metrics
        embed.add_field(
            name="📈 Performance Stats",
            value=f"Load Level: {current_load.name}\nAnalysis Mode: {analysis_mode.name}\nActive Requests: {active_requests}",
            inline=True
        )
        
        # Processing optimizations
        embed.add_field(
            name="🔧 Active Optimizations",
            value="• **Request Queuing** - Prioritized processing\n"
                  "• **Load-based Scaling** - Dynamic analysis depth\n"
                  "• **Memory Management** - Automatic cleanup\n"
                  "• **Database Pool** - Optimized connections\n"
                  "• **Background Tasks** - Non-blocking operations",
            inline=False
        )
        
        # Recommendations based on load
        if current_load in [LoadLevel.HEAVY, LoadLevel.CRITICAL]:
            embed.add_field(
                name="⚠️ Performance Notice",
                value="High system load detected. Recommendations are processed with priority queuing "
                      "and analysis is optimized for faster responses. All functionality remains available.",
                inline=False
            )
        elif current_load == LoadLevel.MODERATE:
            embed.add_field(
                name="💡 System Info",
                value="Moderate system load. Processing is optimized for balanced performance and accuracy.",
                inline=False
            )
        else:
            embed.add_field(
                name="✅ System Status",
                value="System operating at optimal performance with full analysis capabilities.",
                inline=False
            )
        
        embed.set_footer(text="Performance metrics update in real-time")
        
        await interaction.response.send_message(embed=embed, ephemeral=True)
        
    except Exception as e:
        print(f"Error in performance command: {e}")
        error_embed = discord.Embed(
            title="❌ Performance Error",
            description="Unable to retrieve performance metrics at this time.",
            color=discord.Color.red()
        )
        await interaction.response.send_message(embed=error_embed, ephemeral=True)

