# Alert command functionality removed

async def handle_alerts_command(interaction: discord.Interaction, action: str, pair: str = None):
    """Handle alerts command"""
    user_id = str(interaction.user.id)
    
    # Check command access
    has_access, error_msg = security_check(user_id, 'alerts')
    if not has_access:
        await handle_access_denial(interaction, error_msg)
        return
    
    if action == "view":
        alerts = get_user_alerts(user_id)
        
        if not alerts:
            embed = discord.Embed(
                title="🔔 Your Active Alerts",
                description="No active alerts. Use `/alerts create` to set up price alerts!",
                color=discord.Color.blue()
            )
        else:
            embed = discord.Embed(
                title="🔔 Your Active Alerts",
                color=discord.Color.green(),
                timestamp=datetime.now(timezone.utc)
            )
            
            alerts_text = ""
            for alert in alerts[:15]:  # Show max 15 alerts
                alert_id = alert[0]
                alert_pair = alert[2]
                target_value = alert[4]
                condition = alert[5]
                created = datetime.fromisoformat(alert[7]).strftime("%m/%d %H:%M")
                alert_name = alert[9] if len(alert) > 9 and alert[9] else f"{alert_pair} Alert"
                expiry = alert[10] if len(alert) > 10 and alert[10] else None
                
                condition_emoji = "📈" if condition == "above" else "📉"
                alerts_text += f"{condition_emoji} **{alert_name}** (ID: {alert_id})\n"
                alerts_text += f"   {alert_pair} {condition} {target_value:.5f}\n"
                alerts_text += f"   Created: {created}"
                
                if expiry:
                    expiry_time = datetime.fromisoformat(expiry)
                    if expiry_time > datetime.now(timezone.utc):
                        alerts_text += f" | Expires: <t:{int(expiry_time.timestamp())}:R>"
                    else:
                        alerts_text += f" | ⚠️ EXPIRED"
                
                alerts_text += "\n\n"
            
            embed.description = alerts_text
            embed.set_footer(text=f"Showing {min(15, len(alerts))} of {len(alerts)} alerts")
    
    elif action == "create":
        if not pair or pair not in FOREX_PAIRS:
            embed = discord.Embed(
                title="❌ Invalid Pair",
                description="Please specify a valid currency pair.",
                color=discord.Color.red()
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)
        else:
            modal = AlertModal(pair)
            await interaction.response.send_modal(modal)
            return
    
    elif action == "manage":
        embed = discord.Embed(
            title="🔧 Alert Management",
            description="Use the buttons below to manage your alerts",
            color=discord.Color.blue()
        )
        
        alerts = get_user_alerts(user_id)
        embed.add_field(name="📊 Quick Stats", value=f"Active alerts: {len(alerts)}/20", inline=True)
        
        view = AlertManagementView(user_id)
        await interaction.response.send_message(embed=embed, view=view, ephemeral=True)
        return
    
    elif action == "stats":
        await interaction.response.defer()
        
        # Get alert statistics
        alerts = get_user_alerts(user_id, include_expired=True)
        history = get_alert_history(user_id, days_back=30)
        
        embed = discord.Embed(
            title="📊 Alert Statistics",
            color=discord.Color.purple(),
            timestamp=datetime.now(timezone.utc)
        )
        
        # Current stats
        active_count = len(get_user_alerts(user_id))
        total_created = len(alerts)
        triggered_count = len(history)
        
        stats_text = f"🟢 Active: {active_count}\n"
        stats_text += f"📝 Total Created: {total_created}\n"
        stats_text += f"🔔 Triggered (30d): {triggered_count}"
        
        embed.add_field(name="📈 Overview", value=stats_text, inline=True)
        
        # Success rate
        if total_created > 0:
            success_rate = (triggered_count / total_created) * 100
            embed.add_field(name="🎯 Trigger Rate", value=f"{success_rate:.1f}%", inline=True)
        
        # Most alerted pairs
        if history:
            from collections import Counter
            pair_counts = Counter(alert[2] for alert in history)
            top_pair = pair_counts.most_common(1)[0]
            embed.add_field(name="🏆 Most Triggered", value=f"{top_pair[0]} ({top_pair[1]}x)", inline=True)
        
        await interaction.followup.send(embed=embed)
        return
    
    elif action == "clear":
        conn = sqlite3.connect('signals.db')
        c = conn.cursor()
        c.execute('UPDATE user_alerts SET is_active = 0 WHERE user_id = ?', (user_id,))
        cleared_count = c.rowcount
        conn.commit()
        conn.close()
        
        embed = discord.Embed(
            title="🗑️ Alerts Cleared",
            description=f"Deactivated {cleared_count} alerts.",
            color=discord.Color.green()
        )
    
    await interaction.response.send_message(embed=embed, ephemeral=True)


