# split_command_logic.py

async def process_data_chunk(data_chunk):
    """
    Processes a chunk of data. This function should be CPU-bound.
    """
    # Simulate CPU-intensive processing
    await asyncio.sleep(1)
    return len(data_chunk)

async def process_large_command(data):
    """
    Splits large command logic into smaller tasks to reduce memory usage and improve modularity.
    """
    chunk_size = 1000  # Adjust based on available memory
    results = []

    for i in range(0, len(data), chunk_size):
        chunk = data[i:i + chunk_size]
        result = await process_data_chunk(chunk)
        results.append(result)

    return sum(results)
    
async def run_in_executor(func, *args):
    """Runs a CPU-bound function in a separate thread."""
    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(executor, func, *args)

def get_cpu_usage():
    """Returns the current CPU usage as a percentage."""
    return psutil.cpu_percent(interval=1)
    
    

