last_heartbeat = datetime.now(timezone.utc)
background_analysis_queue = asyncio.Queue()
analysis_in_progress = False

async def background_analysis_worker():
    """Background worker for analysis to reduce main thread load in resource-constrained environment"""
    global analysis_in_progress
    
    while True:
        task = None
        try:
            # Get analysis task from queue
            task = await background_analysis_queue.get()
            analysis_in_progress = True
            
            # Process analysis in background thread to avoid blocking
            loop = asyncio.get_event_loop()
            result = await loop.run_in_executor(executor, task['function'], *task['args'])
            
            # Cache the result if successful
            # Cache removed for real-time accuracy
            
            # Clean up memory after each analysis
            cleanup_memory()
            
        except asyncio.CancelledError:
            # Task was cancelled, don't call task_done()
            analysis_in_progress = False
            break
        except Exception as e:
            print(f"Background analysis error: {e}")
        finally:
            analysis_in_progress = False
            # Only call task_done() if we actually got a task
            if task is not None:
                try:
                    background_analysis_queue.task_done()
                except ValueError:
                    # task_done() called too many times, skip
                    pass
            # Small delay to prevent overwhelming the 0.5v CPU
            await asyncio.sleep(0.1)

@tasks.loop(seconds=45)  # Reduced frequency for resource optimization
async def heartbeat():
    global last_heartbeat
    current_time = datetime.now(timezone.utc)

    if (current_time - last_heartbeat).total_seconds() >= 90:  # Reduced frequency for 512MB RAM
        try:
            # Lightweight heartbeat for resource-constrained environment
            memory_info = psutil.virtual_memory()
            
            # Only perform maintenance if memory usage is getting high
            if memory_info.percent > 75:  # 75% of 512MB
                print(f"Memory usage high ({memory_info.percent}%), performing cleanup...")
                cleanup_memory()
                check_memory_and_cleanup()
            
            # Check if analysis queue is getting too large
            queue_size = background_analysis_queue.qsize()
            if queue_size > 5:  # Limit queue size for resource constraints
                print(f"Analysis queue full ({queue_size}), clearing old tasks...")
                # Clear some old tasks to prevent memory overflow
                while queue_size > 3:
                    try:
                        background_analysis_queue.get_nowait()
                        queue_size -= 1
                    except asyncio.QueueEmpty:
                        break
            
            last_heartbeat = current_time
            
        except Exception as e:
            print(f"Heartbeat error: {e}")
            # Aggressive cleanup on error
            cleanup_memory()
        
@bot.event
async def on_ready():
    print(f'{bot.user} has connected to Discord!')
    print(f'Bot ID: {bot.user.id}')
    print(f'Connected to {len(bot.guilds)} guilds')
    
    try:
        # Optimized command syncing with rate limit prevention
        tree_commands = bot.tree.get_commands()
        print(f"Commands in tree: {len(tree_commands)}")
        
        # Only sync if we have commands and it's been a while since last sync
        if len(tree_commands) > 0:
            try:
                # Check if commands are already synced by testing one
                existing_commands = await bot.tree.fetch_commands()
                if len(existing_commands) == len(tree_commands):
                    print(f"✓ Commands already synced ({len(existing_commands)} commands)")
                else:
                    print("Syncing commands...")
                    synced = await bot.tree.sync()
                    print(f"✓ Successfully synced {len(synced)} command(s)")
                    
            except discord.HTTPException as http_err:
                if http_err.status == 429:  # Rate limited
                    print("⚠ Rate limited - commands will sync automatically later")
                elif http_err.status == 403:
                    print("⚠ Permission denied - check bot permissions")
                else:
                    print(f"⚠ Sync error: {http_err}")
                        
            except Exception as e:
                print(f"Command sync error: {e}")
        else:
            print("No commands found in tree")
        
        # Start other services after successful sync
        heartbeat.start()
        
        # Start background analysis worker for resource optimization
        print("Starting background analysis worker for resource-constrained environment...")
        bot.loop.create_task(background_analysis_worker())
        
        # Alert system removed as requested
        
        # Initial memory cleanup
        cleanup_memory()
        print("Resource optimization enabled for 512MB RAM environment")
        print("Bot is fully ready and operational!")
        
    except discord.HTTPException as e:
        print(f"HTTP error during command sync: {e}")
        print(f"Status: {e.status}, Code: {e.code}")
        if e.status == 403:
            print("Bot lacks permissions to sync commands in this guild")
        elif e.status == 429:
            print("Rate limited - Discord is blocking command sync temporarily")
    except discord.Forbidden:
        print("Bot doesn't have permission to sync commands")
    except Exception as e:
        print(f"Unexpected error during sync: {e}")
        import traceback
        traceback.print_exc()

@bot.tree.error
async def on_app_command_error(interaction: discord.Interaction, error: app_commands.AppCommandError):
    """Handle application command errors."""
    print(f"Command error: {error}")
    
    if isinstance(error, app_commands.CommandInvokeError):
        print(f"Command invoke error: {error.original}")
        
        # Check if it's a NotFound error (interaction timeout)
        if "10062" in str(error.original) or "Unknown interaction" in str(error.original):
            print("Interaction timed out - no response possible")
            return
    
    # Try to respond if interaction hasn't been responded to yet
    try:
        if not interaction.response.is_done():
            embed = discord.Embed(
                title="❌ Command Error",
                description="An error occurred while processing your command. Please try again later.",
                color=discord.Color.red()
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)
    except discord.NotFound:
        print("Interaction already expired - cannot send error response")
    except Exception as e:
        print(f"Failed to send error response: {e}")


# Helper functions for verification and authorization
async def check_verification(user_id: str) -> bool:
    """Check if user is verified"""
    user_data = load_user_data()
    return str(user_id) in user_data.get("user_verification", {})

async def verify_user(user_id: str):
    """Verify a user"""
    user_data = load_user_data()
    user_data["user_verification"][str(user_id)] = True
    save_user_data(user_data)

def is_user_premium(user_id: str) -> bool:
    """Check if user has premium access and handle expiration"""
    user_data = load_user_data()
    auth_data = user_data.get("user_authorization", {})
    
    if str(user_id) not in auth_data:
        return False
    
    user_auth = auth_data[str(user_id)]
    expires_at = user_auth.get("expires_at")
    
    # If no expiration date, it's permanent premium
    if not expires_at:
        return True
    
    # Check if premium access has expired
    try:
        expiry_date = datetime.fromisoformat(expires_at)
        current_time = datetime.now()
        
        if current_time > expiry_date:
            # Premium access has expired, remove it
            del auth_data[str(user_id)]
            save_user_data(user_data)
            return False
        
        return True
    except (ValueError, TypeError):
        # Invalid date format, assume expired
        del auth_data[str(user_id)]
        save_user_data(user_data)
        return False

def is_user_blacklisted(user_id: str) -> bool:
    """Check if user is blacklisted"""
    user_data = load_user_data()
    return str(user_id) in user_data.get("blacklisted_users", [])

def get_daily_quota() -> int:
    """Get the daily quota for freemium users"""
    user_data = load_user_data()
    return int(user_data.get("settings", {}).get("QUOTA", "5"))

def check_user_quota(user_id: str) -> bool:
    """Check if user has remaining quota for today"""
    user_data = load_user_data()
    today = datetime.now().strftime("%Y-%m-%d")
    user_quotas = user_data.get("user_quotas", {})
    user_quota_data = user_quotas.get(str(user_id), {})
    
    if user_quota_data.get("date") != today:
        # Reset quota for new day
        user_quotas[str(user_id)] = {"date": today, "used": 0}
        user_data["user_quotas"] = user_quotas
        save_user_data(user_data)
        return True
    
    daily_quota = get_daily_quota()
    return user_quota_data.get("used", 0) < daily_quota

def use_user_quota(user_id: str):
    """Use one quota for the user"""
    user_data = load_user_data()
    today = datetime.now().strftime("%Y-%m-%d")
    user_quotas = user_data.get("user_quotas", {})
    
    if str(user_id) not in user_quotas:
        user_quotas[str(user_id)] = {"date": today, "used": 0}
    
    user_quotas[str(user_id)]["used"] += 1
    user_data["user_quotas"] = user_quotas
    save_user_data(user_data)

def get_remaining_quota(user_id: str) -> int:
    """Get remaining quota for user"""
    user_data = load_user_data()
    today = datetime.now().strftime("%Y-%m-%d")
    user_quotas = user_data.get("user_quotas", {})
    user_quota_data = user_quotas.get(str(user_id), {})
    
    if user_quota_data.get("date") != today:
        return get_daily_quota()
    
    daily_quota = get_daily_quota()
    used = user_quota_data.get("used", 0)
    return max(0, daily_quota - used)

def has_used_recommendation(user_id: str, pair: str) -> bool:
    """Check if freemium user has already used recommendation for this pair"""
    user_data = load_user_data()
    user_recs = user_data.get("user_recommendations", {}).get(str(user_id), [])
    return pair in user_recs

def use_recommendation(user_id: str, pair: str):
    """Mark that freemium user has used recommendation for this pair"""
    user_data = load_user_data()
    if "user_recommendations" not in user_data:
        user_data["user_recommendations"] = {}
    if str(user_id) not in user_data["user_recommendations"]:
        user_data["user_recommendations"][str(user_id)] = []
    
    if pair not in user_data["user_recommendations"][str(user_id)]:
        user_data["user_recommendations"][str(user_id)].append(pair)
        save_user_data(user_data)

# Verification Modal
class VerificationModal(discord.ui.Modal, title="User Verification"):
    verification_text = discord.ui.TextInput(
        label="Verification",
        placeholder="Type the exact phrase to verify you're not a bot",
        required=True,
        max_length=100
    )

    def __init__(self):
        super().__init__()

    async def on_submit(self, interaction: discord.Interaction):
        if self.verification_text.value.strip() == "I'am a user, not a bot":
            await verify_user(str(interaction.user.id))
            embed = discord.Embed(
                title="✅ Verification Successful",
                description="You are now verified and can use the bot commands!",
                color=discord.Color.green()
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)
        else:
            embed = discord.Embed(
                title="❌ Verification Failed",
                description="Please type the exact phrase: I'am a user, not a bot",
                color=discord.Color.red()
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)

