# Profile Command
@bot.tree.command(name="profile", description="View your user profile and statistics")
async def profile_command(interaction: discord.Interaction):
    user_id = interaction.user.id
    
    # Create or update user profile
    profile = create_user_profile(user_id, interaction.user.display_name, 
                                 interaction.guild.name if interaction.guild else None)
    
    user_data = load_user_data()
    
    # Get user statistics
    is_premium = str(user_id) in user_data.get("user_authorization", {})
    is_verified = user_data.get("user_verification", {}).get(str(user_id), {}).get("verified", False)
    commands_used = profile.get("commands_used", 0)
    join_date = profile.get("join_date", "Unknown")
    last_active = profile.get("last_active", "Unknown")
    
    # Format dates
    try:
        join_date_formatted = datetime.fromisoformat(join_date.replace('Z', '+00:00')).strftime("%B %d, %Y")
    except:
        join_date_formatted = "Unknown"
    
    try:
        last_active_formatted = datetime.fromisoformat(last_active.replace('Z', '+00:00')).strftime("%B %d, %Y at %H:%M UTC")
    except:
        last_active_formatted = "Unknown"
    
    # Create embed
    embed = discord.Embed(
        title=f"👤 Profile: {interaction.user.display_name}",
        color=discord.Color.blue() if is_premium else discord.Color.light_grey()
    )
    
    embed.add_field(
        name="📊 Account Status",
        value=f"{'🌟 Premium' if is_premium else '🆓 Free'}\n{'✅ Verified' if is_verified else '⏳ Unverified'}",
        inline=True
    )
    
    embed.add_field(
        name="📈 Usage Statistics",
        value=f"Commands Used: {commands_used}\nJoined: {join_date_formatted}",
        inline=True
    )
    
    embed.add_field(
        name="⏰ Activity",
        value=f"Last Active: {last_active_formatted}",
        inline=False
    )
    
    # Add recommendation usage for freemium users
    if not is_premium:
        today = datetime.now(timezone.utc).date()
        daily_count = 0
        
        if user_id in freemium_daily_recommendations:
            user_rec_data = freemium_daily_recommendations[user_id]
            if user_rec_data['date'] == today:
                daily_count = user_rec_data['count']
        
        embed.add_field(
            name="🎯 Daily Recommendations",
            value=f"Used: {daily_count}/1 today\n{'✅ Available' if daily_count == 0 else '⏳ Tomorrow for next free recommendation'}",
            inline=True
        )
    
    # Add cooldown information
    on_cooldown, time_remaining = check_cooldown(user_id)
    if on_cooldown:
        embed.add_field(
            name="⏱️ Signal Cooldown",
            value=f"{time_remaining} seconds remaining",
            inline=True
        )
    
    embed.set_thumbnail(url=interaction.user.display_avatar.url)
    embed.set_footer(text=f"User ID: {user_id}")
    
    # Create view with alerts button
    view = ProfileView(user_id)
    
    await interaction.response.send_message(embed=embed, view=view, ephemeral=True)

class ProfileView(discord.ui.View):
    def __init__(self, user_id):
        super().__init__(timeout=300)
        self.user_id = user_id
        
    @discord.ui.button(label="🔔 Manage Alerts", style=discord.ButtonStyle.primary)
    async def alerts_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        # Execute the alerts functionality
        await interaction.response.defer(ephemeral=True)
        
        # Get user alerts
        alerts = get_user_alerts(self.user_id)
        
        if not alerts:
            embed = discord.Embed(
                title="📊 Price Alerts",
                description="You don't have any active alerts.\n\nUse the `/alerts` command to create new alerts!",
                color=discord.Color.blue()
            )
            await interaction.followup.send(embed=embed, ephemeral=True)
        else:
            embed = discord.Embed(
                title="🔔 Alert Management",
                description="Use the buttons below to manage your alerts",
                color=discord.Color.blue()
            )
            
            embed.add_field(name="📊 Quick Stats", value=f"Active alerts: {len(alerts)}/20", inline=True)
            
            view = AlertManagementView(self.user_id)
            await interaction.followup.send(embed=embed, view=view, ephemeral=True)

# Background task scheduler for optimization
# Pre-computation scheduler removed to save API calls

@tasks.loop(minutes=1)
async def optimization_monitor():
    """Enhanced system performance monitor with aggressive memory management"""
    try:
        # Get detailed memory stats
        memory_info = get_memory_usage()
        memory_percent = memory_info['percent']
        memory_rss = memory_info['rss']
        queue_size = background_analysis_queue.qsize() if 'background_analysis_queue' in globals() else 0
        
        # Enhanced memory management with multiple tiers
        if memory_percent > 90 or memory_rss > 450:  # Critical memory usage
            print(f"CRITICAL memory usage: {memory_percent:.1f}% ({memory_rss:.1f}MB)")
            # Aggressive cleanup
            global MAX_CACHE_SIZE, MAX_CHART_CACHE_SIZE
            MAX_CACHE_SIZE = 10
            MAX_CHART_CACHE_SIZE = 5
            # Cache management removed for real-time accuracy
            collected = cleanup_memory()
            print(f"Emergency cleanup: collected {collected} objects")
            
        elif memory_percent > 80 or memory_rss > 350:  # High memory usage
            print(f"High memory usage: {memory_percent:.1f}% ({memory_rss:.1f}MB)")
            # Cache management removed for real-time accuracy
            cleanup_memory()
            
        elif memory_percent > 70 or memory_rss > 250:  # Moderate memory usage
            # Proactive cleanup - cache management removed for real-time accuracy
            pass
            
        # Queue management with memory awareness
        if queue_size > 30 or memory_percent > 75:
            print(f"High load detected: {queue_size} queued, {memory_percent:.1f}% RAM")
            # Reduce cache expiry for memory relief
            global CACHE_EXPIRY
            CACHE_EXPIRY = max(30, CACHE_EXPIRY - 15)  # Minimum 30 seconds
        elif queue_size < 5 and memory_percent < 60:
            # Restore normal cache expiry when load is low
            CACHE_EXPIRY = min(60, CACHE_EXPIRY + 10)  # Maximum 1 minute for optimized performance
            
        # Log comprehensive system status (cache-free system)
        print(f"System: {memory_percent:.1f}% RAM ({memory_rss:.1f}MB), {queue_size} queued, real-time processing")
        
    except Exception as e:
        print(f"Optimization monitor error: {e}")

# Removed duplicate on_ready function

async def background_worker(worker_name):
    """Background worker to process analysis queue"""
    while True:
        try:
            # Get task from queue with timeout
            task = await asyncio.wait_for(background_analysis_queue.get(), timeout=1.0)
            
            # Process the task
            result = await process_background_task(task)
            
            # Mark task as done
            background_analysis_queue.task_done()
            
        except asyncio.TimeoutError:
            # No tasks in queue, continue
            continue
        except Exception as e:
            print(f"Background worker {worker_name} error: {e}")
            await asyncio.sleep(1)

# Enhanced signal command with rate limiting
async def enhanced_signal_with_rate_limiting(interaction, pair=None, timeframe='1min'):
    """Enhanced signal processing with rate limiting and optimization"""
    user_id = str(interaction.user.id)
    
    # Check rate limits first
    allowed, message = check_rate_limit(user_id)
    if not allowed:
        embed = discord.Embed(
            title="⏱️ Rate Limit Exceeded",
            description=message,
            color=discord.Color.orange()
        )
        await interaction.response.send_message(embed=embed, ephemeral=True)
        return
    
    # Pre-computation removed - direct analysis only
    
    # Check for high load and use simplified analysis
    if optimize_response_for_load():
        print(f"Using simplified analysis due to high load")
        try:
            simplified_result = await execute_simplified_signal_analysis(pair, timeframe)
            return await send_signal_embed(interaction, simplified_result)
        except Exception as e:
            print(f"Simplified analysis failed: {e}")
    
    # Normal processing with caching
    cache_key = f"signal_{pair}_{timeframe}"
    # cached_result = get_cached_analysis(cache_key)  # Cache function not implemented
    cached_result = None
    
    if cached_result:
        print(f"Using cached result for {pair}")
        return await send_signal_embed(interaction, cached_result)
    
    # Queue for background processing
    try:
        result = await queue_background_analysis(
            generate_comprehensive_analysis,
            args=(pair, timeframe),
            cache_key=cache_key,
            priority='high' if user_id in PREMIUM_USERS else 'normal'
        )
        
        if result:
            return await send_signal_embed(interaction, result)
        else:
            # Fallback message for queued processing
            embed = discord.Embed(
                title="⏳ Processing Your Request",
                description="Your signal is being processed. This may take a moment during high usage periods.",
                color=discord.Color.blue()
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)
            
    except Exception as e:
        print(f"Enhanced signal processing error: {e}")
        embed = discord.Embed(
            title="❌ Processing Error",
            description="Unable to process signal at this time. Please try again.",
            color=discord.Color.red()
        )
        await interaction.response.send_message(embed=embed, ephemeral=True)

async def send_signal_embed(interaction, signal_data):
    """Send signal data as embed"""
    if signal_data and 'error' not in signal_data:
        embed = discord.Embed(
            title=f"📊 {signal_data.get('pair', 'Signal')} Analysis",
            description=f"Direction: **{signal_data.get('direction', 'N/A')}**\nConfidence: **{signal_data.get('confidence', 0)}%**",
            color=discord.Color.green() if signal_data.get('direction') == 'CALL' else discord.Color.red()
        )
        
        if signal_data.get('simplified'):
            embed.set_footer(text="Simplified analysis due to high server load")
        
        await interaction.response.send_message(embed=embed, ephemeral=True)
    else:
        embed = discord.Embed(
            title="❌ Analysis Error",
            description="Unable to generate signal at this time.",
            color=discord.Color.red()
        )
        await interaction.response.send_message(embed=embed, ephemeral=True)

